window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k1v3"]=[{"id":"k1v3-b01","courseId":"k1v3","order":1,"title":"Chào AI Tiểu Ngữ!","titleZh":"AI小语，你好！","titlePy":"AI Xiǎoyǔ, nǐ hǎo","vocab":[{"stt":1,"hanzi":"你好","pinyin":"nǐ hǎo","hanviet":"Nễ hảo","pos":"Cụm từ","meaning":"xin chào, chào bạn","comps":"你好吗 (bạn khoẻ không), 大家好 (chào mọi người)","example":{"zh":"老师，你好！","py":"Lǎoshī, nǐ hǎo!","vi":"Em chào thầy ạ!"}},{"stt":2,"hanzi":"大家","pinyin":"dàjiā","hanviet":"Đại gia","pos":"Đại từ","meaning":"mọi người, tất cả","comps":"大家好 (chào mọi người), 大家再见 (tạm biệt mọi người)","example":{"zh":"大家好，同学们！","py":"Dàjiā hǎo, tóngxuémen!","vi":"Chào cả lớp, các em!"}},{"stt":3,"hanzi":"好","pinyin":"hǎo","hanviet":"Hảo","pos":"Tính từ","meaning":"tốt, khoẻ, hay","comps":"很好 (rất tốt), 你好 (chào bạn)","example":{"zh":"同学们，你们好！","py":"Tóngxuémen, nǐmen hǎo!","vi":"Các em, chào các em!"}},{"stt":4,"hanzi":"学生","pinyin":"xuéshēng","hanviet":"Học sinh","pos":"Danh từ","meaning":"học sinh, sinh viên","comps":"好学生 (học sinh giỏi), 学生们 (các học sinh)","example":{"zh":"学生们，你们好！","py":"Xuéshēngmen, nǐmen hǎo!","vi":"Các em học sinh, chào các em!"}},{"stt":5,"hanzi":"们","pinyin":"men","hanviet":"Môn","pos":"Trợ từ","meaning":"hậu tố số nhiều (người)","comps":"我们 (chúng tôi), 老师们 (các thầy cô)","example":{"zh":"同学们，再见！","py":"Tóngxuémen, zàijiàn!","vi":"Các em, tạm biệt nhé!"}},{"stt":6,"hanzi":"老师","pinyin":"lǎoshī","hanviet":"Lão sư","pos":"Danh từ","meaning":"thầy giáo, cô giáo","comps":"老师好 (chào thầy cô), 中文老师 (giáo viên tiếng Trung)","example":{"zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","vi":"Thưa thầy, em chào thầy ạ!"}},{"stt":7,"hanzi":"您","pinyin":"nín","hanviet":"Nâm","pos":"Đại từ","meaning":"ngài, ông/bà (kính ngữ)","comps":"您好 (kính chào), 您们 (sai — dùng 大家)","example":{"zh":"王老师，您好！","py":"Wáng lǎoshī, nín hǎo!","vi":"Thưa cô Vương, em chào cô ạ!"}},{"stt":8,"hanzi":"你们","pinyin":"nǐmen","hanviet":"Nễ môn","pos":"Đại từ","meaning":"các bạn, các anh chị","comps":"你们好 (chào các bạn), 谢谢你们 (cảm ơn các bạn)","example":{"zh":"谢谢你们！","py":"Xièxie nǐmen!","vi":"Cảm ơn các bạn!"}},{"stt":9,"hanzi":"谢谢","pinyin":"xièxie","hanviet":"Tạ tạ","pos":"Động từ","meaning":"cảm ơn","comps":"谢谢你 (cảm ơn bạn), 谢谢老师 (cảm ơn thầy cô)","example":{"zh":"谢谢老师！","py":"Xièxie lǎoshī!","vi":"Em cảm ơn thầy ạ!"}},{"stt":10,"hanzi":"不客气","pinyin":"bú kèqi","hanviet":"Bất khách khí","pos":"Cụm từ","meaning":"không có gì, đừng ngại","comps":"不客气 (không có gì), 谢谢——不客气 (cảm ơn — không có gì)","example":{"zh":"不客气，同学们！","py":"Bú kèqi, tóngxuémen!","vi":"Không có gì đâu các em!"}},{"stt":11,"hanzi":"同学","pinyin":"tóngxué","hanviet":"Đồng học","pos":"Danh từ","meaning":"bạn học, bạn cùng lớp","comps":"同学们 (các bạn học), 老同学 (bạn học cũ)","example":{"zh":"同学们好！","py":"Tóngxuémen hǎo!","vi":"Chào các em!"}},{"stt":12,"hanzi":"再见","pinyin":"zàijiàn","hanviet":"Tái kiến","pos":"Động từ","meaning":"tạm biệt, hẹn gặp lại","comps":"老师再见 (tạm biệt thầy cô), 大家再见 (tạm biệt mọi người)","example":{"zh":"老师，再见！","py":"Lǎoshī, zàijiàn!","vi":"Em chào thầy, em về ạ!"}},{"stt":13,"hanzi":"王老师","pinyin":"Wáng lǎoshī","hanviet":"Vương lão sư","pos":"Danh từ riêng","meaning":"cô Vương (cô giáo Vương Nhất Phi)","comps":"王老师好 (em chào cô Vương), 我们的王老师 (cô Vương của chúng em)","example":{"zh":"王老师好！","py":"Wáng lǎoshī hǎo!","vi":"Em chào cô Vương ạ!"}}],"hanzi":[{"char":"你好","pinyin":"nǐ hǎo","hanviet":"Nễ hảo","chars":["你","好"],"story":"你 = bộ Nhân đứng 亻 (người) + 尔 (chỉ âm đọc), nghĩa là \"bạn\". 好 = 女 (phụ nữ) + 子 (đứa con); người xưa cho rằng phụ nữ có con là điều tốt lành. Ghép lại 你好 = \"chúc bạn tốt lành\" — chính là lời chào."},{"char":"王老师","pinyin":"Wáng lǎoshī","hanviet":"Vương lão sư","chars":["王","老","师"],"story":"王 vẽ ba vạch ngang là Trời – Người – Đất, một vạch dọc nối lại: người thông suốt cả ba là vua, sau dùng làm họ. 老 vẽ ông già chống gậy, 师 nghĩa là bậc thầy. 王老师 = \"thầy/cô họ Vương\"."},{"char":"大家","pinyin":"dàjiā","hanviet":"Đại gia","chars":["大","家"],"story":"大 vẽ một người dang rộng hai tay hai chân, nghĩa là \"to lớn\". 家 = bộ Miên 宀 (mái nhà) trùm lên 豕 (con lợn) — nhà nào nuôi được lợn là nhà có của. 大家 = \"cả nhà lớn\", tức mọi người."},{"char":"好","pinyin":"hǎo","hanviet":"Hảo","chars":["好"],"story":"好 = 女 (phụ nữ) + 子 (đứa con). Chữ hội ý: người xưa cho rằng phụ nữ sinh được con là điều tốt đẹp nhất, nên 好 mang nghĩa \"tốt, hay, khoẻ\"."},{"char":"学生","pinyin":"xuéshēng","hanviet":"Học sinh","chars":["学","生"],"story":"学 vẽ hai bàn tay đang bày chữ dưới mái nhà cho đứa trẻ 子 ở dưới, nghĩa là \"học\". 生 vẽ mầm cây nhú lên khỏi mặt đất, nghĩa là \"sinh ra, sống\". 学生 = người đang lớn lên nhờ học."},{"char":"们","pinyin":"men","hanviet":"Môn","chars":["们"],"story":"们 = bộ Nhân đứng 亻 (người) + 门 mén (cái cửa, chỉ âm đọc). Chữ hình thanh điển hình: bộ 亻 cho biết chữ này liên quan tới người, nên 们 chỉ dùng làm hậu tố số nhiều cho người."},{"char":"老师","pinyin":"lǎoshī","hanviet":"Lão sư","chars":["老","师"],"story":"老 vẽ một ông già tóc dài chống gậy, nghĩa là \"già, lâu năm\". 师 vốn chỉ người đứng đầu một đám đông, sau thành \"bậc thầy\". 老师 = người thầy lâu năm, tức thầy giáo, cô giáo."},{"char":"您","pinyin":"nín","hanviet":"Nâm","chars":["您"],"story":"您 = 你 (bạn) đặt trên bộ Tâm 心 (trái tim). Nói chuyện với người trên mà đặt cả tấm lòng vào — đó chính là kính ngữ. Nhìn chữ là nhớ ngay: có trái tim ở dưới thì phải lễ phép."},{"char":"你们","pinyin":"nǐmen","hanviet":"Nễ môn","chars":["你","们"],"story":"你 = 亻 (người) + 尔 (chỉ âm), nghĩa là \"bạn\"; 们 = 亻 + 门 (chỉ âm), là hậu tố số nhiều dành cho người. Ghép lại 你们 = \"các bạn\", tức số nhiều của 你."},{"char":"谢谢","pinyin":"xièxie","hanviet":"Tạ tạ","chars":["谢","谢"],"story":"谢 = bộ Ngôn 讠 (lời nói) + 射 shè (bắn ra, chỉ âm). Lời nói bắn ra từ trong lòng chính là lời cảm tạ. Người Trung Quốc nói lặp hai lần 谢谢 cho thân mật, chữ thứ hai đọc thanh nhẹ."},{"char":"不客气","pinyin":"bú kèqi","hanviet":"Bất khách khí","chars":["不","客","气"],"story":"不 vẽ mầm cây bị chặn không mọc lên được, nghĩa là \"không\". 客 = 宀 (mái nhà) + 各, chỉ người khách. 气 vẽ làn hơi bốc lên. 不客气 = \"đừng làm khách\", tức \"đừng khách sáo, không có gì\"."},{"char":"同学","pinyin":"tóngxué","hanviet":"Đồng học","chars":["同","学"],"story":"同 vẽ một cái khung 冂 trùm lên 一 và 口 — nhiều miệng nói cùng một lời, nghĩa là \"giống nhau, cùng\". 学 là \"học\". 同学 = người cùng học với mình, tức bạn học."},{"char":"再见","pinyin":"zàijiàn","hanviet":"Tái kiến","chars":["再","见"],"story":"再 vốn vẽ hình chồng thêm một lớp nữa, nghĩa là \"lại, lần nữa\". 见 = 目 (con mắt) đặt trên 儿 (đôi chân người), nghĩa là \"nhìn thấy\". 再见 = \"lại gặp nhau nữa\", tức tạm biệt."}],"grammar":[{"title":"Ngữ âm — Bốn thanh điệu (绕口令)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>mā 妈</b><small>thanh 1 — cao đều</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>má 麻</b><small>thanh 2 — lên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>mǎ 马</b><small>thanh 3 — xuống rồi lên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>mà 骂</b><small>thanh 4 — xuống gắt</small></span></div>","summary":"<p class=\"gr-lead\">Bốn thanh điệu</p><ul><li>Tiếng Trung có <b>4 thanh điệu</b>: thanh 1 cao và đều, thanh 2 đi lên như dấu sắc, thanh 3 hạ thật thấp rồi mới nâng lên, thanh 4 rơi xuống dứt khoát như dấu nặng.</li><li>Bài vè <span class=\"zh\">妈种麻，我放马</span> nghĩa là \"Mẹ trồng gai, tôi thả ngựa\" — bốn chữ <span class=\"zh\">妈 · 麻 · 马 · 骂</span> đọc <b>cùng âm ma</b>, chỉ khác nhau ở thanh.</li><li>Hai chữ thanh 3 đứng liền nhau thì chữ trước <b>biến thành thanh 2</b>: <span class=\"zh\">你好</span> viết là nǐ hǎo nhưng đọc thành <b>ní hǎo</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">妈种麻，我放马　·　马吃麻，妈骂马</span></p>","note":"<b>Lưu ý:</b> Thanh 3 <b>không phải</b> dấu hỏi tiếng Việt: phải kéo giọng xuống thật thấp rồi mới nâng lên, đừng ngắt ngang ở giữa.","examples":[{"zh":"妈种麻，我放马。","py":"Mā zhòng má, wǒ fàng mǎ.","vi":"Mẹ trồng cây gai, tôi thả ngựa."}],"exercises":[]},{"title":"Mẫu câu chào hỏi \"……好！\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>称呼 / 人称代词</b><small>người được chào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>好！</b><small>chào</small></span></div>","summary":"<p class=\"gr-lead\">Cách chào hỏi</p><ul><li>Ghép <b>người được chào</b> với chữ <span class=\"zh\">好</span> là thành lời chào: <span class=\"zh\">你好</span>, <span class=\"zh\">你们好</span>, <span class=\"zh\">大家好</span>, <span class=\"zh\">老师好</span>.</li><li><span class=\"zh\">您</span> là dạng <b>lịch sự</b> của <span class=\"zh\">你</span>, dùng với thầy cô, người lớn tuổi và khách — nhìn bộ Tâm 心 ở dưới là nhớ ngay.</li><li>Người kia chào thế nào thì mình <b>đáp lại y như vậy</b>: <span class=\"zh\">你好！——你好！</span>　<span class=\"zh\">老师好！——同学们好！</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你好！　·　您好！　·　大家好！　·　老师好！</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">您</span> <b>không có dạng số nhiều</b>: không nói <span class=\"zh\">您们</span>. Muốn chào lễ phép nhiều người thì dùng <span class=\"zh\">大家好</span>.","examples":[{"zh":"王老师，您好！","py":"Wáng lǎoshī, nín hǎo!","vi":"Thưa cô Vương, em chào cô ạ!"}],"exercises":[]},{"title":"Hậu tố số nhiều \"们\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>指人名词 / 代词</b><small>từ chỉ người</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>们</b><small>số nhiều</small></span></div>","summary":"<p class=\"gr-lead\">Số nhiều người</p><ul><li><span class=\"zh\">们</span> chỉ gắn sau <b>từ chỉ người</b>: <span class=\"zh\">你们</span>, <span class=\"zh\">学生们</span>, <span class=\"zh\">同学们</span>, <span class=\"zh\">老师们</span>.</li><li>Chữ <span class=\"zh\">们</span> đọc <b>thanh nhẹ</b> (men), không đánh dấu thanh; <span class=\"zh\">学生们</span> đọc là xuéshēngmen.</li><li>Thầy cô gọi cả lớp thì dùng <span class=\"zh\">同学们</span>, học sinh gọi nhau cũng dùng được — đây là cách xưng hô quen thuộc nhất trong lớp.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你 → 你们　·　学生 → 学生们　·　同学 → 同学们</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">们</span> <b>không dùng cho đồ vật</b>: không nói <span class=\"zh\">书们</span>. Tiếng Trung không đánh dấu số nhiều cho vật như tiếng Anh.","examples":[{"zh":"同学们，再见！","py":"Tóngxuémen, zàijiàn!","vi":"Các em, tạm biệt nhé!"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Cô Vương chào trợ lý AI Tiểu Ngữ","lines":[{"speaker":"王","name":"Cô Vương","zh":"AI小语，你好！","py":"AI Xiǎoyǔ, nǐ hǎo!","vi":"AI Tiểu Ngữ, chào em!"},{"speaker":"语","name":"Tiểu Ngữ","zh":"王老师，你好！","py":"Wáng lǎoshī, nǐ hǎo!","vi":"Cô Vương, em chào cô ạ!"}]},{"titleZh":"课文二","titleVi":"Buổi đầu — cô Vương chào cả lớp","lines":[{"speaker":"王","name":"Cô Vương","zh":"大家好！","py":"Dàjiā hǎo!","vi":"Chào cả lớp!"},{"speaker":"生","name":"Các học sinh","zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","vi":"Chúng em chào cô ạ!"},{"speaker":"语","name":"Tiểu Ngữ","zh":"你们好！","py":"Nǐmen hǎo!","vi":"Chào các bạn!"},{"speaker":"生","name":"Các học sinh","zh":"你好，小语！","py":"Nǐ hǎo, Xiǎoyǔ!","vi":"Chào bạn, Tiểu Ngữ!"}]},{"titleZh":"课文三","titleVi":"Cuối buổi học — cảm ơn, tạm biệt","lines":[{"speaker":"生","name":"Các học sinh","zh":"谢谢！","py":"Xièxie!","vi":"Chúng em cảm ơn ạ!"},{"speaker":"语","name":"Tiểu Ngữ","zh":"不客气！","py":"Bú kèqi!","vi":"Không có gì đâu!"},{"speaker":"王","name":"Cô Vương","zh":"同学们，再见！","py":"Tóngxuémen, zàijiàn!","vi":"Các em, tạm biệt nhé!"},{"speaker":"生","name":"Các học sinh","zh":"老师，再见！","py":"Lǎoshī, zàijiàn!","vi":"Chúng em chào cô ạ!"}]}]},"extra":[]},{"id":"k1v3-b02","courseId":"k1v3","order":2,"title":"Tôi tên là Lý Văn","titleZh":"我叫李文","titlePy":"wǒ jiào Lǐ Wén","vocab":[{"stt":1,"hanzi":"请问","pinyin":"qǐngwèn","hanviet":"Thỉnh vấn","pos":"Động từ","meaning":"xin hỏi, cho hỏi","comps":"请问 (xin hỏi), 请 (mời, xin)","example":{"zh":"请问，你叫什么名字？","py":"Qǐngwèn, nǐ jiào shénme míngzi?","vi":"Cho hỏi, bạn tên là gì?"}},{"stt":2,"hanzi":"你","pinyin":"nǐ","hanviet":"Nễ","pos":"Đại từ","meaning":"bạn, cậu, anh/chị","comps":"你好 (chào bạn), 你们 (các bạn)","example":{"zh":"很高兴认识你。","py":"Hěn gāoxìng rènshi nǐ.","vi":"Rất vui được quen bạn."}},{"stt":3,"hanzi":"叫","pinyin":"jiào","hanviet":"Khiếu","pos":"Động từ","meaning":"gọi, kêu; tên là","comps":"叫什么 (tên là gì), 我叫 (tôi tên là)","example":{"zh":"我叫李文。","py":"Wǒ jiào Lǐ Wén.","vi":"Tôi tên là Lý Văn."}},{"stt":4,"hanzi":"什么","pinyin":"shénme","hanviet":"Thập ma","pos":"Đại từ nghi vấn","meaning":"gì, cái gì, nào","comps":"什么名字 (tên gì), 为什么 (tại sao)","example":{"zh":"请问，你叫什么？","py":"Qǐngwèn, nǐ jiào shénme?","vi":"Cho hỏi, bạn tên là gì?"}},{"stt":5,"hanzi":"名字","pinyin":"míngzi","hanviet":"Danh tự","pos":"Danh từ","meaning":"tên, tên gọi","comps":"我的名字 (tên của tôi), 起名字 (đặt tên)","example":{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"}},{"stt":6,"hanzi":"我","pinyin":"wǒ","hanviet":"Ngã","pos":"Đại từ","meaning":"tôi, tớ, mình","comps":"我们 (chúng tôi), 我是 (tôi là)","example":{"zh":"我叫白家月。","py":"Wǒ jiào Bái Jiāyuè.","vi":"Mình tên là Bạch Gia Nguyệt."}},{"stt":7,"hanzi":"不","pinyin":"bù","hanviet":"Bất","pos":"Phó từ","meaning":"không (phủ định)","comps":"不是 (không phải), 不客气 (không có gì)","example":{"zh":"我不是陈天中。","py":"Wǒ bú shì Chén Tiānzhōng.","vi":"Mình không phải Trần Thiên Trung."}},{"stt":8,"hanzi":"是","pinyin":"shì","hanviet":"Thị","pos":"Động từ","meaning":"là, chính là","comps":"我是 (tôi là), 不是 (không phải)","example":{"zh":"我是李文。","py":"Wǒ shì Lǐ Wén.","vi":"Tôi là Lý Văn."}},{"stt":9,"hanzi":"对不起","pinyin":"duìbuqǐ","hanviet":"Đối bất khởi","pos":"Động từ","meaning":"xin lỗi, có lỗi","comps":"对不起 (xin lỗi), 对 (đúng)","example":{"zh":"对不起，老师！","py":"Duìbuqǐ, lǎoshī!","vi":"Em xin lỗi thầy ạ!"}},{"stt":10,"hanzi":"没关系","pinyin":"méi guānxi","hanviet":"Một quan hệ","pos":"Cụm từ","meaning":"không sao, không có gì","comps":"没关系 (không sao), 没有 (không có)","example":{"zh":"没关系，不客气！","py":"Méi guānxi, bú kèqi!","vi":"Không sao đâu, không có gì!"}},{"stt":11,"hanzi":"没事","pinyin":"méishì","hanviet":"Một sự","pos":"Động từ","meaning":"không sao, không có gì (khẩu ngữ)","comps":"没事没事 (không sao đâu), 没事儿 (không sao — khẩu ngữ)","example":{"zh":"对不起！——没事没事。","py":"Duìbuqǐ! — Méishì méishì.","vi":"Xin lỗi nhé! — Không sao, không sao."}},{"stt":12,"hanzi":"很","pinyin":"hěn","hanviet":"Ngận","pos":"Phó từ","meaning":"rất","comps":"很好 (rất tốt), 很高兴 (rất vui)","example":{"zh":"我很高兴。","py":"Wǒ hěn gāoxìng.","vi":"Mình rất vui."}},{"stt":13,"hanzi":"高兴","pinyin":"gāoxìng","hanviet":"Cao hứng","pos":"Tính từ","meaning":"vui, vui mừng","comps":"很高兴 (rất vui), 不高兴 (không vui)","example":{"zh":"认识你很高兴。","py":"Rènshi nǐ hěn gāoxìng.","vi":"Quen được bạn mình rất vui."}},{"stt":14,"hanzi":"认识","pinyin":"rènshi","hanviet":"Nhận thức","pos":"Động từ","meaning":"quen, quen biết","comps":"认识你 (quen bạn), 不认识 (không quen)","example":{"zh":"认识你我也很高兴。","py":"Rènshi nǐ wǒ yě hěn gāoxìng.","vi":"Quen được bạn mình cũng rất vui."}},{"stt":15,"hanzi":"也","pinyin":"yě","hanviet":"Dã","pos":"Phó từ","meaning":"cũng","comps":"我也 (tôi cũng), 也是 (cũng là)","example":{"zh":"我也很高兴。","py":"Wǒ yě hěn gāoxìng.","vi":"Mình cũng rất vui."}},{"stt":16,"hanzi":"陈天中","pinyin":"Chén Tiānzhōng","hanviet":"Trần Thiên Trung","pos":"Danh từ riêng","meaning":"Trần Thiên Trung (tên)","comps":"陈 (họ Trần), 天 (trời, ngày)","example":{"zh":"你好，陈天中！","py":"Nǐ hǎo, Chén Tiānzhōng!","vi":"Chào bạn, Trần Thiên Trung!"}},{"stt":17,"hanzi":"白家月","pinyin":"Bái Jiāyuè","hanviet":"Bạch Gia Nguyệt","pos":"Danh từ riêng","meaning":"Bạch Gia Nguyệt (tên)","comps":"白 (họ Bạch, trắng), 家 (nhà)","example":{"zh":"白家月，你好！","py":"Bái Jiāyuè, nǐ hǎo!","vi":"Bạch Gia Nguyệt, chào bạn!"}},{"stt":18,"hanzi":"李文","pinyin":"Lǐ Wén","hanviet":"Lý Văn","pos":"Danh từ riêng","meaning":"Lý Văn (tên người)","comps":"李 (họ Lý), 文 (văn, chữ nghĩa)","example":{"zh":"我是李文，很高兴认识你。","py":"Wǒ shì Lǐ Wén, hěn gāoxìng rènshi nǐ.","vi":"Mình là Lý Văn, rất vui được quen bạn."}}],"hanzi":[{"char":"请问","pinyin":"qǐngwèn","hanviet":"Thỉnh vấn","chars":["请","问"],"story":"请 = bộ Ngôn 讠 (lời nói) + 青 qīng (chỉ âm), nghĩa là \"mời, xin\". 问 = 门 (cái cửa) trùm lên 口 (cái miệng) — đứng ngoài cửa mở miệng hỏi vào. 请问 = \"xin phép được hỏi\", câu mở lời lịch sự nhất."},{"char":"你","pinyin":"nǐ","hanviet":"Nễ","chars":["你"],"story":"你 = bộ Nhân đứng 亻 (người) + 尔 (chỉ âm đọc). Chữ hình thanh: bộ 亻 cho biết đây là một con người, nên 你 nghĩa là \"bạn, cậu\". Thêm bộ Tâm 心 ở dưới thì thành 您 kính ngữ đã học ở bài 1."},{"char":"叫","pinyin":"jiào","hanviet":"Khiếu","chars":["叫"],"story":"叫 = bộ Khẩu 口 (cái miệng) + 丩 jiū (hai sợi dây quấn nhau, chỉ âm). Miệng phát ra tiếng gọi, nên 叫 nghĩa là \"gọi, kêu\"; từ đó có nghĩa quen thuộc \"tên là\"."},{"char":"什么","pinyin":"shénme","hanviet":"Thập ma","chars":["什","么"],"story":"什 = 亻 (người) + 十 (mười) — vốn chỉ một tổ mười người lính. 么 phần dưới là 幺 (sợi tơ nhỏ xíu). Hai chữ ghép lại thành từ để hỏi 什么 \"gì, cái gì\", đọc thanh nhẹ ở chữ sau."},{"char":"名字","pinyin":"míngzi","hanviet":"Danh tự","chars":["名","字"],"story":"名 = 夕 (buổi tối) + 口 (miệng): trời tối không nhìn rõ mặt nên phải xưng tên ra. 字 = 宀 (mái nhà) trùm 子 (đứa con), ý chữ viết sinh sôi trong nhà. 名字 = tên gọi."},{"char":"我","pinyin":"wǒ","hanviet":"Ngã","chars":["我"],"story":"我 vốn vẽ một loại binh khí có răng cưa (phần bên phải chính là 戈 — cây qua). Người xưa mượn hẳn chữ này làm đại từ \"tôi\", nay không còn liên quan gì tới vũ khí nữa."},{"char":"不","pinyin":"bù","hanviet":"Bất","chars":["不"],"story":"不 vẽ mầm cây đâm xuống dưới nhưng vướng phải một vạch chắn nên không mọc lên được — vì thế 不 nghĩa là \"không, chẳng\". Đứng trước động từ và tính từ để phủ định."},{"char":"是","pinyin":"shì","hanviet":"Thị","chars":["是"],"story":"是 = 日 (mặt trời) đặt trên 正 (ngay thẳng, đúng đắn). Lấy mặt trời làm chuẩn thì mọi thứ đều đúng, nên 是 nghĩa gốc là \"đúng, phải\"; ngày nay dùng chủ yếu làm động từ \"là\"."},{"char":"对不起","pinyin":"duìbuqǐ","hanviet":"Đối bất khởi","chars":["对","不","起"],"story":"对 = 又 (bàn tay) + 寸 (tấc), nghĩa \"đúng, đối đáp\". 起 = 走 (bước đi) + 己 (chỉ âm), nghĩa \"đứng dậy\". 对不起 nghĩa đen là \"không ngẩng mặt đối diện với người ta được\" — chính là lời xin lỗi."},{"char":"没关系","pinyin":"méi guānxi","hanviet":"Một quan hệ","chars":["没","关","系"],"story":"没 = 氵 (nước) + 殳, ý chìm mất, nay dùng là \"không có\". 关 là \"đóng, liên quan\", 系 vẽ bàn tay nắm những sợi tơ, nghĩa \"buộc, ràng buộc\". 没关系 = \"chẳng ràng buộc gì cả\" → không sao đâu."},{"char":"没事","pinyin":"méishì","hanviet":"Một sự","chars":["没","事"],"story":"没 = bộ Thuỷ 氵 (nước) + 殳: vốn là \"chìm mất dưới nước\", nên mang nghĩa \"không có\". 事 vẽ bàn tay cầm thẻ ghi việc, nghĩa là \"việc\". 没事 = \"chẳng có việc gì\" → không sao đâu. Trong khẩu ngữ người Trung Quốc hay nói lặp: 没事没事！"},{"char":"陈天中","pinyin":"Chén Tiānzhōng","hanviet":"Trần Thiên Trung","chars":["陈","天","中"],"story":"陈 = 阝 (gò đất) + 东 (phía đông), là một trong những họ lớn của Trung Quốc. 天 vẽ người dang tay 大 với một vạch ngang trên đầu — chính là bầu trời. 中 vẽ mũi tên cắm trúng ngay giữa vòng, nghĩa \"ở giữa\"."},{"char":"白家月","pinyin":"Bái Jiāyuè","hanviet":"Bạch Gia Nguyệt","chars":["白","家","月"],"story":"白 vẽ hạt gạo trắng (có sách nói là tia nắng đầu ngày), nghĩa \"trắng\", đồng thời là một họ. 家 = 宀 (mái nhà) trùm 豕 (con lợn) — nhà nuôi được lợn là nhà có của. 月 vẽ mảnh trăng khuyết."},{"char":"李文","pinyin":"Lǐ Wén","hanviet":"Lý Văn","chars":["李","文"],"story":"李 = 木 (cây) + 子 (quả), vốn chỉ cây mận, sau thành họ phổ biến bậc nhất Trung Quốc. 文 vẽ hình hoa văn thêu trước ngực áo người, nghĩa là \"văn vẻ, chữ nghĩa\"."},{"char":"很","pinyin":"hěn","hanviet":"Ngận","chars":["很"],"story":"很 = bộ Xích 彳 (bước chân trái, chỉ việc đi lại) + 艮 gèn (chỉ âm đọc). Nghĩa gốc là \"cãi lại, ngang bướng\", nay chỉ còn dùng làm phó từ \"rất\" — trước tính từ tiếng Trung gần như luôn có 很."},{"char":"高兴","pinyin":"gāoxìng","hanviet":"Cao hứng","chars":["高","兴"],"story":"高 vẽ một toà lầu cao có mái, có cửa, nghĩa là \"cao\". 兴 vẽ bốn bàn tay cùng nâng một vật lên, nghĩa \"dấy lên, hưng khởi\". 高兴 = lòng dâng cao lên → vui mừng, phấn khởi."},{"char":"认识","pinyin":"rènshi","hanviet":"Nhận thức","chars":["认","识"],"story":"认 = 讠 (lời nói) + 人 (chỉ âm), nghĩa \"nhận ra\". 识 = 讠 + 只 (chỉ âm), nghĩa \"biết\". Cả hai chữ đều mang bộ Ngôn vì muốn biết nhau thì phải nói chuyện với nhau. 识 ở đây đọc thanh nhẹ shi."},{"char":"也","pinyin":"yě","hanviet":"Dã","chars":["也"],"story":"也 vốn vẽ một cái chậu rửa (có sách nói là con rắn), nhưng bị mượn hẳn làm phó từ \"cũng\" và không bao giờ trở lại nghĩa gốc. Đây là chữ giả tá điển hình — cứ nhớ mặt chữ là đủ."}],"grammar":[{"title":"Trật tự cơ bản của câu tiếng Trung","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>谓语</b><small>vị ngữ (động/tính từ)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Chủ + Vị + Tân ngữ</p><ul><li>Trật tự cơ bản của tiếng Trung là <b>Chủ ngữ + Vị ngữ + Tân ngữ</b> — <b>giống hệt tiếng Việt</b>, đây là lợi thế rất lớn của người Việt khi học.</li><li>Câu hỏi <b>giữ nguyên trật tự</b> ấy, chỉ thay đúng chỗ cần hỏi bằng từ để hỏi: <span class=\"zh\">我叫李文</span> → <span class=\"zh\">你叫什么名字？</span></li><li>Phó từ <span class=\"zh\">不</span>, <span class=\"zh\">很</span>, <span class=\"zh\">也</span> luôn đứng <b>ngay trước vị ngữ</b>: <span class=\"zh\">我不是安妮</span>　·　<span class=\"zh\">我也很高兴</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我　叫　李文。</span> = Tôi (chủ ngữ) + tên là (vị ngữ) + Lý Văn (tân ngữ)</p>","note":"<b>Lưu ý:</b> Tính từ làm vị ngữ thì <b>không thêm</b> <span class=\"zh\">是</span>: nói <span class=\"zh\">我很高兴</span>, <b>không nói</b> <span class=\"zh\">我是高兴</span>.","examples":[{"zh":"我叫李文。","py":"Wǒ jiào Lǐ Wén.","vi":"Tôi tên là Lý Văn."},{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"},{"zh":"我叫白家月。","py":"Wǒ jiào Bái Jiāyuè.","vi":"Mình tên là Bạch Gia Nguyệt."},{"zh":"我是学生。","py":"Wǒ shì xuéshēng.","vi":"Mình là học sinh."}],"exercises":[]},{"title":"Ngữ âm — Luyện âm j · q · x (绕口令)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>加 jiā</b><small>cộng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>减 jiǎn</b><small>trừ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>几 jǐ</b><small>mấy</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>七 qī</b><small>bảy</small></span></div>","summary":"<p class=\"gr-lead\">Luyện âm j, q, x</p><ul><li>Cả bài vè là một bài toán vui: <b>7 + 1 − 1 = mấy?</b> — cộng xong trừ xong thì <b>vẫn là 7</b>.</li><li>Ba phụ âm <b>j · q · x</b> đều đặt <b>đầu lưỡi sát chân răng dưới</b>, hai môi <b>kéo dẹt</b> như đang cười: <span class=\"zh\">加 jiā</span>　·　<span class=\"zh\">七 qī</span>.</li><li><span class=\"zh\">q</span> <b>bật hơi mạnh</b>, <span class=\"zh\">j</span> <b>không bật hơi</b> — đọc liền <span class=\"zh\">七 qī</span> rồi <span class=\"zh\">几 jǐ</span> sẽ thấy ngay khác biệt.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">七加一，再减一，加完减完等于几？加完减完还是七。</span></p>","note":"<b>Lưu ý:</b> Người Việt hay đọc <span class=\"zh\">j q x</span> thành \"gi · ch · x\" tiếng Việt hoặc lẫn sang <span class=\"zh\">zh ch sh</span>. Phải <b>dẹt môi và đưa lưỡi ra trước</b>.","examples":[{"zh":"七加一，再减一。","py":"Qī jiā yī, zài jiǎn yī.","vi":"Bảy cộng một, rồi trừ một."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Cô Vương hỏi tên học sinh mới","lines":[{"speaker":"王","name":"Cô Vương","zh":"请问，你叫什么名字？","py":"Qǐngwèn, nǐ jiào shénme míngzi?","vi":"Cho cô hỏi, em tên là gì?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"我叫陈天中。","py":"Wǒ jiào Chén Tiānzhōng.","vi":"Em tên là Trần Thiên Trung ạ."}]},{"titleZh":"课文二","titleVi":"Nhận nhầm người rồi xin lỗi nhau","lines":[{"speaker":"中","name":"Trần Thiên Trung","zh":"你好，安妮！","py":"Nǐ hǎo, Ānnī!","vi":"Chào bạn, Annie!"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"你好，陈天中！我不是安妮，我是白家月。","py":"Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","vi":"Chào bạn, Trần Thiên Trung! Mình không phải Annie, mình là Bạch Gia Nguyệt."},{"speaker":"中","name":"Trần Thiên Trung","zh":"对不起！","py":"Duìbuqǐ!","vi":"Xin lỗi bạn nhé!"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"没关系！","py":"Méi guānxi!","vi":"Không sao đâu!"}]},{"titleZh":"课文三","titleVi":"Hai bạn mới làm quen với nhau","lines":[{"speaker":"文","name":"Lý Văn","zh":"你好！我叫李文。","py":"Nǐ hǎo! Wǒ jiào Lǐ Wén.","vi":"Chào bạn! Mình tên là Lý Văn."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"你好！我叫白家月。","py":"Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","vi":"Chào bạn! Mình tên là Bạch Gia Nguyệt."},{"speaker":"文","name":"Lý Văn","zh":"很高兴认识你。","py":"Hěn gāoxìng rènshi nǐ.","vi":"Rất vui được quen bạn."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"认识你我也很高兴。","py":"Rènshi nǐ wǒ yě hěn gāoxìng.","vi":"Quen được bạn mình cũng rất vui."}]}]},"extra":[]},{"id":"k1v3-b03","courseId":"k1v3","order":3,"title":"Tôi là người Trung Quốc","titleZh":"我是中国人","titlePy":"wǒ shì Zhōngguó rén","vocab":[{"stt":1,"hanzi":"人","pinyin":"rén","hanviet":"Nhân","pos":"Danh từ","meaning":"người","comps":"中国人 (người Trung Quốc), 女人 (phụ nữ)","example":{"zh":"她是泰国人。","py":"Tā shì Tàiguó rén.","vi":"Cô ấy là người Thái Lan."}},{"stt":2,"hanzi":"的","pinyin":"de","hanviet":"Đích","pos":"Trợ từ","meaning":"của (trợ từ kết cấu)","comps":"我的 (của tôi), 谁的 (của ai)","example":{"zh":"这是我的老师。","py":"Zhè shì wǒ de lǎoshī.","vi":"Đây là thầy giáo của tôi."}},{"stt":3,"hanzi":"这","pinyin":"zhè","hanviet":"Giá","pos":"Đại từ","meaning":"này, đây, cái này","comps":"这是 (đây là), 这个 (cái này)","example":{"zh":"这是我女朋友。","py":"Zhè shì wǒ nǚpéngyou.","vi":"Đây là bạn gái mình."}},{"stt":4,"hanzi":"谁","pinyin":"shéi","hanviet":"Thuỳ","pos":"Đại từ nghi vấn","meaning":"ai","comps":"是谁 (là ai), 谁的 (của ai)","example":{"zh":"这是谁？","py":"Zhè shì shéi?","vi":"Đây là ai vậy?"}},{"stt":5,"hanzi":"女朋友","pinyin":"nǚpéngyou","hanviet":"Nữ Bằng Hữu","pos":"Danh từ","meaning":"bạn gái","comps":"我女朋友 (bạn gái tôi), 朋友 (bạn bè)","example":{"zh":"你女朋友是哪国人？","py":"Nǐ nǚpéngyou shì nǎ guó rén?","vi":"Bạn gái cậu là người nước nào?"}},{"stt":6,"hanzi":"哪","pinyin":"nǎ","hanviet":"Na","pos":"Đại từ nghi vấn","meaning":"nào, cái nào","comps":"哪国 (nước nào), 哪个 (cái nào)","example":{"zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"}},{"stt":7,"hanzi":"国","pinyin":"guó","hanviet":"Quốc","pos":"Danh từ","meaning":"nước, quốc gia","comps":"国人 (người nước…), 中国 (Trung Quốc)","example":{"zh":"泰国也很好。","py":"Tàiguó yě hěn hǎo.","vi":"Thái Lan cũng rất đẹp."}},{"stt":8,"hanzi":"她","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"cô ấy, chị ấy, bà ấy","comps":"她是 (cô ấy là), 她们 (các cô ấy)","example":{"zh":"她是我姐姐。","py":"Tā shì wǒ jiějie.","vi":"Cô ấy là chị gái mình."}},{"stt":9,"hanzi":"喂","pinyin":"wèi","hanviet":"Uy","pos":"Thán từ","meaning":"a lô; này! (gọi ai đó)","comps":"喂，你好 (a lô, chào bạn), 喂 (này!)","example":{"zh":"喂，你好！","py":"Wèi, nǐ hǎo!","vi":"A lô, chào bạn!"}},{"stt":10,"hanzi":"姐姐","pinyin":"jiějie","hanviet":"Tỷ Tỷ","pos":"Danh từ","meaning":"chị gái","comps":"我姐姐 (chị gái tôi), 姐姐们 (các chị)","example":{"zh":"姐姐，你还忙吗？","py":"Jiějie, nǐ hái máng ma?","vi":"Chị ơi, chị vẫn bận à?"}},{"stt":11,"hanzi":"工作","pinyin":"gōngzuò","hanviet":"Công Tác","pos":"Danh từ","meaning":"công việc","comps":"工作很忙 (công việc rất bận), 工作人 (người làm việc)","example":{"zh":"你工作忙吗？","py":"Nǐ gōngzuò máng ma?","vi":"Công việc của bạn có bận không?"}},{"stt":12,"hanzi":"还","pinyin":"hái","hanviet":"Hoàn","pos":"Phó từ","meaning":"vẫn, còn","comps":"还很忙 (vẫn rất bận), 还是 (vẫn là)","example":{"zh":"我还很忙。","py":"Wǒ hái hěn máng.","vi":"Mình vẫn rất bận."}},{"stt":13,"hanzi":"忙","pinyin":"máng","hanviet":"Mang","pos":"Tính từ","meaning":"bận, bận rộn","comps":"很忙 (rất bận), 不忙 (không bận)","example":{"zh":"老师工作很忙。","py":"Lǎoshī gōngzuò hěn máng.","vi":"Công việc của thầy rất bận."}},{"stt":14,"hanzi":"吗","pinyin":"ma","hanviet":"Ma","pos":"Trợ từ","meaning":"trợ từ hỏi (…không?)","comps":"…吗？ (…không?), 好吗 (được không)","example":{"zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","vi":"Bạn là người Trung Quốc phải không?"}},{"stt":15,"hanzi":"对","pinyin":"duì","hanviet":"Đối","pos":"Tính từ","meaning":"đúng, phải","comps":"对 (đúng vậy), 不对 (không đúng)","example":{"zh":"对，我是法国人。","py":"Duì, wǒ shì Fǎguó rén.","vi":"Đúng, mình là người Pháp."}},{"stt":16,"hanzi":"太","pinyin":"tài","hanviet":"Thái","pos":"Phó từ","meaning":"quá, lắm","comps":"太忙 (quá bận), 不太 (không lắm)","example":{"zh":"我不太忙。","py":"Wǒ bú tài máng.","vi":"Mình không bận lắm."}},{"stt":17,"hanzi":"我们","pinyin":"wǒmen","hanviet":"Ngã Môn","pos":"Đại từ","meaning":"chúng tôi, chúng ta","comps":"我们的 (của chúng tôi), 我们是 (chúng tôi là)","example":{"zh":"我们很想你。","py":"Wǒmen hěn xiǎng nǐ.","vi":"Chúng tôi rất nhớ cậu."}},{"stt":18,"hanzi":"想","pinyin":"xiǎng","hanviet":"Tưởng","pos":"Động từ","meaning":"nhớ (nhớ ai đó)","comps":"想你 (nhớ bạn), 想想 (nghĩ một chút)","example":{"zh":"我也想你们。","py":"Wǒ yě xiǎng nǐmen.","vi":"Em cũng nhớ mọi người."}},{"stt":19,"hanzi":"中国","pinyin":"Zhōngguó","hanviet":"Trung Quốc","pos":"Danh từ riêng","meaning":"Trung Quốc","comps":"中国人 (người Trung Quốc), 中国老师 (giáo viên Trung Quốc)","example":{"zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Tôi là người Trung Quốc."}},{"stt":20,"hanzi":"法国","pinyin":"Fǎguó","hanviet":"Pháp Quốc","pos":"Danh từ riêng","meaning":"nước Pháp","comps":"法国人 (người Pháp), 去法国 (đi Pháp)","example":{"zh":"我的老师是法国人。","py":"Wǒ de lǎoshī shì Fǎguó rén.","vi":"Thầy giáo của tôi là người Pháp."}},{"stt":21,"hanzi":"中文","pinyin":"Zhōngwén","hanviet":"Trung Văn","pos":"Danh từ riêng","meaning":"tiếng Trung, Trung văn","comps":"中文老师 (giáo viên tiếng Trung), 学中文 (học tiếng Trung)","example":{"zh":"我的中文老师很忙。","py":"Wǒ de Zhōngwén lǎoshī hěn máng.","vi":"Cô giáo tiếng Trung của tôi rất bận."}},{"stt":22,"hanzi":"泰国","pinyin":"Tàiguó","hanviet":"Thái Quốc","pos":"Danh từ riêng","meaning":"Thái Lan","comps":"泰国人 (người Thái Lan), 去泰国 (đi Thái Lan)","example":{"zh":"我女朋友是泰国人。","py":"Wǒ nǚpéngyou shì Tàiguó rén.","vi":"Bạn gái mình là người Thái Lan."}}],"hanzi":[{"char":"人","pinyin":"rén","hanviet":"Nhân","chars":["人"],"story":"人 vẽ dáng một người đứng nhìn nghiêng, hai chân bước ra hai bên. Đây là chữ tượng hình đơn giản nhất, chỉ hai nét, và là bộ thủ rất hay gặp — viết gọn lại thành 亻 như trong 你, 们, 作."},{"char":"的","pinyin":"de","hanviet":"Đích","chars":["的"],"story":"的 = 白 (trắng, sáng rõ) + 勺 (cái muôi, chỉ âm). Nghĩa gốc là cái đích ngắm sáng rõ (còn giữ trong 目的 mùdì). Nay chủ yếu dùng làm trợ từ kết cấu, đọc thanh nhẹ de."},{"char":"中国","pinyin":"Zhōngguó","hanviet":"Trung Quốc","chars":["中","国"],"story":"中 vẽ mũi tên cắm trúng ngay giữa vòng tròn, nghĩa \"ở giữa\". 国 = 囗 (vòng biên giới) bao lấy 玉 (viên ngọc quý) — trong biên giới có báu vật cần giữ. 中国 = \"nước ở chính giữa\"."},{"char":"法国","pinyin":"Fǎguó","hanviet":"Pháp Quốc","chars":["法","国"],"story":"法 = 氵 (nước) + 去 (đi) — luật lệ phải công bằng phẳng phiu như mặt nước, nên 法 nghĩa là \"phép, luật\". Ở đây 法 chỉ mượn âm để phiên chữ \"Fran-\" của France. 法国 = nước Pháp."},{"char":"中文","pinyin":"Zhōngwén","hanviet":"Trung Văn","chars":["中","文"],"story":"中 là \"ở giữa\", ở đây thay cho 中国. 文 vẽ hình hoa văn thêu trước ngực áo người, nghĩa \"văn vẻ, chữ nghĩa\". 中文 = chữ nghĩa và tiếng nói của Trung Quốc."},{"char":"这","pinyin":"zhè","hanviet":"Giá","chars":["这"],"story":"这 = bộ Sước 辶 (bước chân đi) + 文. Nghĩa là \"này, cái này\" — cái ở ngay trước mặt, chỉ bước một bước là tới. Nhớ cặp đôi: 这 (gần) ↔ 那 (xa)."},{"char":"谁","pinyin":"shéi","hanviet":"Thuỳ","chars":["谁"],"story":"谁 = bộ Ngôn 讠 (lời nói) + 隹 zhuī (con chim đuôi ngắn, chỉ âm). Dùng lời nói để hỏi cho ra người nào → \"ai\". Khẩu ngữ đọc shéi, văn viết đọc shuí, cùng một chữ."},{"char":"女朋友","pinyin":"nǚpéngyou","hanviet":"Nữ Bằng Hữu","chars":["女","朋","友"],"story":"女 vẽ người phụ nữ ngồi khoanh tay. 朋 vốn vẽ hai xâu vỏ sò cùng loại treo cạnh nhau = cùng nhóm. 友 vẽ hai bàn tay nắm lấy nhau = bè bạn. 女朋友 = người bạn nữ thân thiết, tức bạn gái."},{"char":"哪","pinyin":"nǎ","hanviet":"Na","chars":["哪"],"story":"哪 = bộ Khẩu 口 (miệng) + 那 (chỉ âm nà). Rất dễ nhớ: 那 là \"kia\" (khẳng định), thêm cái miệng vào hỏi thì thành 哪 \"nào\". Chú ý thanh điệu khác nhau: nà ↔ nǎ."},{"char":"国","pinyin":"guó","hanviet":"Quốc","chars":["国"],"story":"国 = 囗 (vòng vây khép kín, chính là biên giới) bao lấy 玉 (viên ngọc quý). Trong biên giới có báu vật cần bảo vệ — đó chính là một quốc gia. Chữ phồn thể 國 bên trong có cả cây giáo 戈."},{"char":"她","pinyin":"tā","hanviet":"Tha","chars":["她"],"story":"她 = 女 (phụ nữ) + 也 (chỉ âm). Chữ này mới có khoảng một trăm năm, do người ta tách từ 他 ra để phân biệt nam nữ khi dịch sách phương Tây. Hai chữ đọc y hệt nhau: tā."},{"char":"泰国","pinyin":"Tàiguó","hanviet":"Thái Quốc","chars":["泰","国"],"story":"泰 phần dưới chính là 水 (nước) viết biến thể, nghĩa \"yên ổn, thái bình\" (như trong 泰山). Ở đây mượn âm để phiên chữ \"Thai\". 泰国 = nước Thái Lan."},{"char":"喂","pinyin":"wèi","hanviet":"Uy","chars":["喂"],"story":"喂 = bộ Khẩu 口 (miệng) + 畏 wèi (sợ hãi, chỉ âm) — tiếng gọi bật ra từ miệng. Lưu ý: nghe điện thoại thường đọc thanh 2 (wéi) cho nhẹ nhàng, còn gọi to ai đó thì đọc thanh 4 (wèi)."},{"char":"姐姐","pinyin":"jiějie","hanviet":"Tỷ Tỷ","chars":["姐","姐"],"story":"姐 = 女 (phụ nữ) + 且 qiě (chỉ âm). Người phụ nữ sinh ra trước mình trong nhà chính là chị gái. Người Trung Quốc nói lặp hai lần cho thân mật, chữ thứ hai đọc thanh nhẹ jie."},{"char":"工作","pinyin":"gōngzuò","hanviet":"Công Tác","chars":["工","作"],"story":"工 vẽ cái thước hoặc cái đục của người thợ, nghĩa \"thợ, việc làm\". 作 = 亻 (người) + 乍 (chỉ âm), nghĩa \"làm ra, tạo ra\". 工作 = làm việc, cũng dùng làm danh từ \"công việc\"."},{"char":"还","pinyin":"hái","hanviet":"Hoàn","chars":["还"],"story":"还 = bộ Sước 辶 (bước đi) + 不 (chỉ âm). Chữ này có hai âm: đọc huán nghĩa là \"trả lại, trở về\"; đọc hái làm phó từ \"vẫn, còn\". Bài này dùng âm hái."},{"char":"忙","pinyin":"máng","hanviet":"Mang","chars":["忙"],"story":"忙 = bộ Tâm đứng 忄 (trái tim) + 亡 wáng (mất đi, chỉ âm). Bận rộn tới mức như đánh mất cả trái tim mình — hình ảnh rất đúng với người đi làm."},{"char":"吗","pinyin":"ma","hanviet":"Ma","chars":["吗"],"story":"吗 = bộ Khẩu 口 (miệng) + 马 mǎ (con ngựa, chỉ âm). Chữ hình thanh điển hình: bộ 口 cho biết đây là tiếng phát ra ở cuối câu. Làm trợ từ nghi vấn thì đọc thanh nhẹ ma."},{"char":"对","pinyin":"duì","hanviet":"Đối","chars":["对"],"story":"对 = 又 (bàn tay) + 寸 (tấc, đơn vị đo). Tay cầm thước đo cho khớp vào nhau → \"đúng, chuẩn, đối đáp\". Chữ này đã gặp trong 对不起 ở bài 2."},{"char":"太","pinyin":"tài","hanviet":"Thái","chars":["太"],"story":"太 chính là chữ 大 (to lớn) thêm một dấu chấm ở dưới — to đến mức vượt quá cả mức bình thường. Vì thế 太 nghĩa là \"quá, lắm\", thường đi với 了 thành 太……了."},{"char":"我们","pinyin":"wǒmen","hanviet":"Ngã Môn","chars":["我","们"],"story":"我 vốn vẽ một loại binh khí có răng cưa (phần phải là 戈 cây qua), được mượn hẳn làm đại từ \"tôi\". 们 = 亻 (người) + 门 (chỉ âm), hậu tố số nhiều đã học ở bài 1. 我们 = chúng tôi."},{"char":"想","pinyin":"xiǎng","hanviet":"Tưởng","chars":["想"],"story":"想 = 相 xiāng (nhìn ngắm nhau, chỉ âm) đặt trên 心 (trái tim). Chuyện cứ để trong tim mà ngắm nghía mãi — đó là \"nhớ, nghĩ tới, muốn\"."}],"grammar":[{"title":"Câu chữ 是 (\"是\"字句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>是</b><small>là</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>tân ngữ (danh từ)</small></span></div>","summary":"<p class=\"gr-lead\">A 是 B — \"A là B\"</p><ul><li><span class=\"zh\">是</span> nối <b>hai danh từ</b> với nhau: <span class=\"zh\">我是中国人</span> = \"Tôi là người Trung Quốc\".</li><li>Phủ định đặt <span class=\"zh\">不</span> <b>ngay trước</b> <span class=\"zh\">是</span>, đọc biến điệu thành <b>bú shì</b>: <span class=\"zh\">我不是法国人</span>.</li><li>Thêm <span class=\"zh\">吗</span> ở cuối là thành câu hỏi; trả lời bằng <span class=\"zh\">对</span> hoặc <span class=\"zh\">不是</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我是中国人。</span>　·　<span class=\"zh\">我不是法国人。</span></p>","note":"<b>Lưu ý:</b> Trước <b>tính từ</b> thì <b>không dùng</b> <span class=\"zh\">是</span> mà dùng <span class=\"zh\">很</span>: nói <span class=\"zh\">我很忙</span>, <b>không nói</b> <span class=\"zh\">我是忙</span>.","examples":[{"zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Tôi là người Trung Quốc."},{"zh":"我是法国人。","py":"Wǒ shì Fǎguó rén.","vi":"Tôi là người Pháp."},{"zh":"她是中文老师。","py":"Tā shì Zhōngwén lǎoshī.","vi":"Cô ấy là giáo viên tiếng Trung."},{"zh":"我老师不是法国人。","py":"Wǒ lǎoshī bú shì Fǎguó rén.","vi":"Cô giáo của tôi không phải người Pháp."}],"exercises":[]},{"title":"Trợ từ kết cấu \"的\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>定语</b><small>người/vật sở hữu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>của</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>中心语</b><small>danh từ chính</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ sở hữu \"của\"</p><ul><li><span class=\"zh\">的</span> đứng <b>giữa</b> người sở hữu và thứ được sở hữu: <span class=\"zh\">我的名字</span>　·　<span class=\"zh\">老师的女朋友</span>.</li><li>Trật tự <b>ngược với tiếng Việt</b>: ta nói \"tên <b>của tôi</b>\", tiếng Trung nói <span class=\"zh\">我的名字</span> — phần sở hữu đứng <b>trước</b>.</li><li>Quan hệ <b>thân thiết</b> (người nhà, bạn bè) thường <b>lược bỏ</b> <span class=\"zh\">的</span>: <span class=\"zh\">我姐姐</span>　·　<span class=\"zh\">我女朋友</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我的中文老师</span> = giáo viên tiếng Trung <b>của tôi</b></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">的</span> ở đây đọc <b>thanh nhẹ</b> (de), không đọc thành dì như trong <span class=\"zh\">目的</span>.","examples":[{"zh":"我的中文老师是中国人。","py":"Wǒ de Zhōngwén lǎoshī shì Zhōngguó rén.","vi":"Giáo viên tiếng Trung của tôi là người Trung Quốc."},{"zh":"白家月的中文老师","py":"Bái Jiāyuè de Zhōngwén lǎoshī","vi":"giáo viên tiếng Trung của Bạch Gia Nguyệt"},{"zh":"你的名字","py":"nǐ de míngzi","vi":"tên của bạn"},{"zh":"我老师","py":"wǒ lǎoshī","vi":"cô giáo của tôi (lược 的)"},{"zh":"我学生","py":"wǒ xuéshēng","vi":"học sinh của tôi (lược 的)"},{"zh":"你同学","py":"nǐ tóngxué","vi":"bạn học của bạn (lược 的)"},{"zh":"我妈妈","py":"wǒ māma","vi":"mẹ tôi (lược 的)"}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">这是我____。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">老师，您好！</span></span></span><span class=\"qz-hint\">Đây là cô giáo của mình. — Em chào cô ạ!</span>","answer":["老师","的老师"],"explain":"这是我老师。 (Zhè shì wǒ lǎoshī.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">李文</span><span class=\"zh\">请问，你{{0}}叫什么名字？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">白家月</span><span class=\"zh\">我{{1}}叫王一飞。</span></span></span><span class=\"qz-hint\">Cho mình hỏi, cô giáo của bạn tên là gì? — Cô giáo của mình tên là Vương Nhất Phi.</span>","blanks":[["老师","的老师"],["老师","的老师"]],"explain":"请问，你老师叫什么名字？ (Qǐngwèn, nǐ lǎoshī jiào shénme míngzi?) · 我老师叫王一飞。 (Wǒ lǎoshī jiào Wáng Yīfēi.)"}]},{"title":"Câu hỏi đúng–sai với \"吗\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>陈述句</b><small>câu trần thuật</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b><small>trợ từ nghi vấn</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi \"… không?\"</p><ul><li>Chỉ cần thêm <span class=\"zh\">吗</span> vào <b>cuối câu trần thuật</b>, <b>không đảo</b> trật tự gì cả: <span class=\"zh\">你很忙</span> → <span class=\"zh\">你很忙吗？</span></li><li>Trả lời <b>khẳng định</b> bằng <span class=\"zh\">对</span> hoặc nhắc lại vị ngữ; <b>phủ định</b> bằng <span class=\"zh\">不</span> + vị ngữ.</li><li><span class=\"zh\">吗</span> đọc <b>thanh nhẹ</b> và ngắn (ma), không kéo dài, không lên giọng như tiếng Việt.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">你工作还忙吗？</span> —— <span class=\"zh\">对，还很忙。</span></p>","note":"<b>Lưu ý:</b> Câu <b>đã có từ để hỏi</b> (<span class=\"zh\">谁</span>, <span class=\"zh\">哪</span>, <span class=\"zh\">什么</span>) thì <b>không thêm</b> <span class=\"zh\">吗</span>: nói <span class=\"zh\">这是谁？</span>, không nói <span class=\"zh\">这是谁吗？</span>","examples":[{"zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","vi":"Bạn là người Trung Quốc phải không?"},{"zh":"你也很忙吗？","py":"Nǐ yě hěn máng ma?","vi":"Bạn cũng bận lắm à?"},{"zh":"你是他的中文老师吗？","py":"Nǐ shì tā de Zhōngwén lǎoshī ma?","vi":"Bạn là giáo viên tiếng Trung của anh ấy à?"},{"zh":"你有姐姐吗？","py":"Nǐ yǒu jiějie ma?","vi":"Bạn có chị gái không?"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai bạn nói về quốc tịch","lines":[{"speaker":"文","name":"Lý Văn","zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Mình là người Trung Quốc."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我是法国人。我的中文老师也是中国人。","py":"Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","vi":"Mình là người Pháp. Cô giáo tiếng Trung của mình cũng là người Trung Quốc."}]},{"titleZh":"课文二","titleVi":"Xem ảnh — hỏi về bạn gái của bạn","lines":[{"speaker":"妮","name":"Annie","zh":"这是谁？","py":"Zhè shì shéi?","vi":"Đây là ai vậy?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"这是我女朋友。","py":"Zhè shì wǒ nǚpéngyou.","vi":"Đây là bạn gái mình."},{"speaker":"妮","name":"Annie","zh":"你女朋友是哪国人？","py":"Nǐ nǚpéngyou shì nǎ guó rén?","vi":"Bạn gái cậu là người nước nào?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"她也是泰国人。","py":"Tā yě shì Tàiguó rén.","vi":"Cô ấy cũng là người Thái Lan."}]},{"titleZh":"课文三","titleVi":"Chị gọi điện hỏi thăm em gái","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"喂，一飞！","py":"Wèi, Yīfēi!","vi":"A lô, Nhất Phi à!"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"姐姐！","py":"Jiějie!","vi":"Chị ơi!"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你工作还忙吗？","py":"Nǐ gōngzuò hái máng ma?","vi":"Công việc của em vẫn bận à?"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"对，还很忙。你也很忙吗？","py":"Duì, hái hěn máng. Nǐ yě hěn máng ma?","vi":"Vâng, vẫn bận lắm. Chị cũng bận lắm à?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我不太忙。我们很想你。","py":"Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","vi":"Chị không bận lắm. Cả nhà rất nhớ em."},{"speaker":"飞","name":"Vương Nhất Phi","zh":"我也想你们。","py":"Wǒ yě xiǎng nǐmen.","vi":"Em cũng nhớ mọi người."}]}]},"extra":[],"activity":{"act":[{"zh":"多人活动","py":"duōrén huódòng","tag":"Hoạt động nhóm","mean":"Nhóm 3–4 người · Giới thiệu nhau","q":{"zh":"3~4人一组，互相介绍，然后请一组同学展示。","py":"Sān dào sì rén yì zǔ, hùxiāng jièshào, ránhòu qǐng yì zǔ tóngxué zhǎnshì.","vi":"Nhóm 3–4 người tự giới thiệu và giới thiệu nhau, sau đó một nhóm trình bày trước lớp."},"items":[{"zh":"我叫白家月，我是法国人。","py":"Wǒ jiào Bái Jiāyuè, wǒ shì Fǎguó rén.","vi":"Mình tên là Bạch Gia Nguyệt, mình là người Pháp."},{"zh":"陈天中是我同学，他是泰国人。","py":"Chén Tiānzhōng shì wǒ tóngxué, tā shì Tàiguó rén.","vi":"Trần Thiên Trung là bạn học của mình, bạn ấy là người Thái Lan."},{"zh":"这是我的中文老师，她叫王一飞。","py":"Zhè shì wǒ de Zhōngwén lǎoshī, tā jiào Wáng Yīfēi.","vi":"Đây là cô giáo tiếng Trung của mình, cô ấy tên là Vương Nhất Phi."}]}],"speak":[]},"review":{"range":"1–3","rows":[{"l":2,"zh":"汉语的基本语序","vi":"Trật tự từ cơ bản","ex":{"zh":"我叫白家月。","py":"Wǒ jiào Bái Jiāyuè.","vi":"Mình tên là Bạch Gia Nguyệt."}},{"l":1,"zh":"招呼语","vi":"Lời chào hỏi","ex":{"zh":"你好！","py":"Nǐ hǎo!","vi":"Xin chào!"}},{"l":1,"zh":"致谢语","vi":"Lời cảm ơn","ex":{"zh":"谢谢！","py":"Xièxie!","vi":"Cảm ơn!"}},{"l":1,"zh":"告别语","vi":"Lời tạm biệt","ex":{"zh":"再见！","py":"Zàijiàn!","vi":"Tạm biệt!"}},{"l":2,"zh":"致歉语","vi":"Lời xin lỗi","ex":{"zh":"对不起。","py":"Duìbuqǐ.","vi":"Xin lỗi."}},{"l":2,"zh":"自我介绍、互相介绍","vi":"Tự giới thiệu, giới thiệu nhau","ex":{"zh":"我叫李文。","py":"Wǒ jiào Lǐ Wén.","vi":"Mình tên là Lý Văn."}},{"l":3,"zh":"\"是\"字句","vi":"Câu chữ 是","ex":{"zh":"我是学生。","py":"Wǒ shì xuéshēng.","vi":"Tôi là học sinh."}},{"l":3,"zh":"结构助词\"的\"","vi":"Trợ từ kết cấu 的","ex":{"zh":"我的中文老师","py":"wǒ de Zhōngwén lǎoshī","vi":"giáo viên tiếng Trung của tôi"}},{"l":3,"zh":"用\"吗\"的是非问句","vi":"Câu hỏi có / không với 吗","ex":{"zh":"你是学生吗？","py":"Nǐ shì xuéshēng ma?","vi":"Bạn là học sinh à?"}}]}},{"id":"k1v3-b04","courseId":"k1v3","order":4,"title":"Tôi có hai đứa con","titleZh":"我有两个孩子","titlePy":"wǒ yǒu liǎng gè háizi","vocab":[{"stt":1,"hanzi":"有","pinyin":"yǒu","hanviet":"Hữu","pos":"Động từ","meaning":"có, sở hữu","comps":"有人 (có người), 有钱 (có tiền)","example":{"zh":"我有两个孩子。","py":"Wǒ yǒu liǎng gè háizi.","vi":"Tôi có hai đứa con."}},{"stt":2,"hanzi":"多少","pinyin":"duōshao","hanviet":"Đa thiểu","pos":"Đại từ nghi vấn","meaning":"bao nhiêu","comps":"多少人 (bao nhiêu người), 多少个 (bao nhiêu cái)","example":{"zh":"你有多少个学生？","py":"Nǐ yǒu duōshao gè xuéshēng?","vi":"Bạn có bao nhiêu học sinh?"}},{"stt":3,"hanzi":"个","pinyin":"gè","hanviet":"Cá","pos":"Lượng từ","meaning":"cái, chiếc, người","comps":"一个人 (một người), 两个 (hai cái)","example":{"zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Cô ấy có hai mươi học sinh."}},{"stt":4,"hanzi":"哥哥","pinyin":"gēge","hanviet":"Ca ca","pos":"Danh từ","meaning":"anh trai","comps":"大哥 (anh cả), 我哥哥 (anh trai tôi)","example":{"zh":"我有两个哥哥。","py":"Wǒ yǒu liǎng gè gēge.","vi":"Tôi có hai anh trai."}},{"stt":5,"hanzi":"呢","pinyin":"ne","hanviet":"Ni","pos":"Trợ từ","meaning":"còn … thì sao? (hỏi lại)","comps":"你呢？(còn bạn?), 我呢？(còn tôi?)","example":{"zh":"我有两个哥哥，你呢？","py":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vi":"Tôi có hai anh trai, còn bạn?"}},{"stt":6,"hanzi":"没有","pinyin":"méiyǒu","hanviet":"Một hữu","pos":"Động từ","meaning":"không có, chưa có","comps":"没有人 (không có ai), 我没有 (tôi không có)","example":{"zh":"我没有哥哥。","py":"Wǒ méiyǒu gēge.","vi":"Tôi không có anh trai."}},{"stt":7,"hanzi":"家","pinyin":"jiā","hanviet":"Gia","pos":"Danh từ","meaning":"nhà, gia đình","comps":"我家 (nhà tôi), 家人 (người nhà)","example":{"zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"}},{"stt":8,"hanzi":"几","pinyin":"jǐ","hanviet":"Kỷ","pos":"Đại từ nghi vấn","meaning":"mấy (số nhỏ, dưới 10)","comps":"几个 (mấy cái), 几岁 (mấy tuổi)","example":{"zh":"你有几个孩子？","py":"Nǐ yǒu jǐ gè háizi?","vi":"Bạn có mấy đứa con?"}},{"stt":9,"hanzi":"口","pinyin":"kǒu","hanviet":"Khẩu","pos":"Lượng từ","meaning":"miệng; đếm nhân khẩu","comps":"四口人 (bốn người), 人口 (dân số)","example":{"zh":"我家有四口人。","py":"Wǒ jiā yǒu sì kǒu rén.","vi":"Nhà tôi có bốn người."}},{"stt":10,"hanzi":"爸爸","pinyin":"bàba","hanviet":"Ba ba","pos":"Danh từ","meaning":"bố, ba, cha","comps":"我爸爸 (bố tôi), 爸爸妈妈 (bố mẹ)","example":{"zh":"这是我爸爸。","py":"Zhè shì wǒ bàba.","vi":"Đây là bố tôi."}},{"stt":11,"hanzi":"妈妈","pinyin":"māma","hanviet":"Ma ma","pos":"Danh từ","meaning":"mẹ, má","comps":"我妈妈 (mẹ tôi), 妈妈们 (các mẹ)","example":{"zh":"我妈妈是老师。","py":"Wǒ māma shì lǎoshī.","vi":"Mẹ tôi là giáo viên."}},{"stt":12,"hanzi":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","pos":"Danh từ","meaning":"em gái","comps":"小妹 (em gái út), 我妹妹 (em gái tôi)","example":{"zh":"我有一个妹妹。","py":"Wǒ yǒu yí gè mèimei.","vi":"Tôi có một em gái."}},{"stt":13,"hanzi":"和","pinyin":"hé","hanviet":"Hoà","pos":"Liên từ","meaning":"và, với, cùng","comps":"我和你 (tôi và bạn), 爸爸和妈妈 (bố và mẹ)","example":{"zh":"我有哥哥和妹妹。","py":"Wǒ yǒu gēge hé mèimei.","vi":"Tôi có anh trai và em gái."}},{"stt":14,"hanzi":"儿子","pinyin":"érzi","hanviet":"Nhi tử","pos":"Danh từ","meaning":"con trai","comps":"我儿子 (con trai tôi), 大儿子 (con trai lớn)","example":{"zh":"这是我儿子。","py":"Zhè shì wǒ érzi.","vi":"Đây là con trai tôi."}},{"stt":15,"hanzi":"孩子","pinyin":"háizi","hanviet":"Hài tử","pos":"Danh từ","meaning":"con, đứa trẻ","comps":"小孩子 (trẻ con), 两个孩子 (hai đứa con)","example":{"zh":"她有两个孩子。","py":"Tā yǒu liǎng gè háizi.","vi":"Cô ấy có hai đứa con."}},{"stt":16,"hanzi":"女儿","pinyin":"nǚ'ér","hanviet":"Nữ nhi","pos":"Danh từ","meaning":"con gái","comps":"我女儿 (con gái tôi), 大女儿 (con gái lớn)","example":{"zh":"我有一个女儿。","py":"Wǒ yǒu yí gè nǚ'ér.","vi":"Tôi có một con gái."}},{"stt":17,"hanzi":"岁","pinyin":"suì","hanviet":"Tuế","pos":"Lượng từ","meaning":"tuổi","comps":"五岁 (năm tuổi), 几岁 (mấy tuổi)","example":{"zh":"他今年五岁。","py":"Tā jīnnián wǔ suì.","vi":"Cháu năm nay năm tuổi."}},{"stt":18,"hanzi":"他","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"anh ấy, ông ấy, cậu bé ấy","comps":"他们 (họ), 他是我儿子 (cậu bé là con trai tôi)","example":{"zh":"他今年五岁。","py":"Tā jīnnián wǔ suì.","vi":"Năm nay cháu năm tuổi."}},{"stt":19,"hanzi":"今年","pinyin":"jīnnián","hanviet":"Kim niên","pos":"Danh từ","meaning":"năm nay","comps":"今天 (hôm nay), 明年 (năm sau)","example":{"zh":"你今年多大？","py":"Nǐ jīnnián duō dà?","vi":"Năm nay bạn bao nhiêu tuổi?"}},{"stt":20,"hanzi":"多","pinyin":"duō","hanviet":"Đa","pos":"Đại từ nghi vấn","meaning":"bao (nhiêu) — 多大: bao nhiêu tuổi","comps":"多大 (bao nhiêu tuổi), 很多 (rất nhiều)","example":{"zh":"您女儿多大？","py":"Nín nǚ'ér duō dà?","vi":"Con gái chị bao nhiêu tuổi?"}},{"stt":21,"hanzi":"大","pinyin":"dà","hanviet":"Đại","pos":"Tính từ","meaning":"to, lớn; tuổi tác","comps":"多大 (bao nhiêu tuổi), 大人 (người lớn)","example":{"zh":"她今年多大？","py":"Tā jīnnián duō dà?","vi":"Năm nay cô ấy bao nhiêu tuổi?"}}],"hanzi":[{"char":"有","pinyin":"yǒu","hanviet":"Hữu","chars":["有"],"story":"有 gồm phần trên là biến thể của 又 (bàn tay) và phần dưới là 月, vốn viết từ 肉 (miếng thịt). Bàn tay cầm được miếng thịt nghĩa là trong nhà có của ăn, nên 有 mang nghĩa \"có, sở hữu\"."},{"char":"多少","pinyin":"duōshao","hanviet":"Đa thiểu","chars":["多","少"],"story":"多 là hai chữ 夕 (buổi tối) chồng lên nhau — hết tối này sang tối khác, ngày tháng chất chồng nên nghĩa là \"nhiều\". 少 là chữ 小 (nhỏ) thêm một nét phẩy như bị gạt bớt đi, nghĩa là \"ít\". Ghép \"nhiều – ít\" lại thành câu hỏi về số lượng."},{"char":"个","pinyin":"gè","hanviet":"Cá","chars":["个"],"story":"个 gồm 人 (người) ở trên và một nét sổ thẳng ở dưới, vẽ hình một thân tre đơn lẻ tách ra khỏi bụi. Vì đếm từng cây tre một nên 个 trở thành lượng từ dùng chung nhất, đếm được cả người lẫn vật."},{"char":"哥哥","pinyin":"gēge","hanviet":"Ca ca","chars":["哥","哥"],"story":"哥 là hai chữ 可 chồng lên nhau, mà 可 lại có bộ Khẩu 口 (miệng) — chữ này vốn tả tiếng hát ngân dài, sau được mượn để gọi anh trai. Tiếng Trung hay gọi người thân bằng cách lặp chữ, nên thành 哥哥, chữ sau đọc thanh nhẹ."},{"char":"呢","pinyin":"ne","hanviet":"Ni","chars":["呢"],"story":"呢 gồm bộ Khẩu 口 (miệng, cho biết đây là tiếng thốt ra khi nói) và 尼 ní chỉ âm đọc — một chữ hình thanh điển hình, cùng khuôn với 吗 (口 + 马) đã học. Làm trợ từ ngữ khí thì đọc thanh nhẹ ne."},{"char":"没有","pinyin":"méiyǒu","hanviet":"Một hữu","chars":["没","有"],"story":"没 gồm bộ Thuỷ 氵 (nước) và 殳, vẽ cảnh vật chìm mất dưới nước nên có nghĩa \"mất đi, không còn\". Ghép trước 有 (có) thành 没有 = \"không có\". Đây là lý do phủ định của 有 phải dùng 没 chứ không dùng 不."},{"char":"家","pinyin":"jiā","hanviet":"Gia","chars":["家"],"story":"家 gồm bộ Miên 宀 (mái nhà) ở trên và 豕 (con lợn) ở dưới. Người xưa nuôi lợn ngay dưới mái nhà; nhà nào có lợn là nhà có của ăn của để, nên chữ này chỉ \"nhà, gia đình\"."},{"char":"几","pinyin":"jǐ","hanviet":"Kỷ","chars":["几"],"story":"几 vốn là chữ tượng hình, vẽ cái bàn nhỏ (cái kỷ) có hai chân đỡ. Về sau chữ được mượn dùng làm từ để hỏi số lượng nhỏ \"mấy\" — nghĩa gốc \"cái kỷ\" nay hầu như không còn dùng."},{"char":"口","pinyin":"kǒu","hanviet":"Khẩu","chars":["口"],"story":"口 là chữ tượng hình, vẽ hình cái miệng đang há ra. Người Trung Quốc đếm người trong một gia đình bằng lượng từ 口 vì mỗi thành viên là một miệng ăn — cùng lối nghĩ với \"nhân khẩu\" trong tiếng Việt."},{"char":"爸爸","pinyin":"bàba","hanviet":"Ba ba","chars":["爸","爸"],"story":"爸 gồm bộ 父 (cha) ở trên chỉ nghĩa và 巴 bā ở dưới chỉ âm đọc — một chữ hình thanh. Bộ 父 vốn vẽ bàn tay cầm cây rìu, hình ảnh người đàn ông trụ cột. Gọi lặp thành 爸爸 cho thân mật, chữ sau đọc thanh nhẹ."},{"char":"妈妈","pinyin":"māma","hanviet":"Ma ma","chars":["妈","妈"],"story":"妈 gồm bộ Nữ 女 (phụ nữ) chỉ nghĩa và 马 mǎ chỉ âm đọc. Chữ này cùng một khuôn hình thanh với 吗 (口 + 马) đã học ở bài trước — nhớ 马 là nhớ được cả hai chữ."},{"char":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","chars":["妹","妹"],"story":"妹 gồm bộ Nữ 女 (con gái) và 未 wèi chỉ âm, nghĩa gốc của 未 là \"chưa\". Người con gái sinh sau, tuổi còn \"chưa\" lớn, chính là em gái — nên 妹 nghĩa là \"em gái\"."},{"char":"和","pinyin":"hé","hanviet":"Hoà","chars":["和"],"story":"和 gồm 禾 (cây lúa) và 口 (miệng). Có lúa chia đủ cho mọi miệng ăn thì nhà cửa êm ấm, nên chữ này nghĩa gốc là \"hoà thuận, hoà hợp\". Từ nghĩa \"cùng nhau\" đó, 和 được dùng làm liên từ \"và\"."},{"char":"儿子","pinyin":"érzi","hanviet":"Nhi tử","chars":["儿","子"],"story":"儿 vẽ hình một đứa trẻ mà phần thóp trên đầu còn chưa liền lại. 子 vẽ em bé quấn tã, chỉ ló ra cái đầu và hai cánh tay giơ lên. Hai chữ tượng hình cùng chỉ trẻ con, ghép lại thành \"con trai\"."},{"char":"孩子","pinyin":"háizi","hanviet":"Hài tử","chars":["孩","子"],"story":"孩 gồm bộ Tử 子 (đứa bé) chỉ nghĩa và 亥 hài chỉ âm đọc. Ghép với 子 phía sau thành 孩子 — hậu tố 子 lúc này mất nghĩa riêng và đọc thanh nhẹ zi, giống 儿子, 妻子."},{"char":"女儿","pinyin":"nǚ'ér","hanviet":"Nữ nhi","chars":["女","儿"],"story":"女 là chữ tượng hình, vẽ người phụ nữ đang quỳ, hai tay khoanh trước ngực. Ghép với 儿 (đứa trẻ) thành 女儿 — đứa con là con gái. Chú ý pinyin viết có dấu nháy: nǚ’ér, để tách rõ hai âm tiết."},{"char":"岁","pinyin":"suì","hanviet":"Tuế","chars":["岁"],"story":"岁 gồm 山 (núi) ở trên và 夕 (chiều tối) ở dưới. Dạng phồn thể 歲 vốn chỉ sao Tuế đi hết một vòng trời là tròn một năm, nên 岁 mang nghĩa \"năm\" và dùng để đếm \"tuổi\"."},{"char":"他","pinyin":"tā","hanviet":"Tha","chars":["他"],"story":"他 = bộ Nhân đứng 亻 (người) + 也 (chỉ âm). Ngôi thứ ba chỉ nam giới: anh ấy, ông ấy. Phân biệt cùng âm tā: 她 có bộ Nữ 女 (cô ấy) — bài 3; 它 dùng cho đồ vật, con vật — bài 5."},{"char":"今年","pinyin":"jīnnián","hanviet":"Kim niên","chars":["今","年"],"story":"今 vẽ hình cái miệng khép lại, chỉ ngay thời điểm đang nói — \"bây giờ\". 年 vốn vẽ người vác bó lúa 禾 trên lưng, vì mỗi mùa lúa chín là tròn một năm. Ghép lại thành \"năm nay\"."},{"char":"多","pinyin":"duō","hanviet":"Đa","chars":["多"],"story":"多 là hai chữ 夕 (buổi tối) xếp chồng lên nhau. Đêm nối đêm, ngày tháng cứ chất chồng thêm mãi, nên 多 có nghĩa \"nhiều\". Khi đứng trước tính từ, 多 lại thành từ để hỏi mức độ: 多大, 多少."},{"char":"大","pinyin":"dà","hanviet":"Đại","chars":["大"],"story":"大 là chữ tượng hình, vẽ một người đứng thẳng dang rộng hai tay hai chân — dáng người vươn ra hết cỡ. Từ hình ảnh đó chữ mang nghĩa \"to, lớn\", và khi hỏi tuổi thì 多大 chính là hỏi \"lớn bao nhiêu\"."}],"grammar":[{"title":"Câu chữ 有 (mẫu 1/2)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>有 / 没有</b><small>có / không có</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(数量词)</b><small>số + lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Diễn đạt \"có\"</p><ul><li><span class=\"zh\">有</span> cho biết <b>ai sở hữu cái gì</b> hoặc <b>ở đâu có cái gì</b>: <span class=\"zh\">我有两个哥哥。</span></li><li>Trước tân ngữ thường có <b>số từ + lượng từ</b>: <span class=\"zh\">有二十个学生</span>, <span class=\"zh\">有四口人</span>.</li><li>Muốn hỏi thì thêm <span class=\"zh\">吗</span> vào cuối, hoặc dùng <span class=\"zh\">几 / 多少</span> để hỏi số lượng.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我有两个孩子。</span>　·　phủ định: <span class=\"zh\">我没有哥哥。</span></p>","note":"<b>Lưu ý:</b> Phủ định của <span class=\"zh\">有</span> <b>bắt buộc</b> là <span class=\"zh\">没有</span> — tuyệt đối <b>không</b> nói <span class=\"zh\">不有</span>.","examples":[{"zh":"我有两个孩子。","py":"Wǒ yǒu liǎng gè háizi.","vi":"Tôi có hai đứa con."},{"zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Cô ấy có hai mươi học sinh."},{"zh":"她有一个姐姐。","py":"Tā yǒu yí gè jiějie.","vi":"Cô ấy có một chị gái."},{"zh":"我没/没有姐姐。","py":"Wǒ méi/méiyǒu jiějie.","vi":"Tôi không có chị gái."}],"exercises":[]},{"title":"Cách đọc số đếm 1 – 100","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>二</b><small>2</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>十</b><small>10</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>二十</b><small>20</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>二十一</b><small>21</small></span></div>","summary":"<p class=\"gr-lead\">Cách đọc số đếm</p><ul><li>Số từ 11 đến 99 ghép theo công thức <b>hàng chục + <span class=\"zh\">十</span> + hàng đơn vị</b>: <span class=\"zh\">三十五</span> = 35.</li><li>Số tròn chục thì bỏ hàng đơn vị: <span class=\"zh\">二十</span> (20), <span class=\"zh\">五十</span> (50), <span class=\"zh\">一百</span> (100).</li><li>Đứng <b>trước lượng từ</b>, số 2 phải đọc là <span class=\"zh\">两</span>: <span class=\"zh\">两个孩子</span>, <span class=\"zh\">两口人</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">数字</span> · Số đếm</h4><div class=\"ct-box\"><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Chữ</th><th>Pinyin</th><th>Hán Việt</th><th>Nghĩa</th></tr></thead><tbody><tr><td><b class=\"zh\">一</b></td><td>yī</td><td>Nhất</td><td>một · 1</td></tr><tr><td><b class=\"zh\">二</b></td><td>èr</td><td>Nhị</td><td>hai · 2</td></tr><tr><td><b class=\"zh\">三</b></td><td>sān</td><td>Tam</td><td>ba · 3</td></tr><tr><td><b class=\"zh\">四</b></td><td>sì</td><td>Tứ</td><td>bốn · 4</td></tr><tr><td><b class=\"zh\">五</b></td><td>wǔ</td><td>Ngũ</td><td>năm · 5</td></tr><tr><td><b class=\"zh\">六</b></td><td>liù</td><td>Lục</td><td>sáu · 6</td></tr><tr><td><b class=\"zh\">七</b></td><td>qī</td><td>Thất</td><td>bảy · 7</td></tr><tr><td><b class=\"zh\">八</b></td><td>bā</td><td>Bát</td><td>tám · 8</td></tr><tr><td><b class=\"zh\">九</b></td><td>jiǔ</td><td>Cửu</td><td>chín · 9</td></tr><tr><td><b class=\"zh\">十</b></td><td>shí</td><td>Thập</td><td>mười · 10</td></tr><tr><td><b class=\"zh\">零</b></td><td>líng</td><td>Linh</td><td>không · 0</td></tr><tr><td><b class=\"zh\">两</b></td><td>liǎng</td><td>Lưỡng</td><td>hai (trước lượng từ)</td></tr><tr><td><b class=\"zh\">百</b></td><td>bǎi</td><td>Bách</td><td>trăm · 100</td></tr><tr><td><b class=\"zh\">千</b></td><td>qiān</td><td>Thiên</td><td>nghìn · 1000</td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">十一</span> (11)　·　<span class=\"zh\">二十</span> (20)　·　<span class=\"zh\">九十九</span> (99)</p>","note":"<b>Lưu ý:</b> Nói <span class=\"zh\">二个</span> là <b>sai</b>, phải là <span class=\"zh\">两个</span>; nhưng khi đọc số thì vẫn giữ <span class=\"zh\">十二</span>, <span class=\"zh\">二十</span>.","examples":[{"zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Cô ấy có hai mươi học sinh."},{"zh":"一百","py":"yìbǎi","vi":"100"},{"zh":"二百零八","py":"èrbǎi líng bā","vi":"208"},{"zh":"九百九十九","py":"jiǔbǎi jiǔshíjiǔ","vi":"999"},{"zh":"一千","py":"yìqiān","vi":"1000"},{"zh":"一千五百二十八","py":"yìqiān wǔbǎi èrshíbā","vi":"1528"},{"zh":"九千九百九十九","py":"jiǔqiān jiǔbǎi jiǔshíjiǔ","vi":"9999"},{"zh":"十二","py":"shí'èr","vi":"12"},{"zh":"二十二","py":"èrshí'èr","vi":"22"},{"zh":"一百二十二","py":"yìbǎi èrshí'èr","vi":"122"},{"zh":"两个人","py":"liǎng gè rén","vi":"hai người"},{"zh":"两口人","py":"liǎng kǒu rén","vi":"(nhà có) hai người"},{"zh":"两本书","py":"liǎng běn shū","vi":"hai quyển sách"}],"exercises":[]},{"title":"Trợ từ ngữ khí 呢","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>câu hỏi</b><small>nêu trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>→</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词 / 代词</b><small>đối tượng mới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>呢？</b><small>còn … thì sao?</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi lại: còn …?</p><ul><li>Đặt <span class=\"zh\">呢</span> sau danh từ hoặc đại từ để <b>hỏi lại đúng câu hỏi vừa rồi</b> mà không cần nhắc lại cả câu.</li><li>Chỉ dùng được khi trước đó <b>đã có một câu hỏi hoặc một câu kể làm nền</b>: <span class=\"zh\">她很忙，你呢？</span></li><li>Làm trợ từ thì <span class=\"zh\">呢</span> đọc <b>thanh nhẹ</b> ne, không đọc thanh 2 như chữ 尼.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我有两个哥哥，你呢？</span> = Tôi có hai anh trai, còn bạn?</p>","note":"<b>Lưu ý:</b> Không dùng <span class=\"zh\">呢</span> chung với <span class=\"zh\">吗</span> trong một câu: nói <span class=\"zh\">你呢？</span>, <b>không</b> nói <span class=\"zh\">你呢吗？</span>","examples":[{"zh":"我没有哥哥，你呢？","py":"Wǒ méiyǒu gēge, nǐ ne?","vi":"Mình không có anh trai, còn bạn?"},{"zh":"我有两个哥哥，你呢？","py":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vi":"Mình có hai anh trai, còn bạn?"},{"zh":"我叫白家月，你呢？","py":"Wǒ jiào Bái Jiāyuè, nǐ ne?","vi":"Mình tên là Bạch Gia Nguyệt, còn bạn?"},{"zh":"我是中国人，你呢？","py":"Wǒ shì Zhōngguó rén, nǐ ne?","vi":"Mình là người Trung Quốc, còn bạn?"}],"exercises":[]},{"title":"Danh lượng từ và kết cấu số – lượng – danh","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>数词</b><small>số từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span></div>","summary":"<p class=\"gr-lead\">Danh lượng từ</p><ul><li>Trong tiếng Trung, số từ <b>không đứng thẳng</b> trước danh từ — bắt buộc chèn một <b>lượng từ</b> vào giữa.</li><li><span class=\"zh\">个</span> là lượng từ <b>dùng chung nhất</b>, đếm được cả người lẫn vật: <span class=\"zh\">一个人</span>, <span class=\"zh\">两个孩子</span>.</li><li><span class=\"zh\">口</span> chỉ dùng đếm <b>nhân khẩu trong một gia đình</b>: <span class=\"zh\">我家有四口人。</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">两个孩子</span>　·　<span class=\"zh\">四口人</span>　·　<span class=\"zh\">二十个学生</span></p>","note":"<b>Lưu ý:</b> Người Việt quen nói \"hai đứa con\" nên hay bỏ lượng từ — <span class=\"zh\">两孩子</span> là <b>sai</b>, phải là <span class=\"zh\">两个孩子</span>.","examples":[{"zh":"我家有四口人。","py":"Wǒ jiā yǒu sì kǒu rén.","vi":"Nhà tôi có bốn người."},{"zh":"四口","py":"sì kǒu","vi":"bốn (người — lượng từ 口)"},{"zh":"四口人","py":"sì kǒu rén","vi":"(nhà có) bốn người"},{"zh":"两个","py":"liǎng gè","vi":"hai (cái / người)"},{"zh":"两个学生","py":"liǎng gè xuéshēng","vi":"hai học sinh"}],"exercises":[{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你家有{{0}}？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我家有三口人，你家呢？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我家有{{1}}。</span></span></span><span class=\"qz-hint\">Nhà bạn có mấy người? — Nhà mình có ba người, nhà bạn thì sao? — Nhà mình có bốn người.</span>","blanks":[["几口人"],["四口人"]],"explain":"你家有几口人？ (Nǐ jiā yǒu jǐ kǒu rén?) · 我家有四口人。 (Wǒ jiā yǒu sì kǒu rén.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你有姐姐吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我有____姐姐，你呢？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我有两个姐姐。</span></span></span><span class=\"qz-hint\">Bạn có chị gái không? — Mình có một chị gái, còn bạn? — Mình có hai chị gái.</span>","answer":["一个"],"explain":"我有一个姐姐，你呢？ (Wǒ yǒu yí gè jiějie, nǐ ne?)"}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — Lưu Minh hỏi về Nhất Phi","lines":[{"speaker":"明","name":"Lưu Minh","zh":"一飞忙吗？","py":"Yīfēi máng ma?","vi":"Nhất Phi bận không?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"她很忙。","py":"Tā hěn máng.","vi":"Cô ấy bận lắm."},{"speaker":"明","name":"Lưu Minh","zh":"她有多少个学生？","py":"Tā yǒu duōshao gè xuéshēng?","vi":"Cô ấy có bao nhiêu học sinh?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"她有二十个学生。","py":"Tā yǒu èrshí gè xuéshēng.","vi":"Cô ấy có hai mươi học sinh."}]},{"titleZh":"课文二 · 在公司里","titleVi":"Ở công ty — hỏi nhau về gia đình","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我有两个哥哥，你呢？","py":"Wǒ yǒu liǎng gè gēge, nǐ ne?","vi":"Mình có hai anh trai, còn bạn?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我没有哥哥。","py":"Wǒ méiyǒu gēge.","vi":"Mình không có anh trai."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我家有四口人，爸爸、妈妈、妹妹和我。","py":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","vi":"Nhà mình có bốn người: bố, mẹ, em gái và mình."}]},{"titleZh":"课文三 · 在街上","titleVi":"Trên phố — gặp nhau hỏi về con cái","lines":[{"speaker":"乐","name":"Dương Đồng Lạc","zh":"这是您儿子吗？","py":"Zhè shì nín érzi ma?","vi":"Đây là con trai chị à?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"是的。我有两个孩子，一个儿子，一个女儿。","py":"Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","vi":"Đúng vậy. Mình có hai đứa con, một trai một gái."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"您儿子几岁？","py":"Nín érzi jǐ suì?","vi":"Con trai chị mấy tuổi rồi?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"他今年五岁。","py":"Tā jīnnián wǔ suì.","vi":"Cháu năm nay năm tuổi."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"您女儿多大？","py":"Nín nǚ'ér duō dà?","vi":"Còn con gái chị bao nhiêu tuổi?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"她今年十二。","py":"Tā jīnnián shí'èr.","vi":"Cháu năm nay mười hai."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hỏi nhau về tuổi và gia đình","q":{"zh":"两人一组，互相询问个人和家庭情况（年龄、家庭人口等），可虚拟。","py":"Liǎng rén yì zǔ, hùxiāng xúnwèn gèrén hé jiātíng qíngkuàng (niánlíng, jiātíng rénkǒu děng), kě xūnǐ.","vi":"Hai người một nhóm, hỏi nhau về bản thân và gia đình (tuổi, số người trong nhà…), có thể hư cấu."},"items":[{"lines":[{"who":"A","zh":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"},{"who":"B","zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","vi":"Mình là người Trung Quốc."}]},{"lines":[{"who":"A","zh":"你家有几口人？","py":"Nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"who":"B","zh":"我家有四口人，爸爸、妈妈、哥哥和我。","py":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, gēge hé wǒ.","vi":"Nhà mình có bốn người: bố, mẹ, anh trai và mình."}]},{"lines":[{"who":"A","zh":"你今年多大？","py":"Nǐ jīnnián duō dà?","vi":"Năm nay bạn bao nhiêu tuổi?"},{"who":"B","zh":"我今年二十岁。","py":"Wǒ jīnnián èrshí suì.","vi":"Năm nay mình hai mươi tuổi."}]}]}],"speak":[]}},{"id":"k1v3-b05","courseId":"k1v3","order":5,"title":"Hôm nay tôi được nghỉ","titleZh":"今天我休息","titlePy":"jīntiān wǒ xiūxi","vocab":[{"stt":1,"hanzi":"今天","pinyin":"jīntiān","hanviet":"Kim thiên","pos":"Danh từ","meaning":"hôm nay","comps":"今天几号 (hôm nay ngày mấy), 今年 (năm nay)","example":{"zh":"今天我休息。","py":"Jīntiān wǒ xiūxi.","vi":"Hôm nay tôi được nghỉ."}},{"stt":2,"hanzi":"号","pinyin":"hào","hanviet":"Hiệu","pos":"Lượng từ","meaning":"ngày (trong tháng, khẩu ngữ)","comps":"几号 (ngày mấy), 八号 (ngày mùng 8)","example":{"zh":"今天几号？","py":"Jīntiān jǐ hào?","vi":"Hôm nay ngày mấy?"}},{"stt":3,"hanzi":"月","pinyin":"yuè","hanviet":"Nguyệt","pos":"Danh từ","meaning":"tháng; mặt trăng","comps":"九月 (tháng chín), 一个月 (một tháng)","example":{"zh":"今天九月八号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay ngày 8 tháng 9."}},{"stt":4,"hanzi":"日","pinyin":"rì","hanviet":"Nhật","pos":"Lượng từ","meaning":"ngày (trong tháng, văn viết)","comps":"星期日 (Chủ Nhật), 生日 (sinh nhật)","example":{"zh":"今天九月八日。","py":"Jīntiān jiǔ yuè bā rì.","vi":"Hôm nay ngày 8 tháng 9."}},{"stt":5,"hanzi":"星期","pinyin":"xīngqī","hanviet":"Tinh kỳ","pos":"Danh từ","meaning":"tuần lễ; thứ trong tuần","comps":"星期一 (thứ Hai), 星期几 (thứ mấy)","example":{"zh":"今天星期几？","py":"Jīntiān xīngqī jǐ?","vi":"Hôm nay là thứ mấy?"}},{"stt":6,"hanzi":"星期日","pinyin":"Xīngqīrì","hanviet":"Tinh kỳ nhật","pos":"Danh từ","meaning":"Chủ Nhật (= 星期天)","comps":"星期天 (Chủ Nhật), 星期六 (thứ Bảy)","example":{"zh":"星期日我休息。","py":"Xīngqīrì wǒ xiūxi.","vi":"Chủ Nhật tôi được nghỉ."}},{"stt":7,"hanzi":"星期天","pinyin":"Xīngqītiān","hanviet":"Tinh kỳ thiên","pos":"Danh từ","meaning":"Chủ Nhật (khẩu ngữ, = 星期日)","comps":"这个星期天 (Chủ Nhật này), 星期天休息 (Chủ Nhật nghỉ)","example":{"zh":"星期天我也做饭。","py":"Xīngqītiān wǒ yě zuò fàn.","vi":"Chủ Nhật tôi cũng nấu cơm."}},{"stt":8,"hanzi":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","pos":"Động từ","meaning":"nghỉ, nghỉ ngơi","comps":"休息一下 (nghỉ một lát), 休息时间 (giờ nghỉ)","example":{"zh":"你今天休息吗？","py":"Nǐ jīntiān xiūxi ma?","vi":"Hôm nay bạn được nghỉ không?"}},{"stt":9,"hanzi":"会","pinyin":"huì","hanviet":"Hội","pos":"Động từ năng nguyện","meaning":"biết (làm gì đó)","comps":"会做饭 (biết nấu ăn), 不会 (không biết)","example":{"zh":"你会做饭吗？","py":"Nǐ huì zuò fàn ma?","vi":"Bạn biết nấu ăn không?"}},{"stt":10,"hanzi":"做饭","pinyin":"zuò fàn","hanviet":"Tố phạn","pos":"Động từ","meaning":"nấu cơm, nấu ăn","comps":"会做饭 (biết nấu ăn), 做中国菜 (nấu món Trung)","example":{"zh":"星期日我做饭。","py":"Xīngqīrì wǒ zuò fàn.","vi":"Chủ Nhật tôi nấu cơm."}},{"stt":11,"hanzi":"做","pinyin":"zuò","hanviet":"Tố","pos":"Động từ","meaning":"làm, chế tạo","comps":"做什么 (làm gì), 做菜 (nấu món ăn)","example":{"zh":"你会做什么？","py":"Nǐ huì zuò shénme?","vi":"Bạn biết làm món gì?"}},{"stt":12,"hanzi":"面条儿","pinyin":"miàntiáor","hanviet":"Diện điều nhi","pos":"Danh từ","meaning":"mì sợi","comps":"做面条儿 (làm mì), 吃面条儿 (ăn mì)","example":{"zh":"我会做面条儿。","py":"Wǒ huì zuò miàntiáor.","vi":"Tôi biết làm mì sợi."}},{"stt":13,"hanzi":"饺子","pinyin":"jiǎozi","hanviet":"Giáo tử","pos":"Danh từ","meaning":"sủi cảo, bánh chẻo","comps":"做饺子 (làm sủi cảo), 吃饺子 (ăn sủi cảo)","example":{"zh":"我会做饺子。","py":"Wǒ huì zuò jiǎozi.","vi":"Tôi biết làm sủi cảo."}},{"stt":14,"hanzi":"一些","pinyin":"yìxiē","hanviet":"Nhất ta","pos":"Số lượng từ","meaning":"một vài, một ít","comps":"一些人 (một vài người), 一些菜 (vài món ăn)","example":{"zh":"我会做一些菜。","py":"Wǒ huì zuò yìxiē cài.","vi":"Tôi nấu được vài món ăn."}},{"stt":15,"hanzi":"菜","pinyin":"cài","hanviet":"Thái","pos":"Danh từ","meaning":"món ăn; rau","comps":"做菜 (nấu món ăn), 中国菜 (món Trung Quốc)","example":{"zh":"我喜欢中国菜。","py":"Wǒ xǐhuan Zhōngguó cài.","vi":"Tôi thích món ăn Trung Quốc."}},{"stt":16,"hanzi":"下班","pinyin":"xiàbān","hanviet":"Hạ ban","pos":"Động từ","meaning":"tan làm (↔ 上班 đi làm)","comps":"上班 (đi làm), 下班时间 (giờ tan làm)","example":{"zh":"同乐，下班吗？","py":"Tónglè, xiàbān ma?","vi":"Đồng Lạc, tan làm rồi à?"}},{"stt":17,"hanzi":"新","pinyin":"xīn","hanviet":"Tân","pos":"Tính từ","meaning":"mới","comps":"新电脑 (máy tính mới), 新年 (năm mới)","example":{"zh":"这是我的新电脑。","py":"Zhè shì wǒ de xīn diànnǎo.","vi":"Đây là máy tính mới của tôi."}},{"stt":18,"hanzi":"电脑","pinyin":"diànnǎo","hanviet":"Điện não","pos":"Danh từ","meaning":"máy tính, máy vi tính","comps":"新电脑 (máy tính mới), 电话 (điện thoại)","example":{"zh":"这是新电脑吗？","py":"Zhè shì xīn diànnǎo ma?","vi":"Đây là máy tính mới à?"}},{"stt":19,"hanzi":"真","pinyin":"zhēn","hanviet":"Chân","pos":"Phó từ","meaning":"thật là, quả là","comps":"真好看 (đẹp thật), 真好 (tốt thật)","example":{"zh":"真好看！","py":"Zhēn hǎokàn!","vi":"Đẹp thật đấy!"}},{"stt":20,"hanzi":"好看","pinyin":"hǎokàn","hanviet":"Hảo khán","pos":"Tính từ","meaning":"đẹp, dễ nhìn","comps":"真好看 (đẹp thật), 不好看 (không đẹp)","example":{"zh":"你的电脑真好看。","py":"Nǐ de diànnǎo zhēn hǎokàn.","vi":"Máy tính của bạn đẹp thật."}},{"stt":21,"hanzi":"喜欢","pinyin":"xǐhuan","hanviet":"Hỉ hoan","pos":"Động từ","meaning":"thích, ưa thích","comps":"很喜欢 (rất thích), 不喜欢 (không thích)","example":{"zh":"我很喜欢它。","py":"Wǒ hěn xǐhuan tā.","vi":"Tôi rất thích nó."}},{"stt":22,"hanzi":"它","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"nó (đồ vật, con vật)","comps":"喜欢它 (thích nó), 它们 (chúng nó)","example":{"zh":"我也很喜欢它。","py":"Wǒ yě hěn xǐhuan tā.","vi":"Tôi cũng rất thích nó."}}],"hanzi":[{"char":"今天","pinyin":"jīntiān","hanviet":"Kim thiên","chars":["今","天"],"story":"今 vẽ hình cái miệng khép lại, chỉ đúng thời điểm đang nói — \"bây giờ\". 天 là chữ 大 (người dang tay) thêm một nét ngang trên đầu, chỉ bầu trời ở ngay trên đầu người, rồi mở rộng thành \"ngày\". Ghép lại thành \"hôm nay\"."},{"char":"号","pinyin":"hào","hanviet":"Hiệu","chars":["号"],"story":"号 gồm 口 (miệng) ở trên và 丂 ở dưới, vốn tả tiếng kêu to, hô lên. Từ việc \"hô số\" mà chữ mang nghĩa \"số hiệu\", rồi được dùng để gọi ngày trong tháng theo lối khẩu ngữ: 八号, 九号."},{"char":"月","pinyin":"yuè","hanviet":"Nguyệt","chars":["月"],"story":"月 là chữ tượng hình, vẽ hình mặt trăng khuyết — người xưa cố ý vẽ khuyết để khỏi lẫn với 日 (mặt trời) tròn. Trăng tròn rồi lại khuyết trọn một vòng là một tháng, nên 月 vừa là \"mặt trăng\" vừa là \"tháng\"."},{"char":"日","pinyin":"rì","hanviet":"Nhật","chars":["日"],"story":"日 là chữ tượng hình, vẽ vòng tròn mặt trời có một chấm ở giữa, về sau viết vuông vắn thành hình như ngày nay. Mặt trời mọc rồi lặn là trọn một ngày, nên 日 cũng nghĩa là \"ngày\" — dùng trong văn viết, còn khẩu ngữ nói 号."},{"char":"星期","pinyin":"xīngqī","hanviet":"Tinh kỳ","chars":["星","期"],"story":"星 gồm 日 (mặt trời) ở trên chỉ nghĩa ánh sáng và 生 shēng ở dưới chỉ âm — nghĩa là \"ngôi sao\". 期 gồm 其 chỉ âm và 月 (tháng) chỉ nghĩa thời gian, nghĩa là \"kỳ hạn\". Ghép lại chỉ chu kỳ bảy ngày, tức \"tuần lễ\"."},{"char":"星期日","pinyin":"Xīngqīrì","hanviet":"Tinh kỳ nhật","chars":["星","期","日"],"story":"Các thứ trong tuần đều ghép 星期 với số đếm: 星期一 (thứ Hai) cho tới 星期六 (thứ Bảy). Riêng Chủ Nhật không dùng số mà dùng 日 (mặt trời) trong văn viết, hoặc 天 (trời) trong khẩu ngữ — 星期日 và 星期天 hoàn toàn như nhau."},{"char":"星期天","pinyin":"Xīngqītiān","hanviet":"Tinh kỳ thiên","chars":["星","期","天"],"story":"星 = 日 (ánh sáng) + 生 (chỉ âm): ngôi sao; 期 = 其 (chỉ âm) + 月 (mặt trăng): kỳ hẹn, chu kỳ; 天 vẽ người 大 với vạch trên đầu là bầu trời, nghĩa \"trời, ngày\". 星期天 = ngày \"trời\" của tuần — Chủ Nhật, dùng nhiều trong khẩu ngữ, nghĩa như 星期日."},{"char":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","chars":["休","息"],"story":"休 gồm bộ Nhân đứng 亻 (người) và 木 (cây) — hình người ngồi tựa vào gốc cây, chính là đang nghỉ. 息 gồm 自 (vốn vẽ cái mũi) đặt trên 心 (trái tim): thở đều, tim êm. Hai chữ cùng nghĩa ghép lại thành \"nghỉ ngơi\"."},{"char":"会","pinyin":"huì","hanviet":"Hội","chars":["会"],"story":"会 có dạng phồn thể là 會, vẽ cái nồi cùng nắp đậy khít vào nhau, nghĩa gốc là \"hợp lại, gặp gỡ\" (còn thấy ở 开会 — họp). Từ ý \"làm cho khớp được\" mà chữ sinh thêm nghĩa \"biết làm, có khả năng làm\"."},{"char":"做饭","pinyin":"zuò fàn","hanviet":"Tố phạn","chars":["做","饭"],"story":"做 gồm bộ Nhân đứng 亻 (người), 古 và 攵 (hình bàn tay cầm cây que) — người ra tay làm việc. 饭 gồm bộ Thực 饣 (ăn) chỉ nghĩa và 反 fǎn chỉ âm, nghĩa là \"cơm\". Ghép lại: \"làm cơm\" tức là nấu ăn."},{"char":"做","pinyin":"zuò","hanviet":"Tố","chars":["做"],"story":"做 gồm ba phần: bộ Nhân đứng 亻 (người), 古 (xưa) chỉ âm, và 攵 vốn là hình bàn tay cầm cây que gõ xuống. Con người vung tay ra làm việc, nên chữ này mang nghĩa \"làm, chế tạo\"."},{"char":"面条儿","pinyin":"miàntiáor","hanviet":"Diện điều nhi","chars":["面","条","儿"],"story":"面 vốn vẽ khuôn mặt, về sau mượn dùng để chỉ bột mì. 条 có bộ 木 (gỗ), chỉ những vật dài như cành cây, nghĩa là \"sợi, thanh\". Bột mì kéo thành sợi dài chính là 面条; thêm 儿 hoá theo giọng Bắc Kinh nên đọc miàntiáor."},{"char":"饺子","pinyin":"jiǎozi","hanviet":"Giáo tử","chars":["饺","子"],"story":"饺 gồm bộ Thực 饣 (ăn) chỉ nghĩa và 交 jiāo chỉ âm — mà 交 lại có nghĩa \"giao nhau, chắp lại\", đúng như hình cái bánh gấp mép khép kín. 子 phía sau là hậu tố quen thuộc, đọc thanh nhẹ zi."},{"char":"一些","pinyin":"yìxiē","hanviet":"Nhất ta","chars":["一","些"],"story":"些 gồm 此 (này) ở trên và 二 ở dưới — ý chỉ \"chừng đôi ba cái này\", tức một số lượng nhỏ không nói rõ. Ghép với 一 thành 一些. Chú ý 一 ở đây biến điệu, đọc thanh 4: yìxiē."},{"char":"菜","pinyin":"cài","hanviet":"Thái","chars":["菜"],"story":"菜 gồm bộ Thảo 艹 (cỏ cây) ở trên và 采 cǎi (hái) ở dưới, mà 采 lại là hình bàn tay hái lá trên cây. Rau hái về nấu lên thành món, nên 菜 vừa nghĩa là \"rau\" vừa nghĩa là \"món ăn\"."},{"char":"下班","pinyin":"xiàbān","hanviet":"Hạ ban","chars":["下","班"],"story":"班 gồm hai chữ 王 (vốn là 玉 — ngọc) kẹp con dao 刂 ở giữa, nghĩa gốc là chia khối ngọc thành từng phần, sau chỉ \"ca, kíp làm việc\". 上班 là lên ca — đi làm; 下班 là xuống ca — tan làm. Cặp 上 ↔ 下 đối nhau rất dễ nhớ."},{"char":"新","pinyin":"xīn","hanviet":"Tân","chars":["新"],"story":"新 gồm 亲 bên trái chỉ âm và 斤 (cái rìu) bên phải chỉ nghĩa. Nghĩa gốc là dùng rìu đẵn cây lấy củi tươi; củi vừa chặt là củi mới, nên chữ mang nghĩa \"mới\"."},{"char":"电脑","pinyin":"diànnǎo","hanviet":"Điện não","chars":["电","脑"],"story":"电 vốn vẽ tia chớp loằng ngoằng xé ra giữa đám mây, nghĩa là \"điện\". 脑 gồm bộ Nhục 月 (thịt, cơ thể) và phần bên phải tả hộp sọ, nghĩa là \"não\". \"Bộ não chạy bằng điện\" chính là cái máy tính."},{"char":"真","pinyin":"zhēn","hanviet":"Chân","chars":["真"],"story":"真 phía trên là 十, ở giữa là 目 (con mắt) đặt trên một cái giá đỡ. Người xưa phải đưa mắt xem xét thật kỹ mới biết đâu là thật, nên chữ mang nghĩa \"chân thật\". Làm phó từ thì thành lời cảm thán \"thật là…\"."},{"char":"好看","pinyin":"hǎokàn","hanviet":"Hảo khán","chars":["好","看"],"story":"好 gồm 女 (phụ nữ) và 子 (đứa con) — người xưa cho rằng phụ nữ sinh được con là điều tốt đẹp. 看 là bàn tay 手 che trên con mắt 目 để nhìn ra xa. \"Nhìn vào thấy tốt\" chính là đẹp mắt, dễ nhìn."},{"char":"喜欢","pinyin":"xǐhuan","hanviet":"Hỉ hoan","chars":["喜","欢"],"story":"喜 phía trên là cái trống 壴, phía dưới là 口 (miệng) — gõ trống và mở miệng cười, tức là vui mừng. 欢 gồm 又 (bàn tay) và 欠 (người há miệng thở ra), tả dáng người reo vui. Hai chữ cùng chỉ niềm vui, ghép lại thành \"thích\"."},{"char":"它","pinyin":"tā","hanviet":"Tha","chars":["它"],"story":"它 gồm bộ Miên 宀 ở trên và 匕 ở dưới; chữ này vốn vẽ hình con rắn, về sau được mượn làm đại từ ngôi thứ ba. So với 他 (bộ 亻, chỉ nam) và 她 (bộ 女, chỉ nữ) học ở bài trước, 它 dùng cho đồ vật và con vật."}],"grammar":[{"title":"Cách diễn đạt thời gian (năm – tháng – ngày – thứ)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>2026年</b><small>năm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>9月</b><small>tháng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>8号</b><small>ngày</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>星期日</b><small>thứ</small></span></div>","summary":"<p class=\"gr-lead\">Cách nói ngày tháng</p><ul><li>Tiếng Trung đọc thời gian từ <b>đơn vị lớn xuống đơn vị nhỏ</b>: năm → tháng → ngày → thứ, <b>ngược hẳn</b> tiếng Việt.</li><li>Ngày trong tháng: <b>khẩu ngữ</b> dùng <span class=\"zh\">号</span>, <b>văn viết</b> dùng <span class=\"zh\">日</span> — <span class=\"zh\">八号</span> = <span class=\"zh\">八日</span>.</li><li>Thứ trong tuần ghép <span class=\"zh\">星期</span> + số: <span class=\"zh\">星期一</span> … <span class=\"zh\">星期六</span>; Chủ Nhật là <span class=\"zh\">星期日 / 星期天</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">今天九月八号，星期日。</span> = Hôm nay ngày 8 tháng 9, Chủ Nhật.</p>","note":"<b>Lưu ý:</b> Hỏi ngày bằng <span class=\"zh\">几号</span>, hỏi thứ bằng <span class=\"zh\">星期几</span> — câu đã có <span class=\"zh\">几</span> thì <b>không thêm</b> <span class=\"zh\">吗</span>.","examples":[{"zh":"今天九月八号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay là ngày 8 tháng 9."},{"zh":"1992年5月16日/号，星期六","py":"yī jiǔ jiǔ èr nián wǔ yuè shíliù rì/hào, Xīngqīliù","vi":"Thứ bảy, ngày 16 tháng 5 năm 1992"},{"zh":"2024年10月22日/号，星期二","py":"èr líng èr sì nián shí yuè èrshí'èr rì/hào, Xīngqī'èr","vi":"Thứ ba, ngày 22 tháng 10 năm 2024"},{"zh":"今天9月8号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay ngày 8 tháng 9."},{"zh":"今天是2025年5月22号。","py":"Jīntiān shì èr líng èr wǔ nián wǔ yuè èrshí'èr hào.","vi":"Hôm nay là ngày 22 tháng 5 năm 2025."},{"zh":"明天是2024年8月18号，星期天。","py":"Míngtiān shì èr líng èr sì nián bā yuè shíbā hào, Xīngqītiān.","vi":"Ngày mai là chủ nhật, ngày 18 tháng 8 năm 2024."}],"exercises":[]},{"title":"Câu vị ngữ danh từ (名词谓语句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(是)</b><small>thường lược bỏ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>名词短语</b><small>cụm danh từ làm vị ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Câu không cần 是</p><ul><li>Khi vị ngữ chỉ <b>ngày tháng, thứ, giờ, tuổi tác hay quê quán</b>, câu <b>không cần</b> <span class=\"zh\">是</span>: <span class=\"zh\">今天星期日。</span></li><li>Đây là chỗ khác hẳn tiếng Việt — ta luôn nói \"hôm nay <b>là</b> Chủ Nhật\", tiếng Trung bỏ hẳn động từ.</li><li>Vẫn thêm được <span class=\"zh\">是</span> cho trang trọng: <span class=\"zh\">今天是星期日。</span> Cả hai câu đều đúng.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">今天星期日。</span>　·　phủ định: <span class=\"zh\">今天不是星期日。</span></p>","note":"<b>Lưu ý:</b> Nhưng khi <b>phủ định</b> thì <b>bắt buộc</b> phải có <span class=\"zh\">是</span>: <span class=\"zh\">今天不是星期日。</span>","examples":[{"zh":"今天星期日。","py":"Jīntiān Xīngqīrì.","vi":"Hôm nay là Chủ Nhật."},{"zh":"A：今天几号？　B：今天5月1号。","py":"A: Jīntiān jǐ hào?　B: Jīntiān wǔ yuè yī hào.","vi":"A: Hôm nay ngày mấy? — B: Hôm nay ngày 1 tháng 5."},{"zh":"我妹妹12岁。","py":"Wǒ mèimei shí'èr suì.","vi":"Em gái tôi 12 tuổi."}],"exercises":[]},{"title":"Động từ năng nguyện 会","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>会</b><small>biết làm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Biết làm nhờ học</p><ul><li><span class=\"zh\">会</span> đứng <b>trước động từ</b>, cho biết người ta <b>biết làm</b> việc gì đó vì <b>đã học qua</b>: <span class=\"zh\">我会做饭。</span></li><li>Phủ định dùng <span class=\"zh\">不会</span>; câu hỏi thêm <span class=\"zh\">吗</span> hoặc dùng dạng chính phản <span class=\"zh\">会不会</span>.</li><li>Trả lời được gọn lỏn bằng <span class=\"zh\">会</span> hoặc <span class=\"zh\">不会</span>, không cần nhắc lại động từ phía sau.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我会做饭。</span>　·　phủ định: <span class=\"zh\">我不会做饭。</span></p>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">会</span> phải là <b>động từ</b>, không chen <span class=\"zh\">很</span> hay <span class=\"zh\">是</span> vào giữa: nói <span class=\"zh\">我会做饭</span>, <b>không</b> nói <span class=\"zh\">我会很做饭</span>.","examples":[{"zh":"你会做饭吗？","py":"Nǐ huì zuò fàn ma?","vi":"Bạn biết nấu ăn không?"},{"zh":"我会做面条儿。","py":"Wǒ huì zuò miàntiáor.","vi":"Tôi biết nấu mì."},{"zh":"我不会做菜。","py":"Wǒ bú huì zuò cài.","vi":"Tôi không biết nấu món ăn."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — hỏi nhau hôm nay ngày mấy","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"今天几号？","py":"Jīntiān jǐ hào?","vi":"Hôm nay ngày mấy?"},{"speaker":"明","name":"Lưu Minh","zh":"今天9月8号。","py":"Jīntiān jiǔ yuè bā hào.","vi":"Hôm nay ngày 8 tháng 9."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"星期几？","py":"Xīngqī jǐ?","vi":"Thứ mấy?"},{"speaker":"明","name":"Lưu Minh","zh":"星期日。今天我休息。","py":"Xīngqīrì. Jīntiān wǒ xiūxi.","vi":"Chủ Nhật. Hôm nay mình được nghỉ."}]},{"titleZh":"课文二 · 在公司里","titleVi":"Ở công ty — hỏi nhau chuyện nấu ăn","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你会做饭吗？","py":"Nǐ huì zuò fàn ma?","vi":"Bạn biết nấu ăn không?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我会做。","py":"Wǒ huì zuò.","vi":"Mình biết nấu chứ."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你会做什么？","py":"Nǐ huì zuò shénme?","vi":"Bạn biết nấu món gì?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","py":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","vi":"Mình biết làm mì sợi, sủi cảo, cũng nấu được vài món ăn. Chủ Nhật mình cũng tự nấu."}]},{"titleZh":"课文三 · 在公司里","titleVi":"Tan làm — khoe chiếc máy tính mới","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"同乐，下班吗？","py":"Tónglè, xiàbān ma?","vi":"Đồng Lạc, tan làm rồi à?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"下班。","py":"Xiàbān.","vi":"Ừ, tan làm rồi."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"这是你的新电脑吗？","py":"Zhè shì nǐ de xīn diànnǎo ma?","vi":"Đây là máy tính mới của bạn à?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"是的，是我的新电脑。","py":"Shì de, shì wǒ de xīn diànnǎo.","vi":"Đúng rồi, máy tính mới của mình đấy."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"真好看！","py":"Zhēn hǎokàn!","vi":"Đẹp thật đấy!"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我也很喜欢它。","py":"Wǒ yě hěn xǐhuan tā.","vi":"Mình cũng rất thích nó."}]}]},"extra":[],"activity":{"act":[{"zh":"小组游戏","py":"xiǎozǔ yóuxì","tag":"Trò chơi nhóm","mean":"Trò chơi giành trả lời \"会不会\"","q":{"zh":"一个人拿着词语卡片，询问其他人会不会做这件事，其他人抢答。抢答最少者成为下一轮的提问者。","py":"Yí gè rén názhe cíyǔ kǎpiàn, xúnwèn qítā rén huì bu huì zuò zhè jiàn shì, qítā rén qiǎngdá. Qiǎngdá zuì shǎo zhě chéngwéi xià yì lún de tíwènzhě.","vi":"Một người cầm thẻ từ, hỏi mọi người có biết làm việc đó không, mọi người giành trả lời. Ai trả lời ít nhất sẽ làm người hỏi vòng sau."},"items":[{"lines":[{"who":"A","zh":"你们会做饭吗？","py":"Nǐmen huì zuò fàn ma?","vi":"Các bạn có biết nấu cơm không?"},{"who":"B","zh":"我会。","py":"Wǒ huì.","vi":"Mình biết."}]},{"lines":[{"who":"A","zh":"你们会做这个菜吗？","py":"Nǐmen huì zuò zhège cài ma?","vi":"Các bạn có biết nấu món này không?"},{"who":"C","zh":"我不会做。","py":"Wǒ bú huì zuò.","vi":"Mình không biết nấu."}]},{"lines":[{"who":"A","zh":"你们会做饺子吗？","py":"Nǐmen huì zuò jiǎozi ma?","vi":"Các bạn có biết làm sủi cảo không?"},{"who":"D","zh":"我会做饺子，也会做面条儿。","py":"Wǒ huì zuò jiǎozi, yě huì zuò miàntiáor.","vi":"Mình biết làm sủi cảo, cũng biết nấu mì."}]}]}],"speak":[]}},{"id":"k1v3-b06","courseId":"k1v3","order":6,"title":"Số điện thoại của bạn là bao nhiêu?","titleZh":"你的手机号是多少？","titlePy":"nǐ de shǒujī hào shì duōshao","vocab":[{"stt":1,"hanzi":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","pos":"Danh từ","meaning":"điện thoại di động","comps":"手机号 (số di động), 买手机 (mua điện thoại)","example":{"zh":"这是我的手机。","py":"Zhè shì wǒ de shǒujī.","vi":"Đây là điện thoại của mình."}},{"stt":2,"hanzi":"电话","pinyin":"diànhuà","hanviet":"Điện thoại","pos":"Danh từ","meaning":"điện thoại; cuộc gọi","comps":"打电话 (gọi điện), 电话号 (số điện thoại)","example":{"zh":"你的电话是多少？","py":"Nǐ de diànhuà shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?"}},{"stt":3,"hanzi":"号","pinyin":"hào","hanviet":"Hiệu","pos":"Danh từ","meaning":"số (số điện thoại, số phòng…)","comps":"手机号 (số di động), 八号 (mồng tám)","example":{"zh":"你的手机号是多少？","py":"Nǐ de shǒujīhào shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?"}},{"stt":4,"hanzi":"明天","pinyin":"míngtiān","hanviet":"Minh thiên","pos":"Danh từ","meaning":"ngày mai","comps":"明天见 (mai gặp lại), 明天下午 (chiều mai)","example":{"zh":"明天我想去超市。","py":"Míngtiān wǒ xiǎng qù chāoshì.","vi":"Ngày mai mình muốn đi siêu thị."}},{"stt":5,"hanzi":"去","pinyin":"qù","hanviet":"Khứ","pos":"Động từ","meaning":"đi, đi đến","comps":"去哪儿 (đi đâu), 去超市 (đi siêu thị)","example":{"zh":"明天你去哪儿？","py":"Míngtiān nǐ qù nǎr?","vi":"Ngày mai bạn đi đâu?"}},{"stt":6,"hanzi":"哪儿","pinyin":"nǎr","hanviet":"Na nhi","pos":"Đại từ nghi vấn","meaning":"ở đâu, chỗ nào","comps":"去哪儿 (đi đâu), 在哪儿 (ở đâu)","example":{"zh":"你想去哪儿吃晚饭？","py":"Nǐ xiǎng qù nǎr chī wǎnfàn?","vi":"Bạn muốn đi đâu ăn tối?"}},{"stt":7,"hanzi":"想","pinyin":"xiǎng","hanviet":"Tưởng","pos":"Động từ năng nguyện","meaning":"muốn (mong muốn, dự định)","comps":"想去 (muốn đi), 想吃 (muốn ăn)","example":{"zh":"我想吃包子。","py":"Wǒ xiǎng chī bāozi.","vi":"Mình muốn ăn bánh bao."}},{"stt":8,"hanzi":"超市","pinyin":"chāoshì","hanviet":"Siêu thị","pos":"Danh từ","meaning":"siêu thị","comps":"去超市 (đi siêu thị), 大超市 (siêu thị lớn)","example":{"zh":"我去超市买东西。","py":"Wǒ qù chāoshì mǎi dōngxi.","vi":"Mình đi siêu thị mua đồ."}},{"stt":9,"hanzi":"买","pinyin":"mǎi","hanviet":"Mãi","pos":"Động từ","meaning":"mua (↔ 卖 mài: bán)","comps":"买东西 (mua đồ), 买牛奶 (mua sữa)","example":{"zh":"我想买些牛奶。","py":"Wǒ xiǎng mǎi xiē niúnǎi.","vi":"Mình muốn mua ít sữa."}},{"stt":10,"hanzi":"东西","pinyin":"dōngxi","hanviet":"Đông tây","pos":"Danh từ","meaning":"đồ, đồ đạc, thứ","comps":"买东西 (mua đồ), 好东西 (thứ tốt)","example":{"zh":"那边的东西非常好。","py":"Nàbiān de dōngxi fēicháng hǎo.","vi":"Đồ bên kia rất tốt."}},{"stt":11,"hanzi":"些","pinyin":"xiē","hanviet":"Ta","pos":"Lượng từ","meaning":"một ít, vài","comps":"一些 (một ít), 这些 (những cái này)","example":{"zh":"这些东西非常好。","py":"Zhèxiē dōngxi fēicháng hǎo.","vi":"Mấy thứ này rất tốt."}},{"stt":12,"hanzi":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu nãi","pos":"Danh từ","meaning":"sữa bò","comps":"买牛奶 (mua sữa), 一些牛奶 (một ít sữa)","example":{"zh":"超市的牛奶非常好。","py":"Chāoshì de niúnǎi fēicháng hǎo.","vi":"Sữa ở siêu thị rất ngon."}},{"stt":13,"hanzi":"吃","pinyin":"chī","hanviet":"Ngật","pos":"Động từ","meaning":"ăn","comps":"吃饭 (ăn cơm), 吃包子 (ăn bánh bao)","example":{"zh":"我们去哪儿吃晚饭？","py":"Wǒmen qù nǎr chī wǎnfàn?","vi":"Chúng ta đi đâu ăn tối?"}},{"stt":14,"hanzi":"晚饭","pinyin":"wǎnfàn","hanviet":"Vãn phạn","pos":"Danh từ","meaning":"bữa tối, cơm tối","comps":"吃晚饭 (ăn tối), 做晚饭 (nấu cơm tối)","example":{"zh":"晚饭我想吃包子。","py":"Wǎnfàn wǒ xiǎng chī bāozi.","vi":"Bữa tối mình muốn ăn bánh bao."}},{"stt":15,"hanzi":"那边","pinyin":"nàbiān","hanviet":"Na biên","pos":"Đại từ","meaning":"đằng kia (↔ 这边)","comps":"这边 (đằng này), 那边的 (của đằng kia)","example":{"zh":"那边的包子非常好吃。","py":"Nàbiān de bāozi fēicháng hǎochī.","vi":"Bánh bao đằng kia rất ngon."}},{"stt":16,"hanzi":"包子","pinyin":"bāozi","hanviet":"Bao tử","pos":"Danh từ","meaning":"bánh bao","comps":"吃包子 (ăn bánh bao), 买包子 (mua bánh bao)","example":{"zh":"这些包子非常好吃。","py":"Zhèxiē bāozi fēicháng hǎochī.","vi":"Mấy cái bánh bao này rất ngon."}},{"stt":17,"hanzi":"非常","pinyin":"fēicháng","hanviet":"Phi thường","pos":"Phó từ","meaning":"rất, vô cùng","comps":"非常好 (rất tốt), 非常好吃 (rất ngon)","example":{"zh":"米饭非常好吃。","py":"Mǐfàn fēicháng hǎochī.","vi":"Cơm rất ngon."}},{"stt":18,"hanzi":"好吃","pinyin":"hǎochī","hanviet":"Hảo ngật","pos":"Tính từ","meaning":"ngon (đồ ăn)","comps":"很好吃 (rất ngon), 不好吃 (không ngon)","example":{"zh":"西安饭店的包子好吃吗？","py":"Xī'ān Fàndiàn de bāozi hǎochī ma?","vi":"Bánh bao nhà hàng Tây An ngon không?"}},{"stt":19,"hanzi":"米饭","pinyin":"mǐfàn","hanviet":"Mễ phạn","pos":"Danh từ","meaning":"cơm (gạo tẻ)","comps":"吃米饭 (ăn cơm), 一些米饭 (một ít cơm)","example":{"zh":"我不想吃米饭。","py":"Wǒ bù xiǎng chī mǐfàn.","vi":"Mình không muốn ăn cơm."}},{"stt":20,"hanzi":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","pos":"Đại từ nghi vấn","meaning":"thế nào, làm sao","comps":"怎么去 (đi thế nào), 怎么吃 (ăn thế nào)","example":{"zh":"我们怎么去超市？","py":"Wǒmen zěnme qù chāoshì?","vi":"Chúng ta đi siêu thị bằng gì?"}},{"stt":21,"hanzi":"坐","pinyin":"zuò","hanviet":"Toạ","pos":"Động từ","meaning":"ngồi; đi bằng (xe)","comps":"请坐 (mời ngồi), 坐出租车 (đi taxi)","example":{"zh":"我们坐出租车去。","py":"Wǒmen zuò chūzūchē qù.","vi":"Chúng ta đi bằng taxi."}},{"stt":22,"hanzi":"出租车","pinyin":"chūzūchē","hanviet":"Xuất tô xa","pos":"Danh từ","meaning":"xe taxi","comps":"坐出租车 (đi taxi), 一个出租车 (một chiếc taxi)","example":{"zh":"坐出租车去饭店。","py":"Zuò chūzūchē qù fàndiàn.","vi":"Đi taxi tới nhà hàng."}},{"stt":23,"hanzi":"西安饭店","pinyin":"Xī'ān Fàndiàn","hanviet":"Tây An phạn điếm","pos":"Danh từ riêng","meaning":"nhà hàng Tây An","comps":"去西安饭店 (đi nhà hàng Tây An)","example":{"zh":"明天我想去西安饭店。","py":"Míngtiān wǒ xiǎng qù Xī'ān Fàndiàn.","vi":"Ngày mai mình muốn đến nhà hàng Tây An."}}],"hanzi":[{"char":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","chars":["手","机"],"story":"手 là chữ tượng hình, vẽ bàn tay xoè năm ngón. 机 (機) = 木 (gỗ) + 几 jī chỉ âm, vốn chỉ cỗ máy làm bằng gỗ. 手机 nghĩa đen là \"cái máy cầm trên tay\" — điện thoại di động."},{"char":"电话","pinyin":"diànhuà","hanviet":"Điện thoại","chars":["电","话"],"story":"电 (電) vốn vẽ tia chớp loé ra từ đám mây, nay chỉ điện. 话 (話) = 讠 (bộ ngôn, lời nói) + 舌 (cái lưỡi). 电话 = \"lời nói chạy bằng điện\"."},{"char":"号","pinyin":"hào","hanviet":"Hiệu","chars":["号"],"story":"号 (號) gồm 口 (miệng) ở trên và 丂 (hơi thoát ra) ở dưới, nghĩa gốc là kêu to, hô hào. Về sau mượn dùng chỉ số hiệu, thứ tự — nên có cả nghĩa \"số\" lẫn \"ngày trong tháng\"."},{"char":"明天","pinyin":"míngtiān","hanviet":"Minh thiên","chars":["明","天"],"story":"明 = 日 (mặt trời) + 月 (mặt trăng) ghép lại thành \"sáng\". 天 vẽ một người dang hai tay, thêm vạch ngang trên đầu chỉ bầu trời, từ đó có nghĩa \"ngày\". 明天 = ngày sáng sắp tới, tức ngày mai."},{"char":"去","pinyin":"qù","hanviet":"Khứ","chars":["去"],"story":"去 chữ cổ vẽ một người (phần trên) đang rời khỏi cửa hang, cửa nhà (phần dưới 厶). Từ hình ảnh bỏ đi khỏi một chỗ mà thành nghĩa \"đi, đi tới\"."},{"char":"哪儿","pinyin":"nǎr","hanviet":"Na nhi","chars":["哪","儿"],"story":"哪 = 口 (miệng, báo đây là tiếng hỏi phát ra từ miệng) + 那 nà chỉ âm — một chữ hình thanh điển hình. 儿 là hậu tố nhi hoá của khẩu ngữ Bắc Kinh, không mang nghĩa riêng."},{"char":"想","pinyin":"xiǎng","hanviet":"Tưởng","chars":["想"],"story":"想 = 相 xiāng (gồm 木 cây và 目 mắt — mắt ngắm nhìn, chỉ âm) + 心 (trái tim) ở dưới. Việc diễn ra trong lòng: nghĩ ngợi, nhớ nhung, rồi thành \"muốn\"."},{"char":"超市","pinyin":"chāoshì","hanviet":"Siêu thị","chars":["超","市"],"story":"超 = 走 (bộ tẩu, chạy) + 召 chỉ âm, nghĩa là vượt qua, siêu việt. 市 vốn chỉ cái chợ. 超市 là bản dịch của \"supermarket\": cái chợ vượt trội hơn chợ thường."},{"char":"买","pinyin":"mǎi","hanviet":"Mãi","chars":["买"],"story":"买 (買) = 网 (cái lưới, viết gọn ở trên) + 贝 (vỏ sò — tiền của người xưa): bỏ tiền ra gom đồ vào lưới. Chữ ngược lại 卖 (賣) mài \"bán\" chỉ thêm một nét ở trên đầu — nhớ kỹ 买 mǎi thanh 3 là mua, 卖 mài thanh 4 là bán."},{"char":"东西","pinyin":"dōngxi","hanviet":"Đông tây","chars":["东","西"],"story":"东 (東) vẽ mặt trời nhô lên sau thân cây — hướng đông; 西 vẽ cái tổ chim, lúc chim về tổ là mặt trời lặn ở hướng tây. Người xưa đi chợ đông chợ tây mua đồ, nên 东西 (đọc thanh nhẹ dōngxi) thành nghĩa \"đồ vật\"."},{"char":"些","pinyin":"xiē","hanviet":"Ta","chars":["些"],"story":"些 = 此 cǐ (chỉ âm) ở trên + 二 ở dưới. Con số không rõ ràng, chỉ chừng vài ba cái — nên 些 nghĩa là \"một ít, vài\", luôn đi sau 这/那/一."},{"char":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu nãi","chars":["牛","奶"],"story":"牛 vẽ đầu con bò nhìn từ trước, hai cái sừng cong lên. 奶 = 女 (bộ nữ) + 乃 chỉ âm nǎi, chỉ bầu sữa mẹ. 牛奶 là sữa lấy từ con bò."},{"char":"吃","pinyin":"chī","hanviet":"Ngật","chars":["吃"],"story":"吃 = 口 (cái miệng, chỉ nghĩa) + 乞 qǐ (chỉ âm). Hễ thấy bộ 口 bên trái là biết chữ liên quan tới miệng — ở đây là việc đưa thức ăn vào miệng."},{"char":"晚饭","pinyin":"wǎnfàn","hanviet":"Vãn phạn","chars":["晚","饭"],"story":"晚 = 日 (mặt trời) + 免 chỉ âm: lúc mặt trời đã khuất, tức buổi tối, muộn. 饭 (飯) = 饣 (bộ thực, viết gọn của 食) + 反 chỉ âm. 晚饭 là bữa cơm buổi tối."},{"char":"那边","pinyin":"nàbiān","hanviet":"Na biên","chars":["那","边"],"story":"那 nghĩa là \"kia, ấy\". 边 (邊) có bộ 辶 (bộ sước, chỉ sự đi lại) — chỗ đi tới rìa, thành nghĩa \"bên, phía\". 那边 đằng kia, đối lại với 这边 zhèbian đằng này (这 cũng có bộ 辶)."},{"char":"包子","pinyin":"bāozi","hanviet":"Bao tử","chars":["包","子"],"story":"包 vẽ cái bào thai được bọc trong bụng mẹ, nên có nghĩa \"bọc, gói\". 子 ở đây chỉ là hậu tố danh từ đọc thanh nhẹ. Cục bột bọc lấy nhân bên trong chính là cái bánh bao."},{"char":"非常","pinyin":"fēicháng","hanviet":"Phi thường","chars":["非","常"],"story":"非 vẽ hai cánh chim xoè ra ngược chiều nhau, nghĩa là \"trái, không phải\". 常 = 尚 (chỉ âm) + 巾 (khăn vải), nghĩa là thường, bình thường. 非常 = \"không bình thường\" → khác thường, rất."},{"char":"好吃","pinyin":"hǎochī","hanviet":"Hảo ngật","chars":["好","吃"],"story":"好 = 女 (phụ nữ) + 子 (đứa con), người xưa cho rằng như thế là điều tốt đẹp. 好 đứng trước một động từ cảm giác thì thành \"làm việc đó thấy dễ chịu\": 好吃 ngon, 好看 đẹp, 好听 hay."},{"char":"米饭","pinyin":"mǐfàn","hanviet":"Mễ phạn","chars":["米","饭"],"story":"米 vẽ những hạt gạo rơi rải hai bên một cây đòn xay. 饭 (飯) = 饣 (bộ thực) + 反 chỉ âm. 米饭 là cơm nấu từ gạo tẻ, phân biệt với 面条 mì sợi."},{"char":"怎么","pinyin":"zěnme","hanviet":"Chẩm ma","chars":["怎","么"],"story":"怎 = 乍 zhà (chỉ âm) + 心 (trái tim) ở dưới: trong lòng đang thắc mắc \"thế nào đây?\". 么 (麼) là hậu tố nghi vấn đọc thanh nhẹ, cũng gặp trong 什么."},{"char":"坐","pinyin":"zuò","hanviet":"Toạ","chars":["坐"],"story":"坐 vẽ hai chữ 人 (hai người) ngồi đối nhau trên chữ 土 (mặt đất). Nghĩa gốc là ngồi; vì lên xe cũng là ngồi nên 坐 mở rộng thành \"đi bằng phương tiện\": 坐出租车, 坐飞机."},{"char":"出租车","pinyin":"chūzūchē","hanviet":"Xuất tô xa","chars":["出","租","车"],"story":"出 vẽ bàn chân bước ra khỏi cửa hang, nghĩa là \"ra\". 租 = 禾 (cây lúa) + 且 chỉ âm — xưa thuê ruộng trả bằng lúa, nên 租 là thuê. 车 (車) vẽ chiếc xe nhìn từ trên xuống. 出租车 = \"xe cho thuê\" = taxi."},{"char":"西安饭店","pinyin":"Xī'ān Fàndiàn","hanviet":"Tây An phạn điếm","chars":["西","安","饭","店"],"story":"西安 là cố đô nghìn năm của Trung Quốc: 西 (hướng tây) + 安 = 宀 (mái nhà) + 女 (phụ nữ) — trong nhà yên ổn. 饭店 = 饭 (cơm) + 店 (cửa hàng), là nhà hàng, tiệm ăn."}],"grammar":[{"title":"Động từ năng nguyện 想","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>想</b><small>muốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Muốn làm gì</p><ul><li>Động từ năng nguyện (<span class=\"zh\">能愿动词</span>) luôn đứng <b>ngay trước động từ chính</b>, không bao giờ đứng một mình làm vị ngữ.</li><li><span class=\"zh\">想</span> ở bài này = <b>mong muốn, dự định</b> (\"muốn\"), khác <span class=\"zh\">想</span> ở <b>Bài 3</b> là động từ \"nhớ\" (<span class=\"zh\">我很想你</span>).</li><li>Phủ định thêm <span class=\"zh\">不</span> ở trước: <span class=\"zh\">不想去</span>　·　<span class=\"zh\">不想吃包子</span>. Hỏi bằng <span class=\"zh\">吗</span>: <span class=\"zh\">你想去超市吗？</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我想吃包子。</span> = Mình muốn ăn bánh bao.　·　phủ định: <span class=\"zh\">我哥哥不想休息。</span></p>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">想</span> phải là <b>động từ</b>, tuyệt đối <b>không thêm</b> <span class=\"zh\">是</span>: nói <span class=\"zh\">我想吃米饭</span> ✓, không nói <span class=\"zh\">我想是吃米饭</span> ✗.","examples":[{"zh":"我想去超市买东西。","py":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vi":"Mình muốn đi siêu thị mua đồ."},{"zh":"我想去超市。","py":"Wǒ xiǎng qù chāoshì.","vi":"Tôi muốn đi siêu thị."},{"zh":"我哥哥不想休息。","py":"Wǒ gēge bù xiǎng xiūxi.","vi":"Anh trai tôi không muốn nghỉ."}],"exercises":[]},{"title":"Câu liên động (连动句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词1 + 宾语</b><small>việc làm trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>动词2 + 宾语</b><small>việc làm sau</small></span></div>","summary":"<p class=\"gr-lead\">Hai động từ nối tiếp</p><ul><li>Một chủ ngữ làm <b>hai (hoặc nhiều) hành động nối tiếp</b>, viết liền nhau, <b>không dùng liên từ</b> nào ở giữa — khác hẳn tiếng Việt hay thêm \"rồi\", \"để\".</li><li>Thứ tự các động từ đi <b>đúng theo trình tự thời gian</b>. Động từ thứ hai thường là <b>mục đích</b> của động từ thứ nhất: <span class=\"zh\">去超市买东西</span> = đi siêu thị <b>để</b> mua đồ.</li><li>Nói phương tiện đi lại thì <span class=\"zh\">坐</span> + xe đứng <b>trước</b> động từ chính: <span class=\"zh\">坐出租车去西安饭店</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我去超市买东西。</span> = Mình đi siêu thị mua đồ.　·　<span class=\"zh\">坐出租车去</span> = đi bằng taxi.</p>","note":"<b>Lưu ý:</b> Từ phủ định <span class=\"zh\">不</span> và động từ năng nguyện <span class=\"zh\">想</span> đặt <b>trước động từ THỨ NHẤT</b>: <span class=\"zh\">我想去超市买东西</span> ✓, không nói <span class=\"zh\">我去超市想买东西</span> ✗.","examples":[{"zh":"我们坐出租车去吃晚饭。","py":"Wǒmen zuò chūzūchē qù chī wǎnfàn.","vi":"Chúng ta đi taxi đến ăn tối."},{"zh":"我想去超市买东西。","py":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vi":"Tôi muốn đi siêu thị mua đồ. (mục đích)"},{"zh":"我们去西安饭店吃晚饭。","py":"Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn.","vi":"Chúng ta đến khách sạn Tây An ăn tối. (mục đích)"},{"zh":"我们坐出租车去西安饭店。","py":"Wǒmen zuò chūzūchē qù Xī'ān Fàndiàn.","vi":"Chúng ta đi taxi đến khách sạn Tây An. (cách thức)"},{"zh":"她坐出租车去超市。","py":"Tā zuò chūzūchē qù chāoshì.","vi":"Cô ấy đi taxi đến siêu thị. (cách thức)"}],"exercises":[]},{"title":"Đại từ nghi vấn 怎么","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>怎么</b><small>bằng cách nào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi cách thức</p><ul><li><span class=\"zh\">怎么</span> hỏi <b>cách thức</b> \"làm thế nào, bằng cách nào\", đặt <b>ngay trước động từ</b>; trật tự phần còn lại của câu <b>giữ nguyên</b> như câu trần thuật.</li><li>Trả lời bằng <b>chính cách làm</b>, không cần lặp lại <span class=\"zh\">怎么</span>: <span class=\"zh\">坐出租车去</span>　·　<span class=\"zh\">这个字怎么写？</span></li><li>Đứng trước <span class=\"zh\">不</span> hoặc một trạng thái thì <span class=\"zh\">怎么</span> mang nghĩa <b>hỏi lý do</b> \"sao lại…\": <span class=\"zh\">你怎么不吃包子？</span> = Sao con không ăn bánh bao?</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我们怎么去？</span> —— <span class=\"zh\">坐出租车去。</span> = Đi bằng gì? — Đi taxi.</p>","note":"<b>Lưu ý:</b> Câu đã có <span class=\"zh\">怎么</span> thì <b>không thêm</b> <span class=\"zh\">吗</span> ở cuối. Và đừng lẫn <span class=\"zh\">怎么</span> (hỏi cách làm) với <span class=\"zh\">怎么样</span> (hỏi nhận xét, \"thế nào\").","examples":[{"zh":"我们怎么去西安饭店？","py":"Wǒmen zěnme qù Xī'ān Fàndiàn?","vi":"Chúng ta đến nhà hàng Tây An bằng gì?"},{"zh":"我们怎么去？","py":"Wǒmen zěnme qù?","vi":"Chúng ta đi bằng gì?"},{"zh":"她怎么去超市？","py":"Tā zěnme qù chāoshì?","vi":"Cô ấy đi siêu thị bằng gì?"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai bạn trao đổi số điện thoại","lines":[{"speaker":"文","name":"Lý Văn","zh":"家月，你的手机号是多少？","py":"Jiāyuè, nǐ de shǒujīhào shì duōshao?","vi":"Gia Nguyệt ơi, số điện thoại của cậu là bao nhiêu?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我的手机号是+33 601493190。","py":"Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","vi":"Số điện thoại của mình là +33 601493190."},{"speaker":"文","name":"Lý Văn","zh":"我的手机号是+86 13552721160。","py":"Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","vi":"Số điện thoại của mình là +86 13552721160."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"好的。","py":"Hǎo de.","vi":"Được rồi."}]},{"titleZh":"课文二","titleVi":"Hỏi nhau mai đi đâu, mua gì","lines":[{"speaker":"中","name":"Trần Thiên Trung","zh":"家月，明天你去哪儿？","py":"Jiāyuè, míngtiān nǐ qù nǎr?","vi":"Gia Nguyệt ơi, ngày mai cậu đi đâu?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我想去超市买东西。","py":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","vi":"Mình muốn đi siêu thị mua đồ."},{"speaker":"中","name":"Trần Thiên Trung","zh":"你去超市买什么？","py":"Nǐ qù chāoshì mǎi shénme?","vi":"Cậu đi siêu thị mua gì thế?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我想买些牛奶。","py":"Wǒ xiǎng mǎi xiē niúnǎi.","vi":"Mình muốn mua ít sữa."}]},{"titleZh":"课文三","titleVi":"Cả nhà bàn Chủ Nhật đi đâu ăn tối","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"星期天我们去哪儿吃晚饭？","py":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","vi":"Chủ Nhật cả nhà mình đi đâu ăn tối đây?"},{"speaker":"明","name":"Lưu Minh","zh":"我还想去西安饭店。","py":"Wǒ hái xiǎng qù Xī'ān Fàndiàn.","vi":"Anh vẫn muốn đến nhà hàng Tây An."},{"speaker":"雪","name":"Lưu Tiểu Tuyết","zh":"那边的包子非常好吃，我想吃包子。","py":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","vi":"Bánh bao đằng đó ngon lắm, con muốn ăn bánh bao."},{"speaker":"明","name":"Lưu Tiểu Minh","zh":"妈妈，我想吃米饭，不想吃包子。","py":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","vi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"好的。我们怎么去？","py":"Hǎo de. Wǒmen zěnme qù?","vi":"Được rồi, vậy nhà mình đi bằng gì?"},{"speaker":"明","name":"Lưu Minh","zh":"坐出租车去。","py":"Zuò chūzūchē qù.","vi":"Đi taxi thôi."}]}]},"extra":[],"activity":{"act":[{"zh":"填写表格","py":"tiánxiě biǎogé","tag":"Điền bảng","mean":"Điền bảng · Bữa sáng trong tuần","q":{"zh":"两人一组，填写星期一、星期二和星期六早饭吃什么，填好后分享。","py":"Liǎng rén yì zǔ, tiánxiě Xīngqīyī, Xīngqī'èr hé Xīngqīliù zǎofàn chī shénme, tiánhǎo hòu fēnxiǎng.","vi":"Hai người một nhóm, điền xem sáng thứ hai, thứ ba và thứ bảy ăn gì, điền xong thì chia sẻ."},"items":[{"zh":"A 包子　B 面条儿　C 饺子　D 米饭","py":"A bāozi　B miàntiáor　C jiǎozi　D mǐfàn","vi":"A bánh bao · B mì · C sủi cảo · D cơm"},{"zh":"星期一早饭我吃饺子。","py":"Xīngqīyī zǎofàn wǒ chī jiǎozi.","vi":"Bữa sáng thứ hai mình ăn sủi cảo."},{"zh":"星期二早饭我吃包子。","py":"Xīngqī'èr zǎofàn wǒ chī bāozi.","vi":"Bữa sáng thứ ba mình ăn bánh bao."},{"zh":"星期六早饭我吃面条儿。","py":"Xīngqīliù zǎofàn wǒ chī miàntiáor.","vi":"Bữa sáng thứ bảy mình ăn mì."},{"zh":"你星期一早饭吃什么？","py":"Nǐ Xīngqīyī zǎofàn chī shénme?","vi":"Bữa sáng thứ hai bạn ăn gì?"}]}],"speak":[]},"review":{"range":"4–6","rows":[{"l":4,"zh":"\"有\"字句（1）","vi":"Câu chữ 有 (1)","ex":{"zh":"她有十个学生。","py":"Tā yǒu shí gè xuéshēng.","vi":"Cô ấy có mười học sinh."}},{"l":4,"zh":"数字的表达","vi":"Cách nói số","ex":{"zh":"二十二，九百九十九","py":"èrshí'èr, jiǔbǎi jiǔshíjiǔ","vi":"22, 999"}},{"l":4,"zh":"语气助词\"呢\"（1）","vi":"Trợ từ ngữ khí 呢 (1)","ex":{"zh":"我是学生，你呢？","py":"Wǒ shì xuéshēng, nǐ ne?","vi":"Mình là học sinh, còn bạn?"}},{"l":4,"zh":"名量词和名量结构","vi":"Lượng từ và cấu trúc Số + Lượng","ex":{"zh":"一个，五口人","py":"yí gè, wǔ kǒu rén","vi":"một cái, (nhà có) năm người"}},{"l":4,"zh":"问年龄时，对不同年龄的人使用不同的询问方式。","vi":"Hỏi tuổi người ở độ tuổi khác nhau thì hỏi khác nhau","ex":{"zh":"你女儿今年几岁？· 您多大？","py":"Nǐ nǚ'ér jīnnián jǐ suì? · Nín duō dà?","vi":"Con gái chị năm nay mấy tuổi? · Bác bao nhiêu tuổi ạ?"}},{"l":5,"zh":"时间的表达（1）","vi":"Cách nói thời gian (1)","ex":{"zh":"2025年1月1日，星期三","py":"èr líng èr wǔ nián yī yuè yī rì, Xīngqīsān","vi":"Thứ tư, ngày 1 tháng 1 năm 2025"}},{"l":5,"zh":"名词谓语句","vi":"Câu vị ngữ danh từ","ex":{"zh":"今天星期四。","py":"Jīntiān Xīngqīsì.","vi":"Hôm nay thứ năm."}},{"l":5,"zh":"能愿动词\"会\"","vi":"Động từ năng nguyện 会","ex":{"zh":"我会做饭。","py":"Wǒ huì zuò fàn.","vi":"Tôi biết nấu cơm."}},{"l":6,"zh":"能愿动词\"想\"","vi":"Động từ năng nguyện 想","ex":{"zh":"我想去超市。","py":"Wǒ xiǎng qù chāoshì.","vi":"Tôi muốn đi siêu thị."}},{"l":6,"zh":"连动句（1）","vi":"Câu liên động (1)","ex":{"zh":"我去超市买东西。","py":"Wǒ qù chāoshì mǎi dōngxi.","vi":"Tôi đi siêu thị mua đồ."}},{"l":6,"zh":"疑问代词\"怎么\"","vi":"Đại từ nghi vấn 怎么","ex":{"zh":"你怎么去超市？","py":"Nǐ zěnme qù chāoshì?","vi":"Bạn đi siêu thị bằng gì?"}}]}},{"id":"k1v3-b07","courseId":"k1v3","order":7,"title":"Sáu rưỡi tối tôi tan làm","titleZh":"我晚上六点半下班","titlePy":"wǒ wǎnshang liù diǎn bàn xiàbān","vocab":[{"stt":1,"hanzi":"现在","pinyin":"xiànzài","hanviet":"Hiện tại","pos":"Danh từ","meaning":"bây giờ, hiện nay","comps":"现在几点 (bây giờ mấy giờ), 现在去 (đi bây giờ)","example":{"zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ mấy giờ rồi?"}},{"stt":2,"hanzi":"点","pinyin":"diǎn","hanviet":"Điểm","pos":"Lượng từ","meaning":"giờ (chỉ thời điểm)","comps":"八点 (tám giờ), 几点 (mấy giờ)","example":{"zh":"我八点去医院。","py":"Wǒ bā diǎn qù yīyuàn.","vi":"Tám giờ mình đi bệnh viện."}},{"stt":3,"hanzi":"早上","pinyin":"zǎoshang","hanviet":"Tảo thượng","pos":"Danh từ","meaning":"sáng sớm (5h–9h)","comps":"早上好 (chào buổi sáng), 早上八点 (tám giờ sáng)","example":{"zh":"早上八点四十。","py":"Zǎoshang bā diǎn sìshí.","vi":"Tám giờ bốn mươi sáng."}},{"stt":4,"hanzi":"上午","pinyin":"shàngwǔ","hanviet":"Thượng ngọ","pos":"Danh từ","meaning":"buổi sáng (9h–12h)","comps":"上午有课 (sáng có tiết), 明天上午 (sáng mai)","example":{"zh":"我上午十点有课。","py":"Wǒ shàngwǔ shí diǎn yǒu kè.","vi":"Mười giờ sáng mình có tiết."}},{"stt":5,"hanzi":"分","pinyin":"fēn","hanviet":"Phân","pos":"Lượng từ","meaning":"phút; hào (tiền)","comps":"十分 (mười phút), 四十分 (bốn mươi phút)","example":{"zh":"现在十点十分。","py":"Xiànzài shí diǎn shí fēn.","vi":"Bây giờ mười giờ mười."}},{"stt":6,"hanzi":"课","pinyin":"kè","hanviet":"Khoá","pos":"Danh từ","meaning":"tiết học, bài học","comps":"有课 (có tiết), 上课 (lên lớp)","example":{"zh":"我下午两点有课。","py":"Wǒ xiàwǔ liǎng diǎn yǒu kè.","vi":"Chiều hai giờ mình có tiết."}},{"stt":7,"hanzi":"下午","pinyin":"xiàwǔ","hanviet":"Hạ ngọ","pos":"Danh từ","meaning":"buổi chiều","comps":"下午见 (chiều gặp), 明天下午 (chiều mai)","example":{"zh":"下午我想去看电影。","py":"Xiàwǔ wǒ xiǎng qù kàn diànyǐng.","vi":"Chiều nay mình muốn đi xem phim."}},{"stt":8,"hanzi":"见","pinyin":"jiàn","hanviet":"Kiến","pos":"Động từ","meaning":"gặp, gặp mặt","comps":"再见 (tạm biệt), 明天见 (mai gặp lại)","example":{"zh":"我们下午两点见。","py":"Wǒmen xiàwǔ liǎng diǎn jiàn.","vi":"Chiều hai giờ chúng mình gặp nhau."}},{"stt":9,"hanzi":"吧","pinyin":"ba","hanviet":"Ba","pos":"Trợ từ","meaning":"trợ từ: đề nghị, rủ","comps":"我们去吧 (mình đi nhé), 你看吧 (bạn xem đi)","example":{"zh":"我们下午两点见吧。","py":"Wǒmen xiàwǔ liǎng diǎn jiàn ba.","vi":"Chiều hai giờ mình gặp nhau nhé."}},{"stt":10,"hanzi":"电影院","pinyin":"diànyǐngyuàn","hanviet":"Điện ảnh viện","pos":"Danh từ","meaning":"rạp chiếu phim","comps":"去电影院 (đi rạp phim), 电影院里 (trong rạp)","example":{"zh":"我想去电影院看电影。","py":"Wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng.","vi":"Mình muốn đi rạp xem phim."}},{"stt":11,"hanzi":"看","pinyin":"kàn","hanviet":"Khán","pos":"Động từ","meaning":"xem, nhìn, đọc","comps":"看电影 (xem phim), 看看 (xem thử)","example":{"zh":"下午你看电影吗？","py":"Xiàwǔ nǐ kàn diànyǐng ma?","vi":"Chiều nay cậu xem phim không?"}},{"stt":12,"hanzi":"电影","pinyin":"diànyǐng","hanviet":"Điện ảnh","pos":"Danh từ","meaning":"phim, bộ phim","comps":"看电影 (xem phim), 中国电影 (phim Trung Quốc)","example":{"zh":"这个电影非常好看。","py":"Zhège diànyǐng fēicháng hǎokàn.","vi":"Bộ phim này rất hay."}},{"stt":13,"hanzi":"事","pinyin":"shì","hanviet":"Sự","pos":"Danh từ","meaning":"việc, chuyện","comps":"有事 (có việc), 没事 (không sao)","example":{"zh":"我下午还有事。","py":"Wǒ xiàwǔ hái yǒu shì.","vi":"Chiều nay mình còn có việc."}},{"stt":14,"hanzi":"上课","pinyin":"shàngkè","hanviet":"Thượng khoá","pos":"Động từ","meaning":"lên lớp, vào học","comps":"去上课 (đi học), 上课呢 (đang học)","example":{"zh":"我下午两点上课。","py":"Wǒ xiàwǔ liǎng diǎn shàngkè.","vi":"Chiều hai giờ mình vào học."}},{"stt":15,"hanzi":"呢","pinyin":"ne","hanviet":"Ni","pos":"Trợ từ","meaning":"… đấy, … cơ (khẳng định sự thật)","comps":"你呢 (còn bạn), 在家呢 (đang ở nhà)","example":{"zh":"你在哪儿呢？","py":"Nǐ zài nǎr ne?","vi":"Bạn đang ở đâu đấy?"}},{"stt":16,"hanzi":"半","pinyin":"bàn","hanviet":"Bán","pos":"Số từ","meaning":"rưỡi; một nửa","comps":"六点半 (sáu rưỡi), 一半 (một nửa)","example":{"zh":"我六点半下班。","py":"Wǒ liù diǎn bàn xiàbān.","vi":"Sáu rưỡi mình tan làm."}},{"stt":17,"hanzi":"下课","pinyin":"xiàkè","hanviet":"Hạ khoá","pos":"Động từ","meaning":"tan học, hết tiết","comps":"四点下课 (bốn giờ tan học), 下课后 (sau giờ học)","example":{"zh":"我四点半下课。","py":"Wǒ sì diǎn bàn xiàkè.","vi":"Bốn rưỡi mình tan học."}},{"stt":18,"hanzi":"在","pinyin":"zài","hanviet":"Tại","pos":"Động từ","meaning":"ở, ở tại","comps":"在家 (ở nhà), 在哪儿 (ở đâu)","example":{"zh":"我在家里呢。","py":"Wǒ zài jiā li ne.","vi":"Mình đang ở nhà."}},{"stt":19,"hanzi":"家","pinyin":"jiā","hanviet":"Gia","pos":"Danh từ","meaning":"nhà, chỗ ở","comps":"家里 (trong nhà), 回家 (về nhà)","example":{"zh":"晚上我在家看电影。","py":"Wǎnshang wǒ zài jiā kàn diànyǐng.","vi":"Buổi tối mình ở nhà xem phim."}},{"stt":20,"hanzi":"里","pinyin":"li / lǐ","hanviet":"Lý","pos":"Danh từ","meaning":"bên trong, trong","comps":"家里 (trong nhà), 店里 (trong cửa hàng)","example":{"zh":"你去店里买些菜吧。","py":"Nǐ qù diàn li mǎi xiē cài ba.","vi":"Bạn ra cửa hàng mua ít rau nhé."}},{"stt":21,"hanzi":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","pos":"Danh từ","meaning":"buổi tối","comps":"晚上好 (chào buổi tối), 晚上六点 (sáu giờ tối)","example":{"zh":"我晚上六点半下班。","py":"Wǒ wǎnshang liù diǎn bàn xiàbān.","vi":"Sáu rưỡi tối mình tan làm."}},{"stt":22,"hanzi":"医院","pinyin":"yīyuàn","hanviet":"Y viện","pos":"Danh từ","meaning":"bệnh viện","comps":"去医院 (đi bệnh viện), 在医院 (ở bệnh viện)","example":{"zh":"我八点去医院上班。","py":"Wǒ bā diǎn qù yīyuàn shàngbān.","vi":"Tám giờ mình đến bệnh viện làm."}},{"stt":23,"hanzi":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","pos":"Động từ","meaning":"đi làm, vào ca","comps":"去上班 (đi làm), 上班呢 (đang làm)","example":{"zh":"早上八点我上班。","py":"Zǎoshang bā diǎn wǒ shàngbān.","vi":"Tám giờ sáng mình vào làm."}},{"stt":24,"hanzi":"店","pinyin":"diàn","hanviet":"Điếm","pos":"Danh từ","meaning":"cửa hàng, tiệm","comps":"店里 (trong cửa hàng), 饭店 (nhà hàng)","example":{"zh":"我想去店里买菜。","py":"Wǒ xiǎng qù diàn li mǎi cài.","vi":"Mình muốn ra cửa hàng mua rau."}},{"stt":25,"hanzi":"菜","pinyin":"cài","hanviet":"Thái","pos":"Danh từ","meaning":"rau, rau xanh","comps":"买菜 (mua rau), 中国菜 (món Trung Quốc)","example":{"zh":"这些菜非常好吃。","py":"Zhèxiē cài fēicháng hǎochī.","vi":"Mấy món này rất ngon."}},{"stt":26,"hanzi":"分钟","pinyin":"fēnzhōng","hanviet":"Phân chung","pos":"Lượng từ","meaning":"phút (chỉ độ dài)","comps":"十分钟 (mười phút), 半分钟 (nửa phút)","example":{"zh":"我十分钟后去。","py":"Wǒ shí fēnzhōng hòu qù.","vi":"Mười phút nữa mình đi."}},{"stt":27,"hanzi":"后","pinyin":"hòu","hanviet":"Hậu","pos":"Danh từ","meaning":"sau, phía sau","comps":"下课后 (sau giờ học), 十分钟后 (mười phút sau)","example":{"zh":"下课后我去看电影。","py":"Xiàkè hòu wǒ qù kàn diànyǐng.","vi":"Tan học xong mình đi xem phim."}}],"hanzi":[{"char":"现在","pinyin":"xiànzài","hanviet":"Hiện tại","chars":["现","在"],"story":"现 (現) = 王 (viết gọn của 玉, viên ngọc) + 见 (nhìn thấy): viên ngọc lộ ra trước mắt, nên nghĩa là \"hiện ra\". 在 = 才 (mầm cây nhú) + 土 (đất) — có mặt ở đó. 现在 là \"cái đang lộ ra lúc này\" — bây giờ."},{"char":"点","pinyin":"diǎn","hanviet":"Điểm","chars":["点"],"story":"点 (點) = 黑 (màu đen) + 占 chỉ âm zhān, nghĩa gốc là \"vết chấm đen\". Kim đồng hồ chỉ vào cái chấm nào thì đọc số ấy, nên 点 thành đơn vị \"giờ\": 八点, 六点."},{"char":"早上","pinyin":"zǎoshang","hanviet":"Tảo thượng","chars":["早","上"],"story":"早 = 日 (mặt trời) đặt trên 十 (vốn vẽ ngọn cây) — mặt trời vừa nhô lên khỏi ngọn cây, tức sớm. 上 vẽ một vạch nằm TRÊN vạch mốc, chỉ phía trên; ở đây chỉ khoảng thời gian. 早上 là lúc sáng sớm."},{"char":"上午","pinyin":"shàngwǔ","hanviet":"Thượng ngọ","chars":["上","午"],"story":"午 là giờ Ngọ trong mười hai địa chi, tức giữa trưa. 上 nghĩa \"trên, trước\", nên 上午 là khoảng TRƯỚC giữa trưa — buổi sáng. Cặp đối lập là 下午 sau giữa trưa."},{"char":"分","pinyin":"fēn","hanviet":"Phân","chars":["分"],"story":"分 = 八 (hai nét toẽ ra hai bên, chỉ sự chia tách) + 刀 (con dao) — lấy dao chia đôi. Từ nghĩa \"chia nhỏ\" mà thành đơn vị nhỏ: phút là phần nhỏ của giờ, hào là phần nhỏ của đồng."},{"char":"课","pinyin":"kè","hanviet":"Khoá","chars":["课"],"story":"课 (課) = 讠 (bộ ngôn, lời nói) + 果 guǒ chỉ âm. Nghĩa gốc là khảo hạch học trò bằng lời, về sau thành bài học, tiết học, môn học."},{"char":"下午","pinyin":"xiàwǔ","hanviet":"Hạ ngọ","chars":["下","午"],"story":"下 vẽ một vạch nằm DƯỚI vạch mốc, ngược hẳn với 上 — chỉ phía dưới, phía sau. 午 là giữa trưa. 下午 là khoảng SAU giữa trưa, tức buổi chiều."},{"char":"见","pinyin":"jiàn","hanviet":"Kiến","chars":["见"],"story":"见 (見) = 目 (con mắt) đặt trên 儿 (đôi chân người) — vẽ một người mở to mắt mà nhìn. Từ \"nhìn thấy\" mà thành \"gặp mặt\": 再见, 明天见."},{"char":"吧","pinyin":"ba","hanviet":"Ba","chars":["吧"],"story":"吧 = 口 (cái miệng, báo đây là tiếng thốt ra) + 巴 bā chỉ âm — chữ hình thanh điển hình. Vì là trợ từ ngữ khí nên đọc THANH NHẸ ba, không đọc bā."},{"char":"电影院","pinyin":"diànyǐngyuàn","hanviet":"Điện ảnh viện","chars":["电","影","院"],"story":"电 (電) vốn vẽ tia chớp loé ra từ đám mây. 影 = 景 (cảnh có ánh sáng) + 彡 (ba nét chỉ vệt bóng) = cái bóng. 院 = 阝(bức tường đất) + 完 chỉ âm, là khu có tường bao. 电影院 = khu chiếu những cái bóng chạy bằng điện."},{"char":"看","pinyin":"kàn","hanviet":"Khán","chars":["看"],"story":"看 = 手 (bàn tay, viết gọn thành 三 nét ở trên) + 目 (con mắt) — hình ảnh đưa tay lên che nắng trên trán rồi nhìn ra xa. Nghĩa: nhìn, xem, đọc."},{"char":"电影","pinyin":"diànyǐng","hanviet":"Điện ảnh","chars":["电","影"],"story":"电 là điện, 影 là cái bóng: 景 (cảnh sáng) ghép với 彡 (vệt bóng tối). Có ánh sáng thì có bóng — 电影 chính là những cái bóng chuyển động được nhờ điện, tức bộ phim."},{"char":"事","pinyin":"shì","hanviet":"Sự","chars":["事"],"story":"事 chữ cổ vẽ một bàn tay cầm cây bút (hoặc thẻ tre) đang ghi chép công việc. Nghĩa nay là việc, chuyện: 有事 có việc, 没事 không sao."},{"char":"上课","pinyin":"shàngkè","hanviet":"Thượng khoá","chars":["上","课"],"story":"上 (lên) + 课 (tiết học) = lên lớp, vào tiết học. Cặp ngược lại là 下课 tan học — chỉ khác nhau đúng chữ 上 ↔ 下, giống hệt các cặp 上午 ↔ 下午 và 上班 ↔ 下班."},{"char":"呢","pinyin":"ne","hanviet":"Ni","chars":["呢"],"story":"呢 = 口 (cái miệng) + 尼 ní chỉ âm. Cũng như 吗 và 吧, hễ là trợ từ ngữ khí thì có bộ 口 bên trái và đọc THANH NHẸ: ne."},{"char":"半","pinyin":"bàn","hanviet":"Bán","chars":["半"],"story":"半 = 八 (chia ra hai bên) + 牛 (con bò) — hình ảnh chẻ đôi con bò, nên nghĩa gốc là \"một nửa\". Nói giờ thì 六点半 là sáu giờ ba mươi, tức sáu rưỡi."},{"char":"下课","pinyin":"xiàkè","hanviet":"Hạ khoá","chars":["下","课"],"story":"下 (xuống, hết) + 课 (tiết học) = hết tiết, tan học. Nhớ theo cặp với 上课: giờ học bắt đầu là 上, giờ học kết thúc là 下."},{"char":"在","pinyin":"zài","hanviet":"Tại","chars":["在"],"story":"在 = 才 (mầm cây vừa nhú) + 土 (mặt đất) — cái mầm đang nằm trong đất, tức \"có mặt ở đó\". 在 vừa là động từ \"ở\" (我在家), vừa là giới từ \"tại\" (在家看电影)."},{"char":"家","pinyin":"jiā","hanviet":"Gia","chars":["家"],"story":"家 = 宀 (mái nhà) + 豕 (con lợn). Người xưa nuôi lợn ngay dưới mái nhà, có lợn trong chuồng là nhà cửa no đủ — từ đó 家 thành \"nhà, gia đình\"."},{"char":"里","pinyin":"li / lǐ","hanviet":"Lý","chars":["里"],"story":"里 = 田 (thửa ruộng) + 土 (đất), vốn chỉ xóm làng. Khi làm phương vị từ chỉ \"bên trong\" (viết đầy đủ là 裏/裡), nó luôn đứng SAU danh từ và đọc nhẹ: 家里, 店里, 电影院里."},{"char":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","chars":["晚","上"],"story":"晚 = 日 (mặt trời) + 免 miǎn chỉ âm — mặt trời đã khuất, tức muộn, tối. Chữ 上 ở đây cũng chỉ khoảng thời gian như trong 早上. 晚上 là buổi tối."},{"char":"医院","pinyin":"yīyuàn","hanviet":"Y viện","chars":["医","院"],"story":"医 (醫) giản thể giữ lại 匚 (cái hộp đựng) bọc lấy 矢 (mũi tên) — hộp đựng đồ nghề gắp tên, chữa vết thương. 院 là khu đất có tường bao. 医院 = khu có tường bao dành cho việc chữa bệnh, cùng chữ 院 với 电影院."},{"char":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","chars":["上","班"],"story":"班 vốn = 玨 (hai viên ngọc) + 刀 (con dao) — chia khối ngọc ra từng phần, nên thành nghĩa \"ca, tổ, lớp\". 上班 là lên ca, đi làm; ngược lại là 下班 tan ca, tan làm."},{"char":"店","pinyin":"diàn","hanviet":"Điếm","chars":["店"],"story":"店 = 广 (mái hiên nhà, không có tường trước) + 占 zhàn chỉ âm. Chỗ dựng dưới mái hiên để bày hàng bán — cửa hàng, tiệm: 饭店, 书店."},{"char":"菜","pinyin":"cài","hanviet":"Thái","chars":["菜"],"story":"菜 = 艹 (bộ thảo, cây cỏ) ở trên + 采 cǎi (hái, chỉ âm) ở dưới — thứ cây cỏ hái được để ăn. Nghĩa gốc là rau, sau mở rộng thành \"món ăn\" nói chung: 买菜, 中国菜."},{"char":"分钟","pinyin":"fēnzhōng","hanviet":"Phân chung","chars":["分","钟"],"story":"分 là chia nhỏ. 钟 (鐘) = 钅(bộ kim, kim loại) + 中 chỉ âm — vốn là cái chuông đồng, sau chỉ cái đồng hồ. 分钟 là \"phút của đồng hồ\", dùng nói ĐỘ DÀI thời gian, khác 分 dùng nói thời điểm."},{"char":"后","pinyin":"hòu","hanviet":"Hậu","chars":["后"],"story":"后 (後) giản thể mượn hình chữ 后 (vốn nghĩa là hoàng hậu) cho gọn nét. Làm phương vị từ thì 后 nghĩa là \"sau\" và luôn đứng SAU cụm thời gian hoặc danh từ: 十分钟后, 下课后."}],"grammar":[{"title":"Cách nói thời gian (mẫu 2/2) — giờ phút","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>早上 / 晚上</b><small>buổi trong ngày</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>六点</b><small>giờ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>半 / 十分</b><small>rưỡi hoặc phút</small></span></div>","summary":"<p class=\"gr-lead\">Cách nói giờ phút</p><ul><li>Đọc giờ theo thứ tự <b>buổi → giờ → phút</b>, <b>ngược hẳn tiếng Việt</b>: \"sáu rưỡi tối\" phải nói <span class=\"zh\">晚上六点半</span>.</li><li><span class=\"zh\">点</span> là giờ, <span class=\"zh\">分</span> là phút, đúng 30 phút thì nói <span class=\"zh\">半</span>. Hỏi giờ dùng <span class=\"zh\">几点</span>: <span class=\"zh\">现在几点？</span></li><li>Số phút <b>nhỏ hơn 10</b> bắt buộc kèm chữ <span class=\"zh\">分</span>: <span class=\"zh\">十点十分</span> ✓; còn số tròn chục có thể bỏ: <span class=\"zh\">八点四十</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">八点四十</span> 8h40　·　<span class=\"zh\">十点十分</span> 10h10　·　<span class=\"zh\">六点半</span> 6h30</p>","note":"<b>Lưu ý:</b> Hai giờ nói <span class=\"zh\">两点</span>, <b>không nói</b> <span class=\"zh\">二点</span>. Và đừng lẫn <span class=\"zh\">分</span> (thời điểm) với <span class=\"zh\">分钟</span> (độ dài): <span class=\"zh\">十分</span> là 10 phút của giờ nào đó, <span class=\"zh\">十分钟</span> là khoảng mười phút.","examples":[{"zh":"我晚上六点半下班。","py":"Wǒ wǎnshang liù diǎn bàn xiàbān.","vi":"Sáu rưỡi tối mình tan làm."},{"zh":"九点","py":"jiǔ diǎn","vi":"9:00"},{"zh":"二十点","py":"èrshí diǎn","vi":"20:00"},{"zh":"十五点四十","py":"shíwǔ diǎn sìshí","vi":"15:40"},{"zh":"二十一点十分","py":"èrshíyī diǎn shí fēn","vi":"21:10"},{"zh":"二十二点零五","py":"èrshí'èr diǎn líng wǔ","vi":"22:05"},{"zh":"上午","py":"shàngwǔ","vi":"buổi sáng"},{"zh":"中午十二点","py":"zhōngwǔ shí'èr diǎn","vi":"12 giờ trưa"},{"zh":"下午两点半","py":"xiàwǔ liǎng diǎn bàn","vi":"2 giờ rưỡi chiều"},{"zh":"晚上九点十分","py":"wǎnshang jiǔ diǎn shí fēn","vi":"9 giờ 10 tối"}],"exercises":[]},{"title":"Trợ từ ngữ khí 吧","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>việc muốn rủ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吧</b><small>nhé, đi</small></span></div>","summary":"<p class=\"gr-lead\">Rủ rê, đề nghị</p><ul><li><span class=\"zh\">吧</span> đặt <b>cuối câu</b>, đọc thanh nhẹ, làm cho lời nói <b>mềm đi</b> — thành lời rủ rê, đề nghị hoặc nhắc nhở, thay vì ra lệnh.</li><li><span class=\"zh\">我们 + 动词 + 吧</span> = \"chúng mình … nhé\"; <span class=\"zh\">你 + 动词 + 吧</span> = \"bạn … đi nhé\": <span class=\"zh\">你去店里买些菜吧。</span></li><li>Ngoài rủ rê, <span class=\"zh\">吧</span> còn dùng để <b>phỏng đoán</b> điều mình đã đoán được: <span class=\"zh\">你是学生吧？</span> = Bạn là học sinh phải không?</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我们下午两点见吧。</span> = Chiều hai giờ mình gặp nhau nhé.</p>","note":"<b>Lưu ý:</b> <span class=\"zh\">吧</span> <b>không phải</b> từ để hỏi, nên câu đã có <span class=\"zh\">吧</span> thì <b>không thêm</b> <span class=\"zh\">吗</span> nữa.","examples":[{"zh":"你去店里买些菜吧。","py":"Nǐ qù diàn li mǎi xiē cài ba.","vi":"Anh ra cửa hàng mua ít rau nhé."},{"zh":"A：我们下午三点见吧。　B：好的。","py":"A: Wǒmen xiàwǔ sān diǎn jiàn ba.　B: Hǎo de.","vi":"A: 3 giờ chiều chúng ta gặp nhau nhé. — B: Được."},{"zh":"A：你去超市买吧。　B：超市没有。","py":"A: Nǐ qù chāoshì mǎi ba.　B: Chāoshì méiyǒu.","vi":"A: Bạn ra siêu thị mua đi. — B: Siêu thị không có."},{"zh":"A：我们去西安饭店吃晚饭吧。　B：好的。","py":"A: Wǒmen qù Xī'ān Fàndiàn chī wǎnfàn ba.　B: Hǎo de.","vi":"A: Chúng ta đến khách sạn Tây An ăn tối nhé. — B: Được."}],"exercises":[]},{"title":"Vị trí của phó từ và từ chỉ thời gian làm trạng ngữ","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>时间词</b><small>khi nào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>副词</b><small>还 · 不 · 非常</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Trước động từ</p><ul><li>Trạng ngữ (<span class=\"zh\">状语</span>) trong tiếng Trung <b>luôn đứng trước động từ</b> — tiếng Việt hay để sau (\"mình tan làm lúc sáu rưỡi tối\"), tiếng Trung phải đảo lên: <span class=\"zh\">我晚上六点半下班</span>.</li><li>Từ chỉ thời gian đặt <b>sau chủ ngữ</b> hoặc <b>đầu câu</b> đều được: <span class=\"zh\">我晚上六点半下班</span> = <span class=\"zh\">晚上六点半我下班</span>.</li><li>Có nhiều mốc thời gian thì viết từ <b>lớn tới nhỏ</b>: <span class=\"zh\">明天下午两点</span> (ngày → buổi → giờ).</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我明天下午两点还上课呢。</span> = Chiều mai hai giờ mình vẫn còn đang học cơ.</p>","note":"<b>Lưu ý:</b> Phó từ (<span class=\"zh\">还, 不, 非常</span>) đứng <b>sau</b> từ chỉ thời gian và <b>ngay trước</b> động từ: <span class=\"zh\">我明天下午还上课</span> ✓　·　<span class=\"zh\">我还明天下午上课</span> ✗.","examples":[{"zh":"我下午还有事。","py":"Wǒ xiàwǔ hái yǒu shì.","vi":"Chiều nay mình còn có việc."},{"zh":"我不想去。","py":"Wǒ bù xiǎng qù.","vi":"Tôi không muốn đi."},{"zh":"妹妹很高兴。","py":"Mèimei hěn gāoxìng.","vi":"Em gái rất vui."},{"zh":"她上午十点半上课。","py":"Tā shàngwǔ shí diǎn bàn shàngkè.","vi":"Cô ấy vào học lúc 10 giờ rưỡi sáng."}],"exercises":[{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们{{0}}点见？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我们下午{{1}}见吧。</span></span></span><span class=\"qz-hint\">Mấy giờ chúng ta gặp nhau? — 2 giờ chiều chúng ta gặp nhé.</span>","blanks":[["几"],["两点","两点钟"]],"explain":"我们几点见？ (Wǒmen jǐ diǎn jiàn?) · 我们下午两点见吧。 (Wǒmen xiàwǔ liǎng diǎn jiàn ba.)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你上午去上课，是吗？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对，我____有课。</span></span></span><span class=\"qz-hint\">Buổi sáng bạn đi học, phải không? — Đúng, buổi sáng mình có tiết học.</span>","answer":["上午"],"explain":"对，我上午有课。 (Duì, wǒ shàngwǔ yǒu kè.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我们{{0}}去超市吧。</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">对不起，我{{1}}有课。</span></span></span><span class=\"qz-hint\">Chiều nay chúng ta đi siêu thị nhé. — Xin lỗi, buổi chiều mình có tiết học.</span>","blanks":[["下午","今天下午"],["下午"]],"explain":"我们下午去超市吧。 (Wǒmen xiàwǔ qù chāoshì ba.) · 对不起，我下午有课。 (Duìbuqǐ, wǒ xiàwǔ yǒu kè.)"}]},{"title":"Trợ từ ngữ khí 呢 (2)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>sự việc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>呢</b><small>… cơ, … đấy</small></span></div>","summary":"<p class=\"gr-lead\">Khẳng định sự thật</p><ul><li>Đặt <span class=\"zh\">呢</span> cuối câu trần thuật để <b>khẳng định một sự thật</b> với người nghe: <span class=\"zh\">李文晚上还有事呢。</span> = Tối nay Lý Văn còn có việc <b>đấy</b>.</li><li><span class=\"zh\">名词 / 代词 + 呢？</span> là cách <b>hỏi lại</b> \"còn … thì sao?\" mà không phải lặp cả câu — đã học ở <b>Bài 4</b>: <span class=\"zh\">明天呢？</span></li><li>Câu đã có từ để hỏi mà thêm <span class=\"zh\">呢</span> thì lời hỏi <b>mềm và thân mật hơn</b>: <span class=\"zh\">你在哪儿呢？</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我明天下午两点还上课呢。</span> = Chiều mai hai giờ mình còn có tiết đấy.</p>","note":"<b>Lưu ý:</b> Cùng một chữ <span class=\"zh\">呢</span> nhưng <b>hai chức năng khác hẳn</b>: hỏi lại — 呢 (1), Bài 4 — và khẳng định sự thật — 呢 (2), bài này. <span class=\"zh\">呢</span> luôn đọc thanh nhẹ và <b>không bao giờ</b> đi cùng <span class=\"zh\">吗</span>.","examples":[{"zh":"你在哪儿呢？","py":"Nǐ zài nǎr ne?","vi":"Anh đang ở đâu đấy?"},{"zh":"我明天下午两点还上课呢。","py":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.","vi":"2 giờ chiều mai mình còn phải đi học đấy."},{"zh":"妹妹会做两个菜呢。","py":"Mèimei huì zuò liǎng gè cài ne.","vi":"Em gái biết nấu hai món đấy."},{"zh":"李文晚上还有事呢。","py":"Lǐ Wén wǎnshang hái yǒu shì ne.","vi":"Buổi tối Lý Văn còn có việc đấy."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai bạn hỏi giờ và hẹn gặp nhau","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"现在几点？","py":"Xiànzài jǐ diǎn?","vi":"Bây giờ mấy giờ rồi?"},{"speaker":"妮","name":"Annie","zh":"早上八点四十。","py":"Zǎoshang bā diǎn sìshí.","vi":"Tám giờ bốn mươi sáng."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我上午十点十分有课。","py":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","vi":"Mười giờ mười sáng nay mình có tiết."},{"speaker":"妮","name":"Annie","zh":"好的，我们下午两点见吧。","py":"Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","vi":"Được, vậy chiều hai giờ mình gặp nhau nhé."}]},{"titleZh":"课文二","titleVi":"Rủ đi xem phim nhưng bạn bận","lines":[{"speaker":"文","name":"Lý Văn","zh":"下午我想去电影院看电影，你去吗？","py":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","vi":"Chiều nay mình muốn đi rạp xem phim, cậu đi không?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我不想去，下午还有事。","py":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","vi":"Mình không muốn đi, chiều còn có việc."},{"speaker":"文","name":"Lý Văn","zh":"好的。明天呢？","py":"Hǎo de. Míngtiān ne?","vi":"Được thôi. Thế còn mai?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我明天下午两点还上课呢，四点半下课。","py":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","vi":"Chiều mai hai giờ mình vẫn đang học cơ, bốn rưỡi mới tan."}]},{"titleZh":"课文三","titleVi":"Vợ chồng gọi điện dặn việc nhà","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"喂，你在哪儿呢？","py":"Wèi, nǐ zài nǎr ne?","vi":"A lô, anh đang ở đâu đấy?"},{"speaker":"明","name":"Lưu Minh","zh":"我在家里呢。","py":"Wǒ zài jiā li ne.","vi":"Anh đang ở nhà."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我晚上六点半下班。","py":"Wǒ wǎnshang liù diǎn bàn xiàbān.","vi":"Tối nay sáu rưỡi em tan làm."},{"speaker":"明","name":"Lưu Minh","zh":"我八点去医院上班。","py":"Wǒ bā diǎn qù yīyuàn shàngbān.","vi":"Tám giờ anh đến bệnh viện vào ca."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"好的，你去店里买些菜吧。","py":"Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","vi":"Được rồi, anh ra cửa hàng mua ít rau nhé."},{"speaker":"明","name":"Lưu Minh","zh":"好，我十分钟后去。","py":"Hǎo, wǒ shí fēnzhōng hòu qù.","vi":"Ừ, mười phút nữa anh đi."}]}]},"extra":[],"activity":{"act":[{"zh":"填写表格","py":"tiánxiě biǎogé","tag":"Điền bảng","mean":"Điền bảng · Giờ giấc của em","q":{"zh":"三人一组，每人根据自己的情况填写时间，填好后分享。","py":"Sān rén yì zǔ, měi rén gēnjù zìjǐ de qíngkuàng tiánxiě shíjiān, tiánhǎo hòu fēnxiǎng.","vi":"Nhóm 3 người, mỗi người điền giờ theo thực tế của mình, điền xong thì chia sẻ."},"items":[{"zh":"午饭　·　休息　·　下课","py":"wǔfàn · xiūxi · xiàkè","vi":"bữa trưa · nghỉ ngơi · tan học"},{"zh":"我中午十二点吃午饭。","py":"Wǒ zhōngwǔ shí'èr diǎn chī wǔfàn.","vi":"12 giờ trưa mình ăn trưa."},{"zh":"我下午一点休息。","py":"Wǒ xiàwǔ yī diǎn xiūxi.","vi":"1 giờ chiều mình nghỉ ngơi."},{"zh":"我下午四点下课。","py":"Wǒ xiàwǔ sì diǎn xiàkè.","vi":"4 giờ chiều mình tan học."},{"zh":"你几点吃午饭？","py":"Nǐ jǐ diǎn chī wǔfàn?","vi":"Bạn ăn trưa lúc mấy giờ?"}]}],"speak":[]}},{"id":"k1v3-b08","courseId":"k1v3","order":8,"title":"Bố tôi cũng làm ở bệnh viện","titleZh":"我爸爸也在医院工作","titlePy":"wǒ bàba yě zài yīyuàn gōngzuò","vocab":[{"stt":1,"hanzi":"房间","pinyin":"fángjiān","hanviet":"Phòng gian","pos":"Danh từ","meaning":"căn phòng","comps":"房间里 (trong phòng), 房间外 (ngoài phòng)","example":{"zh":"房间外有一只小猫。","py":"Fángjiān wài yǒu yì zhī xiǎo māo.","vi":"Ngoài phòng có một con mèo nhỏ."}},{"stt":2,"hanzi":"外","pinyin":"wài","hanviet":"Ngoại","pos":"Danh từ","meaning":"bên ngoài, ngoài","comps":"房间外 (ngoài phòng), 外边 (bên ngoài)","example":{"zh":"小猫在房间外。","py":"Xiǎo māo zài fángjiān wài.","vi":"Con mèo ở ngoài phòng."}},{"stt":3,"hanzi":"只","pinyin":"zhī","hanviet":"Chích","pos":"Lượng từ","meaning":"con (đếm con vật)","comps":"一只猫 (một con mèo), 这只 (con này)","example":{"zh":"这只小猫真漂亮！","py":"Zhè zhī xiǎo māo zhēn piàoliang!","vi":"Con mèo nhỏ này xinh thật!"}},{"stt":4,"hanzi":"小","pinyin":"xiǎo","hanviet":"Tiểu","pos":"Tính từ","meaning":"nhỏ, bé (↔ 大 lớn)","comps":"小猫 (mèo con), 小胡 (Tiểu Hồ)","example":{"zh":"桌子下有一只小猫。","py":"Zhuōzi xià yǒu yì zhī xiǎo māo.","vi":"Dưới gầm bàn có một con mèo nhỏ."}},{"stt":5,"hanzi":"猫","pinyin":"māo","hanviet":"Miêu","pos":"Danh từ","meaning":"con mèo","comps":"小猫 (mèo con), 一只猫 (một con mèo)","example":{"zh":"我没看见那只猫。","py":"Wǒ méi kànjiàn nà zhī māo.","vi":"Mình không thấy con mèo đó."}},{"stt":6,"hanzi":"没","pinyin":"méi","hanviet":"Một","pos":"Phó từ","meaning":"chưa; không có","comps":"没有 (không có), 没吃 (chưa ăn)","example":{"zh":"我还没吃午饭呢。","py":"Wǒ hái méi chī wǔfàn ne.","vi":"Mình vẫn chưa ăn trưa."}},{"stt":7,"hanzi":"看见","pinyin":"kànjiàn","hanviet":"Khán kiến","pos":"Động từ","meaning":"nhìn thấy, thấy","comps":"看见了 (đã thấy), 没看见 (không thấy)","example":{"zh":"我没看见小猫。","py":"Wǒ méi kànjiàn xiǎo māo.","vi":"Mình không nhìn thấy con mèo."}},{"stt":8,"hanzi":"桌子","pinyin":"zhuōzi","hanviet":"Trác tử","pos":"Danh từ","meaning":"cái bàn","comps":"桌子上 (trên bàn), 桌子下 (dưới gầm bàn)","example":{"zh":"它在桌子下呢。","py":"Tā zài zhuōzi xià ne.","vi":"Nó đang ở dưới gầm bàn."}},{"stt":9,"hanzi":"下","pinyin":"xià","hanviet":"Hạ","pos":"Danh từ","meaning":"phía dưới, dưới","comps":"桌子下 (dưới bàn), 下边 (phía dưới)","example":{"zh":"小猫在桌子下。","py":"Xiǎo māo zài zhuōzi xià.","vi":"Con mèo ở dưới gầm bàn."}},{"stt":10,"hanzi":"漂亮","pinyin":"piàoliang","hanviet":"Phiêu lượng","pos":"Tính từ","meaning":"xinh, đẹp","comps":"很漂亮 (rất xinh), 非常漂亮 (đẹp vô cùng)","example":{"zh":"这只小猫非常漂亮。","py":"Zhè zhī xiǎo māo fēicháng piàoliang.","vi":"Con mèo nhỏ này đẹp lắm."}},{"stt":11,"hanzi":"在","pinyin":"zài","hanviet":"Tại","pos":"Giới từ","meaning":"ở, tại (nơi chốn)","comps":"在学校 (ở trường), 在医院 (ở bệnh viện)","example":{"zh":"我在学校吃午饭。","py":"Wǒ zài xuéxiào chī wǔfàn.","vi":"Mình ăn trưa ở trường."}},{"stt":12,"hanzi":"学校","pinyin":"xuéxiào","hanviet":"Học hiệu","pos":"Danh từ","meaning":"trường học","comps":"去学校 (đến trường), 学校前 (trước trường)","example":{"zh":"我在学校书店前见你。","py":"Wǒ zài xuéxiào shūdiàn qián jiàn nǐ.","vi":"Mình gặp cậu trước hiệu sách của trường."}},{"stt":13,"hanzi":"书店","pinyin":"shūdiàn","hanviet":"Thư điếm","pos":"Danh từ","meaning":"hiệu sách","comps":"去书店 (đi hiệu sách), 书店前 (trước hiệu sách)","example":{"zh":"书店在学校里。","py":"Shūdiàn zài xuéxiào li.","vi":"Hiệu sách nằm trong trường."}},{"stt":14,"hanzi":"前","pinyin":"qián","hanviet":"Tiền","pos":"Danh từ","meaning":"phía trước, trước","comps":"书店前 (trước hiệu sách), 前边 (đằng trước)","example":{"zh":"在学校前见吧。","py":"Zài xuéxiào qián jiàn ba.","vi":"Gặp nhau trước cổng trường nhé."}},{"stt":15,"hanzi":"能","pinyin":"néng","hanviet":"Năng","pos":"Động từ năng nguyện","meaning":"có thể, được","comps":"能到 (đến được), 不能去 (không đi được)","example":{"zh":"下午两点你能到吗？","py":"Xiàwǔ liǎng diǎn nǐ néng dào ma?","vi":"Chiều hai giờ cậu đến được không?"}},{"stt":16,"hanzi":"到","pinyin":"dào","hanviet":"Đáo","pos":"Động từ","meaning":"đến, tới","comps":"能到 (đến được), 到学校 (đến trường)","example":{"zh":"我两点能到。","py":"Wǒ liǎng diǎn néng dào.","vi":"Hai giờ mình đến được."}},{"stt":17,"hanzi":"午饭","pinyin":"wǔfàn","hanviet":"Ngọ phạn","pos":"Danh từ","meaning":"bữa trưa, cơm trưa","comps":"吃午饭 (ăn trưa), 做午饭 (nấu cơm trưa)","example":{"zh":"我在学校吃午饭。","py":"Wǒ zài xuéxiào chī wǔfàn.","vi":"Mình ăn cơm trưa ở trường."}},{"stt":18,"hanzi":"饭","pinyin":"fàn","hanviet":"Phạn","pos":"Danh từ","meaning":"cơm; bữa cơm","comps":"吃饭 (ăn cơm), 午饭 (cơm trưa)","example":{"zh":"你还没吃饭呢？","py":"Nǐ hái méi chī fàn ne?","vi":"Anh vẫn chưa ăn cơm à?"}},{"stt":19,"hanzi":"大","pinyin":"dà","hanviet":"Đại","pos":"Tính từ","meaning":"to, lớn (↔ 小 nhỏ)","comps":"大医院 (bệnh viện lớn), 大学校 (trường lớn)","example":{"zh":"大医院病人多。","py":"Dà yīyuàn bìngrén duō.","vi":"Bệnh viện lớn thì bệnh nhân đông."}},{"stt":20,"hanzi":"病人","pinyin":"bìngrén","hanviet":"Bệnh nhân","pos":"Danh từ","meaning":"bệnh nhân","comps":"看病人 (thăm bệnh nhân), 病人多 (đông bệnh nhân)","example":{"zh":"医院里病人非常多。","py":"Yīyuàn li bìngrén fēicháng duō.","vi":"Trong bệnh viện rất đông bệnh nhân."}},{"stt":21,"hanzi":"多","pinyin":"duō","hanviet":"Đa","pos":"Tính từ","meaning":"nhiều (↔ 少 ít)","comps":"很多 (rất nhiều), 病人多 (bệnh nhân đông)","example":{"zh":"这个书店的书很多。","py":"Zhège shūdiàn de shū hěn duō.","vi":"Hiệu sách này có rất nhiều sách."}},{"stt":22,"hanzi":"医生","pinyin":"yīshēng","hanviet":"Y sinh","pos":"Danh từ","meaning":"bác sĩ","comps":"胡医生 (bác sĩ Hồ), 大医生 (bác sĩ giỏi)","example":{"zh":"你家有两个医生？","py":"Nǐ jiā yǒu liǎng gè yīshēng?","vi":"Nhà anh có hai bác sĩ à?"}},{"stt":23,"hanzi":"工作","pinyin":"gōngzuò","hanviet":"Công tác","pos":"Động từ","meaning":"làm việc; công việc","comps":"在医院工作 (làm ở bệnh viện), 工作忙 (công việc bận)","example":{"zh":"我爸爸在医院工作。","py":"Wǒ bàba zài yīyuàn gōngzuò.","vi":"Bố mình làm việc ở bệnh viện."}},{"stt":24,"hanzi":"胡医生","pinyin":"Hú yīshēng","hanviet":"Hồ y sinh","pos":"Danh từ riêng","meaning":"bác sĩ Hồ (Dr. Hu)","comps":"小胡 (Tiểu Hồ), 胡医生的房间 (phòng bác sĩ Hồ)","example":{"zh":"胡医生在医院工作。","py":"Hú yīshēng zài yīyuàn gōngzuò.","vi":"Bác sĩ Hồ làm việc ở bệnh viện."}}],"hanzi":[{"char":"房间","pinyin":"fángjiān","hanviet":"Phòng gian","chars":["房","间"],"story":"房 = 户 (cánh cửa một cánh) + 方 fāng chỉ âm — gian nhà có cửa riêng. 间 (間) = 门 (cái cửa) + 日 (mặt trời): nắng lọt qua khe cửa, nên 间 nghĩa là \"khoảng, khe ở giữa\". 房间 = khoảng không gian trong nhà, tức căn phòng."},{"char":"外","pinyin":"wài","hanviet":"Ngoại","chars":["外"],"story":"外 = 夕 (buổi chiều tối) + 卜 (việc bói toán). Người xưa quen bói vào buổi sáng; bói lúc chiều tối là trái lệ thường, là \"ở ngoài lệ\" — từ đó 外 thành nghĩa \"bên ngoài\"."},{"char":"只","pinyin":"zhī","hanviet":"Chích","chars":["只"],"story":"只 (隻) chữ cổ vẽ một bàn tay 又 đang cầm một con chim 隹 — bắt được đúng MỘT con. Vì thế 只 thành lượng từ đếm con vật: 一只猫, 一只鸟."},{"char":"小","pinyin":"xiǎo","hanviet":"Tiểu","chars":["小"],"story":"小 vẽ ba hạt cát nhỏ rơi xuống, ý nói vật bị chia vụn ra. Ngược hẳn với 大. Đặt trước họ người thì thành cách gọi thân mật với người ít tuổi hơn: 小胡, 小李."},{"char":"猫","pinyin":"māo","hanviet":"Miêu","chars":["猫"],"story":"猫 (貓) = 犭 (bộ khuyển, dáng con thú bốn chân) + 苗 miáo chỉ âm. Bộ 犭 cho biết đây là con vật, phần 苗 cho biết chữ đọc gần giống māo — một chữ hình thanh điển hình."},{"char":"没","pinyin":"méi","hanviet":"Một","chars":["没"],"story":"没 = 氵 (bộ thuỷ, nước) + 殳, nghĩa gốc là \"chìm xuống nước, mất đi\". Từ nghĩa \"mất, không còn\" mà 没 thành từ phủ định: phủ định sự tồn tại (没有) và phủ định việc ĐÃ xảy ra (没吃)."},{"char":"看见","pinyin":"kànjiàn","hanviet":"Khán kiến","chars":["看","见"],"story":"看 = 手 (bàn tay) đặt trên 目 (con mắt) — đưa tay che nắng mà nhìn. 见 = 目 trên 儿 (chân người) — người mở to mắt mà thấy. 看 là HÀNH ĐỘNG nhìn, 见 là KẾT QUẢ thấy được; ghép lại 看见 nghĩa là nhìn và thấy được."},{"char":"桌子","pinyin":"zhuōzi","hanviet":"Trác tử","chars":["桌","子"],"story":"桌 phần dưới là 木 (gỗ), phần trên vẽ mặt bàn phẳng đặt trên chân — đồ bằng gỗ có mặt phẳng. 子 ở đây chỉ là hậu tố danh từ đọc thanh nhẹ, cũng gặp trong 包子 đã học ở Bài 6."},{"char":"下","pinyin":"xià","hanviet":"Hạ","chars":["下"],"story":"下 vẽ một vạch nằm DƯỚI vạch mốc, chỉ phía dưới — ngược hẳn 上. Làm phương vị từ thì 下 đứng SAU danh từ: 桌子下 (dưới gầm bàn), khác với 下课, 下班 là động từ."},{"char":"漂亮","pinyin":"piàoliang","hanviet":"Phiêu lượng","chars":["漂","亮"],"story":"漂 = 氵 (nước) + 票 piào chỉ âm, vốn nghĩa \"trôi nổi trên mặt nước\". 亮 = 高 viết gọn + 儿, nghĩa là sáng sủa. Ghép lại chỉ vẻ sáng đẹp dễ nhìn. Chữ 亮 ở đây đọc THANH NHẸ: piàoliang."},{"char":"在","pinyin":"zài","hanviet":"Tại","chars":["在"],"story":"在 = 才 (mầm cây vừa nhú) + 土 (mặt đất) — có mặt ở chỗ đó. Bài 7 học 在 làm ĐỘNG TỪ (我在家里呢); bài này 在 làm GIỚI TỪ, đứng trước nơi chốn rồi mới tới động từ chính: 在医院工作."},{"char":"学校","pinyin":"xuéxiào","hanviet":"Học hiệu","chars":["学","校"],"story":"学 (學) vẽ hai bàn tay đang bày que tính dạy đứa trẻ 子 ở dưới mái nhà. 校 = 木 (gỗ) + 交 jiāo chỉ âm, vốn là hàng rào gỗ quây quanh sân. 学校 = nơi có rào bao để dạy trẻ học."},{"char":"书店","pinyin":"shūdiàn","hanviet":"Thư điếm","chars":["书","店"],"story":"书 (書) chữ cổ vẽ một bàn tay cầm bút viết lên tấm thẻ tre. 店 = 广 (mái hiên nhà) + 占 chỉ âm — chỗ dưới mái hiên bày hàng bán, vừa học ở Bài 7. 书店 là cửa hàng bán sách."},{"char":"前","pinyin":"qián","hanviet":"Tiền","chars":["前"],"story":"前 phần trên là dấu vết của 止 (bàn chân), giữa là 舟 (con thuyền) viết gọn thành 月, dưới là 刂. Hình bàn chân đứng trên thuyền tiến tới — nghĩa \"phía trước\". Là phương vị từ, đối lập với 后 học ở Bài 7."},{"char":"能","pinyin":"néng","hanviet":"Năng","chars":["能"],"story":"能 chữ cổ vẽ con GẤU — loài vật khoẻ mạnh, làm được nhiều việc. Từ đó mượn thành nghĩa \"có khả năng, có thể\". Chữ 熊 (con gấu) ngày nay chính là 能 thêm bốn chấm lửa ở dưới."},{"char":"到","pinyin":"dào","hanviet":"Đáo","chars":["到"],"story":"到 = 至 (vẽ mũi tên bay tới cắm xuống đất, nghĩa \"tới nơi\") + 刂 (biến từ 刀 dāo, chỉ âm). Nghĩa: đến, tới nơi — 我两点能到."},{"char":"午饭","pinyin":"wǔfàn","hanviet":"Ngọ phạn","chars":["午","饭"],"story":"午 là giờ Ngọ, tức giữa trưa — đã gặp trong 上午 và 下午 ở Bài 7. 饭 (飯) = 饣 (bộ thực) + 反 chỉ âm. 午饭 là bữa cơm giữa trưa, cùng khuôn với 晚饭 (cơm tối)."},{"char":"饭","pinyin":"fàn","hanviet":"Phạn","chars":["饭"],"story":"饭 (飯) = 饣 (bộ thực, viết gọn của 食 — hình cái vung đậy trên bát cơm) + 反 fǎn chỉ âm. Nghĩa gốc là cơm đã nấu chín, mở rộng thành \"bữa ăn\": 吃饭, 午饭, 晚饭, 米饭."},{"char":"大","pinyin":"dà","hanviet":"Đại","chars":["大"],"story":"大 vẽ một người dang rộng cả hai tay hai chân — hình ảnh to lớn nhất mà người xưa hình dung được. Ngược lại là 小. Thêm một vạch ngang trên đầu chữ 大 thì thành 天 (bầu trời)."},{"char":"病人","pinyin":"bìngrén","hanviet":"Bệnh nhân","chars":["病","人"],"story":"病 = 疒 (bộ nạch — vẽ người nằm nghiêng trên chiếc giường dựng đứng) + 丙 bǐng chỉ âm. Hễ thấy bộ 疒 là biết chữ nói về bệnh tật. 人 vẽ dáng người đứng nhìn nghiêng. 病人 = người đang có bệnh."},{"char":"多","pinyin":"duō","hanviet":"Đa","chars":["多"],"story":"多 là hai chữ 夕 (buổi tối) chồng lên nhau — hết tối này lại tới tối khác, ngày tháng chồng chất, từ đó thành nghĩa \"nhiều\". Chữ ngược lại là 少."},{"char":"医生","pinyin":"yīshēng","hanviet":"Y sinh","chars":["医","生"],"story":"医 (醫) giản thể giữ lại 匚 (cái hộp) bọc lấy 矢 (mũi tên) — hộp đựng đồ nghề gắp tên, chữa vết thương. 生 vẽ mầm cây mọc lên khỏi mặt đất, nghĩa gốc là \"sinh ra, sự sống\". 医生 = người giữ lấy sự sống cho người khác."},{"char":"工作","pinyin":"gōngzuò","hanviet":"Công tác","chars":["工","作"],"story":"工 vẽ cái thước thợ (hoặc cái đục) — dụng cụ của người thợ, nên bản thân 工 đã nghĩa là \"thợ, việc\". 作 = 亻 (người) + 乍 zhà chỉ âm. 工作 là người cầm dụng cụ mà làm — làm việc, công việc."},{"char":"胡医生","pinyin":"Hú yīshēng","hanviet":"Hồ y sinh","chars":["胡","医","生"],"story":"胡 = 古 gǔ (chỉ âm) + 月 (biến từ 肉, bộ nhục) — vốn chỉ phần thịt dưới cằm con vật, về sau thành một họ rất phổ biến của người Trung Quốc. 医生 là bác sĩ. 胡医生 nghĩa là bác sĩ họ Hồ, tiếng Anh ghi là Dr. Hu."}],"grammar":[{"title":"Phương vị từ (方位词)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>名词</b><small>vật hoặc nơi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>外 · 下 · 前 · 里</b><small>phương vị từ</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ vị trí đồ vật</p><ul><li>Phương vị từ (<span class=\"zh\">外, 里, 上, 下, 前, 后</span>) đặt <b>SAU danh từ</b> — <b>ngược hẳn tiếng Việt</b>: ta nói \"ngoài phòng\", tiếng Trung nói <span class=\"zh\">房间外</span>.</li><li>Cả cụm <span class=\"zh\">名词 + 方位词</span> dùng y như một danh từ chỉ nơi chốn, làm chủ ngữ hay tân ngữ đều được: <span class=\"zh\">桌子下有一只小猫。</span></li><li><span class=\"zh\">里</span> đã học ở <b>Bài 7</b> (<span class=\"zh\">家里, 店里</span>) cũng chính là phương vị từ, cùng khuôn này.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">房间外</span> ngoài phòng　·　<span class=\"zh\">桌子下</span> dưới gầm bàn　·　<span class=\"zh\">书店前</span> trước hiệu sách</p>","note":"<b>Lưu ý:</b> Phương vị từ một âm tiết <b>không thêm</b> <span class=\"zh\">的</span> vào giữa: <span class=\"zh\">房间外</span> ✓　·　<span class=\"zh\">房间的外</span> ✗. Muốn nói rõ hơn thì thêm <span class=\"zh\">边 / 面</span>: <span class=\"zh\">外边, 下面</span>.","examples":[{"zh":"房间外有一只小猫。","py":"Fángjiān wài yǒu yì zhī xiǎo māo.","vi":"Ngoài phòng có một con mèo nhỏ."},{"zh":"房间里有一只小猫。","py":"Fángjiān li yǒu yì zhī xiǎo māo.","vi":"Trong phòng có một con mèo nhỏ."},{"zh":"我们去书店外吧。","py":"Wǒmen qù shūdiàn wài ba.","vi":"Chúng ta ra ngoài hiệu sách nhé."},{"zh":"小雪的手机在桌子上呢。","py":"Xiǎoxuě de shǒujī zài zhuōzi shang ne.","vi":"Điện thoại của Tiểu Tuyết ở trên bàn đấy."}],"exercises":[]},{"title":"Giới từ 在","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>在 + 处所</b><small>ở đâu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>làm gì</small></span></div>","summary":"<p class=\"gr-lead\">Làm việc gì ở đâu</p><ul><li><span class=\"zh\">在 + 处所</span> (nơi chốn) đứng <b>trước động từ chính</b> để nói việc đó xảy ra ở đâu. Tiếng Việt để sau (\"ăn trưa <b>ở trường</b>\"), tiếng Trung phải <b>đảo lên trước</b>.</li><li>Phân biệt với <span class=\"zh\">在</span> làm <b>động từ</b> đã học ở Bài 7: <span class=\"zh\">我在家</span> = mình ở nhà (câu chỉ có 在); <span class=\"zh\">我在家吃饭</span> = mình ăn cơm ở nhà (在 là giới từ, 吃 mới là động từ chính).</li><li>Sau <span class=\"zh\">在</span> phải là <b>nơi chốn</b>. Danh từ chỉ đồ vật thì bắt buộc thêm phương vị từ: <span class=\"zh\">在桌子下</span> ✓　·　<span class=\"zh\">在桌子</span> ✗.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我在学校吃午饭。</span> = Mình ăn trưa ở trường.　·　<span class=\"zh\">我爸爸在医院工作。</span></p>","note":"<b>Lưu ý:</b> <b>Không</b> đặt <span class=\"zh\">在 + 处所</span> ra sau động từ: <span class=\"zh\">我在医院工作</span> ✓　·　<span class=\"zh\">我工作在医院</span> ✗.","examples":[{"zh":"我爸爸也在医院工作。","py":"Wǒ bàba yě zài yīyuàn gōngzuò.","vi":"Bố mình cũng làm việc ở bệnh viện."},{"zh":"我在学校吃午饭。","py":"Wǒ zài xuéxiào chī wǔfàn.","vi":"Tôi ăn trưa ở trường."},{"zh":"他爸爸在医院工作。","py":"Tā bàba zài yīyuàn gōngzuò.","vi":"Bố anh ấy làm việc ở bệnh viện."},{"zh":"你在哪儿买菜？","py":"Nǐ zài nǎr mǎi cài?","vi":"Bạn mua rau ở đâu?"}],"exercises":[]},{"title":"Động từ năng nguyện 能","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>能</b><small>có thể</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Có thể làm được</p><ul><li><span class=\"zh\">能</span> đứng <b>ngay trước động từ chính</b>, nói rằng mình <b>có đủ điều kiện, đủ khả năng</b> làm việc đó: <span class=\"zh\">我能到。</span></li><li>Phủ định thêm <span class=\"zh\">不</span>: <span class=\"zh\">不能到</span>. Hỏi bằng <span class=\"zh\">吗</span> hoặc dạng chính phản <span class=\"zh\">能不能</span>: <span class=\"zh\">你能不能到？</span></li><li>So với hai động từ năng nguyện đã học: <span class=\"zh\">会</span> (Bài 5) là <b>biết làm nhờ học</b>, <span class=\"zh\">想</span> (Bài 6) là <b>muốn làm</b>, còn <span class=\"zh\">能</span> là <b>làm được</b> trong hoàn cảnh cụ thể.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">下午两点你能到吗？</span> —— <span class=\"zh\">我能到。</span> Phủ định: <span class=\"zh\">不能到</span></p>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">能</span> phải là <b>động từ</b>, không thêm <span class=\"zh\">是</span> và không thêm <span class=\"zh\">了</span>: <span class=\"zh\">我能到</span> ✓　·　<span class=\"zh\">我能是到</span> ✗.","examples":[{"zh":"下午两点你能到吗？","py":"Xiàwǔ liǎng diǎn nǐ néng dào ma?","vi":"Chiều hai giờ bạn đến được không?"},{"zh":"爸爸能去。","py":"Bàba néng qù.","vi":"Bố đi được."},{"zh":"我不能去学校吃午饭。","py":"Wǒ bù néng qù xuéxiào chī wǔfàn.","vi":"Tôi không thể đến trường ăn trưa."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai bạn tìm chỗ con mèo nhỏ nấp","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"房间外有一只小猫。","py":"Fángjiān wài yǒu yì zhī xiǎo māo.","vi":"Ngoài phòng có một con mèo nhỏ."},{"speaker":"中","name":"Trần Thiên Trung","zh":"我没看见，它在哪儿呢？","py":"Wǒ méi kànjiàn, tā zài nǎr ne?","vi":"Mình không thấy, nó ở đâu đấy?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"它在桌子下呢。","py":"Tā zài zhuōzi xià ne.","vi":"Nó đang ở dưới gầm bàn kìa."},{"speaker":"中","name":"Trần Thiên Trung","zh":"这只小猫真漂亮！","py":"Zhè zhī xiǎo māo zhēn piàoliang!","vi":"Con mèo nhỏ này xinh thật!"}]},{"titleZh":"课文二","titleVi":"Hẹn chỗ gặp trước hiệu sách trường","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我们在哪儿见呢？","py":"Wǒmen zài nǎr jiàn ne?","vi":"Chúng mình gặp nhau ở đâu đây?"},{"speaker":"文","name":"Lý Văn","zh":"在学校书店前见吧。","py":"Zài xuéxiào shūdiàn qián jiàn ba.","vi":"Gặp ở trước hiệu sách của trường nhé."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"好的。下午两点你能到吗？","py":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","vi":"Được. Chiều hai giờ cậu đến được không?"},{"speaker":"文","name":"Lý Văn","zh":"我能到。我在学校吃午饭。","py":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","vi":"Mình đến được. Mình ăn trưa ở trường mà."}]},{"titleZh":"课文三","titleVi":"Hai bác sĩ trò chuyện ở bệnh viện","lines":[{"speaker":"明","name":"Lưu Minh","zh":"小胡，还没吃饭呢？","py":"Xiǎo Hú, hái méi chī fàn ne?","vi":"Tiểu Hồ, vẫn chưa ăn cơm à?"},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"没吃呢。","py":"Méi chī ne.","vi":"Vẫn chưa ăn ạ."},{"speaker":"明","name":"Lưu Minh","zh":"大医院病人多，医生非常忙。","py":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","vi":"Bệnh viện lớn bệnh nhân đông, bác sĩ bận lắm."},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"是的。我爸爸也在医院工作，他也非常忙。","py":"Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","vi":"Đúng thế ạ. Bố em cũng làm ở bệnh viện, ông ấy cũng rất bận."},{"speaker":"明","name":"Lưu Minh","zh":"你家有两个医生？","py":"Nǐ jiā yǒu liǎng gè yīshēng?","vi":"Nhà em có hai bác sĩ cơ à?"},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"对。","py":"Duì.","vi":"Vâng ạ."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hội thoại với từ cho sẵn","q":{"zh":"两人一组，使用以下词语对话：哪儿、东西、呢、下、小猫、吃、在","py":"Liǎng rén yì zǔ, shǐyòng yǐxià cíyǔ duìhuà: nǎr, dōngxi, ne, xià, xiǎo māo, chī, zài","vi":"Hai người một nhóm, dùng các từ sau để hội thoại: 哪儿, 东西, 呢, 下, 小猫, 吃, 在"},"items":[{"lines":[{"who":"A","zh":"你的手机在哪儿？","py":"Nǐ de shǒujī zài nǎr?","vi":"Điện thoại của bạn ở đâu?"},{"who":"B","zh":"我的手机在桌子上。你的手机呢？","py":"Wǒ de shǒujī zài zhuōzi shang. Nǐ de shǒujī ne?","vi":"Điện thoại của mình ở trên bàn. Còn điện thoại của bạn?"},{"who":"A","zh":"我的手机在家里。","py":"Wǒ de shǒujī zài jiā li.","vi":"Điện thoại của mình ở nhà."}]},{"lines":[{"who":"A","zh":"小猫在哪儿？","py":"Xiǎo māo zài nǎr?","vi":"Mèo con ở đâu?"},{"who":"B","zh":"小猫在桌子下吃东西呢。","py":"Xiǎo māo zài zhuōzi xià chī dōngxi ne.","vi":"Mèo con đang ăn ở dưới gầm bàn đấy."}]}]}],"speak":[]}},{"id":"k1v3-b09","courseId":"k1v3","order":9,"title":"Sáng mai tôi học ở trường","titleZh":"我明天上午在学校学习","titlePy":"wǒ míngtiān shàngwǔ zài xuéxiào xuéxí","vocab":[{"stt":1,"hanzi":"前边","pinyin":"qiánbian","hanviet":"Tiền biên","pos":"Danh từ","meaning":"phía trước (↔ 后边)","comps":"学校前边 (trước trường), 前边有 (phía trước có)","example":{"zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường có một rạp chiếu phim."}},{"stt":2,"hanzi":"边","pinyin":"bian / biān","hanviet":"Biên","pos":"Hậu tố / Danh từ","meaning":"bên, phía; mép, rìa","comps":"外边 (bên ngoài), 那边 (bên kia)","example":{"zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường có một rạp chiếu phim."}},{"stt":3,"hanzi":"家","pinyin":"jiā","hanviet":"Gia","pos":"Lượng từ","meaning":"lượng từ: cửa hàng, rạp, công ty…","comps":"一家电影院 (một rạp phim), 家里 (trong nhà)","example":{"zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường có một rạp chiếu phim."}},{"stt":4,"hanzi":"那个","pinyin":"nàge","hanviet":"Na cá","pos":"Đại từ","meaning":"cái đó, cái kia","comps":"那个人 (người kia), 那个电影院 (rạp phim đó)","example":{"zh":"我们去那个电影院看电影。","py":"Wǒmen qù nàge diànyǐngyuàn kàn diànyǐng.","vi":"Chúng mình đến rạp phim đó xem phim."}},{"stt":5,"hanzi":"外边","pinyin":"wàibian","hanviet":"Ngoại biên","pos":"Danh từ","meaning":"bên ngoài (↔ 里边)","comps":"外边见 (gặp ở ngoài), 学校外边 (ngoài trường)","example":{"zh":"我们在电影院外边见。","py":"Wǒmen zài diànyǐngyuàn wàibian jiàn.","vi":"Chúng mình gặp nhau ở ngoài rạp phim."}},{"stt":6,"hanzi":"椅子","pinyin":"yǐzi","hanviet":"Ỷ tử","pos":"Danh từ","meaning":"cái ghế (có tựa)","comps":"椅子上 (trên ghế), 小椅子 (ghế nhỏ)","example":{"zh":"椅子上有一本书。","py":"Yǐzi shang yǒu yì běn shū.","vi":"Trên ghế có một quyển sách."}},{"stt":7,"hanzi":"上","pinyin":"shang / shàng","hanviet":"Thượng","pos":"Danh từ","meaning":"trên, phía trên (↔ 下)","comps":"椅子上 (trên ghế), 桌子上 (trên bàn)","example":{"zh":"桌子上有一本中文书。","py":"Zhuōzi shang yǒu yì běn Zhōngwén shū.","vi":"Trên bàn có một quyển sách tiếng Trung."}},{"stt":8,"hanzi":"本","pinyin":"běn","hanviet":"Bản","pos":"Lượng từ","meaning":"quyển, cuốn (sách)","comps":"一本书 (một quyển sách), 两本 (hai quyển)","example":{"zh":"我有两本中文书。","py":"Wǒ yǒu liǎng běn Zhōngwén shū.","vi":"Mình có hai quyển sách tiếng Trung."}},{"stt":9,"hanzi":"书","pinyin":"shū","hanviet":"Thư","pos":"Danh từ","meaning":"sách, quyển sách","comps":"中文书 (sách tiếng Trung), 读书 (đọc sách)","example":{"zh":"这是我的中文书。","py":"Zhè shì wǒ de Zhōngwén shū.","vi":"Đây là quyển sách tiếng Trung của mình."}},{"stt":10,"hanzi":"那","pinyin":"nà","hanviet":"Na","pos":"Đại từ","meaning":"kia, đó (↔ 这 này)","comps":"那是 (kia là), 那本书 (quyển sách kia)","example":{"zh":"那是谁的书？","py":"Nà shì shéi de shū?","vi":"Kia là sách của ai vậy?"}},{"stt":11,"hanzi":"第","pinyin":"dì","hanviet":"Đệ","pos":"Tiền tố","meaning":"thứ … (số thứ tự)","comps":"第一 (thứ nhất), 第二本 (quyển thứ hai)","example":{"zh":"这是我的第二本中文书。","py":"Zhè shì wǒ de dì-èr běn Zhōngwén shū.","vi":"Đây là quyển sách tiếng Trung thứ hai của mình."}},{"stt":12,"hanzi":"学习","pinyin":"xuéxí","hanviet":"Học tập","pos":"Động từ","meaning":"học, học tập","comps":"学习中文 (học tiếng Trung), 在学校学习 (học ở trường)","example":{"zh":"我明天上午在学校学习。","py":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","vi":"Sáng mai mình học ở trường."}},{"stt":13,"hanzi":"做","pinyin":"zuò","hanviet":"Tố","pos":"Động từ","meaning":"làm (việc gì), tham gia","comps":"做什么 (làm gì), 做饭 (nấu cơm)","example":{"zh":"明天星期六，你做什么？","py":"Míngtiān Xīngqīliù, nǐ zuò shénme?","vi":"Mai là thứ Bảy, cậu làm gì thế?"}},{"stt":14,"hanzi":"白天","pinyin":"báitiān","hanviet":"Bạch thiên","pos":"Danh từ","meaning":"ban ngày (↔ 晚上)","comps":"白天上班 (ngày đi làm), 白天很忙 (ban ngày bận)","example":{"zh":"我白天在家里读书。","py":"Wǒ báitiān zài jiā li dúshū.","vi":"Ban ngày mình đọc sách ở nhà."}},{"stt":15,"hanzi":"读书","pinyin":"dúshū","hanviet":"Độc thư","pos":"Động từ","meaning":"đọc sách; đi học","comps":"在家读书 (đọc sách ở nhà), 读中文书 (đọc sách Trung)","example":{"zh":"她在家里读书。","py":"Tā zài jiā li dúshū.","vi":"Cô ấy đọc sách ở nhà."}},{"stt":16,"hanzi":"和","pinyin":"hé","hanviet":"Hoà","pos":"Giới từ","meaning":"với, cùng (ai)","comps":"我和你 (tôi và bạn), 和朋友 (với bạn bè)","example":{"zh":"我和朋友们去唱歌。","py":"Wǒ hé péngyoumen qù chàng gē.","vi":"Mình đi hát với các bạn."}},{"stt":17,"hanzi":"朋友","pinyin":"péngyou","hanviet":"Bằng hữu","pos":"Danh từ","meaning":"bạn, bạn bè","comps":"好朋友 (bạn thân), 朋友们 (các bạn)","example":{"zh":"他是我的好朋友。","py":"Tā shì wǒ de hǎo péngyou.","vi":"Cậu ấy là bạn thân của mình."}},{"stt":18,"hanzi":"唱","pinyin":"chàng","hanviet":"Xướng","pos":"Động từ","meaning":"hát, ca hát","comps":"唱歌 (hát), 唱中文歌 (hát bài tiếng Trung)","example":{"zh":"我们晚上去外边唱歌。","py":"Wǒmen wǎnshang qù wàibian chàng gē.","vi":"Tối chúng mình ra ngoài hát."}},{"stt":19,"hanzi":"歌","pinyin":"gē","hanviet":"Ca","pos":"Danh từ","meaning":"bài hát, ca khúc","comps":"唱歌 (hát), 中文歌 (bài hát tiếng Trung)","example":{"zh":"我很喜欢中文歌。","py":"Wǒ hěn xǐhuan Zhōngwén gē.","vi":"Mình rất thích bài hát tiếng Trung."}},{"stt":20,"hanzi":"好听","pinyin":"hǎotīng","hanviet":"Hảo thính","pos":"Tính từ","meaning":"hay, dễ nghe (âm thanh)","comps":"很好听 (rất hay), 不好听 (không hay)","example":{"zh":"你唱歌很好听。","py":"Nǐ chàng gē hěn hǎotīng.","vi":"Cậu hát hay lắm."}},{"stt":21,"hanzi":"电视","pinyin":"diànshì","hanviet":"Điện thị","pos":"Danh từ","meaning":"ti vi, truyền hình","comps":"看电视 (xem ti vi), 电视上 (trên ti vi)","example":{"zh":"我在家里看电视。","py":"Wǒ zài jiā li kàn diànshì.","vi":"Mình xem ti vi ở nhà."}},{"stt":22,"hanzi":"狗","pinyin":"gǒu","hanviet":"Cẩu","pos":"Danh từ","meaning":"con chó","comps":"小狗 (chó con), 一只狗 (một con chó)","example":{"zh":"我也有一只小狗。","py":"Wǒ yě yǒu yì zhī xiǎo gǒu.","vi":"Mình cũng có một chú chó nhỏ."}},{"stt":23,"hanzi":"玩","pinyin":"wán","hanviet":"Ngoạn","pos":"Động từ","meaning":"chơi, chơi đùa","comps":"玩儿 (chơi), 和朋友玩 (chơi với bạn)","example":{"zh":"我和小狗玩。","py":"Wǒ hé xiǎo gǒu wán.","vi":"Mình chơi với chú chó nhỏ."}}],"hanzi":[{"char":"前边","pinyin":"qiánbian","hanviet":"Tiền biên","chars":["前","边"],"story":"前 phía trên là 丷 + 一 (bàn chân bước tới), dưới là 月 (nguyệt) và 刂 (dao) — hình người tiến về phía trước. 边 gồm bộ 辶 (bước đi) + 力 (sức), nghĩa gốc là đường ranh, cái rìa. Ghép lại 前边 là \"phía trước\"."},{"char":"边","pinyin":"bian / biān","hanviet":"Biên","chars":["边"],"story":"边 (phồn thể 邊) = bộ 辶 (đi, bước) + 力. Nghĩa gốc là cái rìa, đường biên giới. Trong tiếng Trung hiện đại, 边 đứng SAU các chữ chỉ hướng để thành từ chỉ vị trí: 前边、外边、这边、那边."},{"char":"家","pinyin":"jiā","hanviet":"Gia","chars":["家"],"story":"家 = bộ 宀 (mái nhà) ở trên + 豕 (con lợn) ở dưới. Người xưa nuôi lợn ngay dưới mái nhà, có lợn tức là có nhà cửa yên ổn — nên 家 nghĩa là nhà, gia đình. Về sau mượn làm lượng từ cho cửa hàng, quán xá: 一家电影院."},{"char":"那个","pinyin":"nàge","hanviet":"Na cá","chars":["那","个"],"story":"那 gồm phần bên trái là 冄 và bên phải là 阝 (bộ ấp, chỉ vùng đất), vốn chỉ một vùng đất ở XA. 个 vẽ một nhánh tre, là lượng từ dùng chung nhất. Ghép lại 那个 = \"cái kia, cái đó\" (↔ 这个 cái này)."},{"char":"外边","pinyin":"wàibian","hanviet":"Ngoại biên","chars":["外","边"],"story":"外 = 夕 (buổi chiều tối) + 卜 (bói toán). Người xưa bói vào sáng sớm mới đúng lệ, bói lúc chiều tối là \"ngoài lệ\" — từ đó 外 mang nghĩa bên ngoài. Ghép với 边 thành 外边: phía bên ngoài."},{"char":"椅子","pinyin":"yǐzi","hanviet":"Ỷ tử","chars":["椅","子"],"story":"椅 là chữ hình thanh: bộ 木 (gỗ) chỉ nghĩa — đồ làm bằng gỗ, còn 奇 qí chỉ âm đọc. 子 ở đây là đuôi từ quen thuộc của danh từ đồ vật, giống 桌子、包子、饺子 đã học."},{"char":"上","pinyin":"shang / shàng","hanviet":"Thượng","chars":["上"],"story":"上 là chữ chỉ sự: một nét ngang dài làm mốc, thêm nét ngắn ở PHÍA TRÊN mốc đó → nghĩa \"ở trên\". Chữ ngược lại là 下 (nét ngắn nằm dưới mốc). Làm phương vị từ thì 上 luôn đứng SAU danh từ: 椅子上、桌子上."},{"char":"本","pinyin":"běn","hanviet":"Bản","chars":["本"],"story":"本 chính là chữ 木 (cây) thêm một nét ngang ngắn ngay chỗ gốc rễ, chỉ vào phần gốc — nghĩa gốc là \"gốc, căn bản\" (本来、日本). Sách xưa đóng thành từng tập từ vỏ cây, nên 本 thành lượng từ của sách vở."},{"char":"书","pinyin":"shū","hanviet":"Thư","chars":["书"],"story":"书 (phồn thể 書) vẽ bàn tay cầm bút 聿 viết lên tấm thẻ tre. Nghĩa gốc là \"viết\", rồi chuyển thành \"cái được viết ra\" = sách. Cùng gốc với 画 (vẽ) và 律 (luật) đều có phần 聿."},{"char":"那","pinyin":"nà","hanviet":"Na","chars":["那"],"story":"那 = 冄 bên trái + 阝 (bộ ấp, chỉ vùng đất, xóm làng) bên phải, vốn là tên một vùng đất ở xa. Nay dùng để chỉ người hoặc vật ở XA, đối lập với 这 (này, ở gần)."},{"char":"第","pinyin":"dì","hanviet":"Đệ","chars":["第"],"story":"第 = bộ 竹 (tre) ở trên + 弟 (em) chỉ âm đọc dì. Ngày xưa người ta viết thứ tự lên các thẻ tre rồi xếp theo hàng, nên 第 mang nghĩa \"thứ tự\". Đặt trước số đếm là thành số thứ tự: 第一、第二."},{"char":"学习","pinyin":"xuéxí","hanviet":"Học tập","chars":["学","习"],"story":"学 (學) vẽ hai bàn tay dạy đứa trẻ 子 ngồi dưới mái nhà — chính là lớp học. 习 (習) gồm 羽 (lông cánh) trên 白, vẽ con chim non tập vỗ cánh đi vỗ cánh lại. 学习 = học rồi luyện đi luyện lại."},{"char":"做","pinyin":"zuò","hanviet":"Tố","chars":["做"],"story":"做 là chữ hình thanh: bộ 亻 (người) chỉ nghĩa — đây là việc con người làm, còn 故 gù chỉ âm đọc. 做 thiên về việc CỤ THỂ, tay chân làm ra: 做饭 (nấu cơm), 做作业 (làm bài tập)."},{"char":"白天","pinyin":"báitiān","hanviet":"Bạch thiên","chars":["白","天"],"story":"白 vốn vẽ ánh mặt trời vừa ló, hoặc hạt gạo trắng — nghĩa là trắng, sáng. 天 vẽ một người đứng dang tay, thêm nét ngang trên đầu chỉ bầu trời. 白天 = khoảng trời còn sáng = ban ngày."},{"char":"读书","pinyin":"dúshū","hanviet":"Độc thư","chars":["读","书"],"story":"读 (讀) = bộ 讠 (lời nói) chỉ nghĩa + 卖 chỉ âm — đọc là phát thành tiếng. Ghép với 书 (sách) thành 读书: đọc sách; trong khẩu ngữ còn có nghĩa rộng là \"đi học, ăn học\"."},{"char":"和","pinyin":"hé","hanviet":"Hoà","chars":["和"],"story":"和 = 禾 (cây lúa) chỉ âm + 口 (miệng) chỉ nghĩa. Nghĩa gốc là nhiều giọng hát hoà nhịp với nhau, từ đó ra \"hoà hợp\" (和平 hoà bình). Nay hay dùng nhất là nối hai danh từ: A 和 B."},{"char":"朋友","pinyin":"péngyou","hanviet":"Bằng hữu","chars":["朋","友"],"story":"朋 vẽ hai xâu vỏ sò treo cạnh nhau — cùng một nhóm, cùng một loại. 友 vẽ hai bàn tay cùng chìa về một hướng, ý là chìa tay giúp nhau. 朋友 = những người cùng nhóm, giúp đỡ nhau: bạn bè."},{"char":"唱","pinyin":"chàng","hanviet":"Xướng","chars":["唱"],"story":"唱 là chữ hình thanh rất điển hình: bộ 口 (miệng) chỉ nghĩa — âm thanh phát ra từ miệng, còn 昌 chāng chỉ âm đọc chàng. Mọi chữ có bộ 口 bên trái đều liên quan tới miệng: 吃、喝、叫、听."},{"char":"歌","pinyin":"gē","hanviet":"Ca","chars":["歌"],"story":"歌 = 哥 gē chỉ âm đọc + 欠 chỉ nghĩa (欠 vẽ một người há miệng thở hơi ra). Ghép lại: mở miệng cất tiếng thành lời — bài hát. Đi liền với 唱 thành cụm quen thuộc 唱歌."},{"char":"好听","pinyin":"hǎotīng","hanviet":"Hảo thính","chars":["好","听"],"story":"好听 là từ ghép \"好 + động từ giác quan\": 好 (tốt) + 听 (nghe) = nghe vào thấy dễ chịu, tức là HAY. Cùng khuôn với 好吃 (ngon), 好看 (đẹp mắt), 好喝 (uống ngon). Phủ định là 不好听."},{"char":"电视","pinyin":"diànshì","hanviet":"Điện thị","chars":["电","视"],"story":"电 (電) vẽ tia chớp loé ra từ đám mây, nghĩa là điện. 视 = bộ 礻 (示, thần linh, chỉ việc nhìn ngắm) + 见 (trông thấy) → nhìn, xem. 电视 = cái để xem bằng điện. Cùng họ với 电影、电话 đã học."},{"char":"狗","pinyin":"gǒu","hanviet":"Cẩu","chars":["狗"],"story":"狗 là chữ hình thanh: bộ 犭 (khuyển, vẽ con thú bốn chân) chỉ nghĩa, còn 句 gōu chỉ âm đọc gǒu. Nhớ được bộ 犭 là đoán được nghĩa của cả một loạt chữ về loài thú: 猫 (mèo), 猪 (lợn)."},{"char":"玩","pinyin":"wán","hanviet":"Ngoạn","chars":["玩"],"story":"玩 = bộ 王 (ở đây là 玉, viên ngọc) + 元 yuán chỉ âm. Nghĩa gốc là cầm viên ngọc trong tay xoay ngắm cho vui, từ đó ra nghĩa chơi, giải trí. Khẩu ngữ miền Bắc hay thêm 儿: 玩儿 đọc là wánr."}],"grammar":[{"title":"Câu tồn hiện 存现句","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>处所词</b><small>nơi chốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>有</b><small>có</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>数量词</b><small>số + lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>người / vật</small></span></div>","summary":"<p class=\"gr-lead\">Nói ở đâu có gì</p><ul><li>Câu tồn hiện dùng để nói <b>ở một nơi nào đó có cái gì</b>. Phần chỉ nơi chốn làm <b>chủ ngữ</b>, đứng ngay đầu câu.</li><li>Phần nơi chốn thường là <b>danh từ + phương vị từ</b>: <span class=\"zh\">学校前边</span>, <span class=\"zh\">椅子上</span>, <span class=\"zh\">家里</span>, <span class=\"zh\">电影院外边</span>.</li><li>Người hoặc vật đứng sau <span class=\"zh\">有</span> hầu như luôn kèm <b>số + lượng từ</b>: <span class=\"zh\">一家电影院</span>, <span class=\"zh\">一本书</span>, <span class=\"zh\">一只小狗</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">学校前边有一家电影院。</span> = Phía trước trường có một rạp chiếu phim.</p>","note":"<b>Lưu ý:</b> Nơi chốn đã làm chủ ngữ thì <b>bỏ</b> <span class=\"zh\">在</span>: nói <span class=\"zh\">椅子上有一本书</span>, không nói <span class=\"zh\">在椅子上有一本书</span> ✗. Phủ định dùng <span class=\"zh\">没有</span>, không có <span class=\"zh\">不有</span>.","examples":[{"zh":"椅子上有一本中文书。","py":"Yǐzi shang yǒu yì běn Zhōngwén shū.","vi":"Trên ghế có một quyển sách tiếng Trung."},{"zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường có một rạp chiếu phim."},{"zh":"电影院前边是一家超市。","py":"Diànyǐngyuàn qiánbian shì yì jiā chāoshì.","vi":"Phía trước rạp chiếu phim là một siêu thị."},{"zh":"电影院前边不是超市。","py":"Diànyǐngyuàn qiánbian bú shì chāoshì.","vi":"Phía trước rạp chiếu phim không phải là siêu thị."},{"zh":"桌子上没有小猫。","py":"Zhuōzi shang méiyǒu xiǎo māo.","vi":"Trên bàn không có mèo con."}],"exercises":[]},{"title":"Thứ tự từ chỉ thời gian và nơi chốn làm trạng ngữ","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>时间词</b><small>khi nào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>在 + 处所</b><small>ở đâu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>làm gì</small></span></div>","summary":"<p class=\"gr-lead\">Khi nào rồi ở đâu</p><ul><li>Cả từ chỉ thời gian lẫn từ chỉ nơi chốn đều là <b>trạng ngữ</b>, đều phải đứng <b>trước động từ</b> — ngược hẳn với tiếng Việt.</li><li>Khi câu có cả hai: <b>thời gian đứng trước, nơi chốn đứng sau</b> — <span class=\"zh\">明天上午在学校</span>, <span class=\"zh\">晚上在家里</span>.</li><li>Từ chỉ thời gian có thể chuyển lên <b>trước chủ ngữ</b> để nhấn mạnh: <span class=\"zh\">明天上午我在学校学习。</span> Nơi chốn thì không chuyển được.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我　明天上午　在学校　学习。</span> = Sáng mai tôi học ở trường.</p>","note":"<b>Lưu ý:</b> Người Việt hay nói ngược: <span class=\"zh\">我学习在学校明天上午</span> ✗. Nhớ trật tự <b>Ai — khi nào — ở đâu — làm gì</b>, và nơi chốn <b>phải có</b> <span class=\"zh\">在</span>.","examples":[{"zh":"我明天上午在学校学习。","py":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","vi":"Sáng mai tôi học ở trường."},{"zh":"我们七点在电影院外边见。","py":"Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn.","vi":"7 giờ chúng ta gặp nhau ở ngoài rạp chiếu phim."},{"zh":"安妮下午在家里学中文。","py":"Ānnī xiàwǔ zài jiā li xué Zhōngwén.","vi":"Buổi chiều Annie học tiếng Trung ở nhà."},{"zh":"陈天中明天中午在学校吃午饭。","py":"Chén Tiānzhōng míngtiān zhōngwǔ zài xuéxiào chī wǔfàn.","vi":"Trưa mai Trần Thiên Trung ăn trưa ở trường."}],"exercises":[{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你们今天下午两点____上课？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">在学校。</span></span></span><span class=\"qz-hint\">2 giờ chiều nay các bạn học ở đâu? — Ở trường.</span>","answer":["在哪儿","在哪里"],"explain":"你们今天下午两点在哪儿上课？ (Nǐmen jīntiān xiàwǔ liǎng diǎn zài nǎr shàngkè?)"},{"type":"fill","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你们____在超市买什么呢？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">买菜呢。</span></span></span><span class=\"qz-hint\">Bây giờ các bạn mua gì ở siêu thị thế? — Mua rau đấy.</span>","answer":["现在"],"explain":"你们现在在超市买什么呢？ (Nǐmen xiànzài zài chāoshì mǎi shénme ne?)"}]},{"title":"Cách sử dụng 第","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>第</b><small>thứ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>数词</b><small>số đếm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(名词)</b><small>danh từ</small></span></div>","summary":"<p class=\"gr-lead\">Thứ nhất, thứ hai…</p><ul><li><span class=\"zh\">第</span> đặt <b>trước số đếm</b> để biến số đếm thành số thứ tự: <span class=\"zh\">二</span> (hai) → <span class=\"zh\">第二</span> (thứ hai).</li><li>Sau <span class=\"zh\">第 + 数词</span> vẫn phải có <b>lượng từ</b> rồi mới tới danh từ: <span class=\"zh\">第二本书</span>, <span class=\"zh\">第一个孩子</span>.</li><li>Muốn hỏi \"thứ mấy\" thì dùng <span class=\"zh\">第几</span>: <span class=\"zh\">这是你的第几本中文书？</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">第二本中文书</span> = quyển sách tiếng Trung thứ hai　·　<span class=\"zh\">第一家电影院</span> = rạp phim thứ nhất</p>","note":"<b>Lưu ý:</b> Với số thứ tự, <span class=\"zh\">二</span> <b>không đổi</b> thành <span class=\"zh\">两</span>: nói <span class=\"zh\">第二本</span>, không nói <span class=\"zh\">第两本</span> ✗.","examples":[{"zh":"这是我的第二本中文书。","py":"Zhè shì wǒ de dì-èr běn Zhōngwén shū.","vi":"Đây là quyển sách tiếng Trung thứ hai của mình."},{"zh":"第一，第二，第三","py":"dì yī, dì èr, dì sān","vi":"thứ nhất, thứ hai, thứ ba"},{"zh":"第一个，第二个，第一本","py":"dì yī gè, dì èr gè, dì yī běn","vi":"cái thứ nhất, cái thứ hai, quyển thứ nhất"},{"zh":"第一个学生，第一本书","py":"dì yī gè xuéshēng, dì yī běn shū","vi":"học sinh thứ nhất, quyển sách thứ nhất"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai bạn hẹn nhau đi xem phim","lines":[{"speaker":"文","name":"Lý Văn","zh":"学校前边有一家电影院。","py":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","vi":"Phía trước trường có một rạp chiếu phim."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"对。我们晚上去那个电影院看电影吧。","py":"Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","vi":"Đúng rồi. Tối nay chúng mình đến rạp đó xem phim đi."},{"speaker":"文","name":"Lý Văn","zh":"好！我们七点在电影院外边见，好吗？","py":"Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","vi":"Được! Bảy giờ mình gặp nhau ở ngoài rạp phim nhé?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"好的，晚上七点见！","py":"Hǎo de, wǎnshang qī diǎn jiàn!","vi":"Được, bảy giờ tối gặp nhé!"}]},{"titleZh":"课文二","titleVi":"Trong lớp — hỏi sách trên ghế","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"椅子上有一本中文书，那是谁的书？","py":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","vi":"Trên ghế có một quyển sách tiếng Trung, kia là sách của ai vậy?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"是我的书，谢谢。这是我的第二本中文书。","py":"Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","vi":"Sách của mình đấy, cảm ơn cậu. Đây là quyển sách tiếng Trung thứ hai của mình."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"不客气。你明天上午在哪儿？","py":"Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","vi":"Không có gì. Sáng mai cậu ở đâu?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"我明天上午在学校学习。","py":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","vi":"Sáng mai mình học ở trường."}]},{"titleZh":"课文三","titleVi":"Hỏi nhau cuối tuần này làm gì","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"明天星期六，你做什么？","py":"Míngtiān Xīngqīliù, nǐ zuò shénme?","vi":"Mai là thứ Bảy, em làm gì thế?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我白天在家里读书，晚上和朋友们去外边唱歌。","py":"Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","vi":"Ban ngày em đọc sách ở nhà, tối thì đi hát với các bạn ở ngoài."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你唱歌很好听。","py":"Nǐ chàng gē hěn hǎotīng.","vi":"Em hát hay lắm."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"谢谢！您星期六做什么？","py":"Xièxie! Nín Xīngqīliù zuò shénme?","vi":"Cảm ơn chị! Thứ Bảy chị làm gì ạ?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我在家里做饭、看电视，和孩子们、小狗玩。","py":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","vi":"Chị ở nhà nấu cơm, xem ti vi, chơi với các con và chú chó nhỏ."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我也有一只小狗。","py":"Wǒ yě yǒu yì zhī xiǎo gǒu.","vi":"Em cũng có một chú chó nhỏ."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Đóng vai theo 3 bài khoá","q":{"zh":"两人一组，一个人扮演白家月，另一个人扮演陈天中，仿照本课三篇课文的内容对话。","py":"Liǎng rén yì zǔ, yí gè rén bànyǎn Bái Jiāyuè, lìng yí gè rén bànyǎn Chén Tiānzhōng, fǎngzhào běn kè sān piān kèwén de nèiróng duìhuà.","vi":"Hai người một nhóm, một người đóng Bạch Gia Nguyệt, người kia đóng Trần Thiên Trung, hội thoại theo nội dung 3 bài khoá."},"items":[{"lines":[{"who":"白家月","zh":"我们晚上去看电影吧。","py":"Wǒmen wǎnshang qù kàn diànyǐng ba.","vi":"Tối nay chúng ta đi xem phim nhé."},{"who":"陈天中","zh":"好！我们几点在哪儿见？","py":"Hǎo! Wǒmen jǐ diǎn zài nǎr jiàn?","vi":"Được! Mấy giờ chúng ta gặp nhau ở đâu?"},{"who":"白家月","zh":"七点在电影院外边见吧。","py":"Qī diǎn zài diànyǐngyuàn wàibian jiàn ba.","vi":"7 giờ gặp nhau ở ngoài rạp chiếu phim nhé."}]},{"lines":[{"who":"陈天中","zh":"椅子上有一本书，是你的吗？","py":"Yǐzi shang yǒu yì běn shū, shì nǐ de ma?","vi":"Trên ghế có một quyển sách, là của bạn à?"},{"who":"白家月","zh":"是我的。这是我的第三本中文书。","py":"Shì wǒ de. Zhè shì wǒ de dì sān běn Zhōngwén shū.","vi":"Là của mình. Đây là quyển sách tiếng Trung thứ ba của mình."}]}]}],"speak":[]},"review":{"range":"7–9","rows":[{"l":7,"zh":"时间的表达（2）","vi":"Cách nói giờ giấc (2)","ex":{"zh":"上午十点","py":"shàngwǔ shí diǎn","vi":"10 giờ sáng"}},{"l":8,"zh":"方位词","vi":"Phương vị từ","ex":{"zh":"在桌子上","py":"zài zhuōzi shang","vi":"ở trên bàn"}},{"l":7,"zh":"语气助词\"吧\"（1）","vi":"Trợ từ ngữ khí 吧 (1)","ex":{"zh":"我们上课吧。","py":"Wǒmen shàngkè ba.","vi":"Chúng ta vào học thôi."}},{"l":7,"zh":"副词、时间词语作状语的位置","vi":"Vị trí của phó từ, từ chỉ thời gian làm trạng ngữ","ex":{"zh":"我下午不去学校。","py":"Wǒ xiàwǔ bú qù xuéxiào.","vi":"Chiều nay tôi không đến trường."}},{"l":7,"zh":"语气助词\"呢\"（2）","vi":"Trợ từ ngữ khí 呢 (2)","ex":{"zh":"我下午还有课呢。","py":"Wǒ xiàwǔ hái yǒu kè ne.","vi":"Chiều nay tôi còn có tiết học đấy."}},{"l":8,"zh":"介词\"在\"","vi":"Giới từ 在","ex":{"zh":"我在学校学习。","py":"Wǒ zài xuéxiào xuéxí.","vi":"Tôi học ở trường."}},{"l":8,"zh":"能愿动词\"能\"","vi":"Động từ năng nguyện 能","ex":{"zh":"我能去。","py":"Wǒ néng qù.","vi":"Tôi đi được."}},{"l":9,"zh":"存现句（1）","vi":"Câu tồn hiện (1)","ex":{"zh":"桌子上有/是一本书。","py":"Zhuōzi shang yǒu/shì yì běn shū.","vi":"Trên bàn có / là một quyển sách."}},{"l":9,"zh":"时间词语和处所词语同时作状语的顺序","vi":"Thời gian đứng trước nơi chốn","ex":{"zh":"我们上午十点在书店见吧。","py":"Wǒmen shàngwǔ shí diǎn zài shūdiàn jiàn ba.","vi":"10 giờ sáng chúng ta gặp ở hiệu sách nhé."}},{"l":9,"zh":"表示序数的\"第\"","vi":"Số thứ tự với 第","ex":{"zh":"第一，第一个，第一个学生","py":"dì yī, dì yī gè, dì yī gè xuéshēng","vi":"thứ nhất, cái thứ nhất, học sinh thứ nhất"}}]}},{"id":"k1v3-b10","courseId":"k1v3","order":10,"title":"Táo ở đây rẻ thật!","titleZh":"这儿的苹果真便宜！","titlePy":"zhèr de píngguǒ zhēn piányi","vocab":[{"stt":1,"hanzi":"杯子","pinyin":"bēizi","hanviet":"Bôi tử","pos":"Danh từ","meaning":"cái cốc, cái ly","comps":"一个杯子 (một cái cốc), 水杯 (cốc nước)","example":{"zh":"请问，有杯子吗？","py":"Qǐngwèn, yǒu bēizi ma?","vi":"Cho hỏi, ở đây có cốc không ạ?"}},{"stt":2,"hanzi":"售货员","pinyin":"shòuhuòyuán","hanviet":"Thụ hoá viên","pos":"Danh từ","meaning":"nhân viên bán hàng","comps":"女售货员 (cô bán hàng), 男售货员 (anh bán hàng)","example":{"zh":"售货员在商店工作。","py":"Shòuhuòyuán zài shāngdiàn gōngzuò.","vi":"Nhân viên bán hàng làm việc ở cửa hàng."}},{"stt":3,"hanzi":"这边","pinyin":"zhèbiān","hanviet":"Giá biên","pos":"Đại từ","meaning":"bên này (↔ 那边)","comps":"在这边 (ở bên này), 这边有 (bên này có)","example":{"zh":"杯子在这边。","py":"Bēizi zài zhèbiān.","vi":"Cốc ở bên này."}},{"stt":4,"hanzi":"钱","pinyin":"qián","hanviet":"Tiền","pos":"Danh từ","meaning":"tiền","comps":"多少钱 (bao nhiêu tiền), 五块钱 (năm tệ)","example":{"zh":"多少钱一个？","py":"Duōshao qián yí gè?","vi":"Bao nhiêu tiền một cái?"}},{"stt":5,"hanzi":"这些","pinyin":"zhèxiē","hanviet":"Giá ta","pos":"Đại từ","meaning":"những cái này","comps":"这些人 (những người này), 这些衣服 (số quần áo này)","example":{"zh":"这些七块二。","py":"Zhèxiē qī kuài èr.","vi":"Chỗ này bảy tệ hai."}},{"stt":6,"hanzi":"块","pinyin":"kuài","hanviet":"Khối","pos":"Lượng từ","meaning":"đồng, tệ (khẩu ngữ)","comps":"五块钱 (năm tệ), 三块五 (ba tệ rưỡi)","example":{"zh":"这些五块钱一个。","py":"Zhèxiē wǔ kuài qián yí gè.","vi":"Mấy cái này năm tệ một cái."}},{"stt":7,"hanzi":"那些","pinyin":"nàxiē","hanviet":"Na ta","pos":"Đại từ","meaning":"những cái kia","comps":"那些人 (những người kia), 那些书 (số sách kia)","example":{"zh":"那些十块钱一个。","py":"Nàxiē shí kuài qián yí gè.","vi":"Mấy cái kia mười tệ một cái."}},{"stt":8,"hanzi":"这儿","pinyin":"zhèr","hanviet":"Giá nhi","pos":"Đại từ","meaning":"ở đây, chỗ này","comps":"在这儿 (ở đây), 这儿的 (của ở đây)","example":{"zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây nhiều thật đấy!"}},{"stt":9,"hanzi":"水果","pinyin":"shuǐguǒ","hanviet":"Thuỷ quả","pos":"Danh từ","meaning":"hoa quả, trái cây","comps":"买水果 (mua hoa quả), 水果店 (cửa hàng trái cây)","example":{"zh":"我想买一些水果。","py":"Wǒ xiǎng mǎi yìxiē shuǐguǒ.","vi":"Mình muốn mua một ít hoa quả."}},{"stt":10,"hanzi":"少","pinyin":"shǎo","hanviet":"Thiểu","pos":"Tính từ","meaning":"ít (↔ 多 nhiều)","comps":"不少 (không ít, khá nhiều), 很少 (rất ít)","example":{"zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây nhiều thật đấy!"}},{"stt":11,"hanzi":"斤","pinyin":"jīn","hanviet":"Cân","pos":"Lượng từ","meaning":"cân TQ (= 500g)","comps":"两斤 (hai cân), 一斤苹果 (một cân táo)","example":{"zh":"我想买两斤苹果。","py":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","vi":"Mình muốn mua hai cân táo."}},{"stt":12,"hanzi":"苹果","pinyin":"píngguǒ","hanviet":"Bình quả","pos":"Danh từ","meaning":"quả táo","comps":"一斤苹果 (một cân táo), 买苹果 (mua táo)","example":{"zh":"苹果三块五一斤。","py":"Píngguǒ sān kuài wǔ yì jīn.","vi":"Táo ba tệ rưỡi một cân."}},{"stt":13,"hanzi":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","pos":"Tính từ","meaning":"rẻ (↔ 贵 đắt)","comps":"很便宜 (rất rẻ), 不便宜 (không rẻ)","example":{"zh":"这儿的苹果真便宜！","py":"Zhèr de píngguǒ zhēn piányi!","vi":"Táo ở đây rẻ thật!"}},{"stt":14,"hanzi":"商店","pinyin":"shāngdiàn","hanviet":"Thương điếm","pos":"Danh từ","meaning":"cửa hàng, cửa tiệm","comps":"这家商店 (cửa hàng này), 去商店 (đi cửa hàng)","example":{"zh":"这家商店衣服真多！","py":"Zhè jiā shāngdiàn yīfu zhēn duō!","vi":"Cửa hàng này nhiều quần áo thật!"}},{"stt":15,"hanzi":"衣服","pinyin":"yīfu","hanviet":"Y phục","pos":"Danh từ","meaning":"quần áo","comps":"买衣服 (mua quần áo), 一件衣服 (một bộ đồ)","example":{"zh":"男孩子的衣服在那儿。","py":"Nán háizi de yīfu zài nàr.","vi":"Quần áo con trai ở đằng kia."}},{"stt":16,"hanzi":"件","pinyin":"jiàn","hanviet":"Kiện","pos":"Lượng từ","meaning":"chiếc (quần áo); việc","comps":"一件衣服 (một chiếc áo), 这件 (chiếc này)","example":{"zh":"小雪能穿，买一件吧。","py":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","vi":"Tiểu Tuyết mặc được, mua một chiếc đi."}},{"stt":17,"hanzi":"元","pinyin":"yuán","hanviet":"Nguyên","pos":"Lượng từ","meaning":"đồng, tệ (văn viết)","comps":"一百元 (một trăm tệ), 十元 (mười tệ)","example":{"zh":"这件衣服一百元。","py":"Zhè jiàn yīfu yìbǎi yuán.","vi":"Bộ quần áo này một trăm tệ."}},{"stt":18,"hanzi":"怎么样","pinyin":"zěnmeyàng","hanviet":"Chẩm ma dạng","pos":"Đại từ nghi vấn","meaning":"thế nào, ra sao","comps":"你怎么样 (bạn thế nào), 这个怎么样 (cái này thế nào)","example":{"zh":"这件一百元，怎么样？","py":"Zhè jiàn yìbǎi yuán, zěnmeyàng?","vi":"Cái này một trăm tệ, thấy thế nào?"}},{"stt":19,"hanzi":"贵","pinyin":"guì","hanviet":"Quý","pos":"Tính từ","meaning":"đắt (↔ 便宜 rẻ)","comps":"很贵 (rất đắt), 不贵 (không đắt)","example":{"zh":"好看，也不贵。","py":"Hǎokàn, yě bú guì.","vi":"Đẹp đấy, cũng không đắt."}},{"stt":20,"hanzi":"穿","pinyin":"chuān","hanviet":"Xuyên","pos":"Động từ","meaning":"mặc, đi (giày dép)","comps":"穿衣服 (mặc quần áo), 能穿 (mặc vừa)","example":{"zh":"小雪能穿这件衣服。","py":"Xiǎoxuě néng chuān zhè jiàn yīfu.","vi":"Tiểu Tuyết mặc vừa bộ này."}},{"stt":21,"hanzi":"女","pinyin":"nǚ","hanviet":"Nữ","pos":"Tính từ","meaning":"nữ, con gái (↔ 男)","comps":"女孩子 (bé gái), 女朋友 (bạn gái)","example":{"zh":"这些是女孩子的衣服。","py":"Zhèxiē shì nǚ háizi de yīfu.","vi":"Đây là quần áo của con gái."}},{"stt":22,"hanzi":"男","pinyin":"nán","hanviet":"Nam","pos":"Tính từ","meaning":"nam, con trai (↔ 女)","comps":"男孩子 (bé trai), 男朋友 (bạn trai)","example":{"zh":"男孩子的衣服在那儿。","py":"Nán háizi de yīfu zài nàr.","vi":"Quần áo con trai ở đằng kia."}},{"stt":23,"hanzi":"那儿","pinyin":"nàr","hanviet":"Na nhi","pos":"Đại từ","meaning":"ở kia, chỗ đó","comps":"在那儿 (ở đằng kia), 去那儿 (đến đó)","example":{"zh":"他的衣服在那儿。","py":"Tā de yīfu zài nàr.","vi":"Quần áo của cậu ấy ở đằng kia."}}],"hanzi":[{"char":"杯子","pinyin":"bēizi","hanviet":"Bôi tử","chars":["杯","子"],"story":"杯 là chữ hình thanh: bộ 木 (gỗ) chỉ nghĩa — cốc chén thời xưa tiện từ gỗ, còn 不 chỉ âm đọc bēi. 子 ở đây là đuôi từ quen thuộc của đồ vật, giống 椅子、桌子、包子、饺子 đã học."},{"char":"售货员","pinyin":"shòuhuòyuán","hanviet":"Thụ hoá viên","chars":["售","货","员"],"story":"售 = 隹 (con chim) trên 口 (miệng) — rao lên thành tiếng để bán. 货 = 化 chỉ âm + 贝 (vỏ sò, tiền của người xưa) → hàng hoá. 员 = 口 + 贝, chỉ người làm một công việc. Ghép ba chữ: người bán hàng hoá."},{"char":"这边","pinyin":"zhèbiān","hanviet":"Giá biên","chars":["这","边"],"story":"这 = bộ 辶 (bước đi) + 文, dùng chỉ người hoặc vật ở GẦN (↔ 那 ở xa). 边 nghĩa là bên, phía (đã học ở Bài 9). 这边 = phía bên này. Cặp 这边 ↔ 那边 cô đã cho học từ Bài 6."},{"char":"钱","pinyin":"qián","hanviet":"Tiền","chars":["钱"],"story":"钱 (phồn thể 錢) = bộ 钅 (金, kim loại) chỉ nghĩa + 戋 jiān chỉ âm. Tiền xưa đúc bằng đồng, bằng vàng nên chữ mang bộ kim. Âm Hán Việt đọc là \"Tiền\" — tiếng Việt mượn thẳng chữ này."},{"char":"这些","pinyin":"zhèxiē","hanviet":"Giá ta","chars":["这","些"],"story":"些 gồm 此 (này) ở trên và 二 ở dưới, ý là \"một vài, mấy cái\". Ghép với 这 (này) thành 这些 = những cái này — chính là dạng SỐ NHIỀU của 这个. Cặp đối lập là 那些."},{"char":"块","pinyin":"kuài","hanviet":"Khối","chars":["块"],"story":"块 = bộ 土 (đất) + 夬 guài chỉ âm. Nghĩa gốc là một cục đất, rồi thành lượng từ cho mọi vật thành khối, thành miếng. Trong khẩu ngữ, 块 là đơn vị tiền quen thuộc nhất; văn viết thì dùng 元."},{"char":"那些","pinyin":"nàxiē","hanviet":"Na ta","chars":["那","些"],"story":"那 chỉ người hoặc vật ở XA, 些 chỉ số nhiều \"mấy cái\". 那些 = những cái kia, dạng số nhiều của 那个. Học theo bốn cặp cho dễ nhớ: 这个↔那个, 这些↔那些, 这边↔那边, 这儿↔那儿."},{"char":"这儿","pinyin":"zhèr","hanviet":"Giá nhi","chars":["这","儿"],"story":"儿 vốn vẽ đứa trẻ chưa khép thóp, nghĩa là \"con, trẻ nhỏ\". Ở đây 儿 chỉ là đuôi 儿 hoá của khẩu ngữ miền Bắc, đọc dính vào chữ trước thành zhèr. 这儿 = chỗ này, ở đây; miền Nam nói 这里."},{"char":"水果","pinyin":"shuǐguǒ","hanviet":"Thuỷ quả","chars":["水","果"],"story":"水 vẽ dòng nước chảy giữa, hai bên là các giọt bắn ra. 果 vẽ một cái cây 木 với quả tròn đậu trên ngọn. 水果 = thứ quả mọng nước = trái cây. Chữ 果 còn nằm trong 苹果 học ngay sau đây."},{"char":"少","pinyin":"shǎo","hanviet":"Thiểu","chars":["少"],"story":"少 chính là chữ 小 (nhỏ) thêm một nét phẩy, ý là bớt đi thêm chút nữa → ÍT. Cặp đối 多 ↔ 少 cô đã giới thiệu ở Bài 8. Nhớ kỹ 不少 nghĩa là \"không ít\", tức là KHÁ NHIỀU chứ không phải ít."},{"char":"斤","pinyin":"jīn","hanviet":"Cân","chars":["斤"],"story":"斤 vốn vẽ cái rìu có lưỡi và cán, sau được mượn làm đơn vị cân nặng. Một 斤 của Trung Quốc = 500 gram, tức là NỬA cân theo cách nói của người Việt — chỗ này rất dễ nhầm khi đi chợ."},{"char":"苹果","pinyin":"píngguǒ","hanviet":"Bình quả","chars":["苹","果"],"story":"苹 = bộ 艹 (cỏ cây) chỉ nghĩa + 平 píng chỉ âm — chữ hình thanh điển hình. 果 vẽ quả tròn đậu trên cây 木. 苹果 = quả táo. Thấy bộ 艹 là đoán được chữ nói về cây cỏ, hoa quả."},{"char":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","chars":["便","宜"],"story":"便 có HAI âm: biàn (方便 tiện lợi) và pián — chỉ đọc pián trong đúng từ 便宜 này. 宜 = bộ 宀 (mái nhà) + 且, nghĩa là thích hợp, vừa phải. 便宜 = giá vừa phải, tức là RẺ (↔ 贵 đắt)."},{"char":"商店","pinyin":"shāngdiàn","hanviet":"Thương điếm","chars":["商","店"],"story":"商 vốn vẽ một đài cao có chữ, là tên nhà Thương — triều đại giỏi buôn bán, nên 商 mang nghĩa buôn bán. 店 = bộ 广 (mái hiên) + 占 chỉ âm — chỗ có mái để bày hàng. 店 đã học ở Bài 7 (书店)."},{"char":"衣服","pinyin":"yīfu","hanviet":"Y phục","chars":["衣","服"],"story":"衣 vẽ cổ áo và hai ống tay của chiếc áo cổ xưa; nó là bộ thủ của rất nhiều chữ nói về áo quần. 服 nghĩa gốc là khoác lên người, tuân theo. 衣服 = thứ khoác lên người = quần áo."},{"char":"件","pinyin":"jiàn","hanviet":"Kiện","chars":["件"],"story":"件 = bộ Nhân đứng 亻 (người) + 牛 (con trâu). Người xưa xẻ trâu ra thành từng phần, mỗi phần là \"một kiện\" → nghĩa \"từng cái, từng việc\". Ngày nay 件 là lượng từ cho quần áo (一件衣服) và sự việc (一件事). Đừng nhầm với 见 (gặp) cùng âm jiàn."},{"char":"元","pinyin":"yuán","hanviet":"Nguyên","chars":["元"],"story":"元 vẽ một người có cái đầu được nhấn mạnh bằng hai nét ngang trên cùng, nghĩa gốc là \"đầu, đầu tiên, gốc\" (元旦 mồng một Tết). Nay là đơn vị tiền CHÍNH THỨC ghi trên biển giá và hoá đơn; nói miệng thì dùng 块."},{"char":"怎么样","pinyin":"zěnmeyàng","hanviet":"Chẩm ma dạng","chars":["怎","么","样"],"story":"怎 = 乍 chỉ âm + 心 (quả tim) — trong lòng đang thắc mắc. 么 là đuôi từ nghi vấn. 样 = bộ 木 + 羊, nghĩa là dáng vẻ, kiểu dáng. 怎么样 = \"dáng vẻ ra sao\" = thế nào. Đã học 怎么 ở Bài 6."},{"char":"贵","pinyin":"guì","hanviet":"Quý","chars":["贵"],"story":"贵 (phồn thể 貴) có 贝 (vỏ sò — đồng tiền của người xưa) ở dưới. Cứ chữ nào mang 贝 là dính tới tiền của: 贵 (đắt), 货 (hàng hoá), 员. Cặp đối lập cần thuộc: 贵 ↔ 便宜."},{"char":"穿","pinyin":"chuān","hanviet":"Xuyên","chars":["穿"],"story":"穿 = bộ 穴 (cái hang, lỗ hổng) ở trên + 牙 (răng) ở dưới — răng khoét thủng một lỗ, nghĩa gốc là \"xuyên qua\" (âm Hán Việt đúng là Xuyên). Mặc áo cũng là luồn người qua áo, nên 穿 dùng cho quần áo, giày dép."},{"char":"女","pinyin":"nǚ","hanviet":"Nữ","chars":["女"],"story":"女 vẽ một người phụ nữ đang quỳ, hai tay khoanh trước ngực — dáng ngồi lễ phép thời xưa. Đây là bộ thủ cực quan trọng, có mặt trong 她、妈妈、好、姐姐 mà cô đã dạy."},{"char":"男","pinyin":"nán","hanviet":"Nam","chars":["男"],"story":"男 = 田 (thửa ruộng) ở trên + 力 (sức, vốn vẽ cái cày) ở dưới — người dùng sức cày ruộng. Xã hội xưa coi đó là việc của đàn ông nên 男 nghĩa là nam giới. Cặp đối: 男 ↔ 女."},{"char":"那儿","pinyin":"nàr","hanviet":"Na nhi","chars":["那","儿"],"story":"那 chỉ nơi hoặc vật ở XA, thêm đuôi 儿 hoá của khẩu ngữ miền Bắc thành 那儿, đọc dính lại là nàr. 那儿 = chỗ kia, đằng kia; miền Nam nói 那里. Học kèm cặp 这儿 ↔ 那儿."}],"grammar":[{"title":"Cách đọc số tiền 钱数的表达","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>七</b><small>số nguyên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>块</b><small>tệ (khẩu ngữ)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>二</b><small>số lẻ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(毛)</b><small>hào — thường lược</small></span></div>","summary":"<p class=\"gr-lead\">Cách đọc số tiền</p><ul><li>Tiền Trung Quốc có ba bậc: <span class=\"zh\">元 (块)</span> &gt; <span class=\"zh\">角 (毛)</span> &gt; <span class=\"zh\">分</span>. Một <span class=\"zh\">元</span> = 10 <span class=\"zh\">角</span> = 100 <span class=\"zh\">分</span>.</li><li><b>Khẩu ngữ</b> nói <span class=\"zh\">块 · 毛</span>, còn <b>văn viết</b> và biển giá ghi <span class=\"zh\">元 · 角</span> — nghĩa hoàn toàn như nhau.</li><li>Đơn vị cuối cùng thường được <b>lược bỏ</b>: <span class=\"zh\">三块五(毛钱)</span>, <span class=\"zh\">七块二(毛)</span>. Hỏi giá dùng <span class=\"zh\">多少钱</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">五块钱</span> = 5 tệ　·　<span class=\"zh\">三块五</span> = 3 tệ 5 hào　·　<span class=\"zh\">一百元</span> = 100 tệ</p>","note":"<b>Lưu ý:</b> Số 2 đứng đầu đọc là <span class=\"zh\">两</span>: nói <span class=\"zh\">两块钱</span>, không nói <span class=\"zh\">二块钱</span> ✗. Nhưng ở hàng lẻ thì vẫn là <span class=\"zh\">二</span>: <span class=\"zh\">七块二</span> ✓.","examples":[{"zh":"苹果三块五一斤。","py":"Píngguǒ sān kuài wǔ yì jīn.","vi":"Táo ba tệ rưỡi một cân."},{"zh":"0.02元 ＝ 两分","py":"liǎng fēn","vi":"hai xu"},{"zh":"0.2元 ＝ 两毛","py":"liǎng máo","vi":"hai hào"},{"zh":"3元 ＝ 三块","py":"sān kuài","vi":"ba đồng"},{"zh":"3.2元 ＝ 三块二","py":"sān kuài èr","vi":"ba đồng hai"},{"zh":"6.02元 ＝ 六块零两分","py":"liù kuài líng liǎng fēn","vi":"sáu đồng lẻ hai xu"},{"zh":"202.2元 ＝ 二百零二块两毛","py":"èrbǎi líng èr kuài liǎng máo","vi":"hai trăm lẻ hai đồng hai hào"}],"exercises":[]},{"title":"Câu vị ngữ tính từ 形容词谓语句","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>很 / 真 / 不</b><small>phó từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">Không cần chữ 是</p><ul><li>Tính từ trong tiếng Trung <b>tự làm vị ngữ</b>, đứng ngay sau chủ ngữ — <b>không cần</b> <span class=\"zh\">是</span>.</li><li>Trước tính từ hầu như luôn có một phó từ mức độ: <span class=\"zh\">很</span> (rất), <span class=\"zh\">真</span> (thật là), <span class=\"zh\">太……了</span>.</li><li>Phủ định đặt <span class=\"zh\">不</span> ngay trước tính từ: <span class=\"zh\">不贵</span>, <span class=\"zh\">不便宜</span>, <span class=\"zh\">不少</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这儿的苹果真便宜！</span> = Táo ở đây rẻ thật!　·　phủ định: <span class=\"zh\">也不贵</span></p>","note":"<b>Lưu ý:</b> Lỗi người Việt hay mắc: nói <span class=\"zh\">这个是很贵</span> ✗. Đã có tính từ làm vị ngữ thì <b>bỏ hẳn</b> <span class=\"zh\">是</span> — <span class=\"zh\">这个很贵</span> ✓.","examples":[{"zh":"这儿的苹果真便宜！","py":"Zhèr de píngguǒ zhēn piányi!","vi":"Táo ở đây rẻ thật!"},{"zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây nhiều thật!"},{"zh":"我的房间不大。","py":"Wǒ de fángjiān bú dà.","vi":"Phòng của tôi không to."},{"zh":"那个苹果好吃。","py":"Nàge píngguǒ hǎochī.","vi":"Quả táo kia ngon."}],"exercises":[]},{"title":"Đại từ nghi vấn 怎么样","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>名词 / 话题</b><small>cái muốn hỏi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>怎么样</b><small>thế nào?</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>？</b><small>không thêm 吗</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi thấy thế nào</p><ul><li><span class=\"zh\">怎么样</span> dùng để <b>hỏi ý kiến</b> hoặc hỏi tình trạng: \"… thấy thế nào? … ra sao?\"</li><li>Hay đứng <b>cuối câu</b> ngay sau một đề nghị: <span class=\"zh\">我们晚上去商店，怎么样？</span></li><li>Cũng làm vị ngữ trực tiếp: <span class=\"zh\">这件衣服怎么样？</span> — trả lời bằng đúng một câu vị ngữ tính từ: <span class=\"zh\">很好看。</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">这件一百元，怎么样？</span> = Cái này một trăm tệ, thấy thế nào?</p>","note":"<b>Lưu ý:</b> Câu đã có <span class=\"zh\">怎么样</span> thì <b>không thêm</b> <span class=\"zh\">吗</span> ✗. Phân biệt với <span class=\"zh\">怎么</span> (Bài 6): <span class=\"zh\">怎么</span> hỏi <b>cách thức</b>, <span class=\"zh\">怎么样</span> hỏi <b>ra sao</b>.","examples":[{"zh":"这件衣服怎么样？","py":"Zhè jiàn yīfu zěnmeyàng?","vi":"Bộ quần áo này thế nào?"},{"zh":"A：这个杯子怎么样？　B：我很喜欢，也不贵。","py":"A: Zhège bēizi zěnmeyàng?　B: Wǒ hěn xǐhuan, yě bú guì.","vi":"A: Cái cốc này thế nào? — B: Mình rất thích, lại không đắt."},{"zh":"A：这本书怎么样？　B：很好看。","py":"A: Zhè běn shū zěnmeyàng?　B: Hěn hǎokàn.","vi":"A: Quyển sách này thế nào? — B: Rất hay."},{"zh":"A：这个菜怎么样？　B：这个菜不太好吃，我不喜欢。","py":"A: Zhège cài zěnmeyàng?　B: Zhège cài bú tài hǎochī, wǒ bù xǐhuan.","vi":"A: Món này thế nào? — B: Món này không ngon lắm, mình không thích."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Trong cửa hàng — hỏi mua cái cốc","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"请问，有杯子吗？","py":"Qǐngwèn, yǒu bēizi ma?","vi":"Cho hỏi, ở đây có cốc không ạ?"},{"speaker":"售","name":"Nhân viên","zh":"有，杯子在这边。","py":"Yǒu, bēizi zài zhèbiān.","vi":"Có ạ, cốc ở bên này."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"多少钱一个？","py":"Duōshao qián yí gè?","vi":"Bao nhiêu tiền một cái ạ?"},{"speaker":"售","name":"Nhân viên","zh":"这些五块钱一个，那些十块钱一个。","py":"Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè.","vi":"Mấy cái này năm tệ một cái, mấy cái kia mười tệ một cái."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我买这个吧。","py":"Wǒ mǎi zhège ba.","vi":"Vậy tôi mua cái này nhé."}]},{"titleZh":"课文二","titleVi":"Ở quầy hoa quả — mua hai cân táo","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"这儿的水果真不少！","py":"Zhèr de shuǐguǒ zhēn bù shǎo!","vi":"Hoa quả ở đây nhiều thật đấy!"},{"speaker":"售","name":"Nhân viên","zh":"您想买什么？","py":"Nín xiǎng mǎi shénme?","vi":"Chị muốn mua gì ạ?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我想买两斤苹果。","py":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","vi":"Tôi muốn mua hai cân táo."},{"speaker":"售","name":"Nhân viên","zh":"苹果三块五一斤。这些七块二，七块钱吧。","py":"Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","vi":"Táo ba tệ rưỡi một cân. Chỗ này bảy tệ hai, lấy chị bảy tệ thôi."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"好的，这儿的苹果真便宜！","py":"Hǎo de, zhèr de píngguǒ zhēn piányi!","vi":"Được, táo ở đây rẻ thật!"}]},{"titleZh":"课文三","titleVi":"Hai vợ chồng chọn quần áo cho con","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"这家商店衣服真多！这件一百元，怎么样？","py":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","vi":"Cửa hàng này nhiều quần áo thật! Cái này một trăm tệ, anh thấy thế nào?"},{"speaker":"明","name":"Lưu Minh","zh":"好看，也不贵。","py":"Hǎokàn, yě bú guì.","vi":"Đẹp đấy, cũng không đắt."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"小雪能穿，买一件吧。","py":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","vi":"Tiểu Tuyết mặc vừa đấy, mua một cái đi."},{"speaker":"明","name":"Lưu Minh","zh":"好的。小明能穿吗？","py":"Hǎo de. Xiǎomíng néng chuān ma?","vi":"Được. Thế Tiểu Minh mặc vừa không?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","py":"Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","vi":"Không được. Đây là quần áo con gái mặc, quần áo con trai ở đằng kia."},{"speaker":"明","name":"Lưu Minh","zh":"好的。","py":"Hǎo de.","vi":"Được rồi."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Đóng vai người bán – khách mua","q":{"zh":"三人一组，一个人扮演售货员，两个人扮演顾客，仿照本课三篇课文的内容对话。","py":"Sān rén yì zǔ, yí gè rén bànyǎn shòuhuòyuán, liǎng gè rén bànyǎn gùkè, fǎngzhào běn kè sān piān kèwén de nèiróng duìhuà.","vi":"Nhóm 3 người, một người đóng người bán hàng, hai người đóng khách, hội thoại theo nội dung 3 bài khoá."},"items":[{"lines":[{"who":"顾客","zh":"请问，这个杯子多少钱？","py":"Qǐngwèn, zhège bēizi duōshao qián?","vi":"Cho hỏi, cái cốc này bao nhiêu tiền?"},{"who":"售货员","zh":"二十五块。","py":"Èrshíwǔ kuài.","vi":"Hai mươi lăm đồng."}]},{"lines":[{"who":"顾客","zh":"苹果多少钱一斤？","py":"Píngguǒ duōshao qián yì jīn?","vi":"Táo bao nhiêu tiền một cân?"},{"who":"售货员","zh":"六块。这些苹果很好吃。","py":"Liù kuài. Zhèxiē píngguǒ hěn hǎochī.","vi":"Sáu đồng. Táo này ngon lắm."}]},{"lines":[{"who":"顾客","zh":"这件衣服怎么样？","py":"Zhè jiàn yīfu zěnmeyàng?","vi":"Cái áo này thế nào?"},{"who":"顾客","zh":"很好看，也不贵。","py":"Hěn hǎokàn, yě bú guì.","vi":"Rất đẹp, lại không đắt."}]}]}],"speak":[]}},{"id":"k1v3-b11","courseId":"k1v3","order":11,"title":"Tôi đang học đại học","titleZh":"我读大学呢","titlePy":"wǒ dú dàxué ne","vocab":[{"stt":1,"hanzi":"时候","pinyin":"shíhou","hanviet":"Thời hậu","pos":"Danh từ","meaning":"lúc, khi, thời điểm","comps":"什么时候 (khi nào), 的时候 (lúc mà…)","example":{"zh":"你什么时候能到饭店？","py":"Nǐ shénme shíhou néng dào fàndiàn?","vi":"Khi nào cậu tới nhà hàng được?"}},{"stt":2,"hanzi":"饭店","pinyin":"fàndiàn","hanviet":"Phạn điếm","pos":"Danh từ","meaning":"nhà hàng; khách sạn","comps":"去饭店 (đi nhà hàng), 一家饭店 (một nhà hàng)","example":{"zh":"这家饭店的菜很好吃。","py":"Zhè jiā fàndiàn de cài hěn hǎochī.","vi":"Món ăn của nhà hàng này rất ngon."}},{"stt":3,"hanzi":"知道","pinyin":"zhīdào","hanviet":"Tri đạo","pos":"Động từ","meaning":"biết, biết rằng","comps":"不知道 (không biết), 知不知道 (có biết không)","example":{"zh":"还不知道，正在找呢。","py":"Hái bù zhīdào, zhèngzài zhǎo ne.","vi":"Vẫn chưa biết, đang tìm đây."}},{"stt":4,"hanzi":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","pos":"Phó từ","meaning":"đang (làm gì đó)","comps":"正在找 (đang tìm), 正在学习 (đang học)","example":{"zh":"我正在找饭店呢。","py":"Wǒ zhèngzài zhǎo fàndiàn ne.","vi":"Mình đang tìm nhà hàng đây."}},{"stt":5,"hanzi":"找","pinyin":"zhǎo","hanviet":"Trảo","pos":"Động từ","meaning":"tìm, tìm kiếm","comps":"找人 (tìm người), 正在找 (đang tìm)","example":{"zh":"他在找他的书。","py":"Tā zài zhǎo tā de shū.","vi":"Cậu ấy đang tìm quyển sách của mình."}},{"stt":6,"hanzi":"开车","pinyin":"kāichē","hanviet":"Khai xa","pos":"Động từ","meaning":"lái xe","comps":"开车去 (lái xe đi), 没开车 (không lái xe)","example":{"zh":"你开车没开车？","py":"Nǐ kāichē méi kāichē?","vi":"Cậu có lái xe không?"}},{"stt":7,"hanzi":"车","pinyin":"chē","hanviet":"Xa","pos":"Danh từ","meaning":"xe, xe cộ","comps":"坐车 (đi xe), 开车 (lái xe)","example":{"zh":"我没开车，坐车呢。","py":"Wǒ méi kāichē, zuò chē ne.","vi":"Mình không lái xe, mình đang đi xe đây."}},{"stt":8,"hanzi":"在","pinyin":"zài","hanviet":"Tại","pos":"Phó từ","meaning":"đang (làm gì đó)","comps":"在睡觉 (đang ngủ), 还在 (vẫn đang)","example":{"zh":"他还在睡觉呢。","py":"Tā hái zài shuìjiào ne.","vi":"Cậu ấy vẫn đang ngủ."}},{"stt":9,"hanzi":"读","pinyin":"dú","hanviet":"Độc","pos":"Động từ","meaning":"đọc; học (bậc nào)","comps":"读书 (đọc sách), 读大学 (học đại học)","example":{"zh":"我读大学呢。","py":"Wǒ dú dàxué ne.","vi":"Mình đang học đại học."}},{"stt":10,"hanzi":"大学","pinyin":"dàxué","hanviet":"Đại học","pos":"Danh từ","meaning":"trường đại học","comps":"读大学 (học đại học), 上大学 (vào đại học)","example":{"zh":"你还在读大学吗？","py":"Nǐ hái zài dú dàxué ma?","vi":"Cậu vẫn đang học đại học à?"}},{"stt":11,"hanzi":"大学生","pinyin":"dàxuéshēng","hanviet":"Đại học sinh","pos":"Danh từ","meaning":"sinh viên đại học","comps":"是大学生 (là sinh viên), 大学生们 (các sinh viên)","example":{"zh":"我还是大学生。","py":"Wǒ hái shì dàxuéshēng.","vi":"Mình vẫn là sinh viên."}},{"stt":12,"hanzi":"学","pinyin":"xué","hanviet":"Học","pos":"Động từ","meaning":"học, học ngành gì","comps":"学医 (học ngành y), 学中文 (học tiếng Trung)","example":{"zh":"我学医，我们的课很多。","py":"Wǒ xué yī, wǒmen de kè hěn duō.","vi":"Mình học ngành y, môn học của bọn mình rất nhiều."}},{"stt":13,"hanzi":"医","pinyin":"yī","hanviet":"Y","pos":"Danh từ","meaning":"y học, nghề y","comps":"学医 (học ngành y), 医生 (bác sĩ)","example":{"zh":"我弟弟也想学医。","py":"Wǒ dìdi yě xiǎng xué yī.","vi":"Em trai mình cũng muốn học ngành y."}},{"stt":14,"hanzi":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","pos":"Danh từ","meaning":"em trai","comps":"我弟弟 (em trai tôi), 弟弟们 (các em trai)","example":{"zh":"弟弟起床没起床呢？","py":"Dìdi qǐchuáng méi qǐchuáng ne?","vi":"Em trai dậy chưa thế?"}},{"stt":15,"hanzi":"起床","pinyin":"qǐchuáng","hanviet":"Khởi sàng","pos":"Động từ","meaning":"thức dậy, ngủ dậy","comps":"起床了 (dậy rồi), 没起床 (chưa dậy)","example":{"zh":"他六点起床。","py":"Tā liù diǎn qǐchuáng.","vi":"Cậu ấy sáu giờ ngủ dậy."}},{"stt":16,"hanzi":"睡觉","pinyin":"shuìjiào","hanviet":"Thuỵ giác","pos":"Động từ","meaning":"ngủ, đi ngủ","comps":"在睡觉 (đang ngủ), 去睡觉 (đi ngủ)","example":{"zh":"没起床呢，还在睡觉。","py":"Méi qǐchuáng ne, hái zài shuìjiào.","vi":"Chưa dậy đâu, vẫn đang ngủ."}},{"stt":17,"hanzi":"睡","pinyin":"shuì","hanviet":"Thuỵ","pos":"Động từ","meaning":"ngủ","comps":"还睡呢 (còn ngủ à), 睡觉 (đi ngủ)","example":{"zh":"还睡呢？","py":"Hái shuì ne?","vi":"Vẫn còn ngủ à?"}},{"stt":18,"hanzi":"那里","pinyin":"nàlǐ","hanviet":"Na lý","pos":"Đại từ","meaning":"ở kia (= 那儿)","comps":"去那里 (đến đó), 在那里 (ở đằng kia)","example":{"zh":"他今天去不去那里？","py":"Tā jīntiān qù bu qù nàli?","vi":"Hôm nay em ấy có đi đằng kia không?"}},{"stt":19,"hanzi":"哪里","pinyin":"nǎlǐ","hanviet":"Na lý","pos":"Đại từ nghi vấn","meaning":"ở đâu (= 哪儿)","comps":"去哪里 (đi đâu), 在哪里 (ở đâu)","example":{"zh":"你要去哪里？","py":"Nǐ yào qù nǎli?","vi":"Cậu định đi đâu?"}},{"stt":20,"hanzi":"昨天","pinyin":"zuótiān","hanviet":"Tạc thiên","pos":"Danh từ","meaning":"hôm qua (↔ 明天)","comps":"昨天晚上 (tối qua), 昨天上午 (sáng qua)","example":{"zh":"我昨天问他了。","py":"Wǒ zuótiān wèn tā le.","vi":"Hôm qua mình đã hỏi cậu ấy rồi."}},{"stt":21,"hanzi":"问","pinyin":"wèn","hanviet":"Vấn","pos":"Động từ","meaning":"hỏi","comps":"请问 (xin hỏi), 问他 (hỏi cậu ấy)","example":{"zh":"我昨天问他。","py":"Wǒ zuótiān wèn tā.","vi":"Hôm qua mình hỏi cậu ấy."}},{"stt":22,"hanzi":"对","pinyin":"duì","hanviet":"Đối","pos":"Giới từ","meaning":"với, đối với (ai)","comps":"对我说 (nói với tôi), 对，是的 (đúng vậy)","example":{"zh":"他对我说，他不去。","py":"Tā duì wǒ shuō, tā bú qù.","vi":"Cậu ấy nói với mình là cậu ấy không đi."}},{"stt":23,"hanzi":"说","pinyin":"shuō","hanviet":"Thuyết","pos":"Động từ","meaning":"nói, nói rằng","comps":"对我说 (nói với tôi), 说汉语 (nói tiếng Hán)","example":{"zh":"他说他今天不去。","py":"Tā shuō tā jīntiān bú qù.","vi":"Cậu ấy nói hôm nay cậu ấy không đi."}},{"stt":24,"hanzi":"要","pinyin":"yào","hanviet":"Yêu","pos":"Động từ năng nguyện","meaning":"muốn, định làm","comps":"要去 (định đi), 要不要 (có muốn không)","example":{"zh":"他今天要和小朋友玩。","py":"Tā jīntiān yào hé xiǎopéngyǒu wán.","vi":"Hôm nay em ấy muốn chơi với các bạn nhỏ."}},{"stt":25,"hanzi":"小朋友","pinyin":"xiǎopéngyǒu","hanviet":"Tiểu bằng hữu","pos":"Danh từ","meaning":"bạn nhỏ, trẻ con","comps":"和小朋友玩 (chơi với bạn nhỏ), 小朋友们 (các bạn nhỏ)","example":{"zh":"小朋友们在外边玩儿。","py":"Xiǎopéngyǒumen zài wàibian wánr.","vi":"Các bạn nhỏ đang chơi ở bên ngoài."}}],"hanzi":[{"char":"时候","pinyin":"shíhou","hanviet":"Thời hậu","chars":["时","候"],"story":"时 (時) = bộ 日 (mặt trời) + 寺 chỉ âm — người xưa nhìn bóng mặt trời mà biết giờ. 候 = bộ 亻 (người) ghép với phần chỉ âm, nghĩa gốc là chờ đợi, ngóng tới lúc. 时候 = thời điểm, lúc."},{"char":"饭店","pinyin":"fàndiàn","hanviet":"Phạn điếm","chars":["饭","店"],"story":"饭 = bộ 饣 (thức ăn) + 反 chỉ âm — cơm, bữa ăn (đã học ở Bài 8). 店 = bộ 广 (mái hiên) + 占 chỉ âm — cửa tiệm (Bài 7, Bài 10). 饭店 = tiệm ăn; ở Trung Quốc còn dùng để gọi khách sạn."},{"char":"知道","pinyin":"zhīdào","hanviet":"Tri đạo","chars":["知","道"],"story":"知 = 矢 (mũi tên) + 口 (miệng) — lời nói ra nhanh và trúng đích như mũi tên, tức là đã biết rõ. 道 = bộ 辶 (bước đi) + 首 (cái đầu) — con đường. 知道 = biết đường, nắm rõ."},{"char":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","chars":["正","在"],"story":"正 vẽ bàn chân 止 dừng đúng trên vạch 一 — nghĩa gốc là ngay ngắn, đúng lúc, đúng chỗ. 在 nghĩa là ở, đang. Ghép 正在 = \"đúng lúc đang\", nhấn mạnh việc diễn ra ngay giây phút này."},{"char":"找","pinyin":"zhǎo","hanviet":"Trảo","chars":["找"],"story":"找 = bộ 扌 (bàn tay) + 戈 (cây giáo) — dùng tay lần mò, dò tìm. Nhớ bộ 扌 là đoán được cả loạt động từ dùng tay: 找 (tìm), 打 (đánh), 拿 (cầm)."},{"char":"开车","pinyin":"kāichē","hanviet":"Khai xa","chars":["开","车"],"story":"开 (開) vốn vẽ hai bàn tay đang tháo then cửa — nghĩa là mở ra. 车 (車) vẽ chiếc xe nhìn từ trên xuống. 开车 = \"mở máy chiếc xe\" = lái xe. Cùng khuôn với 开门 (mở cửa)."},{"char":"车","pinyin":"chē","hanviet":"Xa","chars":["车"],"story":"车 (車) là chữ tượng hình rất đẹp: nhìn từ trên xuống thấy thùng xe ở giữa, hai nét ngang là hai bánh xe, nét dọc là trục. Đây là bộ thủ của mọi chữ về xe cộ."},{"char":"在","pinyin":"zài","hanviet":"Tại","chars":["在"],"story":"在 đã học HAI lần rồi: Bài 7 là ĐỘNG TỪ \"ở\" (我在家), Bài 8 là GIỚI TỪ \"tại\" (在学校学习). Bài này là cách dùng thứ BA — PHÓ TỪ đặt trước động từ, nghĩa là \"đang\". Một chữ, ba từ loại."},{"char":"读","pinyin":"dú","hanviet":"Độc","chars":["读"],"story":"读 (讀) = bộ 讠 (lời nói) chỉ nghĩa + 卖 chỉ âm — đọc là phát thành tiếng (đã gặp trong 读书 ở Bài 9). Ngoài \"đọc\", 读 còn nghĩa là theo học một bậc: 读大学, 读中学."},{"char":"大学","pinyin":"dàxué","hanviet":"Đại học","chars":["大","学"],"story":"大 vẽ một người dang rộng hai tay hai chân — to lớn. 学 (學) vẽ hai bàn tay dạy đứa trẻ 子 dưới mái nhà (đã gặp trong 学习 ở Bài 9). 大学 = bậc học lớn nhất = trường đại học."},{"char":"大学生","pinyin":"dàxuéshēng","hanviet":"Đại học sinh","chars":["大","学","生"],"story":"Ghép 大学 (đại học) với 生. 生 vẽ mầm cây nhú lên khỏi mặt đất, nghĩa gốc là sinh ra, sống; trong 学生 (Bài 1) thì 生 chỉ người đang theo học. 大学生 = người học đại học = sinh viên."},{"char":"学","pinyin":"xué","hanviet":"Học","chars":["学"],"story":"学 (學) phía trên là hai bàn tay đỡ lấy 爻 (những vạch tượng trưng cho tri thức), dưới là mái nhà 冖 che đứa trẻ 子 — đúng cảnh lớp học. Đứng một mình, 学 là động từ \"học\": 学医, 学中文."},{"char":"医","pinyin":"yī","hanviet":"Y","chars":["医"],"story":"医 (醫) vẽ một cái hộp 匚 đựng mũi tên 矢 — hộp đồ nghề chữa thương của thầy thuốc thời xưa. Chữ này học sinh đã gặp trong 医生 (bác sĩ) và 医院 (bệnh viện) ở Bài 7 và Bài 8."},{"char":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","chars":["弟","弟"],"story":"弟 vốn vẽ sợi dây quấn quanh cây cọc theo thứ tự từ dưới lên, chỉ thứ bậc — người sinh sau. Lặp lại thành 弟弟 (chữ sau đọc thanh nhẹ) là cách gọi thân mật, cùng kiểu với 哥哥、妈妈、妹妹."},{"char":"起床","pinyin":"qǐchuáng","hanviet":"Khởi sàng","chars":["起","床"],"story":"起 = bộ 走 (bước đi) + 己 chỉ âm — đứng dậy, bắt đầu. 床 = bộ 广 (mái nhà) + 木 (gỗ) — cái giường gỗ kê trong nhà. 起床 = rời khỏi giường = thức dậy."},{"char":"睡觉","pinyin":"shuìjiào","hanviet":"Thuỵ giác","chars":["睡","觉"],"story":"睡 = bộ 目 (con mắt) + 垂 (rủ xuống) — mí mắt sụp xuống. 觉 (覺) có 见 (nhìn thấy) ở dưới, nghĩa gốc là cảm giác, tỉnh giấc; khi đọc jiào thì nghĩa là GIẤC ngủ. 睡觉 = ngủ một giấc."},{"char":"睡","pinyin":"shuì","hanviet":"Thuỵ","chars":["睡"],"story":"睡 = bộ 目 (con mắt) + 垂 (buông rủ xuống). Hình ảnh rất rõ ràng: mí mắt rủ xuống là ngủ. Nói tắt 睡 khi ngữ cảnh đã rõ (还睡呢？), nói đầy đủ thì dùng 睡觉."},{"char":"那里","pinyin":"nàlǐ","hanviet":"Na lý","chars":["那","里"],"story":"那 chỉ nơi hoặc vật ở XA (Bài 9). 里 nghĩa là bên trong, chỗ (đã gặp trong 家里 ở Bài 7). 那里 = chỗ kia — nghĩa hệt 那儿 vừa học ở Bài 10, chỉ khác 那里 thiên về văn viết và cách nói miền Nam."},{"char":"哪里","pinyin":"nǎlǐ","hanviet":"Na lý","chars":["哪","里"],"story":"哪 = bộ 口 (miệng, dùng để hỏi) thêm vào chữ 那. Chỉ khác đúng một bộ 口 mà thành từ để HỎI. 哪里 = ở đâu, chỗ nào, hệt 哪儿. Nhớ kỹ thanh điệu: 那 nà (thanh 4) ↔ 哪 nǎ (thanh 3)."},{"char":"昨天","pinyin":"zuótiān","hanviet":"Tạc thiên","chars":["昨","天"],"story":"昨 = bộ 日 (mặt trời, ngày) + 乍 chỉ âm — cái ngày vừa qua. 天 vẽ người dang tay với nét ngang trên đầu chỉ bầu trời, ở đây nghĩa là \"ngày\". Học trọn bộ ba: 昨天 ↔ 今天 ↔ 明天."},{"char":"问","pinyin":"wèn","hanviet":"Vấn","chars":["问"],"story":"问 (問) = 门 (cánh cửa) bao ở ngoài + 口 (cái miệng) nằm bên trong — đứng ở cửa mà cất tiếng hỏi vào. Học sinh đã gặp chữ này trong 请问 (xin hỏi) ở Bài 10."},{"char":"对","pinyin":"duì","hanviet":"Đối","chars":["对"],"story":"对 (對) nghĩa gốc là đối đáp, trả lời cho khớp. Có hai cách dùng phải phân biệt: đáp \"đúng vậy\" (对！) và làm GIỚI TỪ chỉ đối tượng — 对我说 = nói VỚI tôi. Cùng họ giới từ với 在 (Bài 8)."},{"char":"说","pinyin":"shuō","hanviet":"Thuyết","chars":["说"],"story":"说 (說) = bộ 讠 (lời nói) chỉ nghĩa + 兑 chỉ âm. Cứ chữ nào mang bộ 讠 là dính tới lời nói: 说 (nói), 读 (đọc), 请 (mời), 谢 (cảm ơn), 话 (lời) — phần lớn đã học rồi."},{"char":"要","pinyin":"yào","hanviet":"Yêu","chars":["要"],"story":"要 phía trên là 覀 (biến thể của 襾, cái đai quấn eo), dưới là 女 — vẽ người phụ nữ chống hai tay vào hông. Nghĩa gốc là \"eo\", sau mượn thành \"cần, muốn, đòi\". Ý chí mạnh hơn 想 (Bài 6)."},{"char":"小朋友","pinyin":"xiǎopéngyǒu","hanviet":"Tiểu bằng hữu","chars":["小","朋","友"],"story":"小 (nhỏ) ghép với 朋友 (bạn bè — đã học ở Bài 9). 小朋友 vừa nghĩa là \"bạn nhỏ\" mà trẻ con gọi nhau, vừa là cách người lớn gọi trẻ em nói chung: \"này cháu bé, này con\"."}],"grammar":[{"title":"Câu hỏi chính phản 正反问","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不 / 没</b><small>phủ định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>lặp lại</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi: có … không?</p><ul><li>Câu hỏi chính phản = <b>lặp lại</b> động từ hoặc tính từ, ở giữa đặt <span class=\"zh\">不</span>: <span class=\"zh\">是不是</span>, <span class=\"zh\">忙不忙</span>, <span class=\"zh\">去不去</span>.</li><li>Hỏi việc <b>đã xảy ra hay chưa</b> thì thay <span class=\"zh\">不</span> bằng <span class=\"zh\">没</span>: <span class=\"zh\">开车没开车？</span>, <span class=\"zh\">起床没起床？</span></li><li>Từ hai âm tiết chỉ cần lặp <b>âm đầu</b> cũng được: <span class=\"zh\">知不知道</span>, <span class=\"zh\">喜不喜欢</span> — hoặc lặp cả từ như trong bài.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">忙不忙？</span> = Có bận không?　·　<span class=\"zh\">开车没开车？</span> = Có lái xe không?</p>","note":"<b>Lưu ý:</b> Đây đã là câu hỏi rồi nên <b>không thêm</b> <span class=\"zh\">吗</span> ✗. Chữ <span class=\"zh\">不</span> ở giữa đọc <b>thanh nhẹ</b>: <span class=\"zh\">忙不忙</span> = máng bu máng.","examples":[{"zh":"你们学习忙不忙？","py":"Nǐmen xuéxí máng bu máng?","vi":"Các cậu học có bận không?"},{"zh":"它是不是在超市后边？","py":"Tā shì bu shì zài chāoshì hòubian?","vi":"Nó có phải ở phía sau siêu thị không?"},{"zh":"你去没去学校？","py":"Nǐ qù méi qù xuéxiào?","vi":"Bạn đã đến trường chưa?"},{"zh":"这件衣服好看不好看？","py":"Zhè jiàn yīfu hǎokàn bu hǎokàn?","vi":"Cái áo này có đẹp không?"},{"zh":"A：他去哪儿了？你知道不知道？　B：我不知道。","py":"A: Tā qù nǎr le? Nǐ zhīdào bu zhīdào?　B: Wǒ bù zhīdào.","vi":"A: Anh ấy đi đâu rồi? Bạn có biết không? — B: Mình không biết."},{"zh":"A：昨天你去没去书店？　B：我没去。","py":"A: Zuótiān nǐ qù méi qù shūdiàn?　B: Wǒ méi qù.","vi":"A: Hôm qua bạn có đi hiệu sách không? — B: Mình không đi."},{"zh":"A：这件衣服贵不贵？　B：不贵。","py":"A: Zhè jiàn yīfu guì bu guì?　B: Bú guì.","vi":"A: Cái áo này có đắt không? — B: Không đắt."}],"exercises":[]},{"title":"在、正在 — nói việc đang diễn ra","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(正) 在</b><small>đang</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>làm gì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(呢)</b><small>thường có</small></span></div>","summary":"<p class=\"gr-lead\">Đang làm dở</p><ul><li>Đặt <span class=\"zh\">在</span> hoặc <span class=\"zh\">正在</span> <b>ngay trước động từ</b> để nói việc <b>đang diễn ra</b>.</li><li><span class=\"zh\">正在</span> nhấn mạnh <b>đúng lúc này</b> hơn <span class=\"zh\">在</span>; cuối câu thường thêm <span class=\"zh\">呢</span> — chính là chữ <span class=\"zh\">呢</span> đã học ở Bài 7.</li><li>Có thể dùng riêng <span class=\"zh\">呢</span> và bỏ hẳn <span class=\"zh\">在</span>: <span class=\"zh\">我读大学呢。</span> — đúng tên bài học hôm nay.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">正在找呢。</span> = Đang tìm đây.　·　<span class=\"zh\">还在睡觉。</span> = Vẫn đang ngủ.</p>","note":"<b>Lưu ý:</b> Phủ định dùng <span class=\"zh\">没(有)</span> và <b>bỏ</b> <span class=\"zh\">在</span>: <span class=\"zh\">没起床呢</span> ✓, không nói <span class=\"zh\">不在起床</span> ✗. Đừng nhầm với <span class=\"zh\">在</span> giới từ ở Bài 8.","examples":[{"zh":"他还在睡觉呢。","py":"Tā hái zài shuìjiào ne.","vi":"Cậu ấy vẫn đang ngủ."},{"zh":"你还在读大学吗？","py":"Nǐ hái zài dú dàxué ma?","vi":"Bạn vẫn đang học đại học à?"},{"zh":"学生们在/正在上课呢。","py":"Xuéshēngmen zài/zhèngzài shàngkè ne.","vi":"Các học sinh đang học."},{"zh":"我们读书呢。","py":"Wǒmen dúshū ne.","vi":"Chúng tôi đang đọc sách."},{"zh":"A：你在做什么呢？　B：我正在看电视。","py":"A: Nǐ zài zuò shénme ne?　B: Wǒ zhèngzài kàn diànshì.","vi":"A: Bạn đang làm gì thế? — B: Mình đang xem tivi."},{"zh":"A：我去看电影，你去不去？　B：我在学习呢，不想去。","py":"A: Wǒ qù kàn diànyǐng, nǐ qù bu qù?　B: Wǒ zài xuéxí ne, bù xiǎng qù.","vi":"A: Mình đi xem phim, bạn có đi không? — B: Mình đang học, không muốn đi."},{"zh":"A：你在买菜吗？　B：我没买菜，买水果呢。","py":"A: Nǐ zài mǎi cài ma?　B: Wǒ méi mǎi cài, mǎi shuǐguǒ ne.","vi":"A: Bạn đang mua rau à? — B: Mình không mua rau, đang mua hoa quả."}],"exercises":[]},{"title":"Động từ năng nguyện 要","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>要</b><small>muốn, định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>làm gì</small></span></div>","summary":"<p class=\"gr-lead\">Muốn, định làm gì</p><ul><li><span class=\"zh\">要</span> đặt <b>trước động từ</b>, nghĩa là <b>muốn, định, sẽ</b> làm việc gì.</li><li>Thang ý muốn: <span class=\"zh\">想</span> (muốn, mong — Bài 6) &lt; <span class=\"zh\">要</span> (định, nhất định làm). <span class=\"zh\">要</span> hay đi kèm mốc thời gian: <span class=\"zh\">今天要…</span></li><li>Hỏi bằng chính câu chính phản vừa học: <span class=\"zh\">你要不要去？</span> — trả lời <span class=\"zh\">要</span> hoặc <span class=\"zh\">不想</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">他今天要和小朋友玩。</span> = Hôm nay em ấy muốn chơi với các bạn nhỏ.</p>","note":"<b>Lưu ý:</b> Phủ định của <span class=\"zh\">要</span> là <span class=\"zh\">不想</span>, <b>không phải</b> <span class=\"zh\">不要</span> ✗ — <span class=\"zh\">不要</span> nghĩa là \"đừng\", dùng để can ngăn.","examples":[{"zh":"他今天要和小朋友玩。","py":"Tā jīntiān yào hé xiǎopéngyǒu wán.","vi":"Hôm nay em ấy muốn chơi với các bạn nhỏ."},{"zh":"妈妈要去超市。","py":"Māma yào qù chāoshì.","vi":"Mẹ định đi siêu thị."},{"zh":"白家月要在家里学中文。","py":"Bái Jiāyuè yào zài jiā li xué Zhōngwén.","vi":"Bạch Gia Nguyệt định ở nhà học tiếng Trung."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Gọi điện hỏi đường tới nhà hàng","lines":[{"speaker":"王","name":"Vương Nhất Phi","zh":"喂，李文，你什么时候能到饭店？","py":"Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","vi":"A lô, Lý Văn à, khi nào cậu tới nhà hàng được?"},{"speaker":"文","name":"Lý Văn","zh":"还不知道，正在找呢。它是不是在超市后边？","py":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","vi":"Vẫn chưa biết, mình đang tìm đây. Nó có phải ở phía sau siêu thị không?"},{"speaker":"王","name":"Vương Nhất Phi","zh":"是的。你开车没开车？","py":"Shì de. Nǐ kāichē méi kāichē?","vi":"Đúng rồi. Cậu có lái xe không?"},{"speaker":"文","name":"Lý Văn","zh":"我没开车，坐车呢。","py":"Wǒ méi kāichē, zuò chē ne.","vi":"Mình không lái xe, mình đang đi xe đây."}]},{"titleZh":"课文二","titleVi":"Hỏi thăm chuyện học hành của bạn","lines":[{"speaker":"王","name":"Vương Nhất Phi","zh":"你还在读大学吗？","py":"Nǐ hái zài dú dàxué ma?","vi":"Cậu vẫn đang học đại học à?"},{"speaker":"文","name":"Lý Văn","zh":"对，我读大学呢，还是大学生。","py":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","vi":"Đúng, mình đang học đại học, vẫn là sinh viên."},{"speaker":"王","name":"Vương Nhất Phi","zh":"你们学习忙不忙？","py":"Nǐmen xuéxí máng bu máng?","vi":"Các cậu học có bận không?"},{"speaker":"文","name":"Lý Văn","zh":"非常忙，我学医，我们的课很多。","py":"Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","vi":"Bận lắm, mình học ngành y, môn học của bọn mình rất nhiều."}]},{"titleZh":"课文三","titleVi":"Bố hỏi chị xem em trai dậy chưa","lines":[{"speaker":"明","name":"Lưu Minh","zh":"弟弟起床没起床呢？","py":"Dìdi qǐchuáng méi qǐchuáng ne?","vi":"Em con dậy chưa thế?"},{"speaker":"雪","name":"Lưu Tiểu Tuyết","zh":"没起床呢，还在睡觉。","py":"Méi qǐchuáng ne, hái zài shuìjiào.","vi":"Chưa dậy ạ, vẫn đang ngủ."},{"speaker":"明","name":"Lưu Minh","zh":"还睡呢？他今天去不去那里？","py":"Hái shuì ne? Tā jīntiān qù bu qù nàli?","vi":"Vẫn còn ngủ à? Hôm nay em ấy có đi đằng kia không?"},{"speaker":"雪","name":"Lưu Tiểu Tuyết","zh":"去哪里？","py":"Qù nǎli?","vi":"Đi đâu ạ?"},{"speaker":"明","name":"Lưu Minh","zh":"去超市。","py":"Qù chāoshì.","vi":"Đi siêu thị."},{"speaker":"雪","name":"Lưu Tiểu Tuyết","zh":"我昨天问他，他对我说，他不去，他今天要和小朋友玩。","py":"Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","vi":"Hôm qua con hỏi rồi, em ấy nói với con là em ấy không đi, hôm nay em ấy muốn chơi với các bạn nhỏ."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hỏi nhau: có làm … không?","q":{"zh":"两人一组，互相问答做不做某事。","py":"Liǎng rén yì zǔ, hùxiāng wèndá zuò bu zuò mǒu shì.","vi":"Hai người một nhóm, hỏi đáp nhau xem có làm việc gì đó không."},"items":[{"lines":[{"who":"A","zh":"你去不去吃午饭？","py":"Nǐ qù bu qù chī wǔfàn?","vi":"Bạn có đi ăn trưa không?"},{"who":"B","zh":"我不去。","py":"Wǒ bú qù.","vi":"Mình không đi."}]},{"lines":[{"who":"A","zh":"你在做什么？","py":"Nǐ zài zuò shénme?","vi":"Bạn đang làm gì thế?"},{"who":"B","zh":"我在学中文呢。你学不学？","py":"Wǒ zài xué Zhōngwén ne. Nǐ xué bu xué?","vi":"Mình đang học tiếng Trung. Bạn có học không?"}]}]}],"speak":[]}},{"id":"k1v3-b12","courseId":"k1v3","order":12,"title":"Hôm qua tuyết rơi rồi","titleZh":"昨天下雪了","titlePy":"zuótiān xià xuě le","vocab":[{"stt":1,"hanzi":"天气","pinyin":"tiānqì","hanviet":"Thiên khí","pos":"Danh từ","meaning":"thời tiết","comps":"天气好 (thời tiết đẹp), 看天气 (xem thời tiết)","example":{"zh":"今天天气怎么样？","py":"Jīntiān tiānqì zěnmeyàng?","vi":"Hôm nay thời tiết thế nào?"}},{"stt":2,"hanzi":"这里","pinyin":"zhèlǐ","hanviet":"Giá lý","pos":"Đại từ","meaning":"ở đây (= 这儿)","comps":"这里的 (của nơi này), 在这里 (ở chỗ này)","example":{"zh":"这里的天气很好。","py":"Zhèlǐ de tiānqì hěn hǎo.","vi":"Thời tiết ở đây rất đẹp."}},{"stt":3,"hanzi":"天","pinyin":"tiān","hanviet":"Thiên","pos":"Danh từ","meaning":"trời, thời tiết","comps":"天气 (thời tiết), 天天 (ngày nào cũng)","example":{"zh":"今天天气很冷。","py":"Jīntiān tiānqì hěn lěng.","vi":"Thời tiết hôm nay rất lạnh."}},{"stt":4,"hanzi":"下雨","pinyin":"xià yǔ","hanviet":"Hạ vũ","pos":"Động từ","meaning":"mưa, trời đổ mưa","comps":"下雨了 (mưa rồi), 下大雨 (mưa to)","example":{"zh":"外边下雨了。","py":"Wàibian xià yǔ le.","vi":"Bên ngoài mưa rồi."}},{"stt":5,"hanzi":"了","pinyin":"le","hanviet":"Liễu","pos":"Trợ từ","meaning":"… rồi, đã … rồi","comps":"下雪了 (tuyết rơi rồi), 太好了 (tuyệt quá)","example":{"zh":"我生病了。","py":"Wǒ shēngbìng le.","vi":"Mình bị ốm rồi."}},{"stt":6,"hanzi":"雨","pinyin":"yǔ","hanviet":"Vũ","pos":"Danh từ","meaning":"mưa, cơn mưa","comps":"大雨 (mưa to), 小雨 (mưa nhỏ)","example":{"zh":"雨大吗？","py":"Yǔ dà ma?","vi":"Mưa có to không?"}},{"stt":7,"hanzi":"有点儿","pinyin":"yǒudiǎnr","hanviet":"Hữu điểm nhi","pos":"Phó từ","meaning":"hơi, có chút (chê)","comps":"有点儿冷 (hơi lạnh), 有点儿大 (hơi to)","example":{"zh":"今天有点儿冷。","py":"Jīntiān yǒudiǎnr lěng.","vi":"Hôm nay hơi lạnh."}},{"stt":8,"hanzi":"觉得","pinyin":"juéde","hanviet":"Giác đắc","pos":"Động từ","meaning":"cảm thấy, thấy rằng","comps":"我觉得 (mình thấy), 觉得好 (thấy tốt)","example":{"zh":"我觉得很冷。","py":"Wǒ juéde hěn lěng.","vi":"Mình thấy lạnh lắm."}},{"stt":9,"hanzi":"冷","pinyin":"lěng","hanviet":"Lãnh","pos":"Tính từ","meaning":"lạnh (↔ 热 nóng)","comps":"很冷 (rất lạnh), 太冷了 (lạnh quá)","example":{"zh":"昨天太冷了。","py":"Zuótiān tài lěng le.","vi":"Hôm qua lạnh quá."}},{"stt":10,"hanzi":"下","pinyin":"xià","hanviet":"Hạ","pos":"Động từ","meaning":"rơi xuống; dưới (↔ 上)","comps":"下雪 (tuyết rơi), 下班 (tan làm)","example":{"zh":"下雪了。","py":"Xià xuě le.","vi":"Tuyết rơi rồi."}},{"stt":11,"hanzi":"雪","pinyin":"xuě","hanviet":"Tuyết","pos":"Danh từ","meaning":"tuyết","comps":"下雪 (tuyết rơi), 大雪 (tuyết dày)","example":{"zh":"昨天下雪了。","py":"Zuótiān xià xuě le.","vi":"Hôm qua tuyết rơi rồi."}},{"stt":12,"hanzi":"来","pinyin":"lái","hanviet":"Lai","pos":"Động từ","meaning":"đến, tới (↔ 去 đi)","comps":"来公司 (đến công ty), 回来 (trở về)","example":{"zh":"他昨天没来。","py":"Tā zuótiān méi lái.","vi":"Hôm qua anh ấy không đến."}},{"stt":13,"hanzi":"公司","pinyin":"gōngsī","hanviet":"Công ty","pos":"Danh từ","meaning":"công ty","comps":"在公司 (ở công ty), 来公司 (đến công ty)","example":{"zh":"我在公司工作。","py":"Wǒ zài gōngsī gōngzuò.","vi":"Mình làm việc ở công ty."}},{"stt":14,"hanzi":"生病","pinyin":"shēngbìng","hanviet":"Sinh bệnh","pos":"Động từ","meaning":"bị ốm, ngã bệnh","comps":"生病了 (ốm rồi), 没生病 (không ốm)","example":{"zh":"你生病了吗？","py":"Nǐ shēngbìng le ma?","vi":"Bạn bị ốm à?"}},{"stt":15,"hanzi":"看病","pinyin":"kànbìng","hanviet":"Khán bệnh","pos":"Động từ","meaning":"khám bệnh, đi khám","comps":"去看病 (đi khám), 看病人 (khám bệnh nhân)","example":{"zh":"我去医院看病。","py":"Wǒ qù yīyuàn kànbìng.","vi":"Mình đi bệnh viện khám bệnh."}},{"stt":16,"hanzi":"病","pinyin":"bìng","hanviet":"Bệnh","pos":"Động từ","meaning":"ốm, bị bệnh","comps":"病人 (người bệnh), 我病了 (mình ốm rồi)","example":{"zh":"医生，我病了。","py":"Yīshēng, wǒ bìng le.","vi":"Bác sĩ ơi, em bị ốm rồi."}},{"stt":17,"hanzi":"一点儿","pinyin":"yìdiǎnr","hanviet":"Nhất điểm nhi","pos":"Số lượng từ","meaning":"một chút, một ít","comps":"吃一点儿 (ăn một chút), 一点儿水 (một ít nước)","example":{"zh":"吃一点儿药吧。","py":"Chī yìdiǎnr yào ba.","vi":"Uống một chút thuốc đi."}},{"stt":18,"hanzi":"药","pinyin":"yào","hanviet":"Dược","pos":"Danh từ","meaning":"thuốc","comps":"吃药 (uống thuốc), 买药 (mua thuốc)","example":{"zh":"我不想吃药。","py":"Wǒ bù xiǎng chī yào.","vi":"Mình không muốn uống thuốc."}},{"stt":19,"hanzi":"天","pinyin":"tiān","hanviet":"Thiên","pos":"Lượng từ","meaning":"ngày (đếm ngày)","comps":"半天 (nửa ngày), 三天 (ba ngày)","example":{"zh":"今天休息半天。","py":"Jīntiān xiūxi bàn tiān.","vi":"Hôm nay nghỉ nửa ngày."}},{"stt":20,"hanzi":"回","pinyin":"huí","hanviet":"Hồi","pos":"Động từ","meaning":"về, trở về","comps":"回家 (về nhà), 回来 (trở lại)","example":{"zh":"我想回家。","py":"Wǒ xiǎng huí jiā.","vi":"Mình muốn về nhà."}},{"stt":21,"hanzi":"再","pinyin":"zài","hanviet":"Tái","pos":"Phó từ","meaning":"rồi hẵng, sau đó mới","comps":"再见 (tạm biệt), 再喝 (uống thêm)","example":{"zh":"回家后再喝水。","py":"Huí jiā hòu zài hē shuǐ.","vi":"Về nhà rồi hãy uống nước."}},{"stt":22,"hanzi":"喝","pinyin":"hē","hanviet":"Hát","pos":"Động từ","meaning":"uống","comps":"喝水 (uống nước), 喝茶 (uống trà)","example":{"zh":"你想喝什么？","py":"Nǐ xiǎng hē shénme?","vi":"Bạn muốn uống gì?"}},{"stt":23,"hanzi":"热","pinyin":"rè","hanviet":"Nhiệt","pos":"Tính từ","meaning":"nóng (↔ 冷 lạnh)","comps":"热水 (nước nóng), 很热 (rất nóng)","example":{"zh":"今天太热了。","py":"Jīntiān tài rè le.","vi":"Hôm nay nóng quá."}},{"stt":24,"hanzi":"水","pinyin":"shuǐ","hanviet":"Thuỷ","pos":"Danh từ","meaning":"nước","comps":"热水 (nước nóng), 喝水 (uống nước)","example":{"zh":"喝些热水吧。","py":"Hē xiē rè shuǐ ba.","vi":"Uống chút nước nóng đi."}}],"hanzi":[{"char":"天气","pinyin":"tiānqì","hanviet":"Thiên khí","chars":["天","气"],"story":"天 vẽ một người 大 dang tay, thêm nét ngang to nhất ngay trên đầu — chính là bầu trời. 气 vẽ ba làn hơi bốc lên thành mây. 天气 = \"hơi của trời\" = thời tiết."},{"char":"这里","pinyin":"zhèlǐ","hanviet":"Giá lý","chars":["这","里"],"story":"这 = 辶 (bộ Sước, bước chân) + 文, chỉ cái ở gần ngay trước mắt. 里 vốn vẽ 田 (ruộng) đặt trên 土 (đất) — chỗ dân ở, nên có nghĩa \"bên trong, nơi chốn\". 这里 = nơi này."},{"char":"天","pinyin":"tiān","hanviet":"Thiên","chars":["天"],"story":"天 vẽ một người 大 dang hai tay, thêm nét ngang lớn nhất ở trên đầu — thứ cao nhất, đó là bầu trời. Từ nghĩa \"trời\" mới sinh ra nghĩa \"ngày\": một vòng sáng tối của trời là một 天 (今天, 半天)."},{"char":"下雨","pinyin":"xià yǔ","hanviet":"Hạ vũ","chars":["下","雨"],"story":"下 vẽ một vật nằm dưới đường ngang chỉ mặt chuẩn. 雨 vẽ bầu trời, đám mây và bốn hạt nước đang rơi. 下雨 = nước từ trời rơi xuống = trời mưa."},{"char":"了","pinyin":"le","hanviet":"Liễu","chars":["了"],"story":"了 vốn vẽ đứa trẻ mới sinh được quấn tã, hai tay bó gọn lại — mọi việc đã xong xuôi. Nay 了 làm trợ từ báo việc đã hoàn thành, đọc thanh nhẹ le chứ không đọc liǎo."},{"char":"雨","pinyin":"yǔ","hanviet":"Vũ","chars":["雨"],"story":"雨 là chữ tượng hình: nét ngang trên cùng là bầu trời, khung dưới là đám mây, bốn chấm bên trong là hạt mưa đang rơi. 雨 cũng là bộ thủ của 雪 (tuyết), 雷 (sấm)."},{"char":"有点儿","pinyin":"yǒudiǎnr","hanviet":"Hữu điểm nhi","chars":["有","点","儿"],"story":"有 vẽ bàn tay 又 cầm miếng thịt 月 — \"có trong tay\". 点 = 占 (chỉ âm) + 灬 (lửa) — cái chấm nhỏ. 有点儿 = \"có một chấm nhỏ\" = hơi hơi, thường dùng khi chê."},{"char":"觉得","pinyin":"juéde","hanviet":"Giác đắc","chars":["觉","得"],"story":"觉 có 见 (nhìn thấy) ở dưới — cảm nhận bằng giác quan. 得 = 彳 (bước đi) + 寸 (bàn tay) — đạt được. 觉得 = cảm nhận rồi rút ra = cảm thấy. Ở đây 觉 đọc jué, khác 睡觉 đọc jiào."},{"char":"冷","pinyin":"lěng","hanviet":"Lãnh","chars":["冷"],"story":"冷 = 冫 (bộ Băng, hai giọt nước đóng đá) + 令 lìng chỉ âm. Bộ Băng cho biết chữ này nói về cái lạnh — cũng chính là bộ có trong 冰 (băng)."},{"char":"下","pinyin":"xià","hanviet":"Hạ","chars":["下"],"story":"下 vẽ một vạch dài chỉ mặt chuẩn, thêm nét ngắn ở bên dưới — vật nằm phía dưới. Ngược hẳn với 上 (nét ngắn ở trên). Từ \"phía dưới\" mà ra nghĩa \"rơi xuống\": 下雨, 下雪."},{"char":"雪","pinyin":"xuě","hanviet":"Tuyết","chars":["雪"],"story":"雪 = 雨 (mưa, chỉ nghĩa) + 彐 vốn vẽ một bàn tay. Thứ từ trời rơi xuống mà cầm nắm được, đó là tuyết — khác hẳn hạt mưa vừa chạm tay đã tan."},{"char":"来","pinyin":"lái","hanviet":"Lai","chars":["来"],"story":"来 vốn vẽ cây lúa mạch trĩu bông, thân thẳng hai bên có lá rủ. Người xưa cho rằng lúa mạch là thứ trời đem tới, nên chữ này được mượn dùng cho nghĩa \"đến, tới\"."},{"char":"公司","pinyin":"gōngsī","hanviet":"Công ty","chars":["公","司"],"story":"公 = 八 (chia ra) + 厶 (cái riêng) — chia cái riêng thành của chung. 司 vẽ cái miệng đang ra lệnh, nghĩa là cai quản. 公司 = tổ chức chung có người cai quản = công ty."},{"char":"生病","pinyin":"shēngbìng","hanviet":"Sinh bệnh","chars":["生","病"],"story":"生 vẽ mầm cây nhú lên khỏi mặt đất — sinh ra, phát sinh. 病 = 疒 (bộ Nạch, người nằm nghiêng trên giường) + 丙 bǐng chỉ âm. 生病 = phát sinh bệnh = bị ốm."},{"char":"看病","pinyin":"kànbìng","hanviet":"Khán bệnh","chars":["看","病"],"story":"看 là 手 (bàn tay) đặt trên 目 (con mắt) — che tay lên trán để nhìn cho rõ. 看病 dùng được cho cả hai phía: bệnh nhân đi khám và bác sĩ khám bệnh."},{"char":"病","pinyin":"bìng","hanviet":"Bệnh","chars":["病"],"story":"病 = 疒 (bộ Nạch — vẽ người nằm nghiêng trên chiếc giường dựng đứng) + 丙 bǐng chỉ âm. Hầu hết chữ nói về bệnh tật đều mang bộ Nạch này: 疼, 痛, 疯."},{"char":"一点儿","pinyin":"yìdiǎnr","hanviet":"Nhất điểm nhi","chars":["一","点","儿"],"story":"一 là một nét ngang — số một. 点 là cái chấm nhỏ. 一点儿 = một chấm = một chút. Nhớ phân biệt: 一点儿 đứng SAU động từ (吃一点儿), còn 有点儿 đứng TRƯỚC tính từ và mang ý chê."},{"char":"药","pinyin":"yào","hanviet":"Dược","chars":["药"],"story":"药 = 艹 (bộ Thảo, cây cỏ) + 约 chỉ âm. Người xưa chữa bệnh bằng cây cỏ nên chữ \"thuốc\" mang bộ Thảo. Dạng phồn thể 藥 có 乐 (vui) ở dưới — uống thuốc khỏi bệnh thì vui."},{"char":"回","pinyin":"huí","hanviet":"Hồi","chars":["回"],"story":"回 vẽ hai vòng xoáy lồng vào nhau — dòng nước cuộn tròn quay trở lại chỗ cũ. Từ đó có nghĩa \"quay về, trở lại\": 回家 (về nhà), 回来 (trở về)."},{"char":"再","pinyin":"zài","hanviet":"Tái","chars":["再"],"story":"再 vốn là hình một vật đã có, thêm vào một nét ngang nữa — \"thêm một lần\". 再 nói về việc CHƯA xảy ra (再喝 = lát nữa uống thêm), khác 又 nói việc ĐÃ lặp lại rồi."},{"char":"喝","pinyin":"hē","hanviet":"Hát","chars":["喝"],"story":"喝 = 口 (bộ Khẩu, cái miệng — chỉ nghĩa) + 曷 hé (chỉ âm). Bộ Khẩu cho biết đây là động tác của miệng, đó là uống. Cùng bộ với 吃 (ăn), 叫 (gọi)."},{"char":"热","pinyin":"rè","hanviet":"Nhiệt","chars":["热"],"story":"热 giản thể có 灬 ở dưới — bốn chấm ấy chính là bộ Hoả 火 khi viết ở chân chữ. Có lửa thì nóng. Trái nghĩa hẳn với 冷 mang bộ Băng 冫 (nước đá)."},{"char":"水","pinyin":"shuǐ","hanviet":"Thuỷ","chars":["水"],"story":"水 là chữ tượng hình: nét móc ở giữa là dòng chảy chính, bốn nét hai bên là các nhánh nước rẽ ra. Khi làm bộ thủ, 水 viết gọn thành 氵 (ba chấm thuỷ) như trong 河, 汉, 没."}],"grammar":[{"title":"Câu không chủ vị (非主谓句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(时间词)</b><small>khi nào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>下雨 / 下雪</b><small>hiện tượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b><small>… rồi</small></span></div>","summary":"<p class=\"gr-lead\">Câu không chủ ngữ</p><ul><li>Câu nói về <b>thời tiết, hiện tượng tự nhiên</b> trong tiếng Trung <b>không có chủ ngữ</b>: <span class=\"zh\">下雨了</span>, <span class=\"zh\">下雪了</span>.</li><li>Muốn nói rõ thời gian thì đặt từ chỉ thời gian <b>lên đầu câu</b>: <span class=\"zh\">昨天下雪了。</span></li><li>Ngoài thời tiết, câu không chủ vị còn dùng để chào hỏi, cảm thán: <span class=\"zh\">谢谢！</span>　<span class=\"zh\">再见！</span>　<span class=\"zh\">太冷了！</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">下雨了。</span> = Trời mưa rồi.　·　<span class=\"zh\">昨天下雪了。</span> = Hôm qua tuyết rơi rồi.</p>","note":"<b>Lưu ý:</b> Đừng dịch máy móc \"trời mưa\" thành <span class=\"zh\">天下雨了</span> — tiếng Trung <b>chỉ nói</b> <span class=\"zh\">下雨了</span>.","examples":[{"zh":"昨天下雪了。","py":"Zuótiān xià xuě le.","vi":"Hôm qua tuyết rơi rồi."},{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Mưa rồi."},{"zh":"下雪了。","py":"Xià xuě le.","vi":"Tuyết rơi rồi."},{"zh":"上课了。","py":"Shàngkè le.","vi":"Vào học rồi."},{"zh":"真漂亮！","py":"Zhēn piàoliang!","vi":"Đẹp thật!"},{"zh":"对不起！","py":"Duìbuqǐ!","vi":"Xin lỗi!"},{"zh":"没关系！","py":"Méi guānxi!","vi":"Không sao!"}],"exercises":[]},{"title":"Trợ từ ngữ khí 了","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>… rồi</small></span></div>","summary":"<p class=\"gr-lead\">Việc đã xảy ra</p><ul><li><span class=\"zh\">了</span> đứng <b>cuối câu</b>, báo việc <b>đã xảy ra</b> hoặc tình hình <b>đã thay đổi</b>: <span class=\"zh\">下雨了</span> — trước đó trời chưa mưa.</li><li>Đọc <b>thanh nhẹ</b> <span class=\"zh\">le</span>, không đọc thành <span class=\"zh\">liǎo</span>.</li><li>Muốn hỏi thì thêm <span class=\"zh\">吗</span> vào cuối: <span class=\"zh\">你生病了吗？</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我生病了。</span> = Mình ốm rồi.　·　Phủ định: <span class=\"zh\">我没生病。</span> (bỏ hẳn 了)</p>","note":"<b>Lưu ý:</b> Câu <b>phủ định</b> dùng <span class=\"zh\">没(有)</span> và <b>bỏ hẳn</b> <span class=\"zh\">了</span>: <span class=\"zh\">我没来公司。</span> ✓　<span class=\"zh\">我没来公司了。</span> ✗","examples":[{"zh":"昨天我去医院看病了。","py":"Zuótiān wǒ qù yīyuàn kànbìng le.","vi":"Hôm qua mình đi bệnh viện khám rồi."},{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Mưa rồi."},{"zh":"十二点了，吃午饭吧。","py":"Shí'èr diǎn le, chī wǔfàn ba.","vi":"12 giờ rồi, ăn trưa thôi."},{"zh":"A：弟弟起床了吗？　B：没起床呢。","py":"A: Dìdi qǐchuáng le ma?　B: Méi qǐchuáng ne.","vi":"A: Em trai dậy chưa? — B: Chưa dậy đâu."}],"exercises":[]},{"title":"Mẫu câu 太……了","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>太</b><small>quá</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>… rồi</small></span></div>","summary":"<p class=\"gr-lead\">Quá … rồi!</p><ul><li><span class=\"zh\">太</span> + tính từ + <span class=\"zh\">了</span> diễn tả mức độ <b>rất cao</b>, mang sắc thái <b>cảm thán</b>: <span class=\"zh\">太冷了！</span></li><li>Dùng được cả khi <b>khen</b> (<span class=\"zh\">太好了</span>) lẫn khi <b>than phiền</b> (<span class=\"zh\">太热了</span>).</li><li>Muốn nói \"không … lắm\" thì đặt <span class=\"zh\">不</span> trước <span class=\"zh\">太</span> và <b>bỏ</b> <span class=\"zh\">了</span>: <span class=\"zh\">天气不太好。</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">太冷了！</span> = Lạnh quá!　·　<span class=\"zh\">太好了！</span> = Tuyệt quá!</p>","note":"<b>Lưu ý:</b> Chữ <span class=\"zh\">了</span> ở đây <b>không được thiếu</b>: <span class=\"zh\">太冷</span> ✗ — phải nói <span class=\"zh\">太冷了</span> ✓.","examples":[{"zh":"今天太冷了！","py":"Jīntiān tài lěng le!","vi":"Hôm nay lạnh quá!"},{"zh":"太冷了！","py":"Tài lěng le!","vi":"Lạnh quá!"},{"zh":"这个杯子太小了。","py":"Zhège bēizi tài xiǎo le.","vi":"Cái cốc này nhỏ quá."},{"zh":"我们今天太高兴了！","py":"Wǒmen jīntiān tài gāoxìng le!","vi":"Hôm nay chúng tôi vui quá!"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Hai chị em hỏi nhau về thời tiết","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"今天天气怎么样？","py":"Jīntiān tiānqì zěnmeyàng?","vi":"Hôm nay thời tiết thế nào?"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"这里的天不太好，下雨了。","py":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","vi":"Trời ở đây không đẹp lắm, mưa rồi."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"雨大吗？","py":"Yǔ dà ma?","vi":"Mưa có to không?"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"有点儿大，我觉得很冷。","py":"Yǒudiǎnr dà, wǒ juéde hěn lěng.","vi":"Hơi to, em thấy lạnh lắm."}]},{"titleZh":"课文二","titleVi":"Ở công ty — hỏi vì sao hôm qua nghỉ","lines":[{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"昨天下雪了。","py":"Zuótiān xià xuě le.","vi":"Hôm qua tuyết rơi rồi."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"是的，太冷了。","py":"Shì de, tài lěng le.","vi":"Vâng, lạnh quá chị ạ."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"你昨天没来公司，生病了？","py":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","vi":"Hôm qua em không đến công ty, ốm à?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"对，我昨天去医院看病了。","py":"Duì, wǒ zuótiān qù yīyuàn kànbìng le.","vi":"Vâng, hôm qua em đi bệnh viện khám rồi."}]},{"titleZh":"课文三","titleVi":"Ở bệnh viện — bác sĩ khám bệnh","lines":[{"speaker":"乐","name":"Dương Đồng Lạc","zh":"医生，我病了。","py":"Yīshēng, wǒ bìng le.","vi":"Bác sĩ ơi, em bị ốm rồi."},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"我看看。你觉得怎么样？","py":"Wǒ kànkan. Nǐ juéde zěnmeyàng?","vi":"Để tôi xem nào. Em thấy trong người thế nào?"},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"我很冷。","py":"Wǒ hěn lěng.","vi":"Em thấy lạnh lắm."},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"好的，吃一点儿药，今天休息半天吧。","py":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","vi":"Được rồi, uống một chút thuốc, hôm nay nghỉ nửa ngày nhé."},{"speaker":"乐","name":"Dương Đồng Lạc","zh":"好的。","py":"Hǎo de.","vi":"Vâng ạ."},{"speaker":"胡","name":"Bác sĩ Hồ","zh":"回家后再喝些热水。","py":"Huí jiā hòu zài hē xiē rè shuǐ.","vi":"Về đến nhà thì uống thêm chút nước nóng nữa nhé."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Đóng vai bác sĩ – bệnh nhân","q":{"zh":"两人一组，一个人扮演医生，另一个人扮演病人，病人来看病。","py":"Liǎng rén yì zǔ, yí gè rén bànyǎn yīshēng, lìng yí gè rén bànyǎn bìngrén, bìngrén lái kànbìng.","vi":"Hai người một nhóm, một người đóng bác sĩ, người kia đóng bệnh nhân đến khám bệnh."},"items":[{"lines":[{"who":"病人","zh":"医生，我病了。","py":"Yīshēng, wǒ bìng le.","vi":"Bác sĩ ơi, tôi bị ốm rồi."},{"who":"医生","zh":"我看看。你觉得冷不冷？","py":"Wǒ kànkan. Nǐ juéde lěng bu lěng?","vi":"Để tôi xem. Anh có thấy lạnh không?"}]},{"lines":[{"who":"病人","zh":"有点儿冷。","py":"Yǒudiǎnr lěng.","vi":"Hơi lạnh ạ."},{"who":"医生","zh":"好的，吃一点儿药吧。","py":"Hǎo de, chī yìdiǎnr yào ba.","vi":"Được rồi, uống chút thuốc nhé."}]}]}],"speak":[]},"review":{"range":"10–12","rows":[{"l":10,"zh":"询问商品价格","vi":"Hỏi giá hàng","ex":{"zh":"苹果多少钱？","py":"Píngguǒ duōshao qián?","vi":"Táo bao nhiêu tiền?"}},{"l":10,"zh":"钱数的表达","vi":"Cách nói số tiền","ex":{"zh":"三块二，六块零两分","py":"sān kuài èr, liù kuài líng liǎng fēn","vi":"3,2 đồng; 6,02 đồng"}},{"l":10,"zh":"形容词谓语句","vi":"Câu vị ngữ tính từ","ex":{"zh":"这个苹果很好吃。","py":"Zhège píngguǒ hěn hǎochī.","vi":"Quả táo này rất ngon."}},{"l":10,"zh":"疑问代词\"怎么样\"","vi":"Đại từ nghi vấn 怎么样","ex":{"zh":"这件衣服怎么样？","py":"Zhè jiàn yīfu zěnmeyàng?","vi":"Cái áo này thế nào?"}},{"l":11,"zh":"正反问","vi":"Câu hỏi chính phản","ex":{"zh":"好不好？","py":"Hǎo bu hǎo?","vi":"Được không?"}},{"l":11,"zh":"时间副词\"在/正在\"","vi":"Phó từ thời gian 在 / 正在","ex":{"zh":"他在休息呢。","py":"Tā zài xiūxi ne.","vi":"Anh ấy đang nghỉ."}},{"l":11,"zh":"能愿动词\"要\"","vi":"Động từ năng nguyện 要","ex":{"zh":"我要睡觉。","py":"Wǒ yào shuìjiào.","vi":"Tôi muốn đi ngủ."}},{"l":12,"zh":"非主谓句","vi":"Câu không chủ – vị","ex":{"zh":"下雨了。","py":"Xià yǔ le.","vi":"Mưa rồi."}},{"l":12,"zh":"语气助词\"了（1）\"","vi":"Trợ từ ngữ khí 了 (1)","ex":{"zh":"我去上课了。","py":"Wǒ qù shàngkè le.","vi":"Tôi đi học đây."}},{"l":12,"zh":"\"太……了\"格式","vi":"Mẫu câu 太……了","ex":{"zh":"太冷了！","py":"Tài lěng le!","vi":"Lạnh quá!"}},{"l":12,"zh":"描述天气情况","vi":"Miêu tả thời tiết","ex":{"zh":"今天下雨了。","py":"Jīntiān xià yǔ le.","vi":"Hôm nay mưa rồi."}},{"l":12,"zh":"简单描述病情","vi":"Miêu tả bệnh đơn giản","ex":{"zh":"我病了，觉得很冷。","py":"Wǒ bìng le, juéde hěn lěng.","vi":"Tôi bị ốm rồi, thấy rất lạnh."}}]}},{"id":"k1v3-b13","courseId":"k1v3","order":13,"title":"Cho tôi một cốc trà","titleZh":"请给我一杯茶","titlePy":"qǐng gěi wǒ yì bēi chá","vocab":[{"stt":1,"hanzi":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","pos":"Động từ năng nguyện","meaning":"có thể, được phép","comps":"可以吗 (được không), 不可以 (không được)","example":{"zh":"我可以坐这儿吗？","py":"Wǒ kěyǐ zuò zhèr ma?","vi":"Mình ngồi đây được không?"}},{"stt":2,"hanzi":"再","pinyin":"zài","hanviet":"Tái","pos":"Phó từ","meaning":"lại, thêm nữa","comps":"再要 (gọi thêm), 再问 (hỏi thêm)","example":{"zh":"我可以再问一个问题吗？","py":"Wǒ kěyǐ zài wèn yí gè wèntí ma?","vi":"Mình hỏi thêm một câu được không?"}},{"stt":3,"hanzi":"问题","pinyin":"wèntí","hanviet":"Vấn đề","pos":"Danh từ","meaning":"câu hỏi; vấn đề","comps":"有问题 (có câu hỏi), 问问题 (đặt câu hỏi)","example":{"zh":"你有什么问题？","py":"Nǐ yǒu shénme wèntí?","vi":"Bạn có câu hỏi gì?"}},{"stt":4,"hanzi":"卖","pinyin":"mài","hanviet":"Mại","pos":"Động từ","meaning":"bán (↔ 买 mua)","comps":"卖茶 (bán trà), 不卖 (không bán)","example":{"zh":"这个小店卖面包。","py":"Zhège xiǎo diàn mài miànbāo.","vi":"Cửa hàng nhỏ này bán bánh mì."}},{"stt":5,"hanzi":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","pos":"Động từ","meaning":"gọi điện thoại","comps":"给我打电话 (gọi cho tôi), 打个电话 (gọi một cuộc)","example":{"zh":"你可以打电话问一下。","py":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vi":"Bạn có thể gọi điện hỏi thử xem."}},{"stt":6,"hanzi":"一下","pinyin":"yíxià","hanviet":"Nhất hạ","pos":"Số lượng từ","meaning":"một chút, thử xem","comps":"看一下 (xem một chút), 问一下 (hỏi một chút)","example":{"zh":"我看一下。","py":"Wǒ kàn yíxià.","vi":"Để mình xem một chút."}},{"stt":7,"hanzi":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","pos":"Danh từ","meaning":"nhân viên phục vụ","comps":"叫服务员 (gọi nhân viên), 女服务员 (nữ nhân viên)","example":{"zh":"服务员，请给我一杯茶。","py":"Fúwùyuán, qǐng gěi wǒ yì bēi chá.","vi":"Em ơi, cho anh một cốc trà."}},{"stt":8,"hanzi":"女士","pinyin":"nǚshì","hanviet":"Nữ sĩ","pos":"Danh từ","meaning":"quý bà (gọi phụ nữ)","comps":"王女士 (bà Vương), 女士们 (các quý bà)","example":{"zh":"女士，请坐！","py":"Nǚshì, qǐng zuò!","vi":"Thưa chị, mời chị ngồi!"}},{"stt":9,"hanzi":"请","pinyin":"qǐng","hanviet":"Thỉnh","pos":"Động từ","meaning":"mời, xin mời","comps":"请坐 (mời ngồi), 请问 (xin hỏi)","example":{"zh":"请给我一杯水。","py":"Qǐng gěi wǒ yì bēi shuǐ.","vi":"Cho tôi một cốc nước nhé."}},{"stt":10,"hanzi":"坐","pinyin":"zuò","hanviet":"Toạ","pos":"Động từ","meaning":"ngồi","comps":"请坐 (mời ngồi), 坐车 (đi xe)","example":{"zh":"先生，请坐！","py":"Xiānsheng, qǐng zuò!","vi":"Thưa anh, mời anh ngồi!"}},{"stt":11,"hanzi":"给","pinyin":"gěi","hanviet":"Cấp","pos":"Động từ","meaning":"cho, đưa cho","comps":"给我 (đưa cho tôi), 给你 (cho bạn)","example":{"zh":"请给我这个面包。","py":"Qǐng gěi wǒ zhège miànbāo.","vi":"Cho tôi cái bánh mì này nhé."}},{"stt":12,"hanzi":"杯","pinyin":"bēi","hanviet":"Bôi","pos":"Danh từ","meaning":"cốc, ly (dùng như lượng từ)","comps":"一杯茶 (một cốc trà), 两杯水 (hai cốc nước)","example":{"zh":"我要一杯热水。","py":"Wǒ yào yì bēi rè shuǐ.","vi":"Mình muốn một cốc nước nóng."}},{"stt":13,"hanzi":"要","pinyin":"yào","hanviet":"Yếu","pos":"Động từ","meaning":"muốn, gọi (món)","comps":"要什么 (muốn gì), 还要 (còn muốn nữa)","example":{"zh":"您要什么？","py":"Nín yào shénme?","vi":"Anh muốn dùng gì ạ?"}},{"stt":14,"hanzi":"早饭","pinyin":"zǎofàn","hanviet":"Tảo phạn","pos":"Danh từ","meaning":"bữa sáng","comps":"吃早饭 (ăn sáng), 做早饭 (nấu bữa sáng)","example":{"zh":"我还没吃早饭。","py":"Wǒ hái méi chī zǎofàn.","vi":"Mình vẫn chưa ăn sáng."}},{"stt":15,"hanzi":"这个","pinyin":"zhège","hanviet":"Giá cá","pos":"Đại từ","meaning":"cái này (↔ 那个)","comps":"这个人 (người này), 这个面包 (cái bánh này)","example":{"zh":"我要这个鸡蛋。","py":"Wǒ yào zhège jīdàn.","vi":"Mình lấy quả trứng này."}},{"stt":16,"hanzi":"面包","pinyin":"miànbāo","hanviet":"Diện bao","pos":"Danh từ","meaning":"bánh mì","comps":"吃面包 (ăn bánh mì), 买面包 (mua bánh mì)","example":{"zh":"这个面包很好吃。","py":"Zhège miànbāo hěn hǎochī.","vi":"Cái bánh mì này rất ngon."}},{"stt":17,"hanzi":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","pos":"Danh từ","meaning":"trứng gà","comps":"吃鸡蛋 (ăn trứng), 一个鸡蛋 (một quả trứng)","example":{"zh":"我要面包和鸡蛋。","py":"Wǒ yào miànbāo hé jīdàn.","vi":"Mình lấy bánh mì và trứng gà."}},{"stt":18,"hanzi":"先生","pinyin":"xiānsheng","hanviet":"Tiên sinh","pos":"Danh từ","meaning":"ông, anh (lịch sự)","comps":"王先生 (ông Vương), 先生们 (các quý ông)","example":{"zh":"先生，您要什么？","py":"Xiānsheng, nín yào shénme?","vi":"Thưa anh, anh muốn dùng gì ạ?"}},{"stt":19,"hanzi":"一半","pinyin":"yíbàn","hanviet":"Nhất bán","pos":"Số từ","meaning":"một nửa","comps":"要一半 (lấy một nửa), 一半人 (nửa số người)","example":{"zh":"太多了，我要一半吧。","py":"Tài duō le, wǒ yào yíbàn ba.","vi":"Nhiều quá, tôi lấy một nửa thôi."}},{"stt":20,"hanzi":"茶","pinyin":"chá","hanviet":"Trà","pos":"Danh từ","meaning":"trà, nước chè","comps":"一杯茶 (một cốc trà), 喝茶 (uống trà)","example":{"zh":"请给我一杯茶。","py":"Qǐng gěi wǒ yì bēi chá.","vi":"Cho tôi một cốc trà nhé."}}],"hanzi":[{"char":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","chars":["可","以"],"story":"可 vẽ cái miệng 口 kèm một nét cong — lời nói được chấp thuận, nên có nghĩa \"được\". 以 vốn vẽ người cầm cái cày, nghĩa là \"dùng\". 可以 = \"dùng được\" = có thể, được phép."},{"char":"再","pinyin":"zài","hanviet":"Tái","chars":["再"],"story":"再 vốn là hình một vật đã có, thêm vào một nét ngang nữa — \"thêm một lần\". Nhớ như ở bài 12: 再 nói về việc CHƯA xảy ra (再要 = lát nữa gọi thêm), khác 又 nói việc ĐÃ lặp lại."},{"char":"问题","pinyin":"wèntí","hanviet":"Vấn đề","chars":["问","题"],"story":"问 = 门 (cái cửa, chỉ âm) + 口 (miệng) — đứng ngoài cửa hỏi vọng vào. 题 = 是 + 页 (bộ Hiệt, cái đầu) — điều phải nghĩ trong đầu. 问题 = điều đem ra hỏi = câu hỏi, vấn đề."},{"char":"卖","pinyin":"mài","hanviet":"Mại","chars":["卖"],"story":"卖 dạng phồn thể 賣 có 出 (đi ra) ở trên và 買 (mua) ở dưới — đem hàng đã mua ra ngoài, đó là bán. Nhớ cặp của bài 6: 买 mǎi (mua) không có nét trên, 卖 mài (bán) có thêm nét ở trên."},{"char":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","chars":["打","电","话"],"story":"打 = 扌 (bộ Thủ, bàn tay) + 丁 chỉ âm — động tác của tay. 电 vẽ tia chớp loé ra từ đám mây. 话 = 讠 (lời nói) + 舌 (cái lưỡi). 打电话 = \"gõ lời nói đi bằng điện\" = gọi điện thoại."},{"char":"一下","pinyin":"yíxià","hanviet":"Nhất hạ","chars":["一","下"],"story":"一 là một nét ngang — số một. 下 vẽ vật nằm dưới một đường ngang. 一下 vốn nghĩa \"một cái, một nhát\"; nay đặt sau động từ để làm hành động nhẹ đi và nghe lịch sự hơn."},{"char":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","chars":["服","务","员"],"story":"服 = 月 (thân mình) + 卩 (người quỳ) — phục tùng. 务 là việc phải làm. 员 có 口 trên 贝 (vỏ sò, tiền) — người trong một tập thể. 服务员 = người làm công việc phục vụ."},{"char":"女士","pinyin":"nǚshì","hanviet":"Nữ sĩ","chars":["女","士"],"story":"女 vẽ dáng người phụ nữ ngồi khoanh tay. 士 vốn vẽ cái rìu dựng đứng — người có tài, kẻ sĩ. 女士 là cách gọi trang trọng dành cho phụ nữ, đi thành cặp với 先生 dành cho nam giới."},{"char":"请","pinyin":"qǐng","hanviet":"Thỉnh","chars":["请"],"story":"请 = 讠 (bộ Ngôn, lời nói) + 青 qīng chỉ âm. Bộ Ngôn cho biết đây là lời nói lịch sự khi nhờ vả hay mời mọc: 请坐, 请问, 请给我."},{"char":"坐","pinyin":"zuò","hanviet":"Toạ","chars":["坐"],"story":"坐 vẽ hai chữ 人 (người) ngồi đối diện nhau trên chữ 土 (mặt đất) — hai người ngồi bệt xuống đất. Đó chính là nghĩa \"ngồi\"."},{"char":"给","pinyin":"gěi","hanviet":"Cấp","chars":["给"],"story":"给 = 纟 (bộ Mịch, sợi tơ) + 合 (hợp lại) chỉ âm. Vốn nghĩa \"cung cấp cho đủ\", nay dùng cho nghĩa \"cho, đưa cho\": 给我一杯茶."},{"char":"杯","pinyin":"bēi","hanviet":"Bôi","chars":["杯"],"story":"杯 = 木 (bộ Mộc, cây gỗ) + 不 chỉ âm. Ngày xưa cái cốc được tiện bằng gỗ nên chữ mang bộ Mộc. Nay 杯 làm lượng từ cho mọi thứ đồ uống: 一杯茶, 一杯水."},{"char":"要","pinyin":"yào","hanviet":"Yếu","chars":["要"],"story":"要 vốn vẽ người phụ nữ hai tay chống lên eo — đây chính là chữ \"eo\" 腰 thuở ban đầu. Sau được mượn cho nghĩa \"cần, muốn\". Ở bài 11 要 là động từ năng nguyện, ở bài này là \"gọi món\"."},{"char":"早饭","pinyin":"zǎofàn","hanviet":"Tảo phạn","chars":["早","饭"],"story":"早 = 日 (mặt trời) đặt trên 十 — mặt trời vừa nhô lên khỏi ngọn cây, nghĩa là sớm. 饭 = 饣 (bộ Thực, thức ăn) + 反 chỉ âm. 早饭 = bữa cơm sớm = bữa sáng."},{"char":"这个","pinyin":"zhège","hanviet":"Giá cá","chars":["这","个"],"story":"这 = 辶 (bộ Sước, bước chân) + 文 — cái ở ngay đây. 个 vẽ một cành tre chẻ đôi, thành lượng từ dùng chung cho nhiều thứ. 这个 = cái này, đi cặp với 那个 đã học ở bài 9."},{"char":"面包","pinyin":"miànbāo","hanviet":"Diện bao","chars":["面","包"],"story":"面 vốn vẽ khuôn mặt, sau được dùng cho nghĩa \"bột mì\". 包 vẽ bào thai được bọc kín trong bụng — bao bọc. 面包 = bột mì được gói lại rồi đem nướng = bánh mì."},{"char":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","chars":["鸡","蛋"],"story":"鸡 = 又 (bàn tay) + 鸟 (bộ Điểu, con chim) — con chim mà người ta bắt nuôi được, đó là con gà. 蛋 = 疋 + 虫 (bộ Trùng) — vật do con vật đẻ ra. 鸡蛋 = trứng gà."},{"char":"先生","pinyin":"xiānsheng","hanviet":"Tiên sinh","chars":["先","生"],"story":"先 = nét chỉ bước chân đặt trên 儿 (người) — người đi trước. 生 vẽ mầm cây nhú lên khỏi đất — sinh ra. 先生 = \"người sinh ra trước\", bậc đàn anh; nay là cách gọi lịch sự với nam giới."},{"char":"一半","pinyin":"yíbàn","hanviet":"Nhất bán","chars":["一","半"],"story":"一 là số một. 半 = 八 (chia ra) + 牛 (con bò) — chia đôi con bò, đó là một nửa. 一半 = một nửa; chữ 半 còn đứng trước lượng từ như 半斤, 半天 (bài 12)."},{"char":"茶","pinyin":"chá","hanviet":"Trà","chars":["茶"],"story":"茶 = 艹 (bộ Thảo, cây cỏ) ở trên, 人 (người) và 木 (cây) ở dưới — lá cây được người hái xuống. Cùng bộ Thảo với 药 (bài 12), vì cả thuốc lẫn trà đều đến từ cây cỏ."}],"grammar":[{"title":"Động từ năng nguyện 可以","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>可以</b><small>được phép</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>làm gì</small></span></div>","summary":"<p class=\"gr-lead\">Được phép làm gì</p><ul><li><span class=\"zh\">可以</span> đặt <b>trước động từ</b>, nghĩa là \"được phép, có thể\" — hay dùng để <b>xin phép</b>: <span class=\"zh\">我可以再问您一个问题吗？</span></li><li>Trả lời ngắn chỉ cần <span class=\"zh\">可以。</span> (được) hoặc <span class=\"zh\">不可以。</span> (không được).</li><li>So với các động từ năng nguyện đã học: <span class=\"zh\">想</span> là <b>muốn</b>, <span class=\"zh\">能</span> là <b>đủ điều kiện</b>, <span class=\"zh\">可以</span> nghiêng về <b>được phép</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我可以问您吗？</span> = Em hỏi cô được không?　·　Phủ định: <span class=\"zh\">不可以</span> (không được)</p>","note":"<b>Lưu ý:</b> Phủ định là <span class=\"zh\">不可以</span> — <b>không</b> nói <span class=\"zh\">没可以</span>.","examples":[{"zh":"我可以坐这儿吗？","py":"Wǒ kěyǐ zuò zhèr ma?","vi":"Mình ngồi đây được không?"},{"zh":"我可以再问您一个问题吗？","py":"Wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vi":"Em có thể hỏi cô thêm một câu nữa không ạ?"},{"zh":"你们可以看这本书。","py":"Nǐmen kěyǐ kàn zhè běn shū.","vi":"Các bạn có thể đọc quyển sách này."},{"zh":"A：我可以坐吗？　B：可以，请坐！","py":"A: Wǒ kěyǐ zuò ma?　B: Kěyǐ, qǐng zuò!","vi":"A: Tôi ngồi được không? — B: Được, mời ngồi!"}],"exercises":[]},{"title":"Cấu trúc \"động từ + 一下\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一下</b><small>một cái</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Thử một cái</p><ul><li><span class=\"zh\">一下</span> đứng <b>ngay sau động từ</b>, làm hành động nghe <b>nhẹ và ngắn</b>, lịch sự hơn hẳn: <span class=\"zh\">看一下</span>, <span class=\"zh\">问一下</span>.</li><li>Đọc <span class=\"zh\">yíxià</span> — chữ <span class=\"zh\">一</span> đứng trước thanh 4 <b>biến thành thanh 2</b>.</li><li>Có tân ngữ thì đặt <b>sau</b> <span class=\"zh\">一下</span>: <span class=\"zh\">看一下这个面包</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我看一下。</span> = Để mình xem một cái.　·　<span class=\"zh\">你问一下吧。</span> = Bạn hỏi thử xem.</p>","note":"<b>Lưu ý:</b> Lặp động từ (<span class=\"zh\">看看</span>) và <span class=\"zh\">看一下</span> nghĩa gần như nhau, nhưng <span class=\"zh\">一下</span> <b>đi được với cả động từ hai âm tiết</b>: <span class=\"zh\">介绍一下</span>.","examples":[{"zh":"我看一下。","py":"Wǒ kàn yíxià.","vi":"Để mình xem một chút."},{"zh":"你可以打电话问一下。","py":"Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vi":"Bạn có thể gọi điện hỏi thử."},{"zh":"请休息一下。","py":"Qǐng xiūxi yíxià.","vi":"Mời nghỉ một chút."},{"zh":"你看一下吧。","py":"Nǐ kàn yíxià ba.","vi":"Bạn xem thử đi."}],"exercises":[]},{"title":"Câu hai tân ngữ (双宾语句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>给 / 问</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语 1</b><small>ai</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语 2</b><small>cái gì</small></span></div>","summary":"<p class=\"gr-lead\">Cho ai cái gì</p><ul><li>Một số động từ mang được <b>hai tân ngữ</b> cùng lúc: tân ngữ chỉ <b>người</b> đứng trước, tân ngữ chỉ <b>vật</b> đứng sau.</li><li>Hay gặp nhất ở trình độ sơ cấp: <span class=\"zh\">给</span> (cho), <span class=\"zh\">问</span> (hỏi), <span class=\"zh\">叫</span> (gọi là).</li><li>Tân ngữ chỉ vật thường đi kèm <b>số + lượng từ</b>: <span class=\"zh\">一杯茶</span>, <span class=\"zh\">一个问题</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">请给我一杯茶。</span> = Cho tôi một cốc trà.　·　<span class=\"zh\">我问您一个问题。</span> = Em hỏi cô một câu.</p>","note":"<b>Lưu ý:</b> <b>Không được đảo thứ tự</b>: <span class=\"zh\">给我一杯茶</span> ✓ — <span class=\"zh\">给一杯茶我</span> ✗.","examples":[{"zh":"请给我一杯茶。","py":"Qǐng gěi wǒ yì bēi chá.","vi":"Cho tôi một cốc trà nhé."},{"zh":"请给我一杯牛奶。","py":"Qǐng gěi wǒ yì bēi niúnǎi.","vi":"Cho tôi một cốc sữa."},{"zh":"白家月给安妮一个苹果。","py":"Bái Jiāyuè gěi Ānnī yí gè píngguǒ.","vi":"Bạch Gia Nguyệt đưa cho Annie một quả táo."},{"zh":"我问老师两个问题。","py":"Wǒ wèn lǎoshī liǎng gè wèntí.","vi":"Tôi hỏi cô giáo hai câu hỏi."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Ở lớp — học trò hỏi thêm cô Vương","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"王老师，我可以再问您一个问题吗？","py":"Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?","vi":"Thưa cô Vương, em hỏi cô thêm một câu được không ạ?"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"可以。你有什么问题？","py":"Kěyǐ. Nǐ yǒu shénme wèntí?","vi":"Được chứ. Em có câu hỏi gì nào?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"那个小店卖不卖手机？","py":"Nàge xiǎo diàn mài bu mài shǒujī?","vi":"Cửa hàng nhỏ kia có bán điện thoại không ạ?"},{"speaker":"飞","name":"Vương Nhất Phi","zh":"我不知道。你可以打电话问一下。","py":"Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","vi":"Cô không biết. Em có thể gọi điện hỏi thử xem."}]},{"titleZh":"课文二","titleVi":"Ở quán — nhân viên mời khách gọi món","lines":[{"speaker":"服","name":"Nhân viên","zh":"女士，请坐！您喝什么？","py":"Nǚshì, qǐng zuò! Nín hē shénme?","vi":"Thưa chị, mời chị ngồi! Chị uống gì ạ?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我看一下。请给我一杯牛奶。","py":"Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","vi":"Để tôi xem một chút. Cho tôi một cốc sữa nhé."},{"speaker":"服","name":"Nhân viên","zh":"好的。您还要什么？","py":"Hǎo de. Nín hái yào shénme?","vi":"Vâng ạ. Chị còn muốn gọi gì nữa không?"},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"我还没吃早饭，再要这个面包和鸡蛋吧。","py":"Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","vi":"Tôi vẫn chưa ăn sáng, lấy thêm cái bánh mì này và quả trứng nữa nhé."}]},{"titleZh":"课文三","titleVi":"Ở quán — anh Minh gọi sủi cảo, trà","lines":[{"speaker":"服","name":"Nhân viên","zh":"先生，请坐！您要什么？","py":"Xiānsheng, qǐng zuò! Nín yào shénme?","vi":"Thưa anh, mời anh ngồi! Anh dùng gì ạ?"},{"speaker":"明","name":"Lưu Minh","zh":"我要一斤饺子。","py":"Wǒ yào yì jīn jiǎozi.","vi":"Cho tôi một cân sủi cảo."},{"speaker":"服","name":"Nhân viên","zh":"好的。一斤饺子40个。","py":"Hǎo de. Yì jīn jiǎozi sìshí gè.","vi":"Vâng ạ. Một cân sủi cảo là 40 chiếc."},{"speaker":"明","name":"Lưu Minh","zh":"40个太多了，我要一半吧。","py":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","vi":"40 chiếc nhiều quá, tôi lấy một nửa thôi."},{"speaker":"服","name":"Nhân viên","zh":"半斤20个。您想喝什么？","py":"Bàn jīn èrshí gè. Nín xiǎng hē shénme?","vi":"Nửa cân là 20 chiếc ạ. Anh muốn uống gì?"},{"speaker":"明","name":"Lưu Minh","zh":"请给我一杯茶吧。","py":"Qǐng gěi wǒ yì bēi chá ba.","vi":"Cho tôi một cốc trà nhé."}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Gọi đồ ở quán cà phê","q":{"zh":"三人一组，一个人扮演服务员，两个人扮演顾客，表演在咖啡馆点餐。","py":"Sān rén yì zǔ, yí gè rén bànyǎn fúwùyuán, liǎng gè rén bànyǎn gùkè, biǎoyǎn zài kāfēiguǎn diǎn cān.","vi":"Nhóm 3 người, một người đóng nhân viên phục vụ, hai người đóng khách, diễn cảnh gọi đồ ở quán cà phê."},"items":[{"lines":[{"who":"服务员","zh":"请坐！你们要喝什么？","py":"Qǐng zuò! Nǐmen yào hē shénme?","vi":"Mời ngồi! Các bạn muốn uống gì?"},{"who":"顾客1","zh":"我要一杯茶。","py":"Wǒ yào yì bēi chá.","vi":"Tôi lấy một cốc trà."},{"who":"顾客2","zh":"我要一杯牛奶。","py":"Wǒ yào yì bēi niúnǎi.","vi":"Tôi lấy một cốc sữa."}]},{"lines":[{"who":"服务员","zh":"你们要吃什么？","py":"Nǐmen yào chī shénme?","vi":"Các bạn muốn ăn gì?"},{"who":"顾客1","zh":"请给我们两个面包。","py":"Qǐng gěi wǒmen liǎng gè miànbāo.","vi":"Cho chúng tôi hai cái bánh mì."}]}]}],"speak":[]}},{"id":"k1v3-b14","courseId":"k1v3","order":14,"title":"Tôi đã xem một bộ phim","titleZh":"我看了一个电影","titlePy":"wǒ kànle yí gè diànyǐng","vocab":[{"stt":1,"hanzi":"上","pinyin":"shàng","hanviet":"Thượng","pos":"Động từ","meaning":"lên (tàu, xe, thuyền)","comps":"上火车 (lên tàu), 上车 (lên xe)","example":{"zh":"我们上火车吧。","py":"Wǒmen shàng huǒchē ba.","vi":"Chúng ta lên tàu thôi."}},{"stt":2,"hanzi":"火车","pinyin":"huǒchē","hanviet":"Hoả xa","pos":"Danh từ","meaning":"tàu hoả, xe lửa","comps":"上火车 (lên tàu), 火车站 (ga tàu)","example":{"zh":"中午火车开了。","py":"Zhōngwǔ huǒchē kāi le.","vi":"Trưa nay tàu chạy rồi."}},{"stt":3,"hanzi":"中午","pinyin":"zhōngwǔ","hanviet":"Trung ngọ","pos":"Danh từ","meaning":"buổi trưa","comps":"中午好 (chào buổi trưa), 中午饭 (bữa trưa)","example":{"zh":"中午我在家看书。","py":"Zhōngwǔ wǒ zài jiā kàn shū.","vi":"Buổi trưa mình đọc sách ở nhà."}},{"stt":4,"hanzi":"开","pinyin":"kāi","hanviet":"Khai","pos":"Động từ","meaning":"mở; chạy, lái (xe)","comps":"开车 (lái xe), 车开了 (xe chạy rồi)","example":{"zh":"火车什么时候开？","py":"Huǒchē shénme shíhou kāi?","vi":"Tàu chạy lúc nào vậy?"}},{"stt":5,"hanzi":"有些","pinyin":"yǒuxiē","hanviet":"Hữu ta","pos":"Đại từ","meaning":"một số, có những…","comps":"有些人 (một số người), 有些书 (một số quyển sách)","example":{"zh":"有些人在看书，有些人睡觉了。","py":"Yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","vi":"Có người đang đọc sách, có người ngủ rồi."}},{"stt":6,"hanzi":"有的","pinyin":"yǒude","hanviet":"Hữu đích","pos":"Đại từ","meaning":"có cái, có người","comps":"有的人 (có người), 有的书 (có quyển)","example":{"zh":"这些书，有的很好看。","py":"Zhèxiē shū, yǒude hěn hǎokàn.","vi":"Mấy quyển sách này, có quyển rất hay."}},{"stt":7,"hanzi":"了","pinyin":"le","hanviet":"Liễu","pos":"Trợ từ","meaning":"đã… rồi (hoàn thành)","comps":"看了 (đã xem), 上学了 (đi học rồi)","example":{"zh":"我看了一个电影。","py":"Wǒ kànle yí gè diànyǐng.","vi":"Mình đã xem một bộ phim."}},{"stt":8,"hanzi":"写","pinyin":"xiě","hanviet":"Tả","pos":"Động từ","meaning":"viết","comps":"写字 (viết chữ), 写汉字 (viết chữ Hán)","example":{"zh":"我会写汉字了。","py":"Wǒ huì xiě Hànzì le.","vi":"Mình biết viết chữ Hán rồi."}},{"stt":9,"hanzi":"都","pinyin":"dōu","hanviet":"Đô","pos":"Phó từ","meaning":"đều, tất cả đều","comps":"我们都 (chúng tôi đều), 都会 (đều biết)","example":{"zh":"我们都会写了。","py":"Wǒmen dōu huì xiě le.","vi":"Chúng em đều biết viết rồi."}},{"stt":10,"hanzi":"听见","pinyin":"tīngjiàn","hanviet":"Thính kiến","pos":"Động từ","meaning":"nghe thấy","comps":"听见了 (nghe thấy rồi), 听不见 (không nghe thấy)","example":{"zh":"老师，我听不见。","py":"Lǎoshī, wǒ tīng bú jiàn.","vi":"Thưa thầy, em không nghe thấy."}},{"stt":11,"hanzi":"不要","pinyin":"búyào","hanviet":"Bất yếu","pos":"Phó từ","meaning":"đừng, không được","comps":"不要说话 (đừng nói chuyện), 不要看 (đừng nhìn)","example":{"zh":"请大家不要说话！","py":"Qǐng dàjiā búyào shuōhuà!","vi":"Mời cả lớp đừng nói chuyện!"}},{"stt":12,"hanzi":"说话","pinyin":"shuōhuà","hanviet":"Thuyết thoại","pos":"Động từ","meaning":"nói, nói chuyện","comps":"不要说话 (đừng nói chuyện), 说汉语 (nói tiếng Trung)","example":{"zh":"上课的时候不要说话。","py":"Shàngkè de shíhou búyào shuōhuà.","vi":"Trong giờ học đừng nói chuyện."}},{"stt":13,"hanzi":"听","pinyin":"tīng","hanviet":"Thính","pos":"Động từ","meaning":"nghe","comps":"听见 (nghe thấy), 好听 (nghe hay)","example":{"zh":"请听老师的问题。","py":"Qǐng tīng lǎoshī de wèntí.","vi":"Mời các em nghe câu hỏi của thầy."}},{"stt":14,"hanzi":"哪些","pinyin":"nǎxiē","hanviet":"Ná ta","pos":"Đại từ nghi vấn","meaning":"những cái nào","comps":"哪些人 (những ai), 哪些汉字 (những chữ Hán nào)","example":{"zh":"你会写哪些汉字？","py":"Nǐ huì xiě nǎxiē Hànzì?","vi":"Em biết viết những chữ Hán nào?"}},{"stt":15,"hanzi":"字","pinyin":"zì","hanviet":"Tự","pos":"Danh từ","meaning":"chữ, chữ viết","comps":"汉字 (chữ Hán), 写字 (viết chữ)","example":{"zh":"我会写这些字了。","py":"Wǒ huì xiě zhèxiē zì le.","vi":"Mình biết viết mấy chữ này rồi."}},{"stt":16,"hanzi":"明年","pinyin":"míngnián","hanviet":"Minh niên","pos":"Danh từ","meaning":"năm sau, sang năm","comps":"明年见 (sang năm gặp lại), 到明年 (đến sang năm)","example":{"zh":"明年女儿上中学。","py":"Míngnián nǚ'ér shàng zhōngxué.","vi":"Sang năm con gái lên cấp hai."}},{"stt":17,"hanzi":"上","pinyin":"shàng","hanviet":"Thượng","pos":"Động từ","meaning":"vào học, theo học","comps":"上中学 (học cấp hai), 上小学 (học tiểu học)","example":{"zh":"儿子明年上小学。","py":"Érzi míngnián shàng xiǎoxué.","vi":"Sang năm con trai vào lớp một."}},{"stt":18,"hanzi":"中学","pinyin":"zhōngxué","hanviet":"Trung học","pos":"Danh từ","meaning":"trường trung học","comps":"上中学 (học trung học), 中学生 (học sinh cấp hai)","example":{"zh":"明年他上中学。","py":"Míngnián tā shàng zhōngxué.","vi":"Sang năm cậu ấy lên cấp hai."}},{"stt":19,"hanzi":"中学生","pinyin":"zhōngxuéshēng","hanviet":"Trung học sinh","pos":"Danh từ","meaning":"học sinh trung học","comps":"一个中学生 (một học sinh cấp hai), 中学生们 (các bạn cấp hai)","example":{"zh":"我们家有了一个中学生。","py":"Wǒmen jiā yǒule yí gè zhōngxuéshēng.","vi":"Nhà mình đã có một học sinh cấp hai."}},{"stt":20,"hanzi":"小学","pinyin":"xiǎoxué","hanviet":"Tiểu học","pos":"Danh từ","meaning":"trường tiểu học","comps":"上小学 (học tiểu học), 小学生 (học sinh tiểu học)","example":{"zh":"儿子也上小学了。","py":"Érzi yě shàng xiǎoxué le.","vi":"Con trai cũng vào tiểu học rồi."}},{"stt":21,"hanzi":"小学生","pinyin":"xiǎoxuéshēng","hanviet":"Tiểu học sinh","pos":"Danh từ","meaning":"học sinh tiểu học","comps":"一个小学生 (một học sinh tiểu học), 小学生们 (các em tiểu học)","example":{"zh":"还有了一个小学生。","py":"Hái yǒule yí gè xiǎoxuéshēng.","vi":"Lại có thêm một học sinh tiểu học."}},{"stt":22,"hanzi":"上学","pinyin":"shàngxué","hanviet":"Thượng học","pos":"Động từ","meaning":"đi học, đến trường","comps":"上学了 (đi học rồi), 去上学 (đi tới trường)","example":{"zh":"上学后，他们都忙了。","py":"Shàngxué hòu, tāmen dōu máng le.","vi":"Đi học rồi, các con đều bận cả."}},{"stt":23,"hanzi":"他们","pinyin":"tāmen","hanviet":"Tha môn","pos":"Đại từ","meaning":"họ, bọn họ (nam)","comps":"他们都 (họ đều), 他们的 (của họ)","example":{"zh":"他们都上学了。","py":"Tāmen dōu shàngxué le.","vi":"Các cháu đều đi học rồi."}},{"stt":24,"hanzi":"她们","pinyin":"tāmen","hanviet":"Tha môn","pos":"Đại từ","meaning":"họ, các cô ấy (nữ)","comps":"她们都 (các cô ấy đều), 她们的 (của các cô ấy)","example":{"zh":"她们都是中学生。","py":"Tāmen dōu shì zhōngxuéshēng.","vi":"Các bạn ấy đều là học sinh cấp hai."}},{"stt":25,"hanzi":"它们","pinyin":"tāmen","hanviet":"Tha môn","pos":"Đại từ","meaning":"chúng (vật, con vật)","comps":"它们都 (chúng đều), 它们的 (của chúng)","example":{"zh":"它们是我的书。","py":"Tāmen shì wǒ de shū.","vi":"Chúng là sách của mình."}},{"stt":26,"hanzi":"晚","pinyin":"wǎn","hanviet":"Vãn","pos":"Tính từ","meaning":"muộn, trễ","comps":"太晚了 (muộn quá rồi), 晚上 (buổi tối)","example":{"zh":"太晚了，睡觉吧。","py":"Tài wǎn le, shuìjiào ba.","vi":"Muộn quá rồi, đi ngủ thôi."}},{"stt":27,"hanzi":"汉语","pinyin":"Hànyǔ","hanviet":"Hán ngữ","pos":"Danh từ riêng","meaning":"tiếng Hán, tiếng Trung","comps":"说汉语 (nói tiếng Trung), 学汉语 (học tiếng Trung)","example":{"zh":"你们会说汉语了吗？","py":"Nǐmen huì shuō Hànyǔ le ma?","vi":"Các em biết nói tiếng Trung rồi chứ?"}},{"stt":28,"hanzi":"汉字","pinyin":"Hànzì","hanviet":"Hán tự","pos":"Danh từ riêng","meaning":"chữ Hán","comps":"写汉字 (viết chữ Hán), 学汉字 (học chữ Hán)","example":{"zh":"我们都会写汉字了。","py":"Wǒmen dōu huì xiě Hànzì le.","vi":"Chúng em đều biết viết chữ Hán rồi."}}],"hanzi":[{"char":"上","pinyin":"shàng","hanviet":"Thượng","chars":["上"],"story":"上 vẽ một vạch ngắn nằm TRÊN vạch dài — nghĩa gốc là \"phía trên\". Từ \"lên trên\" sinh ra hai nghĩa động từ của bài này: 上火车 là bước LÊN tàu, còn 上中学 là bước LÊN một bậc học mới, tức \"vào học\"."},{"char":"火车","pinyin":"huǒchē","hanviet":"Hoả xa","chars":["火","车"],"story":"火车 = 火 (ngọn lửa, vẽ hình lửa bốc lên) + 车 (cái xe, vẽ hình chiếc xe nhìn từ trên xuống). Đầu máy xe lửa ngày xưa đốt than sinh lửa để chạy, nên người Trung gọi là \"xe lửa\" — đúng như tiếng Việt."},{"char":"中午","pinyin":"zhōngwǔ","hanviet":"Trung ngọ","chars":["中","午"],"story":"中 vẽ mũi tên cắm trúng GIỮA cái đích, nghĩa là \"giữa\". 午 là khoảng giờ Ngọ (11–13 giờ), lúc mặt trời lên giữa trời. Ghép lại 中午 là \"buổi trưa\" — âm Hán Việt \"Trung ngọ\" người Việt nghe rất quen."},{"char":"开","pinyin":"kāi","hanviet":"Khai","chars":["开"],"story":"开 giản thể vẽ hai bàn tay đang nhấc thanh chốt cửa lên — nghĩa gốc là \"mở cửa\". Từ \"mở\" mở rộng thành \"khởi động, cho chạy\": 开车 lái xe, 车开了 xe chạy rồi."},{"char":"有些","pinyin":"yǒuxiē","hanviet":"Hữu ta","chars":["有","些"],"story":"有些 = 有 (có, vẽ bàn tay cầm miếng thịt) + 些 (một vài, một ít). Chữ 些 đã gặp ở 这些 và 那些 bài 10. Ghép lại nghĩa là \"có một vài\", dùng để tách một phần ra khỏi số đông."},{"char":"有的","pinyin":"yǒude","hanviet":"Hữu đích","chars":["有","的"],"story":"有的 = 有 (có) + 的 (trợ từ kết cấu, bài 3, thay cho danh từ đứng sau). Nghĩa đen là \"cái mà có\", dùng để chỉ một phần trong nhóm: 有的人 = có (những) người. Rất hay đi thành cặp 有的…有的…."},{"char":"了","pinyin":"le","hanviet":"Liễu","chars":["了"],"story":"了 vẽ hình đứa trẻ mới sinh còn quấn tã, hai tay bị bó lại — ý \"gọn xong, kết thúc\". Ngày nay 了 đứng NGAY SAU động từ để báo việc đã hoàn thành (bài này), hoặc đứng CUỐI CÂU để báo tình hình đã đổi khác (bài 12)."},{"char":"写","pinyin":"xiě","hanviet":"Tả","chars":["写"],"story":"写 phồn thể là 寫, gồm bộ 宀 (mái nhà) — nghĩa gốc là \"đặt đồ vào trong nhà\", sau chuyển thành \"chép lại, ghi ra giấy\". Bản giản thể giữ nét trên như một mái nhà nhỏ che lấy ngòi bút."},{"char":"都","pinyin":"dōu","hanviet":"Đô","chars":["都"],"story":"都 = 者 (chỉ âm) + 阝 (bộ ấp, chỉ vùng đất, thành phố). Nghĩa gốc là \"kinh đô\" (đọc dū, như 首都). Vì kinh đô là nơi mọi người tụ về đông đủ nên chữ này còn đọc dōu với nghĩa \"đều, tất cả\"."},{"char":"听见","pinyin":"tīngjiàn","hanviet":"Thính kiến","chars":["听","见"],"story":"听见 = 听 (nghe) + 见 (thấy, bài 7). 见 đứng sau động từ để báo KẾT QUẢ: nghe mà có kết quả thì là \"nghe thấy\". Cùng khuôn với 看见 (nhìn thấy) đã học ở bài 8."},{"char":"不要","pinyin":"búyào","hanviet":"Bất yếu","chars":["不","要"],"story":"不要 = 不 (không) + 要 (muốn, cần — bài 11 và 13). Nghĩa đen là \"không cần\", dùng để khuyên can: \"đừng\". Nhớ phân biệt: 不想 là \"không muốn\" (ý mình), còn 不要 là \"đừng\" (lời nhắc người khác)."},{"char":"说话","pinyin":"shuōhuà","hanviet":"Thuyết thoại","chars":["说","话"],"story":"说话 = 说 (nói, bộ 讠 lời nói) + 话 (lời, gồm 讠 + 舌 cái lưỡi — lời do lưỡi phát ra). Ghép lại là \"nói lời\". Đây là một từ ly hợp: tách ra được thành 说什么话, 说了半天话."},{"char":"听","pinyin":"tīng","hanviet":"Thính","chars":["听"],"story":"听 giản thể = 口 (miệng) + 斤 (chỉ âm). Phồn thể 聽 có bộ 耳 (cái tai) cùng 心 (trái tim) — người xưa cho rằng nghe phải nghe bằng tai và bằng cả tấm lòng. Âm Hán Việt \"Thính\" còn nằm trong \"thính giác\"."},{"char":"哪些","pinyin":"nǎxiē","hanviet":"Ná ta","chars":["哪","些"],"story":"哪些 = 哪 (nào) + 些 (một vài). Hỏi về cả một nhóm nhiều vật: \"những cái nào\". Ba chữ đi thành bộ: 这些 (những cái này) · 那些 (những cái kia) · 哪些 (những cái nào) — chỉ khác chữ đứng trước."},{"char":"字","pinyin":"zì","hanviet":"Tự","chars":["字"],"story":"字 = 宀 (mái nhà) + 子 (đứa con). Nghĩa gốc là \"sinh con trong nhà\". Chữ viết cũng sinh sôi nảy nở từ những chữ gốc ban đầu, nên 字 dần mang nghĩa \"chữ viết\". Âm Hán Việt là \"Tự\", như trong \"văn tự\"."},{"char":"汉语","pinyin":"Hànyǔ","hanviet":"Hán ngữ","chars":["汉","语"],"story":"汉 chỉ dân tộc Hán và triều đại Hán (bộ 氵 nước, vốn là tên con sông Hán Thuỷ). 语 = 讠 (lời nói) + 吾 (chỉ âm) nghĩa là \"ngôn ngữ\". 汉语 là tiếng nói của người Hán — người Việt đọc thẳng là \"Hán ngữ\"."},{"char":"汉字","pinyin":"Hànzì","hanviet":"Hán tự","chars":["汉","字"],"story":"汉字 = 汉 (Hán) + 字 (chữ viết) — chữ viết của người Hán. Hai chữ này khớp từng tiếng với âm Hán Việt \"Hán tự\" mà người Việt vẫn dùng, nên rất dễ nhớ."},{"char":"明年","pinyin":"míngnián","hanviet":"Minh niên","chars":["明","年"],"story":"明 = 日 (mặt trời) + 月 (mặt trăng), nghĩa gốc là \"sáng\"; nhưng đứng trước từ chỉ thời gian thì mang nghĩa \"kế tiếp\": 明天 ngày mai (bài 9), 明年 năm sau. 年 vẽ bó lúa trên lưng người — thu một vụ lúa là hết một năm."},{"char":"中学","pinyin":"zhōngxué","hanviet":"Trung học","chars":["中","学"],"story":"中学 = 中 (giữa) + 学 (học). Đây là bậc học nằm GIỮA tiểu học và đại học nên gọi là \"trung học\". Ba bậc xếp theo cỡ rất dễ nhớ: 小学 → 中学 → 大学 (bài 11)."},{"char":"中学生","pinyin":"zhōngxuéshēng","hanviet":"Trung học sinh","chars":["中","学","生"],"story":"中学生 = 中学 (trường trung học) + 生 (người học). Cùng một khuôn với 学生 (bài 1) và 大学生 (bài 11): chỉ cần đổi tên bậc học đứng trước chữ 生 là ra người học của bậc đó."},{"char":"小学","pinyin":"xiǎoxué","hanviet":"Tiểu học","chars":["小","学"],"story":"小学 = 小 (nhỏ, vẽ ba hạt nhỏ) + 学 (học). Bậc học dành cho trẻ nhỏ. Người Việt gọi là \"tiểu học\" — đúng âm Hán Việt của hai chữ này."},{"char":"小学生","pinyin":"xiǎoxuéshēng","hanviet":"Tiểu học sinh","chars":["小","学","生"],"story":"小学生 = 小学 (trường tiểu học) + 生 (người học). Nhớ cả chùm ba từ: 小学生 · 中学生 · 大学生 — chỉ đổi chữ đứng đầu là đổi bậc học."},{"char":"上学","pinyin":"shàngxué","hanviet":"Thượng học","chars":["上","学"],"story":"上学 = 上 (lên, đến) + 学 (trường học), nghĩa là \"đến trường\". Đây cũng là một từ ly hợp, tách ra được: 上了学, 上过学. Cùng họ với 上班 (bài 7) và 上课 (bài 7) — đều là 上 + nơi/việc phải đến."},{"char":"他们","pinyin":"tāmen","hanviet":"Tha môn","chars":["他","们"],"story":"他们 = 他 (anh ấy, bài 8 — bộ 亻người) + 们 (hậu tố số nhiều, bài 1). Chỉ thêm 们 là ngôi thứ ba số ít thành số nhiều. Nhóm có cả nam lẫn nữ cũng dùng 他们."},{"char":"她们","pinyin":"tāmen","hanviet":"Tha môn","chars":["她","们"],"story":"她们 = 她 (cô ấy, bài 4) + 们. Bộ 女 bên trái cho biết cả nhóm đều là nữ. Đọc y hệt 他们 — chỉ khác khi VIẾT ra, còn nghe thì không phân biệt được."},{"char":"它们","pinyin":"tāmen","hanviet":"Tha môn","chars":["它","们"],"story":"它们 = 它 (nó — chỉ đồ vật, con vật; bài 4) + 们. Ba chữ 他们 · 她们 · 它们 đọc giống hệt nhau, chỉ khác thành phần bên trái: 亻 người nam, 女 người nữ, còn 它 vốn vẽ con rắn nên dùng cho vật."},{"char":"晚","pinyin":"wǎn","hanviet":"Vãn","chars":["晚"],"story":"晚 = 日 (mặt trời) + 免 (chỉ âm wǎn). Mặt trời đã lặn, ngày sắp hết — nên 晚 nghĩa là \"muộn, trễ\", và 晚上 (bài 7) là \"buổi tối\". Âm Hán Việt \"Vãn\" còn trong \"vãn cảnh\"."}],"grammar":[{"title":"Trợ từ động thái 了 (动态助词)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>đã xong</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Hành động đã xong</p><ul><li><span class=\"zh\">了</span> đứng <b>ngay sau động từ</b> để báo hành động <b>đã hoàn thành</b>: <span class=\"zh\">我看了一个电影。</span></li><li>Tân ngữ phía sau thường có <b>số lượng</b> hoặc <b>từ hạn định</b>: <span class=\"zh\">一个电影　·　一个中学生</span>. Tân ngữ trống trơn thì câu chưa trọn ý.</li><li>Bài 12 học <span class=\"zh\">了</span> <b>cuối câu</b> (语气助词) báo tình hình đã đổi khác; bài này là <span class=\"zh\">了</span> <b>sau động từ</b> (动态助词) báo việc đã xong.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我看了一个电影。</span> = Mình đã xem một bộ phim.　·　Phủ định: <span class=\"zh\">没看</span> — bỏ luôn <span class=\"zh\">了</span>.</p>","note":"<b>Lưu ý:</b> Phủ định dùng <span class=\"zh\">没</span> và <b>phải bỏ</b> <span class=\"zh\">了</span>: nói <span class=\"zh\">没看见</span>, <b>không nói</b> <span class=\"zh\">没看见了</span>.","examples":[{"zh":"我看了一个电影。","py":"Wǒ kànle yí gè diànyǐng.","vi":"Mình đã xem một bộ phim."},{"zh":"我买了一个新电脑。","py":"Wǒ mǎile yí gè xīn diànnǎo.","vi":"Tôi đã mua một cái máy tính mới."},{"zh":"我昨天没去商店买东西。","py":"Wǒ zuótiān méi qù shāngdiàn mǎi dōngxi.","vi":"Hôm qua tôi không đi cửa hàng mua đồ."}],"exercises":[{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">你去哪儿{{0}}？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我今天有课，去学校上{{1}}课，还在那儿吃{{2}}午饭。</span></span></span><span class=\"qz-hint\">Bạn đã đi đâu thế? — Hôm nay mình có tiết, đến trường học, còn ăn trưa ở đó nữa.</span>","blanks":[["了"],["了"],["了"]],"explain":"你去哪儿了？ (Nǐ qù nǎr le?) · 我今天有课，去学校上了课，还在那儿吃了午饭。 (Wǒ jīntiān yǒu kè, qù xuéxiào shàng le kè, hái zài nàr chī le wǔfàn.)"},{"type":"fillm","q":"<span class=\"qz-dlg\"><span class=\"qz-ln\"><span class=\"qz-who\">A</span><span class=\"zh\">我昨天看{{0}}电影，{{1}}去超市。你呢？</span></span><span class=\"qz-ln\"><span class=\"qz-who\">B</span><span class=\"zh\">我昨天去{{2}}超市，{{3}}看电影。</span></span></span><span class=\"qz-hint\">Hôm qua mình xem phim, không đi siêu thị. Còn bạn? — Hôm qua mình đi siêu thị, không xem phim.</span>","blanks":[["了"],["没"],["了"],["没"]],"explain":"我昨天看了电影，没去超市。你呢？ (Wǒ zuótiān kàn le diànyǐng, méi qù chāoshì. Nǐ ne?) · 我昨天去了超市，没看电影。 (Wǒ zuótiān qù le chāoshì, méi kàn diànyǐng.)"}]},{"title":"Từ ly hợp 离合词 (说话, 上学…)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>说</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>(什么)</b><small>chen vào giữa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>话</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Động từ tách được</p><ul><li>Từ ly hợp thực chất là <b>động từ + tân ngữ</b> dính liền: <span class=\"zh\">说话</span> (nói + lời), <span class=\"zh\">上学</span> (lên + trường), <span class=\"zh\">睡觉</span> (ngủ + giấc).</li><li>Muốn thêm <span class=\"zh\">了</span>, số lượng hay từ để hỏi thì phải <b>chen vào giữa</b> hai chữ: <span class=\"zh\">说了话　·　上了学　·　说什么话？</span></li><li>Nhiều từ đã học chính là từ ly hợp: <span class=\"zh\">上班　·　下班　·　上课　·　下课　·　开车　·　唱歌　·　睡觉</span>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">说话</span> = 说 + 话　·　<span class=\"zh\">上学</span> = 上 + 学　·　<span class=\"zh\">睡觉</span> = 睡 + 觉</p>","note":"<b>Lưu ý:</b> <b>Không</b> thêm tân ngữ ra sau từ ly hợp: nói <span class=\"zh\">说汉语</span>, <b>không nói</b> <span class=\"zh\">说话汉语</span>.","examples":[{"zh":"请大家不要说话！","py":"Qǐng dàjiā búyào shuōhuà!","vi":"Mời cả lớp đừng nói chuyện!"},{"zh":"睡觉 → 睡了觉；睡了一觉","py":"shuìjiào → shuìle jiào; shuìle yí jiào","vi":"ngủ → đã ngủ; đã ngủ một giấc"},{"zh":"上课 → 上了课；上中文课","py":"shàngkè → shàngle kè; shàng Zhōngwén kè","vi":"vào học → đã học; học tiết tiếng Trung"},{"zh":"下班 → 下了班","py":"xiàbān → xiàle bān","vi":"tan làm → đã tan làm"},{"zh":"生病 → 生了病；生了大病","py":"shēngbìng → shēngle bìng; shēngle dà bìng","vi":"bị ốm → đã ốm; đã ốm nặng"},{"zh":"说话 → 说了话；说了很多话","py":"shuōhuà → shuōle huà; shuōle hěn duō huà","vi":"nói chuyện → đã nói; đã nói rất nhiều"}],"exercises":[]},{"title":"Phó từ phạm vi 都 (đều, tất cả)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>số nhiều</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>都</b><small>đều</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span></div>","summary":"<p class=\"gr-lead\">Đều, tất cả đều</p><ul><li><span class=\"zh\">都</span> gộp chung <b>tất cả</b> những gì nói phía trước, nên chủ ngữ phải là <b>số nhiều</b>: <span class=\"zh\">我们　·　他们　·　这些字</span>.</li><li><span class=\"zh\">都</span> luôn đứng <b>trước động từ</b>, không bao giờ đứng cuối câu: <span class=\"zh\">上学后，他们都忙了。</span></li><li>Chữ <span class=\"zh\">都</span> còn một âm nữa là <b>dū</b> nghĩa \"kinh đô\"; làm phó từ \"đều\" thì luôn đọc <b>dōu</b>.</li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我们都会写了。</span> = Chúng em đều biết viết rồi.　·　<span class=\"zh\">他们都忙了。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">都不</span> = <b>không ai</b> …, còn <span class=\"zh\">不都</span> = <b>không phải ai cũng</b> … — đảo thứ tự là đổi hẳn nghĩa.","examples":[{"zh":"我们都会写了。","py":"Wǒmen dōu huì xiě le.","vi":"Chúng em đều biết viết rồi."},{"zh":"我和我的朋友们都去。","py":"Wǒ hé wǒ de péngyoumen dōu qù.","vi":"Tôi và các bạn của tôi đều đi."},{"zh":"同学们都没听见。","py":"Tóngxuémen dōu méi tīngjiàn.","vi":"Các bạn học đều không nghe thấy."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Trên tàu — hai bạn trò chuyện","lines":[{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"你们上火车后看见王老师了吗？","py":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","vi":"Sau khi lên tàu các cậu có thấy cô Vương không?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"没看见。中午车开后，有些人在看书，有些人睡觉了。","py":"Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","vi":"Không thấy. Trưa tàu chạy rồi, có người đang đọc sách, có người ngủ mất rồi."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"你呢？","py":"Nǐ ne?","vi":"Còn cậu thì sao?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"我看了一个电影。","py":"Wǒ kànle yí gè diànyǐng.","vi":"Mình xem một bộ phim."}]},{"titleZh":"课文二","titleVi":"Trong lớp — cô hỏi về chữ Hán","lines":[{"speaker":"王","name":"Cô Vương Nhất Phi","zh":"你们会说汉语了，也会写汉字了吗？","py":"Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","vi":"Các em biết nói tiếng Trung rồi, biết viết chữ Hán nữa chứ?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我们都会写了。","py":"Wǒmen dōu huì xiě le.","vi":"Chúng em đều biết viết rồi ạ."},{"speaker":"中","name":"Trần Thiên Trung","zh":"老师，我听不见。","py":"Lǎoshī, wǒ tīng bú jiàn.","vi":"Thưa cô, em không nghe thấy ạ."},{"speaker":"王","name":"Cô Vương Nhất Phi","zh":"请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","py":"Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","vi":"Mời cả lớp đừng nói chuyện! Nghe câu hỏi của cô nào: các em đã biết viết những chữ Hán nào rồi?"},{"speaker":"中","name":"Trần Thiên Trung","zh":"我会写这些字了，您看！","py":"Wǒ huì xiě zhèxiē zì le, nín kàn!","vi":"Em biết viết mấy chữ này rồi, cô xem ạ!"}]},{"titleZh":"课文三","titleVi":"Ở nhà — bố mẹ nói chuyện hai con","lines":[{"speaker":"明","name":"Lưu Minh","zh":"明年女儿上中学。","py":"Míngnián nǚ'ér shàng zhōngxué.","vi":"Sang năm con gái lên cấp hai rồi."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"对。儿子也上小学了。","py":"Duì. Érzi yě shàng xiǎoxué le.","vi":"Đúng rồi. Con trai cũng vào tiểu học nữa."},{"speaker":"明","name":"Lưu Minh","zh":"我们家有了一个中学生。","py":"Wǒmen jiā yǒule yí gè zhōngxuéshēng.","vi":"Nhà mình đã có một học sinh cấp hai rồi."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"还有了一个小学生。","py":"Hái yǒule yí gè xiǎoxuéshēng.","vi":"Còn thêm một học sinh tiểu học nữa."},{"speaker":"明","name":"Lưu Minh","zh":"上学后，他们都忙了。","py":"Shàngxué hòu, tāmen dōu máng le.","vi":"Đi học rồi, hai đứa đều bận cả."},{"speaker":"雪","name":"Vương Nhất Tuyết","zh":"是的。太晚了，睡觉吧。","py":"Shì de. Tài wǎn le, shuìjiào ba.","vi":"Ừ. Muộn quá rồi, đi ngủ thôi."}]}]},"extra":[],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Kể cuối tuần trước em đã làm gì","q":{"zh":"两人一组，说一说上星期六或星期日你都做了什么。","py":"Liǎng rén yì zǔ, shuō yi shuō shàng Xīngqīliù huò Xīngqīrì nǐ dōu zuòle shénme.","vi":"Hai người một nhóm, kể xem thứ bảy hoặc chủ nhật tuần trước bạn đã làm những gì."},"items":[{"zh":"我星期六上午上了中文课，","py":"Wǒ Xīngqīliù shàngwǔ shàngle Zhōngwén kè,","vi":"Sáng thứ bảy mình học tiết tiếng Trung,"},{"zh":"中午吃了饭后休息了一下，","py":"zhōngwǔ chīle fàn hòu xiūxile yíxià,","vi":"buổi trưa ăn cơm xong nghỉ một lát,"},{"zh":"下午去商店买了一些东西，","py":"xiàwǔ qù shāngdiàn mǎile yìxiē dōngxi,","vi":"buổi chiều đi cửa hàng mua ít đồ,"},{"zh":"晚上和朋友吃了晚饭。","py":"wǎnshang hé péngyou chīle wǎnfàn.","vi":"buổi tối ăn tối cùng bạn bè."}]}],"speak":[]}},{"id":"k1v3-b15","courseId":"k1v3","order":15,"title":"Hẹn gặp ở sân bay Đại Hưng!","titleZh":"大兴机场见！","titlePy":"dàxīng jīchǎng jiàn","vocab":[{"stt":1,"hanzi":"爱","pinyin":"ài","hanviet":"Ái","pos":"Động từ","meaning":"yêu; thích, mê","comps":"爱吃 (thích ăn), 爱看 (thích xem)","example":{"zh":"我爱吃中国菜。","py":"Wǒ ài chī Zhōngguó cài.","vi":"Mình rất thích ăn món Trung Quốc."}},{"stt":2,"hanzi":"哪个","pinyin":"nǎge","hanviet":"Ná cá","pos":"Đại từ nghi vấn","meaning":"cái nào, món nào","comps":"哪个人 (người nào), 哪个好 (cái nào hơn)","example":{"zh":"你们爱吃哪个菜？","py":"Nǐmen ài chī nǎge cài?","vi":"Các em thích ăn món nào?"}},{"stt":3,"hanzi":"去年","pinyin":"qùnián","hanviet":"Khứ niên","pos":"Danh từ","meaning":"năm ngoái (↔ 明年)","comps":"今年 (năm nay), 明年 (sang năm)","example":{"zh":"去年我去了西安。","py":"Qùnián wǒ qùle Xī'ān.","vi":"Năm ngoái mình đi Tây An."}},{"stt":4,"hanzi":"男朋友","pinyin":"nánpéngyou","hanviet":"Nam bằng hữu","pos":"Danh từ","meaning":"bạn trai (↔ 女朋友)","comps":"我男朋友 (bạn trai tôi), 女朋友 (bạn gái)","example":{"zh":"我和男朋友去了西安。","py":"Wǒ hé nánpéngyou qùle Xī'ān.","vi":"Mình và bạn trai đã đi Tây An."}},{"stt":5,"hanzi":"几","pinyin":"jǐ","hanviet":"Kỷ","pos":"Số từ","meaning":"vài, mấy (số không xác định)","comps":"几个 (mấy cái), 前几年 (mấy năm trước)","example":{"zh":"前几年我去了西安。","py":"Qián jǐ nián wǒ qùle Xī'ān.","vi":"Mấy năm trước mình đã đi Tây An."}},{"stt":6,"hanzi":"年","pinyin":"nián","hanviet":"Niên","pos":"Danh từ","meaning":"năm; đơn vị đếm năm","comps":"去年 (năm ngoái), 明年 (sang năm)","example":{"zh":"前几年我去了西安。","py":"Qián jǐ nián wǒ qùle Xī'ān.","vi":"Mấy năm trước mình đã đi Tây An."}},{"stt":7,"hanzi":"好玩儿","pinyin":"hǎowánr","hanviet":"Hảo ngoạn nhi","pos":"Tính từ","meaning":"vui, thú vị","comps":"非常好玩儿 (cực kỳ vui), 不好玩儿 (không vui)","example":{"zh":"西安非常好玩儿。","py":"Xī'ān fēicháng hǎowánr.","vi":"Tây An cực kỳ thú vị."}},{"stt":8,"hanzi":"飞机","pinyin":"fēijī","hanviet":"Phi cơ","pos":"Danh từ","meaning":"máy bay","comps":"坐飞机 (đi máy bay), 飞机场 (sân bay)","example":{"zh":"我们坐飞机去北京。","py":"Wǒmen zuò fēijī qù Běijīng.","vi":"Chúng mình đi Bắc Kinh bằng máy bay."}},{"stt":9,"hanzi":"要","pinyin":"yào","hanviet":"Yếu","pos":"Động từ","meaning":"cần, mất (thời gian)","comps":"要几个小时 (mất mấy tiếng), 要多少钱 (hết bao nhiêu tiền)","example":{"zh":"到北京要九个小时。","py":"Dào Běijīng yào jiǔ gè xiǎoshí.","vi":"Đến Bắc Kinh mất chín tiếng."}},{"stt":10,"hanzi":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","pos":"Danh từ","meaning":"tiếng, giờ đồng hồ","comps":"一个小时 (một tiếng), 半个小时 (nửa tiếng)","example":{"zh":"我睡了八个小时。","py":"Wǒ shuìle bā gè xiǎoshí.","vi":"Mình đã ngủ tám tiếng."}},{"stt":11,"hanzi":"家人","pinyin":"jiārén","hanviet":"Gia nhân","pos":"Danh từ","meaning":"người nhà, gia đình","comps":"我家人 (người nhà tôi), 家人们 (những người trong nhà)","example":{"zh":"我家人都在北京。","py":"Wǒ jiārén dōu zài Běijīng.","vi":"Người nhà mình đều ở Bắc Kinh."}},{"stt":12,"hanzi":"时间","pinyin":"shíjiān","hanviet":"Thời gian","pos":"Danh từ","meaning":"thời gian","comps":"有时间 (có thời gian), 没时间 (không rảnh)","example":{"zh":"星期天我姐姐也有时间。","py":"Xīngqītiān wǒ jiějie yě yǒu shíjiān.","vi":"Chủ nhật chị mình cũng rảnh."}},{"stt":13,"hanzi":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","pos":"Danh từ","meaning":"sân bay","comps":"去机场 (ra sân bay), 大兴机场 (sân bay Đại Hưng)","example":{"zh":"她可以去机场接你们。","py":"Tā kěyǐ qù jīchǎng jiē nǐmen.","vi":"Chị ấy có thể ra sân bay đón các em."}},{"stt":14,"hanzi":"接","pinyin":"jiē","hanviet":"Tiếp","pos":"Động từ","meaning":"đón; nhận, nghe máy","comps":"接你们 (đón các bạn), 接电话 (nghe điện thoại)","example":{"zh":"我去机场接你。","py":"Wǒ qù jīchǎng jiē nǐ.","vi":"Mình ra sân bay đón bạn."}},{"stt":15,"hanzi":"住","pinyin":"zhù","hanviet":"Trú","pos":"Động từ","meaning":"ở, sống, trọ","comps":"住我家 (ở nhà tôi), 住在北京 (sống ở Bắc Kinh)","example":{"zh":"你们也可以住我家。","py":"Nǐmen yě kěyǐ zhù wǒ jiā.","vi":"Các em cũng có thể ở nhà cô."}},{"stt":16,"hanzi":"早","pinyin":"zǎo","hanviet":"Tảo","pos":"Tính từ","meaning":"sớm (↔ 晚 muộn)","comps":"早上 (buổi sáng), 太早了 (sớm quá)","example":{"zh":"八点到，早不早？","py":"Bā diǎn dào, zǎo bu zǎo?","vi":"Tám giờ tới, có sớm không?"}},{"stt":17,"hanzi":"那","pinyin":"nà","hanviet":"Na","pos":"Liên từ","meaning":"vậy thì, thế thì","comps":"那我们… (vậy chúng ta…), 那好吧 (vậy được rồi)","example":{"zh":"那我们在机场见！","py":"Nà wǒmen zài jīchǎng jiàn!","vi":"Vậy chúng ta gặp nhau ở sân bay nhé!"}},{"stt":18,"hanzi":"大兴机场","pinyin":"Dàxīng Jīchǎng","hanviet":"Đại Hưng cơ trường","pos":"Danh từ riêng","meaning":"sân bay Đại Hưng","comps":"到大兴机场 (đến sân bay Đại Hưng), 在大兴机场见 (gặp ở đó)","example":{"zh":"我们八点到大兴机场。","py":"Wǒmen bā diǎn dào Dàxīng Jīchǎng.","vi":"Chúng em tám giờ tới sân bay Đại Hưng."}},{"stt":19,"hanzi":"西安","pinyin":"Xī'ān","hanviet":"Tây An","pos":"Danh từ riêng","meaning":"Tây An (thành phố)","comps":"去西安 (đi Tây An), 西安人 (người Tây An)","example":{"zh":"我们去西安吧。","py":"Wǒmen qù Xī'ān ba.","vi":"Chúng mình đi Tây An đi."}},{"stt":20,"hanzi":"北京","pinyin":"Běijīng","hanviet":"Bắc Kinh","pos":"Danh từ riêng","meaning":"Bắc Kinh (thủ đô)","comps":"去北京 (đi Bắc Kinh), 北京人 (người Bắc Kinh)","example":{"zh":"今年我想去北京。","py":"Jīnnián wǒ xiǎng qù Běijīng.","vi":"Năm nay mình muốn đi Bắc Kinh."}}],"hanzi":[{"char":"爱","pinyin":"ài","hanviet":"Ái","chars":["爱"],"story":"爱 phồn thể là 愛, ở giữa có bộ 心 (trái tim) — yêu là trao trái tim ra cho người khác. Bản giản thể bỏ 心 và thay bằng 友 (bạn bè). Âm Hán Việt \"Ái\" còn nằm trong \"ái mộ, tình ái\"."},{"char":"哪个","pinyin":"nǎge","hanviet":"Ná cá","chars":["哪","个"],"story":"哪个 = 哪 (nào, bộ 口 vì đây là tiếng hỏi phát ra từ miệng) + 个 (lượng từ phổ biến nhất). Dùng khi hỏi CHỌN MỘT trong nhóm. Cùng bộ ba với 这个 (bài 13) và 那个 (bài 9) — chỉ đổi chữ đứng trước."},{"char":"去年","pinyin":"qùnián","hanviet":"Khứ niên","chars":["去","年"],"story":"去 nghĩa gốc là \"rời đi, đi khỏi\"; đặt trước từ chỉ thời gian thì mang nghĩa \"đã qua rồi\": 去年 là cái năm đã đi qua — năm ngoái. Dãy ba năm liền nhau: 去年 → 今年 → 明年 (bài 14)."},{"char":"男朋友","pinyin":"nánpéngyou","hanviet":"Nam bằng hữu","chars":["男","朋","友"],"story":"男朋友 = 男 (nam — gồm 田 thửa ruộng + 力 sức lực, người ra đồng dùng sức cày cấy; đã học bài 10) + 朋友 (bạn bè, bài 9). Đối lại là 女朋友. Lưu ý: 男朋友 là \"người yêu\", còn bạn bè bình thường chỉ nói 朋友."},{"char":"几","pinyin":"jǐ","hanviet":"Kỷ","chars":["几"],"story":"几 vẽ hình một cái ghế đẩu nhỏ (nghĩa gốc là cái bàn thấp). Ngày nay dùng để hỏi số lượng NHỎ, thường dưới mười: 几个人？ Khi không phải câu hỏi thì 几 nghĩa là \"vài\": 前几年 = mấy năm trước."},{"char":"年","pinyin":"nián","hanviet":"Niên","chars":["年"],"story":"年 vẽ hình một người vác bó lúa trên lưng. Ngày xưa mỗi năm chỉ thu hoạch lúa một vụ, nên hình ảnh gánh lúa về nhà trở thành chữ chỉ \"một năm\". Âm Hán Việt \"Niên\" còn trong \"niên khoá, thiếu niên\"."},{"char":"好玩儿","pinyin":"hǎowánr","hanviet":"Hảo ngoạn nhi","chars":["好","玩","儿"],"story":"好玩儿 = 好 (hay, đáng) + 玩 (chơi, bài 9) + 儿 hoá âm. Cùng một khuôn với 好吃 (bài 6), 好看 (bài 10), 好听 (bài 9): 好 + động từ = \"làm việc đó thấy thích\". Nhớ đọc dính vần thành `hǎowánr`."},{"char":"西安","pinyin":"Xī'ān","hanviet":"Tây An","chars":["西","安"],"story":"西安 = 西 (phía tây) + 安 (bình yên — gồm 宀 mái nhà + 女 người phụ nữ; có nhà có người là yên ổn). \"Miền tây bình yên\" — đây là cố đô của nhiều triều đại Trung Quốc, người Việt gọi thẳng là Tây An."},{"char":"北京","pinyin":"Běijīng","hanviet":"Bắc Kinh","chars":["北","京"],"story":"北京 = 北 (phía bắc — vẽ hai người quay lưng vào nhau) + 京 (kinh đô — vẽ một toà nhà cao dựng trên gò đất). \"Kinh đô phía bắc\" chính là thủ đô Trung Quốc; người Việt đọc là Bắc Kinh."},{"char":"飞机","pinyin":"fēijī","hanviet":"Phi cơ","chars":["飞","机"],"story":"飞机 = 飞 (bay — vẽ hình đôi cánh chim đang vỗ lên) + 机 (máy móc — bộ 木 gỗ chỉ nghĩa, 几 chỉ âm jī). \"Cỗ máy biết bay\" — đúng nghĩa \"phi cơ\" mà người Việt vẫn dùng."},{"char":"要","pinyin":"yào","hanviet":"Yếu","chars":["要"],"story":"要 gồm 覀 (biến thể của 西) + 女, nghĩa gốc là \"cái eo\" (nay viết thành 腰), sau mượn làm \"cần, muốn\". Bài 11 học 要 = \"muốn, sẽ\", bài 13 là \"gọi (món)\", bài này là \"cần, mất bao nhiêu\" khi nói về thời gian hoặc tiền."},{"char":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","chars":["小","时"],"story":"小时 = 小 (nhỏ) + 时 (thời gian). Người xưa chia một ngày thành 12 \"giờ lớn\" 时辰; khi dùng đồng hồ phương Tây chia 24 phần thì mỗi phần chỉ bằng nửa giờ cũ nên gọi là \"giờ nhỏ\". Đếm giờ phải có 个: 一个小时, khác 点 chỉ mốc giờ (bài 7)."},{"char":"家人","pinyin":"jiārén","hanviet":"Gia nhân","chars":["家","人"],"story":"家人 = 家 (nhà — gồm 宀 mái nhà + 豕 con lợn; nhà nào nuôi được lợn là gia đình đủ đầy) + 人 (người). \"Người ở trong nhà\" chính là người thân, gia đình."},{"char":"时间","pinyin":"shíjiān","hanviet":"Thời gian","chars":["时","间"],"story":"时间 = 时 (thời — gồm 日 mặt trời + 寸 tấc, người xưa đo bóng nắng để biết giờ) + 间 (khoảng cách — gồm 门 cánh cửa + 日 ánh nắng lọt qua khe cửa). \"Khoảng của thời gian\". Phân biệt: 时间 là khoảng DÀI, còn 时候 (bài 11) là một THỜI ĐIỂM."},{"char":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","chars":["机","场"],"story":"机场 = 机 (rút gọn của 飞机) + 场 (bãi, sân — bộ 土 đất). \"Bãi cho máy bay đỗ\" chính là sân bay. Cùng khuôn ghép \"loại + nơi chốn\" với 电影院 (bài 7) và 书店 (bài 8)."},{"char":"接","pinyin":"jiē","hanviet":"Tiếp","chars":["接"],"story":"接 = 扌 (bộ tay) + 妾 (chỉ âm). Có bộ tay nên nghĩa gốc là \"đưa tay ra chạm vào, nhận lấy\": nhận đồ, đón người ở sân bay, nghe điện thoại — tiếng Việt cũng nói \"tiếp nhận, tiếp đón\"."},{"char":"住","pinyin":"zhù","hanviet":"Trú","chars":["住"],"story":"住 = 亻 (bộ người) + 主 (chủ, chỉ âm zhǔ). Người làm chủ một chỗ tức là người sống ở đó, nên 住 nghĩa là \"ở, cư trú\". Âm Hán Việt \"Trú\" còn trong \"cư trú, thường trú\"."},{"char":"早","pinyin":"zǎo","hanviet":"Tảo","chars":["早"],"story":"早 = 日 (mặt trời) đặt trên 十 (vốn vẽ cái đầu người). Mặt trời mới nhô lên tới ngang đầu — trời vừa sáng, nên 早 nghĩa là \"sớm\". 早上 (bài 7) chính là \"lúc trời còn sớm\". Đối lại là 晚 (bài 14)."},{"char":"那","pinyin":"nà","hanviet":"Na","chars":["那"],"story":"那 vốn là đại từ chỉ định \"kia, đó\" (đã học ở bài 3 và bài 9). Khi đứng ĐẦU CÂU và nối tiếp lời người vừa nói thì nó thành liên từ: \"vậy thì, thế thì\" — dùng để chốt lại sau khi hai bên đã bàn xong."},{"char":"大兴机场","pinyin":"Dàxīng Jīchǎng","hanviet":"Đại Hưng cơ trường","chars":["大","兴","机","场"],"story":"大兴机场 = 大兴 (tên quận Đại Hưng ở phía nam Bắc Kinh; 兴 nghĩa là \"hưng thịnh, dấy lên\") + 机场 (sân bay). Đây là sân bay mới của Bắc Kinh, phần mái toả ra sáu nhánh nên hay được ví như con sao biển."}],"grammar":[{"title":"Câu ghép đẳng lập \"……，还/也……\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>分句1</b><small>ý thứ nhất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还 / 也</b><small>còn, cũng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>分句2</b><small>ý thứ hai</small></span></div>","summary":"<p class=\"gr-lead\">Còn …, cũng …</p><ul><li><span class=\"zh\">还</span> và <span class=\"zh\">也</span> đều là <b>phó từ</b>, đứng <b>trước động từ</b> của vế sau để nối thêm một ý cùng loại.</li><li><span class=\"zh\">也</span> nhấn ý \"cũng vậy\" — hai vế <b>ngang hàng nhau</b>: <span class=\"zh\">我喜欢这个，也喜欢那个。</span></li><li><span class=\"zh\">还</span> nhấn ý \"hơn nữa, lại còn\" — vế sau <b>thêm một mức</b>: <span class=\"zh\">好吃，还很好看。</span></li></ul><p class=\"gr-key\"><b>Câu mẫu:</b> <span class=\"zh\">我喜欢这个，也喜欢那个。</span>　·　<span class=\"zh\">好吃，还很好看。</span></p>","note":"<b>Lưu ý:</b> Cả hai <b>không đứng đầu câu</b> và <b>không đứng sau</b> động từ: nói <span class=\"zh\">也喜欢</span>, <b>không nói</b> <span class=\"zh\">喜欢也</span>.","examples":[{"zh":"我喜欢这个，也喜欢那个。","py":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","vi":"Mình thích cái này, cũng thích cái kia."},{"zh":"王老师是北京人，李文也是北京人。","py":"Wáng lǎoshī shì Běijīng rén, Lǐ Wén yě shì Běijīng rén.","vi":"Cô Vương là người Bắc Kinh, Lý Văn cũng là người Bắc Kinh."},{"zh":"我喜欢喝中国茶，还喜欢吃中国菜。","py":"Wǒ xǐhuan hē Zhōngguó chá, hái xǐhuan chī Zhōngguó cài.","vi":"Tôi thích uống trà Trung Quốc, còn thích ăn món Trung Quốc."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一","titleVi":"Bữa cơm — Lý Văn đãi các bạn","lines":[{"speaker":"文","name":"Lý Văn","zh":"你们爱吃哪个菜？","py":"Nǐmen ài chī nǎge cài?","vi":"Các cậu thích ăn món nào?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"我喜欢这个，也喜欢那个。","py":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","vi":"Mình thích món này, cũng thích món kia."},{"speaker":"中","name":"Trần Thiên Trung","zh":"这些菜都好吃，还很好看。","py":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","vi":"Mấy món đậu này ngon, lại còn đẹp mắt nữa."},{"speaker":"文","name":"Lý Văn","zh":"我爱吃中国菜，也喜欢做。大家多吃点儿。","py":"Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","vi":"Mình thích ăn món Trung Quốc, cũng thích nấu nữa. Mọi người ăn nhiều vào nhé."}]},{"titleZh":"课文二","titleVi":"Cả nhóm bàn nhau đi chơi ở đâu","lines":[{"speaker":"文","name":"Lý Văn","zh":"你们都想去哪儿？","py":"Nǐmen dōu xiǎng qù nǎr?","vi":"Các cậu đều muốn đi đâu?"},{"speaker":"妮","name":"Annie","zh":"去年我和男朋友去了西安，今年我想去北京。","py":"Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","vi":"Năm ngoái mình với bạn trai đi Tây An rồi, năm nay mình muốn đi Bắc Kinh."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"前几年我去了西安，非常好玩儿。今年我也想去北京。","py":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","vi":"Mấy năm trước mình đã đi Tây An, vui cực kỳ. Năm nay mình cũng muốn đi Bắc Kinh."},{"speaker":"文","name":"Lý Văn","zh":"我和王老师都是北京人，北京非常漂亮。","py":"Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","vi":"Mình với cô Vương đều là người Bắc Kinh, Bắc Kinh đẹp lắm."}]},{"titleZh":"课文三","titleVi":"Chuẩn bị đi Bắc Kinh — cô dặn dò","lines":[{"speaker":"王","name":"Cô Vương Nhất Phi","zh":"你们的飞机到北京要几个小时？","py":"Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?","vi":"Máy bay của các em bay tới Bắc Kinh mất mấy tiếng?"},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"九个小时。","py":"Jiǔ gè xiǎoshí.","vi":"Chín tiếng ạ."},{"speaker":"王","name":"Cô Vương Nhất Phi","zh":"我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","py":"Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","vi":"Người nhà cô đều ở Bắc Kinh, chủ nhật chị cô cũng rảnh, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô."},{"speaker":"妮","name":"Annie","zh":"我们星期日早上八点到大兴机场，早不早？","py":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","vi":"Sáng chủ nhật tám giờ chúng em tới sân bay Đại Hưng, có sớm không ạ?"},{"speaker":"王","name":"Cô Vương Nhất Phi","zh":"不早。","py":"Bù zǎo.","vi":"Không sớm đâu."},{"speaker":"月","name":"Bạch Gia Nguyệt","zh":"谢谢老师！那我们和您姐姐在大兴机场见！","py":"Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","vi":"Cảm ơn cô ạ! Vậy chúng em hẹn gặp chị cô ở sân bay Đại Hưng nhé!"}]}]},"extra":[],"activity":{"act":[{"zh":"角色扮演","py":"juésè bànyǎn","tag":"Đóng vai","mean":"Mời bạn đến nhà nấu món Trung","q":{"zh":"三个人分别扮演李文、陈天中和白家月，李文邀请陈天中和白家月做客，一起做中国菜。","py":"Sān gè rén fēnbié bànyǎn Lǐ Wén, Chén Tiānzhōng hé Bái Jiāyuè, Lǐ Wén yāoqǐng Chén Tiānzhōng hé Bái Jiāyuè zuòkè, yìqǐ zuò Zhōngguó cài.","vi":"Ba người lần lượt đóng Lý Văn, Trần Thiên Trung và Bạch Gia Nguyệt; Lý Văn mời hai bạn đến nhà chơi, cùng nấu món Trung Quốc."},"items":[{"lines":[{"who":"李文","zh":"天中、家月，你们星期六有时间吗？","py":"Tiānzhōng, Jiāyuè, nǐmen Xīngqīliù yǒu shíjiān ma?","vi":"Thiên Trung, Gia Nguyệt, thứ bảy các bạn có rảnh không?"},{"who":"陈天中","zh":"我有时间。","py":"Wǒ yǒu shíjiān.","vi":"Mình rảnh."},{"who":"白家月","zh":"我也有时间。","py":"Wǒ yě yǒu shíjiān.","vi":"Mình cũng rảnh."}]},{"lines":[{"who":"李文","zh":"太好了！你们都来我家吧，我们做中国菜吃，怎么样？","py":"Tài hǎo le! Nǐmen dōu lái wǒ jiā ba, wǒmen zuò Zhōngguó cài chī, zěnmeyàng?","vi":"Tuyệt quá! Các bạn đều đến nhà mình nhé, chúng ta nấu món Trung ăn, thế nào?"}]}]}],"speak":[]},"review":{"range":"13–15","rows":[{"l":13,"zh":"能愿动词\"可以\"","vi":"Động từ năng nguyện 可以","ex":{"zh":"我可以吃吗？","py":"Wǒ kěyǐ chī ma?","vi":"Tôi ăn được không?"}},{"l":13,"zh":"\"动词+一下\"结构","vi":"Cấu trúc Động từ + 一下","ex":{"zh":"看一下","py":"kàn yíxià","vi":"xem thử, xem một chút"}},{"l":13,"zh":"双宾语句（1）","vi":"Câu hai tân ngữ (1)","ex":{"zh":"给我一杯水。","py":"Gěi wǒ yì bēi shuǐ.","vi":"Cho tôi một cốc nước."}},{"l":14,"zh":"动态助词\"了（2）\"","vi":"Trợ từ động thái 了 (2)","ex":{"zh":"读了一本书","py":"dúle yì běn shū","vi":"đã đọc một quyển sách"}},{"l":14,"zh":"离合词（1）","vi":"Từ ly hợp (1)","ex":{"zh":"吃了饭，睡一觉","py":"chīle fàn, shuì yí jiào","vi":"ăn cơm xong, ngủ một giấc"}},{"l":14,"zh":"范围副词\"都\"","vi":"Phó từ phạm vi 都","ex":{"zh":"我们都来了。","py":"Wǒmen dōu lái le.","vi":"Chúng tôi đều đến rồi."}},{"l":15,"zh":"并列复句\"……，还/也……\"","vi":"Câu ghép đẳng lập ……，还/也……","ex":{"zh":"我喜欢看书，也喜欢看电影。","py":"Wǒ xǐhuan kàn shū, yě xǐhuan kàn diànyǐng.","vi":"Tôi thích đọc sách, cũng thích xem phim."}},{"l":15,"zh":"了解中国餐桌文化、待客礼仪。","vi":"Hiểu văn hoá bàn ăn, phép đãi khách của Trung Quốc","ex":{"zh":"大家多吃点儿。","py":"Dàjiā duō chī diǎnr.","vi":"Mọi người ăn nhiều vào nhé!"}}]}}];
